window.BIBLE_DATA = {"version":"2026-10-04","books":[{"id":"GEN","name":"ഉത്പത്തി","chapters":{"1":[{"v":1,"t":"ആദിയിൽ ദൈവം ആകാശവും ഭൂമിയും സൃഷ്ടിച്ചു.","p":1},{"v":2,"t":"ഭൂമി രൂപരഹിതവും ശൂന്യവുമായിരുന്നു. ആഴത്തിനു മുകളിൽ അന്ധകാരം വ്യാപിച്ചിരുന്നു. ദൈവത്തിന്റെ ചൈതന്യം വെള്ളത്തിനു മീതെ ചലിച്ചുകൊണ്ടിരുന്നു."},{"v":3,"t":"ദൈവം അരുളിച്ചെയ്തു: വെളിച്ചം ഉണ്ടാകട്ടെ. വെളിച്ചം ഉണ്ടായി.","p":1},{"v":4,"t":"വെളിച്ചം നല്ലതെന്നു ദൈവം കണ്ടു. വെളിച്ചവും ഇരുളും തമ്മിൽ ദൈവം വേർതിരിച്ചു."},{"v":5,"t":"വെളിച്ചത്തെ പകലെന്നും ഇരുളിനെ രാത്രിയെന്നും ദൈവം വിളിച്ചു. പ്രദോഷമായി, പ്രഭാതമായി - ഒന്നാം ദിവസം."},{"v":6,"t":"ദൈവം അരുളിച്ചെയ്തു: ജലമധ്യത്തിൽ ഒരു വിതാനം ഉണ്ടാകട്ടെ; അത് ജലത്തെ ജലത്തിൽനിന്നു വേർതിരിക്കട്ടെ.","p":1},{"v":7,"t":"ദൈവം വിതാനമുണ്ടാക്കുകയും വിതാനത്തിനു താഴെയുള്ള ജലം വിതാനത്തിനു മുകളിലുള്ള ജലത്തിൽനിന്നു വേർതിരിക്കുകയും ചെയ്തു."},{"v":8,"t":"അപ്രകാരം സംഭവിച്ചു. വിതാനത്തെ ദൈവം ആകാശമെന്നു വിളിച്ചു. പ്രദോഷമായി, പ്രഭാതമായി - രണ്ടാം ദിവസം."},{"v":9,"t":"ദൈവം അരുളിച്ചെയ്തു: ആകാശത്തിനു കീഴെയുള്ള ജലമെല്ലാം ഒരിടത്തു കൂടട്ടെ; ഉണങ്ങിയ കര പ്രത്യക്ഷപ്പെടട്ടെ. അപ്രകാരം സംഭവിച്ചു.","p":1},{"v":10,"t":"ഉണങ്ങിയ കരയെ ഭൂമിയെന്നും ഒന്നിച്ചുകൂടിയ ജലത്തെ കടലെന്നും ദൈവം വിളിച്ചു. അതു നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":11,"t":"ദൈവം വീണ്ടും അരുളിച്ചെയ്തു: പുല്ലും വിത്തുള്ള സസ്യങ്ങളും വിത്തോടുകൂടിയ അത്തനിനം ഫലം ഉത്പാദിപ്പിക്കുന്ന ഫലവൃക്ഷങ്ങളും ഭൂമി മുളപ്പിക്കട്ടെ. അപ്രകാരം സംഭവിച്ചു.","p":1},{"v":12,"t":"പുല്ലും അത്തനിനം വിത്തു മുളപ്പിക്കുന്ന സസ്യങ്ങളും അത്തനിനം വിത്തുള്ളവയും ഫലം ഉത്പാദിപ്പിക്കുന്ന വൃക്ഷങ്ങളും ഭൂമി പുറപ്പെടുവിച്ചു. അവ നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":13,"t":"പ്രദോഷമായി, പ്രഭാതമായി - മൂന്നാം ദിവസം."},{"v":14,"t":"ദൈവം അരുളിച്ചെയ്തു: പകലും രാത്രിയും തമ്മിൽ വേർതിരിക്കാൻ ആകാശവിതാനത്തിൽ ജ്യോതിസ്സുകൾ ഉണ്ടാകട്ടെ. അവ കാലങ്ങളും ദിനങ്ങളും വർഷങ്ങളും കുറിക്കുന്ന അടയാളങ്ങളായിരിക്കട്ടെ.","p":1},{"v":15,"t":"ഭൂമിയിൽ പ്രകാശം ചൊരിയാൻ അവ ആകാശവിതാനത്തിൽ ആയിരിക്കട്ടെ. അപ്രകാരം സംഭവിച്ചു."},{"v":16,"t":"ദൈവം രണ്ട് മഹാജ്യോതിസ്സുകളെ ഉണ്ടാക്കി. പകലിനു വലിയ ജ്യോതിസ്സ്, രാത്രിക്ക് ചെറിയ ജ്യോതിസ്സ്; കൂടാതെ, നക്ഷത്രങ്ങളും."},{"v":17,"t":"ദൈവം അവയെ ആകാശവിതാനത്തിൽ സ്ഥാപിച്ചു; അത് ഭൂമിയിന്മേൽ പ്രകാശം ചൊരിയാനും"},{"v":18,"t":"ദിനരാത്രങ്ങളെ ഭരിക്കാനും വെളിച്ചവും അന്ധകാരവും തമ്മിൽ വേർതിരിക്കാനുമായിരുന്നു. അതു നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":19,"t":"പ്രദോഷമായി, പ്രഭാതമായി - നാലാം ദിവസം."},{"v":20,"t":"ദൈവം അരുളിച്ചെയ്തു: ജലം ജീവനുള്ളവയെക്കൊണ്ടു തിങ്ങിനിറയട്ടെ; പക്ഷികൾ ഭൂമിക്കുമീതെ ആകാശവിതാനത്തു പറക്കട്ടെ.","p":1},{"v":21,"t":"അങ്ങനെ ദൈവം ഭീമാകാരങ്ങളായ ജലജീവികളെയും ജലത്തിൽ പറ്റിച്ചേർന്നു നീന്തുന്ന വിവിധയിനം ജീവികളെയും സൃഷ്ടിച്ചു. അത്തനിനം പക്ഷികളെയും. അവ നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":22,"t":"ദൈവം അവയെ ഇപ്രകാരം അനുഗ്രഹിച്ചു: പെറ്റുപെരുകി സമുദ്രജലത്തിൽ നിറയുവിൻ; പക്ഷികൾ ഭൂമിയിൽ വർധിക്കട്ടെ."},{"v":23,"t":"പ്രദോഷമായി, പ്രഭാതമായി - അഞ്ചാം ദിവസം."},{"v":24,"t":"ദൈവം അരുളിച്ചെയ്തു: ജീവജാലങ്ങളെ, അതായത് കന്നുകാലികൾ, ഇഴജന്തുക്കൾ, കാട്ടുജീവികൾ എന്നിവയെ ഇനമനുസരിച്ച് ഭൂമി പുറപ്പെടുവിക്കട്ടെ. അപ്രകാരം സംഭവിച്ചു.","p":1},{"v":25,"t":"ദൈവം ഇനമനുസരിച്ച് ഭൂമിയിലെ കാട്ടുജീവികളെയും കന്നുകാലികളെയും മണ്ണിലെ സർവ ഇഴജന്തുക്കളെയും ഉരുവാക്കി. അവ നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":26,"t":"അനന്തരം, ദൈവം അരുളിച്ചെയ്തു: നമുക്ക് നമ്മുടെ ഛായയിലും സാദൃശ്യത്തിലും മനുഷ്യനെ ഉരുവാക്കാം. കടലിലെ മത്സ്യങ്ങളുടെയും ആകാശത്തിലെ പറവകളുടെയും കന്നുകാലികളുടെയും ഭൂമി മുഴുവന്റെയും ഭൂമിയിൽ ഇഴയുന്ന എല്ലാ ഇഴജന്തുക്കളുടെയുംമേൽ അവർക്ക് ആധിപത്യം ഉണ്ടാകട്ടെ.","p":1},{"v":27,"t":"അങ്ങനെ, ദൈവം തന്റെ ഛായയിൽ മനുഷ്യനെ സൃഷ്ടിച്ചു. ദൈവത്തിന്റെ ഛായയിൽ അവനെ സൃഷ്ടിച്ചു; ആണും പെണ്ണുമായി അവരെ സൃഷ്ടിച്ചു."},{"v":28,"t":"ദൈവം അവരെ അനുഗ്രഹിച്ചു.അവരോട് ദൈവം അരുൾ ചെയ്തു.പെറ്റുപെരുകിഭൂ"},{"v":29,"t":"ദൈവം വീണ്ടുംഅരുളിച്ചെയ്തു: ഇതാ, ഭൂമിയിലെങ്ങും വിത്ത് ഉല്പാദിപ്പിക്കുന്ന എല്ലാ സസ്യങ്ങളും എല്ലാ വൃക്ഷങ്ങളും ഞാൻ നിങ്ങൾക്കു നൽകുന്നു; അവ നിങ്ങൾക്കു ആഹാരമായിരിക്കും. ഭൂമിയിലെ എല്ലാ വന്യജീവികൾക്കും ആകാശത്തിലെ എല്ലാ പക്ഷികൾക്കും ഭൂമിയിൽ ഇഴയുന്നവയും ജീവശ്വാസമുള്ളവ സകലത്തിനും എല്ലാ ഹരിതസസ്യങ്ങളും ആഹാരമായിരിക്കും; അപ്രകാരം സംഭവിച്ചു. താൻ സൃഷ്ടിച്ചതെല്ലാം ദൈവം കണ്ടു: ഇതാ, വളരെ നല്ലത്! പ്രഭാതമായി, പ്രദോഷമായി - ആറാം ദിവസം."}],"2":[{"v":1,"t":"അങ്ങനെ ആകാശവും ഭൂമിയും അവയുടെ സമസ്ത വ്യൂഹവും പൂർത്തീകരിക്കപ്പെട്ടു.","p":1},{"v":2,"t":"താൻ ചെയ്തുകൊണ്ടിരുന്ന പ്രവൃത്തി ഏഴാം ദിവസം ദൈവം പൂർത്തിയാക്കി. താൻ ചെയ്തിരുന്ന സകല പ്രവൃത്തിയിൽനിന്നും ഏഴാം ദിവസം ദൈവം വിശ്രമിച്ചു."},{"v":3,"t":"ഏഴാം ദിവസത്തെ അനുഗ്രഹിച്ച് ദൈവം അതിനെ വിശുദ്ധീകരിച്ചു. എന്തെന്നാൽ, അന്നു താൻ ചെയ്തുകൊണ്ടിരുന്ന സകല സൃഷ്ടികർമ്മത്തിൽനിന്നും ദൈവം വിശ്രമിച്ചു."},{"v":4,"t":"ആകാശവും ഭൂമിയും സൃഷ്ടിക്കപ്പെട്ടപ്പോഴത്തെ അവയുടെ ഉല്പത്തിക്രമം ഇതായിരുന്നു."},{"h":"ഏദൻതോട്ടം"},{"v":4,"t":"ദൈവമായ കർത്താവ് ഭൂമിയും ആകാശവും സൃഷ്ടിച്ച നാളിൽ","p":1},{"v":5,"t":"ഭൂമിയിൽ കാട്ടുചെടികളൊന്നും അതുവരെ ഉണ്ടായിരുന്നില്ല. വയൽപ്പുല്ലുകളൊന്നും അതുവരെ മുളച്ചിരുന്നില്ല. കാരണം, ദൈവമായ കർത്താവ് ഭൂമിയിൽ മഴ പെയ്യിച്ചിരുന്നില്ല. മണ്ണിൽ അദ്ധ്വാനിക്കാൻ മനുഷ്യനും ഉണ്ടായിരുന്നില്ല."},{"v":6,"t":"എന്നാൽ, ഭൂമിയിൽനിന്ന് കോടമഞ്ഞ് ഉയർന്ന് ഭൂതലമെല്ലാം നനച്ചു."},{"v":7,"t":"ദൈവമായ കർത്താവ് പൂഴി മണ്ണുകൊണ്ട് മനുഷ്യനെ മെനയുകയും ജീവന്റെ ശ്വാസം അവന്റെ നാസാരന്ധ്രങ്ങളിലേക്ക് ഊതുകയും ചെയ്തു. അങ്ങനെ മനുഷ്യൻ ജീവനുള്ളവനായിത്തീർന്നു."},{"v":8,"t":"കിഴക്ക് ഏദനിൽ ദൈവമായ കർത്താവ് ഒരു തോട്ടം നട്ടുപിടിപ്പിക്കുകയും താൻ മെനഞ്ഞ മനുഷ്യനെ അവിടെ നിയോഗിക്കുകയും ചെയ്തു.","p":1},{"v":9,"t":"കാഴ്ചയ്ക്കു മനോഹരവും ഭക്ഷിക്കാൻ ഉപയുക്തവുമായ എല്ലാ വൃക്ഷങ്ങളും ദൈവമായ കർത്താവ് മണ്ണിൽനിന്നു മുളപ്പിച്ചു. തോട്ടത്തിന്റെ നടുവിൽ ജീവന്റെ വൃക്ഷവും നന്മതിന്മകളെക്കുറിച്ചുള്ള അറിവിന്റെ വൃക്ഷവും.","p":1},{"v":10,"t":"തോട്ടം നനയ്ക്കാൻ ഏദനിൽനിന്ന് ഒരു നദി പുറപ്പെട്ടു; അവിടെവെച്ച് അത് നാലു ശാഖകളായി പിരിഞ്ഞു."},{"v":11,"t":"ഒന്നാമത്തേതിന്റെ പേര് പീഷോൻ. അത് സ്വർണ്ണനിറമുള്ള ഹവിലാ മുഴുവൻ ചുറ്റി ഒഴുകുന്നു."},{"v":12,"t":"ആ നാട്ടിലെ സ്വർണ്ണം മേല്ത്തരമാണ്. അവിടെ സുഗന്ധദ്രവ്യങ്ങളും പവിഴക്കല്ലുകളുമുണ്ട്."},{"v":13,"t":"രണ്ടാമത്തെ നദിയുടെ പേര് ഗീഹോൻ. അത് കൂഷ്ദേശം മുഴുവൻ ചുറ്റി ഒഴുകുന്നു."},{"v":14,"t":"മൂന്നാമത്തെ നദിയുടെ പേര് ടൈഗ്രിസ്. അത് അസ്സീറിയായുടെ കിഴക്കുഭാഗത്തു കൂടെ ഒഴുകുന്നു. നാലാമത്തെ നദി യൂഫ്രട്ടീസ്."},{"v":15,"t":"ഏദൻതോട്ടത്തിൽ വേലചെയ്യാനും അതിനെ പരിരക്ഷിക്കാനുമായി ദൈവമായ കർത്താവ് മനുഷ്യനെ അവിടെ കൊണ്ടുപോയി പാർപ്പിച്ചു."},{"v":16,"t":"ദൈവമായ കർത്താവ് മനുഷ്യനോട് ഇങ്ങനെ കല്പിച്ചു: തോട്ടത്തിലെ ഏതു വൃക്ഷത്തിൽനിന്നും നിനക്ക് യഥേഷ്ടം ഭക്ഷിക്കാം."},{"v":17,"t":"എന്നാൽ, നന്മതിന്മകളുടെ അറിവിന്റെ വൃക്ഷത്തിൽനിന്നും നീ ഭക്ഷിക്കരുത്; കാരണം, അതിൽനിന്നു ഭക്ഷിക്കുന്ന ദിവസം നീ തീർച്ചയായും മരിക്കും."},{"v":18,"t":"ദൈവമായ കർത്താവ് അരുളിച്ചെയ്തു: മനുഷ്യൻ ഏകനായിരിക്കുന്നത് നന്നല്ല. അവനുചേർന്ന തുണയെ ഞാൻ അവനുവേണ്ടി സൃഷ്ടിക്കും."},{"v":19,"t":"ദൈവമായ കർത്താവ് കയ്യിലെ സകലമൃഗങ്ങളെയും ആകാശത്തിലെ സകല പക്ഷികളെയും മണ്ണിൽനിന്നു മെനഞ്ഞെടുത്തു; മനുഷ്യൻ എന്തു വിളിക്കുമെന്നു കാണാൻ അവയെ അവന്റെയടുക്കൽ കൊണ്ടുവന്നു. മനുഷ്യൻ ഓരോ ജീവിയെയും എന്തു വിളിച്ചോ, അത് അതിന്റെ പേരായി."},{"v":20,"t":"എല്ലാ കന്നുകാലികൾക്കും ആകാശത്തിലെ പക്ഷികൾക്കും കരയിലെ മൃഗങ്ങൾക്കും മനുഷ്യൻ പേരുനല്കി. എന്നാൽ, തനിക്കു ചേർന്ന തുണയെ മനുഷ്യൻ കണ്ടില്ല."},{"v":21,"t":"അതുകൊണ്ട്, ദൈവമായ കർത്താവ് മനുഷ്യനിൽ ഗാഢനിദ്ര വരുത്തി; അവൻ ഉറങ്ങി. അനന്തരം അവിടെനിന്ന് അവന്റെ വാരിയെല്ലുകളിൽ ഒന്നെടുത്ത് ആവിടം മാംസംകൊണ്ടു മൂടി."},{"v":22,"t":"മനുഷ്യനിൽനിന്നെടുത്ത വാരിയെല്ലുകൊണ്ടു ദൈവമായ കർത്താവ് ഒരു സ്ത്രീയെ രൂപപ്പെടുത്തി. അവളെ മനുഷ്യന്റെ അടുക്കൽ കൊണ്ടുവന്നു."},{"v":23,"t":"അപ്പോൾ മനുഷ്യൻ പറഞ്ഞു: ഒടുവിൽ ഇതാ! ഇവളാണ് എന്റെ അസ്ഥികളിൽനിന്നുള്ള അസ്ഥിയും മാംസത്തിൽനിന്നുള്ള മാംസവും! ഇവൾ നാരിഎന്നു വിളിക്കപ്പെടും; എന്തെന്നാൽ, നരനിൽനിന്നു ഇവൾ എടുക്കപ്പെട്ടു.","p":1},{"v":24,"t":"അതിനാൽ, പുരുഷൻ തന്റെ പിതാവിനെയും മാതാവിനെയും വിട്ടു തന്റെ ഭാര്യയുമായി സംയോജിക്കുകയും അവർ ഏകശരീരമായിത്തീരുകയും ചെയ്യും.","p":1},{"v":25,"t":"അവരിരുവരും, മനുഷ്യനും അവന്റെ സ്ത്രീയും, നഗ്നരായി രുന്നു; എന്നാൽ അവർക്കു ലജ്ജതോന്നിയിരുന്നില്ല."}],"3":[{"h":"മനുഷ്യന്റെ പതനം"},{"v":1,"t":"ദൈവമായ കർത്താവ് ഉരുവാക്കിയ എല്ലാ വന്യജീവികളിലുംവെച്ച് കൗശലമേറിയതായിരുന്നു സർപ്പം. അതു സ്ത്രീയോടു ചോദിച്ചു: തോട്ടത്തിലെ ഒരു വൃക്ഷത്തിൽ നിന്നും ഭക്ഷിക്കരുതെന്ന് ദൈവം വാസ്തവത്തിൽ പറഞ്ഞിട്ടുണ്ടോ?","p":1},{"v":2,"t":"സ്ത്രീ സർപ്പത്തോടു പറഞ്ഞു: തോട്ടത്തിലെ വൃക്ഷങ്ങളുടെ ഫലങ്ങൾ ഞങ്ങൾക്കു ഭക്ഷിക്കാം.","p":1},{"v":3,"t":"എന്നാൽ, 'നിങ്ങൾ മരിക്കാതിരിക്കാൻ തോട്ടത്തിന്റെ നടുവിലുള്ള വൃക്ഷത്തിന്റെ ഫലത്തിൽനിന്നു ഭക്ഷിക്കരുത്; അതിൽ തൊടുകയുമരുത്' എന്നു ദൈവം പറഞ്ഞിട്ടുണ്ട്.","p":1},{"v":4,"t":"സർപ്പം സ്ത്രീയോടു പറഞ്ഞു: നിങ്ങൾ തീർച്ചയായും മരിക്കുകയില്ല.","p":1},{"v":5,"t":"കാരണം, അതിൽനിന്നു തിന്നുന്ന ദിവസം നിങ്ങളുടെ കണ്ണുകൾ തുറക്കുമെന്നും നന്മയും തിന്മയും അറിയുന്നവരായി നിങ്ങൾ ദൈവത്തെപ്പോലെ ആകുമെന്നും ദൈവത്തിന് അറിയാം.","p":1},{"v":6,"t":"ആ വൃക്ഷം ഭക്ഷിക്കാൻ ഉപയുക്തവും കണ്ണുകൾക്ക് ആകർഷകവുമാണെന്ന് സ്ത്രീ കണ്ടു. ആ വൃക്ഷം അറിവുണ്ടാക്കാൻ പര്യാപ്തവുമായിരുന്നു. അവൾ അതിന്റെ ഫലത്തിൽനിന്നു എടുത്തു ഭക്ഷിച്ചു; തന്നോടൊപ്പം ഇരുന്ന ഭർത്താവിനും അവൾ നൽകി; അവനും ഭക്ഷിച്ചു.","p":1},{"v":7,"t":"അപ്പോൾ ഇരുവരുടെയും കണ്ണുകൾ തുറക്കപ്പെട്ടു; തങ്ങൾ നഗ്നരാണെന്ന് അവർ അറിഞ്ഞു. അവർ അത്തിയിലകൾ കൂട്ടിച്ചേർത്തു തങ്ങൾക്കായി അരപ്പട്ടയുണ്ടാക്കി.","p":1},{"v":8,"t":"സായാഹ്നനേരത്ത് തോട്ടത്തിൽ ഉലാത്തുന്ന ദൈവമായ കർത്താവിന്റെ ശബ്ദം അവർ കേട്ടു. മനുഷ്യനും അവന്റെ ഭാര്യയും ദൈവമായ കർത്താവിന്റെ സന്നിധിയിൽനിന്ന് തോട്ടത്തിലെ മരങ്ങൾക്കിടയിലൊളിച്ചു.","p":1},{"v":9,"t":"ദൈവമായ കർത്താവ് മനുഷ്യനെ വിളിച്ച് അവനോടു ചോദിച്ചു: നീ എവിടെയാണ്?","p":1},{"v":10,"t":"അവൻ മറുപടി പറഞ്ഞു: തോട്ടത്തിൽ അവിടത്തെ ശബ്ദം ഞാൻ കേട്ടു. ഞാൻ നഗ്നനായിരുന്നതിനാൽ ഭയപ്പെട്ടുപോയി, അതുകൊണ്ട് ഞാൻ ഒളിച്ചതാണ്.","p":1},{"v":11,"t":"അവിടുന്ന് ചോദിച്ചു: നീ നഗ്നനാണെന്ന് ആരാണ് നിന്നോടു പറഞ്ഞത്? ഭക്ഷിക്കരുതെന്ന് ഞാൻ നിന്നോടു കല്പിച്ച വൃക്ഷത്തിൽനിന്ന് നീ ഭക്ഷിച്ചുവോ?","p":1},{"v":12,"t":"മനുഷ്യൻ പറഞ്ഞു: അങ്ങേ എനിക്കു കൂട്ടിനു തന്ന സ്ത്രീ; അവളാണ് വൃക്ഷത്തിൽനിന്നുള്ള ഫലം എനിക്കു നൽകിയത്. ഞാൻ അതു ഭക്ഷിക്കുകയും ചെയ്തു.","p":1},{"v":13,"t":"ദൈവമായ കർത്താവ് സ്ത്രീയോടു ചോദിച്ചു: നീ എന്താണ് ഈ ചെയ്തത്? സ്ത്രീ പറഞ്ഞു: സർപ്പം എന്നെ വഞ്ചിച്ചു; ഞാൻ ഭക്ഷിക്കുകയും ചെയ്തു.","p":1},{"h":"ശിക്ഷയും വാഗ്ദാനവും"},{"v":14,"t":"ദൈവമായ കർത്താവ് സർപ്പത്തോടു പറഞ്ഞു: ഇതു നീ ചെയ്തതുകൊണ്ട് എല്ലാ കന്നുകാലികളിലും കാട്ടുമൃഗങ്ങളിലുംവെച്ച് നീ ശപിക്കപ്പെട്ടവനായിരിക്കും. നീ ഉരസ്സുകൊണ്ട് ഇഴഞ്ഞുനടക്കും, നിന്റെ ജീവിതകാലമത്രയും പൊടിതിന്നും!","p":1},{"v":15,"t":"നീയും സ്ത്രീയും തമ്മിലും നിന്റെ സന്തതിയും അവളുടെ സന്തതിയും തമ്മിലും ഞാൻ ശത്രുത ഉളവാക്കും. അവൻ നിന്റെ തല തകർക്കും, നീ അവന്റെ കുതികാലിൽ ദംശിക്കുകയും ചെയ്യും.","p":1},{"v":16,"t":"അവിടുന്ന് സ്ത്രീയോടു പറഞ്ഞു: നിന്റെ ഗർഭാവസ്ഥകൾ ഞാൻ തീർച്ചയായും വർധിപ്പിക്കും. നീ വേദനയോടെ മക്കളെ പ്രസവിക്കും. എന്നാലും നിന്റെ അഭിലാഷം നിന്റെ ഭർത്താവിലായിരിക്കും, അവൻ നിന്നെ ഭരിക്കുകയും ചെയ്യും.","p":1},{"v":17,"t":"ആദത്തോട് അവിടന്നു പറഞ്ഞു: നീ നിന്റെ ഭാര്യയുടെ സ്വരം കേൾക്കുകയും തിന്നരുതെന്ന് ഞാൻ കല്പിച്ചിരുന്ന മരത്തിൽനിന്ന് തിന്നുകയും ചെയ്തതു കൊണ്ട് നീ മൂലം മണ്ണ് ശപിക്കപ്പെട്ടതായിരിക്കും. നിന്റെ ആയുഷ്കാലം മുഴുവൻ അധ്വാനംകൊണ്ട് നീ അതിൽനിന്നു ഭക്ഷിക്കും.","p":1},{"v":18,"t":"അത് മുള്ളും മുൾച്ചെടികളും നിനക്കായിമുളപ്പിക്കും. നീ വയൽച്ചെടികൾ ഭക്ഷിക്കും.","p":1},{"v":19,"t":"നീ മണ്ണിൽനിന്ന് എടുക്കപ്പെട്ടതുകൊണ്ട്അതിലേക്കു മടങ്ങുന്നതുവരെ നിന്റെ നെറ്റിയിലെ വിയർപ്പുകൊണ്ട് നീ അപ്പം ഭക്ഷിക്കും. എന്തെന്നാൽ, നീ പൊടിയാണ്; പൊടിയിലേക്കുതന്നെ നീ മടങ്ങും.","p":1},{"v":20,"t":"മനുഷ്യൻ തന്റെ ഭാര്യയെ ഹവ്വാ എന്നു പേരുവിളിച്ചു. കാരണം. അവൾ ജീവനുള്ള എല്ലാറ്റിന്റെയും മാതാവാണ്.","p":1},{"v":21,"t":"ദൈവമായ കർത്താവ് ആദത്തിനും അവന്റെ ഭാര്യയ്ക്കും തോലുകൊണ്ട് ഉടുപ്പുണ്ടാക്കി, അവരെ ധരിപ്പിച്ചു.","p":1},{"v":22,"t":"അനന്തരം ദൈവമായ കർത്താവ് പറഞ്ഞു: മനുഷ്യൻ ഇതാ, നന്മയും തിന്മയും അറിഞ്ഞ് നമ്മിലൊരുവനെപ്പോലെ ആയിരിക്കുന്നു. ഇനി അവൻ കൈ നീട്ടി ജീവന്റെ വൃക്ഷത്തിൽ നിന്നുകൂടി പറിച്ചു തിന്ന്നിത്യം ജീവിക്കുന്നവനാകാൻ ഇടയാകരുത്.","p":1},{"v":23,"t":"എവിടെനിന്ന് അവൻ എടുക്കപ്പെട്ടുവോ, ആ മണ്ണിൽ അധ്വാനിക്കേണ്ടതിന് ദൈവമായ കർത്താവ് അവനെ ഏദൻതോട്ടത്തിൽനിന്നു പുറത്താക്കി.","p":1},{"v":24,"t":"മനുഷ്യനെ പുറത്താക്കിയശേഷം ജീവവൃക്ഷത്തിന്റെ വഴി കാക്കാൻ അവിടന്ന് കെരൂബുകളെ, എല്ലാ വശത്തേക്കുംകറങ്ങുന്നതും തീ ജ്വലിക്കുന്നതുമായ വാളുമായി ഏദൻതോട്ടത്തിനു മുമ്പിൽ കാവൽ നിറുത്തി.","p":1}],"4":[{"h":"കായേനും ആബേലും"},{"v":1,"t":"മനുഷ്യൻ തന്റെ ഭാര്യയായ ഹവ്വായെ അറിഞ്ഞു അവൾ ഗർഭംധരിച്ച് കായേനെ പ്രസവിച്ചു. അവൾ പറഞ്ഞും കർത്താവിന്റെ സഹായത്താൽ ഞാനൊരു ആൺകുഞ്ഞിനെ നേടിയിരിക്കുന്നു.","p":1},{"v":2,"t":"തുടർന്ന് അവൾ അവന്റെ സഹോദരൻ ആബേലിനെ പ്രസവിച്ചു. ആബേൽ ആടുകളെ മേയിക്കുന്നവനും കായേൻ മണ്ണിൽ അധ്വാനിക്കുന്നവനുമായിരുന്നു.","p":1},{"v":3,"t":"യഥാകാലം കായേൻ ഭൂമിയിൽ നിന്നുള്ള വിളവിന്റെ ഒരു ഭാഗം കർത്താവിനു കാണിക്കയായി കൊണ്ടുവന്നു.","p":1},{"v":4,"t":"ആബേലും തന്റെ ആട്ടിൻ കൂട്ടത്തിലെ ചില കടിഞ്ഞൂലുകളെയും അവയുടെ കൊഴുപ്പിന്റെ ഒരു ഭാഗവും കൊണ്ടുവന്നു. ആബേലിലും അവന്റെ കാണിക്കയിലും കർത്താവു പ്രസാദിച്ചു.","p":1},{"v":5,"t":"എന്നാൽ കായേനിലും അവന്റെ കാണിക്കയിലും അവിടന്നു പ്രസാദിച്ചില്ല. അതിനാൽ കായേൽ അത്യധികം കുപിതനായി. അവന്റെ മുഖം താണു.","p":1},{"v":6,"t":"കർത്താവു കായേനോടു ചോദിച്ചു: നീ കോപിച്ചിരിക്കുന്നതെന്തുകൊണ്ട്? നിന്റെ മുഖം താണിരിക്കുന്നതെന്തുകൊണ്ട്?","p":1},{"v":7,"t":"അത് ഉയർത്താൻ തക്ക വിധം നന്നായി വർത്തിച്ചിരുന്നെങ്കിൽ! നീ നല്ലതു ചെയ്യുന്നില്ലെങ്കിൽ വാതില്ക്കൽത്തന്നെ പാപം പതിയിരിക്കുന്നു. അതിന്റെ അഭിലാഷം നിന്നിലാണ്. പക്ഷേ, നീ അതിനെ കീഴടക്കേണ്ടിയിരിക്കുന്നു.","p":1},{"v":8,"t":"കായേൻ തന്റെ സഹോദരനായ ആബേലിനോട് കയർത്തു. അനന്തരം അവർ വയലിലായിരിക്കേ കായേൻ ആബേലിനെതിരേ ചെന്ന് അവനെ കൊന്നു.","p":1},{"v":9,"t":"കർത്താവ് കായേനോടു ചോദിച്ചു: നിന്റെ സഹോദരൻ ആബേൽ എവിടെ? അവൻ പറഞ്ഞു. എനിക്കറിഞ്ഞുകൂടാ. ഞാനാണോ എന്റെ സഹോദരന്റെ കാവല്ക്കാരൻ?","p":1},{"v":10,"t":"എന്നാൽ അവിടന്നു ചോദിച്ചു നീ എന്താണു ചെയ്തത്? നിന്റെ സഹോദരന്റെ രക്തം മണ്ണിൽ നിന്ന് എന്റെ നേർക്കു മുറവിളികൂട്ടുന്നതിന്റെ സ്വരം!","p":1},{"v":11,"t":"നിന്റെ കൈയിൽനിന്ന് നിന്റെ സഹോദരന്റെ രക്തം സ്വീകരിക്കാൻ വായ്പിളർന്ന നിലത്താൽ ഇപ്പോൾ നീ ശപിക്കപ്പെട്ടവനായിരിക്കും.","p":1},{"v":12,"t":"നീ നിലം കൃഷി ചെയ്യുമ്പോൾ ഇനിമുതൽ അത് അതിന്റെ വിള നിനക്കു തരുകയില്ല. നീ ഭൂമിയിൽ അസ്ഥിരനും അലയുന്നവനുമായിരിക്കും.","p":1},{"v":13,"t":"കായേൻ കർത്താവിനോടു പറഞ്ഞു: എനിക്കു വഹിക്കാവുന്നതിലും വലുതാണ് എന്റെ ശിക്ഷ.","p":1},{"v":14,"t":"ഇന്ന് ഇതാ അവിടന്ന് എന്നെ ഈ മണ്ണിൽനിന്ന് ആട്ടിപ്പായിച്ചിരിക്കുന്നു. അവിടത്തെ സന്നിധിയിൽനിന്ന് ഞാൻ സ്വയം ഒളിക്കേണ്ടിയിരിക്കുന്നു. ഞാൻ ഭൂമിയിൽ അസ്ഥിരനും അലയുന്നവനുമായിരിക്കും എന്നെ കണ്ടുമുട്ടുന്ന ആരും എന്നെ കൊല്ലും.","p":1},{"v":15,"t":"കർത്താവ് അവനോടു പറഞ്ഞു. അങ്ങനെയെങ്കിൽ കായനെ കൊല്ലുന്ന ആരുടെമേലും ഏഴ് ഇരട്ടിയായി പ്രതികാരം ചെയ്യപ്പെടും അവനെ കണ്ടുമുട്ടുന്നവർ ആരും അവനെ കൊല്ലാതിരിക്കേണ്ടതിന് കർത്താവ് കായേന്റെ മേൽ ഒരു അടയാളം പതിച്ചു.","p":1},{"v":16,"t":"കായേൻ കർത്താവിൻറെ സന്നിധി വിട്ട് ഏദനു കിഴക്ക് നോദ് ദേശത്ത് വാസമുറപ്പിച്ചു .","p":1},{"h":"കായേന്റെ സന്തതിപരമ്പര"},{"v":17,"t":"കായേൻ തന്റെ ഭാര്യയെ അറിഞ്ഞു. അവൾ ഗർഭം ധരിച്ചു ഹെനോക്കിനെ പ്രസവിച്ചു. അവൻ ഒരു പട്ടണം പണിയുന്നുണ്ടായിരുന്നു. തന്റെ പുത്രന്റെ പേരനുസരിച്ച് ആ പട്ടണത്തിന് അവൻ ഹെനോക്ക് എന്നു പേരിട്ടു.","p":1},{"v":18,"t":"ഹെനോക്കിന് ഈരാദ് ജനിച്ചു; ഈരാദിന് മെഹൂയാവേലിനെ ജനിപ്പിച്ചു; മെഹൂയാവേൽ മെഥൂശായേലിനെ ജനിപ്പിച്ചു. മെഥൂശായേൽ ലാമേക്കിനെ ജനിപ്പിച്ചു.","p":1},{"v":19,"t":"ലാമേക് രണ്ടു സ്ത്രീകളെ ഭാര്യമാരായി സ്വീകരിച്ചു. ഒന്നാമത്തവളുടെ പേര് ആദാ; രണ്ടാമത്തവളുടെ പേര് സില്ലാ.","p":1},{"v":20,"t":"ആദാ യാബാലിനെ പ്രസവിച്ചു. അവൻ ആടുമാടുകളോടൊപ്പം കൂടാരത്തിൽ വസിക്കുന്നവരുടെ പിതാവായിരുന്നു.","p":1},{"v":21,"t":"അവന്റെ സഹോദരന്റെ പേര് യൂബാൽ. കിന്നരവും വേണുവും വായിക്കുന്നവരുടെ പൂർവ്വിതാവായിരുന്നു അവൻ.","p":1},{"v":22,"t":"സില്ലായും പ്രസവിച്ചു, തൂബൽക്കയീനെ. അവൻ ചെമ്പുകൊണ്ടും ഇരുമ്പുകൊണ്ടും എല്ലാത്തരം ഉപകരണങ്ങളും നിർമ്മിക്കുന്നവനായിരുന്നു. തൂബൽക്കയീന്റെ സഹോദരി നാമാ ആയിരുന്നു.","p":1},{"v":23,"t":"ലാമേക് തന്റെ ഭാര്യമാരോടു പറഞ്ഞു: ആദാ, സില്ലാ, എന്റെ സ്വരം കേൾക്കുവിൻ! ലാമേക്കിന്റെ ഭാര്യമാരേ, എന്റെ ഈ വാക്കിനു ചെവിതരുവിൻ: എന്നെ മുറിവേല്പിച്ചതിന് ഒരുവനെ ഞാൻ കൊന്നു; എന്നെ അടിച്ചതിന് ഒരു കുട്ടിയെയും.","p":1},{"v":24,"t":"എന്തെന്നാൽ, കായേന്റെ പ്രതികാരം ഏഴിരട്ടിയെങ്കിൽ ലാമേക്കിന്റെ എഴുപത്തേഴ് ഇരട്ടിയായിരിക്കും.","p":1},{"v":25,"t":"ആദം വീണ്ടും തന്റെ ഭാര്യയെ അറിഞ്ഞു. അവൾ ഒരു പുത്രനു ജന്മം നൽകി. കായേൻ ആബേലിനെ വധിച്ചിരുന്നതുകൊണ്ട്, അവനുപകരം ദൈവം എനിക്ക് മറ്റൊരു സന്താനത്തെ നൽകി എന്ന അർത്ഥത്തിൽ അവൾ അവന് സേത്ത് എന്നു പേരിട്ടു.","p":1},{"v":26,"t":"സേത്തിനും ഒരു പുത്രൻ ജനിച്ചു. അയാൾ അവന് എനോശ് എന്നു പേരിട്ടു. അക്കാലത്താണ് കർത്താവിന്റെ നാമം വിളിച്ചപേക്ഷിക്കാൻ തുടങ്ങിയത്.","p":1}],"5":[{"h":"ആദം മുതൽ നോഹവരെ"},{"v":1,"t":"ആദത്തിന്റെ വംശാവലിഗ്രന്ഥമാണിത്: ദൈവം മനുഷ്യനെ സൃഷ്ടിച്ച ദിവസം തന്റെ സാദൃശ്യത്തിൽ ദൈവം അവനെ രൂപപ്പെടുത്തി.","p":1},{"v":2,"t":"ആണും പെണ്ണുമായി അവരെ അവിടുന്ന് സൃഷ്ടിച്ചു; അവിടുന്ന് അവരെ അനുഗ്രഹിച്ചു. അവർ സൃഷ്ടിക്കപ്പെട്ട ദിവസം മനുഷ്യൻ എന്ന് അവിടുന്ന് അവരെ പേർവിളിച്ചു.","p":1},{"v":3,"t":"നൂറ്റിമുപ്പതു വയസ്സായപ്പോൾ ആദം തന്റെ ഛായയിലും സാദൃശ്യത്തിലും ഒരു പുത്രനെ ജനിപ്പിച്ചു; അവൻ സേത്ത് എന്നു പേരിട്ടു.","p":1},{"v":4,"t":"സേത്തിനെ ജനിപ്പിച്ചശേഷം ആദത്തിന്റെ ആയുസ്സ് എണ്ണൂറു വർഷമായിരുന്നു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":5,"t":"ആദത്തിന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തി മുപ്പതു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു."},{"v":6,"t":"നൂറ്റഞ്ചു വയസ്സായപ്പോൾ സേത്ത് എനോഷിനെ ജനിപ്പിച്ചു.","p":1},{"v":7,"t":"എനോഷിനെ ജനിപ്പിച്ചശേഷം സേത്ത് എണ്ണൂറ്റി ഏഴു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":8,"t":"സേത്തിന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തിപ്പന്ത്രണ്ടു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":9,"t":"തൊണ്ണൂറു വയസ്സായപ്പോൾ എനോഷ് കെയ്‌നാനെ ജനിപ്പിച്ചു.","p":1},{"v":10,"t":"കെയ്‌നാനെ ജനിപ്പിച്ചശേഷം എനോഷ് എണ്ണൂറ്റിപ്പതിനഞ്ചു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":11,"t":"എനോഷിൻ്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തി അഞ്ചു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു."},{"v":12,"t":"എഴുപതു വയസ്സായപ്പോൾ കെയ്‌നാൻ മഹലലേലിനെ ജനിപ്പിച്ചു.","p":1},{"v":13,"t":"മഹലലേലിനെ ജനിപ്പിച്ചശേഷം കെയ്‌നാൻ എണ്ണൂറ്റിപ്പത്തു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":14,"t":"കെയ്‌നാന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തിപ്പത്തു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":15,"t":"അറുപത്തഞ്ചു വയസ്സായപ്പോൾ മഹലലേൽ യാരെദിനെ ജനിപ്പിച്ചു.","p":1},{"v":16,"t":"യാരെദിനെ ജനിപ്പിച്ചശേഷം മഹലലേൽ എണ്ണൂറ്റിമുപ്പതു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":17,"t":"മഹലലേലിന്റെ ആകെ ജീവിതായുസ്സ് എണ്ണൂറ്റി തൊണ്ണൂറ്റി അഞ്ചു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":18,"t":"നൂറ്റിയറുപത്തിരണ്ടു വയസ്സായപ്പോൾ യാരെദ് ഹെനോക്കിനെ ജനിപ്പിച്ചു.","p":1},{"v":19,"t":"ഹെനോക്കിനെ ജനിപ്പിച്ച ശേഷം യാരെദ് എണ്ണൂറു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":20,"t":"യാരെദിന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തി അറുപത്തിരണ്ടു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":21,"t":"അറുപത്തഞ്ചു വയസ്സായപ്പോൾ ഹെനോക്ക് മെത്തുശെലഹിനെ ജനിപ്പിച്ചു.","p":1},{"v":22,"t":"മെത്തുശെലഹിനെ ജനിപ്പിച്ചശേഷം ഹെനോക്ക് മുന്നൂറു വർഷം ദൈവത്തോടൊപ്പം വ്യാപരിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":23,"t":"ഹെനോക്കിന്റെ ആകെ ജീവിതായുസ്സ് മുന്നൂറ്റി അറുപത്തഞ്ചു വർഷമായിരുന്നു.","p":1},{"v":24,"t":"ഹെനോക്ക് ദൈവത്തോടൊപ്പം വ്യാപരിച്ചു. പിന്നെ അവൻ കാണപ്പെട്ടില്ല. കാരണം, ദൈവം അവനെ എടുത്തു.","p":1},{"v":25,"t":"നൂറ്റിയെൺപത്തേഴു വയസ്സായപ്പോൾ മെത്തുശെലഹ് ലാമെക്കിനെ ജനിപ്പിച്ചു.","p":1},{"v":26,"t":"ലാമെക്കിനെ ജനിപ്പിച്ചശേഷം മെത്തുശെലഹ് എഴുനൂറ്റിഎൺപത്തിരണ്ടു വർഷം ജീവിച്ചു. മെത്തുശെലഹ് പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":27,"t":"മെത്തുശെലഹിന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തി അറുപത്തൊമ്പതു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":28,"t":"നൂറ്റിയെൺപത്തിരണ്ടു വയസ്സായപ്പോൾ ലാമെക്ക് ഒരു പുത്രനെ ജനിപ്പിച്ചു.","p":1},{"v":29,"t":"കർത്താവു ശപിച്ച മണ്ണുമുഖാന്തരമുള്ള നമ്മുടെ അധ്വാനത്തിൽനിന്നും കൈകളുടെ ക്ലേശത്തിൽനിന്നും ഇവൻ നമ്മെ ആശ്വസിപ്പിക്കും എന്നു പറഞ്ഞ് അവൻ നോഹ എന്നു പേരിട്ടു.","p":1},{"v":30,"t":"നോഹയെ ജനിപ്പിച്ചശേഷം ലാമെക്ക് അഞ്ഞൂറ്റി തൊണ്ണൂറ്റഞ്ചു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":31,"t":"ലാമെക്കിന്റെ ആകെ ജീവിതായുസ്സ് എഴുനൂറ്റി എഴുപത്തിയേഴു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":32,"t":"നോഹയ്ക്ക് അഞ്ഞൂറു വയസ്സു തികഞ്ഞു. നോഹ ഷേമിനെയും ഹാമിനെയും യാഫെത്തിനെയും ജനിപ്പിച്ചു.","p":1}],"6":[{"h":"തിന്മ വർദ്ധിക്കുന്നു"},{"v":1,"t":"മനുഷ്യൻ ഭൂമിയിൽ പെരുകാൻ തുടങ്ങുകയും അവർക്ക് പുത്രിമാർ ജനിക്കയും ചെയ്തപ്പോൾ","p":1},{"v":2,"t":"മനുഷ്യപുത്രിമാർ അഴകുള്ളവരാണെന്ന് ദൈവപുത്രന്മാർ കണ്ടു. തങ്ങൾ തിരഞ്ഞെടുത്ത എല്ലാവരിൽനിന്നും അവർ തങ്ങൾക്കായി ഭാര്യമാരെ സ്വീകരിച്ചു."},{"v":3,"t":"അപ്പോൾ കർത്താവു പറഞ്ഞു: എന്റെ ചൈതന്യം മനുഷ്യനിൽ എന്നേക്കും നിലനിൽക്കുകയില്ല. കാരണം, അവൻ ജഡംകൂടിയാണ്. അവന്റെ ആയുസ്സ് ഇനിമേൽ നൂറ്റിയിരുപതു വർഷമായിരിക്കും.","p":1},{"v":4,"t":"ദൈവകുമാരന്മാർ മനുഷ്യപുത്രിമാരെ പ്രാപിക്കുകയും അവർക്ക് മക്കൾ ജനിക്കയും ചെയ്തിരുന്ന ആ കാലഘട്ടവും അതിനുശേഷവും ഭൂമിയിൽ നെഫിലുകൾ ഉണ്ടായി. അവരാണ് പുരാതനകാലത്തെ പേരുകേട്ട യുദ്ധവീരന്മാർ.","p":1},{"v":5,"t":"ഭൂമിയിൽ മനുഷ്യന്റെ ദുഷ്ടത വലുതാണെന്നും അവന്റെ ഹൃദയത്തിലെ ചിന്തകളുടെ ഓരോ രൂപവും എപ്പോഴും ദുഷ്ടത മാത്രമാണെന്നും കർത്താവു കണ്ടു.","p":1},{"v":6,"t":"ഭൂമിയിൽ മനുഷ്യനെ രൂപപ്പെടുത്തിയതിൽ കർത്താവു പരിതപിച്ചു; അവിടത്തെ ഹൃദയം നൊന്തു.","p":1},{"v":7,"t":"കർത്താവു അരുളിച്ചെയ്തു: ഞാൻ സൃഷ്ടിച്ച മനുഷ്യനെ ഭൂമുഖത്തുനിന്നു ഞാൻ തുടച്ചുമാറ്റും. മനുഷ്യൻ മുതൽ മൃഗങ്ങളും ഇഴജന്തുക്കളും ആകാശത്തിലെ പറവകളും വരെ തുടച്ചുമാറ്റും. എന്തെന്നാൽ, അവയെ സൃഷ്ടിച്ചതിൽ ഞാൻ പരിതപിക്കുന്നു.","p":1},{"v":8,"t":"എന്നാൽ, നോഹ കർത്താവിന്റെ ദൃഷ്ടിയിൽ പ്രീതി കണ്ടെത്തി.","p":1},{"v":9,"t":"ഇതാണ് നോഹയുടെ വംശാവലി: നോഹ നീതിമാനായിരുന്നു; തന്റെ തലമുറയിലെ പൂർണ്ണനായ മനുഷ്യൻ. ദൈവത്തോടൊപ്പം നോഹ വ്യാപരിച്ചു.","p":1},{"v":10,"t":"നോഹ മൂന്നു പുത്രന്മാരെ ജനിപ്പിച്ചു: ഷേം, ഹാം, യാഫെത്ത്.","p":1},{"v":11,"t":"ദൈവത്തിന്റെ മുമ്പാകെ ഭൂമി ദുഷിച്ചതായിത്തീർന്നു. ഭൂമി അക്രമംകൊണ്ടു നിറഞ്ഞു.","p":1},{"v":12,"t":"ദൈവം ഭൂമിയെ നോക്കി. ഇതാ, അത് ദുഷിച്ചതായിരിക്കുന്നു. കാരണം, എല്ലാ മനുഷ്യരും ഭൂമിയിലെ തങ്ങളുടെ മാർഗ്ഗങ്ങൾ ദുഷിപ്പിച്ചു കളഞ്ഞു.","p":1},{"h":"നോഹയുടെ പെട്ടകം"},{"v":13,"t":"ദൈവം നോഹയോട് അരുളിച്ചെയ്തു: എന്റെ മുമ്പിൽ മനുഷ്യരുടെയെല്ലാം അവസാനം അടുത്തു. കാരണം, അവർമൂലം ഭൂമി അക്രമംകൊണ്ടു നിറഞ്ഞിരിക്കുന്നു. ഇതാ, ഞാൻ അവരെ ഭൂമിയോടൊപ്പം നശിപ്പിക്കും .","p":1},{"v":14,"t":"ഗോഫർമരംകൊണ്ട് നീ ഒരു പെട്ടകം ഉണ്ടാക്കണം. അതിൽ മുറികൾ തിരിക്കുക. അതിന്റെ അകത്തും പുറത്തും കീലുതേയ്കണം."},{"v":15,"t":"ഇങ്ങനെയാണ് അതു ചെയ്യേണ്ടത്. പെട്ടകത്തിനു മൂന്നുറു മുഴം നീളവും അമ്പതു മുഴം വീതിയും മുപ്പതു മുഴം ഉയരവും.","p":1},{"v":16,"t":"പെട്ടകത്തിന് നീ ഒരു മേൽക്കൂര യുണ്ടാക്കണം മേൽക്കൂരയിൽ നിന്ന് ഒരു മുഴം താഴെ പെട്ടകത്തിന് ഒരു ജനലും വശത്ത് ഒരു വാതിലും വയ്ക്കണം കീഴ്ത്തട്ടും രണ്ടാംതട്ടും മൂന്നാംതട്ടുമായി വേണം നീ പണിയാൻ.","p":1},{"v":17,"t":"ഇതാ, ഞാൻ ആകാശത്തിൻ കീഴിൽ ജീവശ്വാസമുള്ള എല്ലാ ശരീരി കളെയും നശിപ്പിക്കാൻ ഭൂമിയിലേക്ക് ജലപ്രളയം കൊണ്ടുവരും. ഭൂമിയിലുള്ളതെല്ലാം നശിക്കും.","p":1},{"v":18,"t":"എന്നാൽ നീയുമായി ഞാൻ എൻ്റെ ഉടമ്പടി ഉറപ്പിക്കും. നീ പെട്ടകത്തിലേക്കു കടക്കണം, നീയും നിന്നോടൊപ്പം നിൻ്റെ പുത്രന്മാരും നിൻ്റെ ഭാര്യയും നിൻ്റെ പുത്രന്മാരുടെ ഭാര്യമാരും നിന്നോടൊപ്പം ജീവൻ നിലനിർത്തേണ്ടതിന് പെട്ടകത്തിലേക്ക് എല്ലാറ്റിലും നിന്ന് - എല്ലാ ജീവികളിലും ശരീരികളിൽ നിന്ന് - ആണും പെണ്ണുമായി ഓരോ ജോഡി കൊണ്ടുവരണം. ജീവൻ നിലനിർത്തേണ്ടതിന് എല്ലാറ്റിറ്റും നിന്ന് പക്ഷികൾ, മൃഗങ്ങൾ എന്നിവയിൽനിന്ന് ഇനംതിരിഞ്ഞ്, ഭൂമിയിൽ ഇഴയുന്ന സകലതിലും നിന്ന് ഇനം തിരിഞ്ഞ് ഓരോ ജോഡി നിൻ്റെ പക്കലേക്ക് വരട്ടെ. നീയാകട്ടെ, ഭക്ഷ്യയോഗ്യമായ എല്ലാ ആഹാര പദാർത്ഥങ്ങളിൽ നിന്നും എടുത്ത് നിൻ്റെ പക്കൽ ശേഖരിക്കണം. അവ നിനക്കും അവർക്കുമുള്ള ഭക്ഷണമായിരിക്കും. ദൈവം തന്നോടു കൽപ്പിച്ചതെല്ലാം നോഹ ചെയ്തു; അപ്രകാരം തന്നെ അവൻ ചെയ്തു.","p":1}],"7":[{"h":"പെട്ടകപ്രവേശം"},{"v":1,"t":"കർത്താവ് നോഹയോട് അരുൾച്ചെയ്തു: നീയും നിൻ്റെ കുടുംബമെല്ലാവരും പെട്ടകത്തിൽ പ്രവേശിക്കുക. കാരണം, ഈ തലമുറയിൽ എൻ്റെ മുമ്പാകെ നിന്നെ ഞാൻ നീതിമാനായി കണ്ടിരിക്കുന്നു.","p":1},{"v":2,"t":"ശുദ്ധിയുള്ള എല്ലാ മൃഗങ്ങളിൽനിന്നും ആണും പെണ്ണുമായി ഏഴു ജോഡിവീതവും ശുദ്ധിയില്ലാത്തമൃഗങ്ങളിൽനിന്ന് ആണും പെണ്ണുമായി ഓരോ ജോഡിവീതം നീ എടുക്കണം.","p":1},{"v":3,"t":"അതുപോലെ, ആകാശത്തിലെ പക്ഷികളിൽനിന്ന് പൂവനും പിടയമായി ഏഴു ജോഡി വീതവും ഭൂമി മുഴുവൻ അവയുടെ വംശപരമ്പര നിലനിർത്തേണ്ടതിനാണിത്.","p":1},{"v":4,"t":"എന്തെന്നാൽ ഏഴു ദിവസം കൂടി കഴിഞ്ഞാൽ നാല്പതു പകലും നാല്പതു രാവും ഭൂമിയിൽ ഞാൻ മഴ പെയ്യിക്കും; ഞാൻ ഉരുവാക്കിയ സകല ജീവികളെയും ഞാൻ ഭൂമുഖത്തുനിന്നു തുടച്ചുനീക്കും.","p":1},{"v":5,"t":"കർത്താവ് തന്നോട് കൽപ്പിച്ചതൊക്കെയും നോഹ ചെയ്തു.","p":1},{"v":6,"t":"നോഹയ്ക്ക് അറുനൂറു വയസ്സുള്ളപ്പോഴാണ് ഭൂമിയിൽ ജലപ്രളയമുണ്ടായത്.","p":1},{"v":7,"t":"നോഹയും അലനോടൊപ്പം അവൻ്റെ പുത്രന്മാരും അവൻ്റെ ഭാര്യയും അവൻ്റെ പുത്രന്മാരുടെ ഭാര്യമാരും ജലപ്രളയത്തിനു മുന്നേ പെട്ടകത്തിലേക്ക് വന്നു.","p":1},{"v":8,"t":"ശുദ്ധിയുള്ള മൃഗങ്ങളിൽനിന്നും ശുദ്ധിയില്ലാത്തവയിൽനിന്നും പക്ഷികളിൽ നിന്നും നിലത്തിഴയുന്ന സകലതിൽനിന്നും,","p":1},{"v":9,"t":"നോഹയോടു കർത്താവു കൽപ്പിച്ചിരുന്നതുപോലെ, രണ്ടുവീതം, ആണും പെണ്ണുമായി നോഹയുടെ അടുത്ത് പെട്ടകത്തിലേക്ക് വന്നു."},{"v":10,"t":"ഏഴാംദിവസം ഭൂമിയിൽ ജലപ്രളയമുണ്ടായി.","p":1},{"v":11,"t":"നോഹയുടെ ജീവിതത്തിൻ്റെഅറുനൂറാം വർഷം രണ്ടാംമാസം പതിനേഴാം ദിവസം, അതേദിവസം, അത്യഗാധത്തിൻ്റെ ഉറവുകളെല്ലാംപൊട്ടിയൊഴുകി; ആകാശജാലകങ്ങൾ തുറക്കപ്പെട്ടു.","p":1},{"v":12,"t":"നാല്പതു പകലും നാല്പതു രാവും ഭൂമിയിൽ മഴ പെയ്തുകൊണ്ടിരുന്നു.","p":1},{"v":13,"t":"ഈ ദിനം തന്നെ നോഹയും നോഹയുടെ പുത്രന്മാരായ ഷേം, ഹാം, യാഫെത്ത് എന്നിവരും നോഹയുടെ ഭാര്യ, അവൻ്റെ പുത്രന്മാരുടെ മൂന്നു ഭാര്യമാർ എന്നിവരും അവനോടൊപ്പം പെട്ടകത്തിൽ പ്രവേശിച്ചു.","p":1},{"v":14,"t":"അവരും ഇനമനുസരിച്ച് എല്ലാ ജീവികളും എല്ലാ കന്നുകാലികളും ഭൂമിയിൽ ഇഴയുന്ന എല്ലാ ഉരഗങ്ങളും എല്ലാ പക്ഷികളും പറവകളും","p":1},{"v":15,"t":"ജീവശ്വാസമുള്ള എല്ലാ ശരീരികളിൽനിന്നും രണ്ടുവീതം നോഹയുടെ അടുത്ത് പെട്ടകത്തിലേക്ക് വന്നു."},{"v":16,"t":"അവനോട് ദൈവം കൽപ്പിച്ചിരുന്നതുപോലെ സകല ശരീരികളിൽനിന്നും ആണും പെണ്ണുമായി വന്നവയെല്ലാം അകത്തുകടന്നു. അവനെ അകത്താക്കി കർത്താവ് വാതിലടച്ചു."},{"h":"ജലപ്രളയം"},{"v":17,"t":"ഭൂമിയുടെമേൽ നാല്പതുദിവസത്തേക്ക് ജലപ്രളയമുണ്ടായി; ജലം പെരുകി പെട്ടകത്തെ ഉയർത്തി; അത് ഭൂമിക്ക് മുകളിൽ ഉയർന്നു പൊങ്ങി","p":1},{"v":18,"t":"ജലം പ്രബലപ്പെടുകയും ഭൂമിയിൽ ഏറെ പെരുകുകയും ചെയ്തു; പെട്ടകം ജല മുഖത്ത് ചരിച്ചു."},{"v":19,"t":"ജലം ഭൂമിക്ക് മേൽ അത്യധികം പ്രബലപ്പെട്ടു. ആകാശം മുഴുവൻ്റേയും കീഴിലുള്ള എല്ലാ ഉന്നതപർവ്വതങ്ങളും മൂടപ്പെട്ടു","p":1},{"v":20,"t":"പർവതങ്ങൾ മൂടപ്പെടുമാറ് ജലം അവയ്ക്ക് മുകളിൽ പതിനഞ്ചു മുഴം ഉയർന്നു നിന്നു."},{"v":21,"t":"പക്ഷികളിലും കന്നുകാലികളിലും വന്യ മൃഗങ്ങളിലും ഭൂമിയിൽ നിറഞ്ഞിരുന്ന എല്ലാ ജന്തുക്കളിലും പെട്ട എല്ലാ രൂപശരീരികളും ചത്തൊടുങ്ങി. ഒപ്പം, എല്ലാ മനുഷ്യരും.","p":1},{"v":22,"t":"കരയിലുള്ളവയിൽ ജീവചൈതന്യശ്വാസം നാസ രന്ധ്രങ്ങളിലുള്ളവയെല്ലാം ചത്തു.","p":1},{"v":23,"t":"മനുഷ്യൻമുതൽ മൃഗംവരേ, ഇഴന്തുമുതൽ ആകാശപ്രാവരേ ഭൂതലത്തെ സകല ജീവികളെയും അവിടന്നു തുടച്ചുമാറ്റി. അവ ഭൂമിയിൽനിന്നു തുടച്ചുനീക്കപ്പെട്ടപ്പോൾ നോഹയും അവനോടൊപ്പം പെട്ടകത്തി ലുണ്ടായിരുന്നവരും മാത്രം അവശേഷിച്ചു.","p":1},{"v":24,"t":"നൂറ്റമ്പതു ദിവസം വെള്ളപ്പൊക്കം ഭൂമിയിന്മേൽ പ്രബലപ്പെട്ടിരുന്നു","p":1}],"8":[{"h":"ജലപ്രളയം ശമിക്കുന്നു"},{"v":1,"t":"നോഹയെയും അവനോടൊപ്പം പെട്ടകത്തിലുണ്ടായിരുന്ന എല്ലാ ജീവികളെയും കന്നുകാലികളെയും ദൈവം ഓർത്തു. ഭൂമിയിന്മേൽ കാറ്റുവീശാൻ ദൈവം ഇടയാക്കി; ജലം അടങ്ങി.","p":1},{"v":2,"t":"ആഴത്തിന്റെ ഉറവുകളും ആകാശത്തിന്റെ ജാലകങ്ങളും അടഞ്ഞു; ആകാശത്തുനിന്നുള്ള മഴ നിലച്ചു.","p":1},{"v":3,"t":"ഭൂമിയിൽനിന്ന് ജലം പിൻവാങ്ങിക്കൊണ്ടിരുന്നു. നൂറ്റമ്പതു ദിവസം കഴിഞ്ഞപ്പോൾ ജലം കുറഞ്ഞു.","p":1},{"v":4,"t":"ഏഴാംമാസം, മാസത്തിന്റെ പതിനേഴാംദിവസം, പെട്ടകം അറാറാത്തു പർവതനിരയിൽ ഉറച്ചു.","p":1},{"v":5,"t":"പത്തു മാസത്തേക്ക് ജലം കുറഞ്ഞുകൊണ്ടേയിരുന്നു. പത്താംമാസം, മാസത്തിന്റെ ഒന്നാംദിവസം പർവത്യശൃംഗങ്ങൾ കണ്ടുതുടങ്ങി.","p":1},{"v":6,"t":"നാല്പതു ദിവസം കഴിഞ്ഞപ്പോൾ നോഹ പെട്ടകത്തിന് താനുണ്ടാക്കിയിരുന്ന കിളിവാതിൽ തുറന്ന്","p":1},{"v":7,"t":"മലങ്കാക്കയെ പുറത്തേക്കയച്ചു. അത് ഭൂമിയിൽ ജലം വറ്റുവോളം പോയുംവന്നും കൊണ്ടിരുന്നു."},{"v":8,"t":"ഭൂതലത്തിൽ ജലത്തിന്റെ ശക്തി കുറഞ്ഞോ എന്നു കാണാൻ അവൻ പിന്നീട് തന്റെ അടുത്തുനിന്നൊരു പ്രാവിനെ പുറത്തേക്കയച്ചു.","p":1},{"v":9,"t":"ഭൂമുഖത്തെല്ലാം ജലമായതിനാൽ കാലുകുത്താൻ ഇടം കാണാതെ പ്രാവ് അവന്റെനേർക്ക് പെട്ടകത്തിലേക്ക് തിരിച്ചുവന്നു. അവൻ കൈനീട്ടി അതിനെ പിടിച്ച് തന്റെ അടുത്തുചേർത്തു, പെട്ടകത്തിലേക്ക് പ്രവേശിപ്പിച്ചു.","p":1},{"v":10,"t":"ഏഴു ദിവസകൂടി കാത്തിരുന്നിട്ടു അവൻ പ്രാവിനെ വീണ്ടും പെട്ടകത്തിനു പുറത്തേക്കയച്ചു.","p":1},{"v":11,"t":"വൈകുന്നേരമായപ്പോൾ പ്രാവ് അവന്റെയടുക്കലേക്കു വന്നു. ഇതാ, അതിന്റെ ചുണ്ടിൽ ഇപ്പോൾ കൊത്തിയെടുത്തൊരു ഒലിവില! അങ്ങനെ, ഭൂതലത്തിൽ ജലത്തിന്റെ ശക്തി കുറഞ്ഞെന്ന് നോഹ അറിഞ്ഞു.","p":1},{"v":12,"t":"എഴുദിവസകൂടി കാത്തിരുന്നശേഷം അവൻ പ്രാവിനെ വീണ്ടും പുറത്തേക്കയച്ചു. അത് പിന്നീടൊരിക്കലും അവന്റെയടുക്കലേക്ക് തിരിച്ചുവന്നില്ല.","p":1},{"v":13,"t":"അറുനൂറ്റിഒന്നാംവർഷം ഒന്നാംമാസത്തിന്റെആദ്യമാസത്തിൽ ഭൂമിയിലുണ്ടായിരുന്ന ജലം വറ്റിത്തീർന്നു. നോഹ പെട്ടകത്തിന്റെ മേൽക്കൂര നീക്കി. അപ്പോൾ അവൻ കണ്ടു: ഇതാ, ഭൂമുഖം ഉണങ്ങിയിരിക്കുന്നു.!","p":1},{"v":14,"t":"രണ്ടാംമാസം, മാസത്തിന്റെ ഇരുപത്തേഴാംദിവസമാണ് ഭൂമി ഉണങ്ങിയത്.","p":1},{"v":15,"t":"ദൈവം നോഹയോട് ഇപ്രകാരം പറഞ്ഞു:","p":1},{"v":16,"t":"പെട്ടകത്തിൽനിന്നു പുറത്തുവരുക; നീയും നിന്നോടൊപ്പം നിന്റെ ഭാര്യയും നിന്റെ പുത്രന്മാരും നിന്റെ പുത്രന്മാരുടെ ഭാര്യമാരും.","p":1},{"v":17,"t":"പക്ഷികളിലും മൃഗങ്ങളിലും ഭൂമിയിൽ ഇഴയുന്ന എല്ലാ ഇഴയുന്ന എല്ലാ ഉരഗങ്ങളിലും കന്നുകാലികളിലുമായി, എല്ലാ ശരീരങ്ങളിൽനിന്നു നിന്നോടൊപ്പമുള്ള എല്ലാ ജന്തുക്കളെയും പുറത്തുകൊണ്ടുവരുക, അവ ഭൂമിയിൽ തിങ്ങിനിറയട്ടെ! ഭൂതലത്തിൽ അവ പെറ്റുപെരുകട്ടെ!\"","p":1},{"v":18,"t":"നോഹ തന്റെ പുത്രന്മാരോടും തന്റെ ഭാര്യയോടും തന്റെ പുത്രന്മാരുടെ ഭാര്യമാരോടൊത്ത് പുറത്തുവന്നു.","p":1},{"v":19,"t":"എല്ലാ ജീവികളും എല്ലാ ഇഴജന്തുക്കളും എല്ലാ പക്ഷികളും, ഭൂതലത്തിൽ ചലിക്കുന്നവയൊക്കെയും, അവയുടെ വർഗ്ഗമനുസരിച്ച്, പെട്ടകത്തിൽനിന്നു പുറത്തുവന്നു.","p":1},{"h":"നോഹ ബലിയർപ്പിക്കുന്നു"},{"v":20,"t":"നോഹ കർത്താവിന് ഒരു ബലിപീഠം നിർമ്മിച്ചു. ശുചിയുള്ള എല്ലാ മൃഗങ്ങളിലും ശുദ്ധിയുള്ള എല്ലാ പക്ഷികളിലുംനിന്നു അവൻ ബലിപീഠത്തിൽ ഹോമയാഗങ്ങൾഉർപ്പിച്ചു.","p":1},{"v":21,"t":"സുരഭിലപരിമളം അസ്വദിച്ചപ്പോൾ കർത്താവ് ഹൃദയത്തിൽ പറഞ്ഞു: ഇനിയൊരിക്കലും മനുഷ്യനെപ്രതി മണ്ണിനെ ഞാൻ ശപിക്കുകയില്ല കാരണം, ചെറുപ്പംമുതൽ മനുഷ്യന്റെ ഹൃദയഭാവനദുഷിച്ചതാണ്. ഞാൻ ചെയ്തതുപോലെ ഇനിയൊരിക്കലും ജീവജാലമൊന്നടങ്കം ഞാൻ നശിപ്പിക്കുകയില്ല.","p":1},{"v":22,"t":"ഭൂമിയുള്ള കാലത്തോളംവിത്തും കൊയ്ത്തും തണുപ്പും ചൂടുംവേനലും വർഷവും പകലും രാത്രിയും നിലയ്ക്കുകയില്ല.","p":1}],"9":[{"h":"നോഹയുമായി ഉടമ്പടി"},{"v":1,"t":"നോഹയെയും അവന്റെ പുത്രന്മാരെയും അനുഗ്രഹിച്ചുകൊണ്ട് ദൈവം അവരോടു പറഞ്ഞു: “പെറ്റുപെരുകി ഭൂമിയിൽ നിറയുവിൻ.","p":1},{"v":2,"t":"നിങ്ങളെക്കുറിച്ചുള്ള ഭയവും നിങ്ങളെക്കുറിച്ചുള്ള നടുക്കവും ഭൂമിയിലെ എല്ലാ മൃഗങ്ങളുടെയും ആകാശത്തിലെ എല്ലാ പക്ഷികളുടെയും മേലും നിലത്തിലെ എല്ലാ ജന്തുക്കളെയും സമുദ്രത്തിലെ എല്ലാ മത്സ്യങ്ങളിലും ഉണ്ടായിരിക്കും; അവ നിങ്ങളുടെ കയ്യിൽ ഏൽപ്പിക്കപ്പെട്ടിരിക്കുന്നു.","p":1},{"v":3,"t":"ചരിക്കുന്ന ഓരോ ജീവിയും നിങ്ങൾക്ക് ആഹാരമായിരിക്കട്ടെ. ഹരിതസസ്യങ്ങളെപ്പോലെ ഇവയെല്ലാം നിങ്ങൾക്ക് ഞാൻ തരുന്നു.","p":1},{"v":4,"t":"എന്നാൽ മാംസം അതിന്റെ ജീവനോടുകൂടെ, രക്തത്തോടുകൂടെ, നിങ്ങൾ ഭക്ഷിക്കരുത്.","p":1},{"v":5,"t":"തീർച്ചയായും നിങ്ങളുടെ ജീവനുവേണ്ടി നിങ്ങളുടെ രക്തം ഞാൻ ആവശ്യപ്പെടും; ഓരോ ജീവിയുടെയും കയ്യിൽനിന്നും അതു ഞാൻ ആവശ്യപ്പെടും; മനുഷ്യന്റെ കയ്യിൽനിന്നും, അവന്റെ സഹോദരന്റെ കയ്യിൽനിന്നും, മനുഷ്യജീവൻ ഞാൻ ആവശ്യപ്പെടും.","p":1},{"v":6,"t":"മനുഷ്യന്റെ രക്തം ചിന്തുന്നവന്റെ രക്തം മനുഷ്യനാൽ ചിന്തപ്പെടും. എന്തെന്നാൽ ദൈവത്തിന്റെ ഛായയിലാണല്ലോ അവിടന്ന് അവനെ മെനഞ്ഞത്.","p":1},{"v":7,"t":"നിങ്ങൾ പെറ്റുപെരുകുവിൻ, ഭൂമിയിൽ നിറയുവിൻ, അവളിൽ നിങ്ങൾ പെരുകുവിൻ!","p":1},{"v":8,"t":"നോഹയോടും അവനോടുകൂടെയുണ്ടായിരുന്ന പുത്രന്മാരോടും ദൈവം ഇപ്രകാരം അരുളിച്ചെയ്തു:","p":1},{"v":9,"t":"“ഞാനിതാ, നിങ്ങളുമായും നിങ്ങൾക്കുശേഷമുള്ള നിങ്ങളുടെ സന്തതികളുമായും എന്റെ ഉടമ്പടി സ്ഥാപിക്കുന്നു;"},{"v":10,"t":"പെട്ടകത്തിൽനിന്നു പുറത്തുവന്നവ തുടങ്ങി ഭൂമിയിലെ സകലജന്തുക്കളുമായും - നിങ്ങളോടൊത്തുള്ള സകല ജീവജാലവുമായും പക്ഷിജാലത്തിലും മൃഗഗണത്തിലും സകല ഭൗമജീവിയിലും നിങ്ങളോടുകൂടെയുള്ളവയുമായും","p":1},{"v":11,"t":"നിങ്ങളുമായും ഞാൻ എന്റെ ഉടമ്പടി സ്ഥാപിക്കുന്നു: ഇനിയൊരിക്കലും ജലപ്രളയത്താൽ ശരീരികളാകമാനം നശിപ്പിക്കപ്പെടുകയില്ല. ഭൂമിയെ നശിപ്പിക്കും വിധം ഇനിയൊരു പ്രളയമുണ്ടാവുകയില്ല."},{"v":12,"t":"അനന്തരം ദൈവം പറഞ്ഞു: ഞാനും നിങ്ങളും തമ്മിലും നിങ്ങളോടൊപ്പമുള്ള എല്ലാ ജീവജാലങ്ങളും തമ്മിലും, തലമുറകളോളം ശാശ്വതമായി, ഞാൻ ഉറപ്പിക്കുന്ന ഉടമ്പടിയുടെ അടയാളം ഇതായിരിക്കും","p":1},{"v":13,"t":"ഞാൻ മേഘത്തിൽ എന്റെ വില്ല് വയ്ക്കുന്നു. അത് ഞാനും ഭൂമിയും തമ്മിലുള്ള ഉടമ്പടിയുടെ അടയാളമായിരിക്കും."},{"v":14,"t":"ഞാൻ ഭൂമി മേഘാവൃതമാക്കുകയും വില്ല് മേഘത്തിൽ പ്രത്യക്ഷമാവുകയും ചെയ്യുമ്പോൾ,"},{"v":15,"t":"നിങ്ങളുമായും സകല ശരീരിയിലുംപെട്ട ഓരോ ജീവജാലവുമായുമുള്ള എന്റെ ഉടമ്പടി ഞാൻ അനുസ്മരിക്കും; ശരീരികളെ ഒന്നാകെ നശിപ്പിക്കുവിൻ ഇനിയൊരിക്കലും ജലം ഒരു പ്രളയമായിത്തീരുകയില്ല."},{"v":16,"t":"വില്ല് മേഘത്തിൽ പ്രത്യക്ഷപ്പെടുമ്പോൾ, ദൈവവും ഭൂമിയിലെ സകല ശരീരിയിലുംപെട്ട ഓരോ ജീവജാലവും തമ്മിലുള്ള ശാശ്വതമായ ഉടമ്പടി ഓർമ്മിക്കാൻവേണ്ടി ഞാൻ അതു നോക്കിക്കാണും."},{"v":17,"t":"ദൈവം നോഹയോട് അരുളിച്ചെയ്തു: ഇത് ഞാനും ഭൂമിയിലെ ഓരോ ശരീരിയും തമ്മിൽ ഞാൻ സ്ഥാപിക്കുന്ന ഉടമ്പടിയുടെ അടയാളമായിരിക്കും.","p":1},{"h":"നോഹയുടെ പുത്രന്മാർ"},{"v":18,"t":"ഷേം, ഹാം, യാഫെത്ത് എന്നിവരാണ് പെട്ടകത്തിൽനിന്നു പുറത്തിറങ്ങിയ നോഹയുടെ പുത്രന്മാർ. ഹാം ആണ് കാനാൻ്റെ പിതാവ്.","p":1},{"v":19,"t":"ഇവരാകുന്നു നോഹയുടെ മൂന്നു പുത്രന്മാർ; ഇവരെക്കൊണ്ടാണ് ഭൂമി മുഴുവൻ നിറഞ്ഞത്.","p":1},{"v":20,"t":"കർഷകവൃത്തി ആരംഭിച്ച്, നോഹ ഒരു മുന്തിരിത്തോട്ടം നട്ടുപിടിപ്പിച്ചു.","p":1},{"v":21,"t":"വീഞ്ഞുകുടിച്ചു ഉന്മത്തനായി അവൻ തന്റെ കൂടാരത്തിന്റെ നടുവിൽ വിവസ്ത്രനായി കിടന്നു."},{"v":22,"t":"കാനാൻ്റെ പിതാവായ ഹാം തന്റെ പിതാവിന്റെ നഗ്നത കാണുകയും പുറത്തുണ്ടായിരുന്ന തന്റെ രണ്ടു സഹോദരന്മാരോട് പറയുകയും ചെയ്തു.","p":1},{"v":23,"t":"ഷേമും യാഫെത്തും മേല് വസ്ത്രമെടുത്തു തങ്ങളിരുവരുടെയും തോളിലിട്ട്, പിറകോട്ടു നടന്നുചെന്ന് സ്വപിതാവിന്റെ നഗ്നത മറച്ചു. മുഖം പിറകോട്ടു തിരിച്ചുരുന്നതിനാൽ തങ്ങളുടെ പിതാവിന്റെ നഗ്നത അവർ കണ്ടില്ല.","p":1},{"v":24,"t":"ലഹരിവിട്ടു ഉണർന്ന നോഹ തന്റെ ഇളയമകൻ തന്നോട് ചെയ്തതെന്തെന്ന് അറിഞ്ഞു."},{"v":25,"t":"അപ്പോൾ അവൻ പറഞ്ഞു: കാനാൻ ശപിക്കപ്പെട്ടവൻ! അവൻ തന്റെ സഹോദരങ്ങൾക്ക് അടിമകളുടെ അടിമയാകും."},{"v":26,"t":"തുടർന്ന് അവൻ പറഞ്ഞു: ശേമിന്റെ ദൈവമായ കർത്താവ് വാഴ്ത്തപ്പെട്ടവൻ! കാനാൻ അവന് അടിമയാകട്ടെ!","p":1},{"v":27,"t":"ദൈവം യാഫെത്തിനെ വിപുലമാക്കട്ടെ! അവൻ ഷേമിന്റെ കൂടാരങ്ങളിൽ പാർക്കട്ടെ! കാനാൻ അവരുടെ അടിമയാകട്ടെ!","p":1},{"v":28,"t":"പ്രളയത്തിനുശേഷം നോഹ മുന്നൂറ്റിമുപ്പതു വർഷം ജീവിച്ചു.","p":1},{"v":29,"t":"നോഹയുടെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തമ്പതു വർഷമായിരുന്നു. അവൻ മരിച്ചു","p":1}],"10":[{"h":"ജനതകളുടെ ഉത്ഭവം"},{"v":1,"t":"നോഹയുടെ പുത്രന്മാരായ ഷേമിന്റെയുംഹാമിന്റെയും യാഫെത്തിന്റെയും തലമുറകൾ - പ്രളയശേഷം അവർ ജന്മംകൊടുത്ത മക്കൾ - ഇവയാണ്.","p":1},{"v":2,"t":"യാഫെത്തിന്റെ മക്കൾ ഗോമെർ, മാഗോഗ്, മാദായ്, യാവാൻ, തുബാൽ, മെഷെക്, തീരാസ്.","p":1},{"v":3,"t":"ഗോമെറിന്റെ മക്കൾ: അഷ്കെനാസ്, റീഫത്ത്, തോഗർമ.","p":1},{"v":4,"t":"യാവാന്റെ മക്കൾ: എലീശാ, തർഷീശ്, കിത്തിം, ദോദാനിം.","p":1},{"v":5,"t":"ഇവരിൽനിന്നാണ് ജനതകൾ അവരുടെ ദേശങ്ങളിൽ ഓരോന്നിന്റെയും ഭാഷയനുസരിച്ച് അവരുടെ ജനതകളിൽ താന്തങ്ങളുടെ വംശമനുസരിച്ചും വിന്യസിക്കപ്പെട്ടത്.","p":1},{"v":6,"t":"ഹാമിന്റെ മക്കൾ: കൂശ്, മിസ്രയിം, ഫുത്ത്, കാനാൻ എന്നിവർ.","p":1},{"v":7,"t":"കുഷിന്റെ മക്കൾ: സേബാ, ഹവീലാ, സബത്താ, റാമാ, സബ്ത്തേക്കാ റാമായുടെ മക്കളാണ് ഷെബായും ദെദാനും.","p":1},{"v":8,"t":"കൂശ് നിമ്രോദിനെ ജനിപ്പിച്ചു. അവൻ ഭൂമിയിൽ ഒരു വീരപുരുഷനാകാൻ തുടങ്ങി.","p":1},{"v":9,"t":"അവൻ കർത്താവിൻമുമ്പിൽ ഒരു നായാട്ടുവിരനായിരുന്നു. അതുകൊണ്ട്, കർത്താവിൻമുമ്പിൽ നിമ്രോദിനെപ്പോലൊരു നായാട്ടുവിരൻ എന്ന ചൊല്ലുണ്ടായി.","p":1},{"v":10,"t":"അവന്റെ രാജ്യത്തിന്റെ ആരംഭം ഷീനാർദേശത്തെ ബാബേൽ, ഏറെക്, അക്കാദ്, കൽനെഎന്നിവയായിരുന്നു.","p":1},{"v":11,"t":"അവൻ ആ നാട്ടിൽനിന്ന് അഷൂറിലേക്ക് പുറപ്പെട്ട് നിനെവേ, രെഹോബോത്ത് ഈർ, കാലാഹ് എന്നിവ പണികഴിപ്പിച്ചു;","p":1},{"v":12,"t":"ഒപ്പം നിനെവേക്കും കാലാഹിനുമിടയിൽ റേസൻ എന്ന മഹാനഗരവും.","p":1},{"v":13,"t":"മിസ്രയിം ജന്മംകൊടുത്തതാണ്ലൂദീം, അനാമീം, ലഹാബീം, നഫ്തൂഹീം,","p":1},{"v":14,"t":"പത്രൂസീം, ഫിലിസ്ത്യർ പുറപ്പെട്ടുപോന്ന കസ്ലൂഹീം, കഫ്തോറിം എന്നിവ."},{"v":15,"t":"കാനാൻ ജന്മംനല്കിയത് തന്റെ കടിഞ്ഞൂലായസീദോനും ഹേത്ത്,","p":1},{"v":16,"t":"ജബൂസ്യർ, അമോര്യർ, ഗിർഗാഷ്യർ,"},{"v":17,"t":"ഹിവ്യർ, അർക്കീയർ, സീന്യർ,"},{"v":18,"t":"അർവാദിയർ, സെമറീയർ, ഹമാത്യർ എന്നിവർക്കുമായിരുന്നു. പില്ക്കാലത്ത് കാനാൻകാരുടെ വംശങ്ങൾ പലയിടത്തും വ്യാപിച്ചു."},{"v":19,"t":"കാനാൻകാരുടെ ദേശാതിർത്തി, സീദോൻ തുടങ്ങി ഗെരാറിലേക്കുള്ള ദിശയിൽ ഗാസ വരെയും സൊദോം-ഗൊമോറ-അദ്മാ ദിശയിൽ സെബോയിം തുടങ്ങി ലാശാ വരെയും ആണ്.","p":1},{"v":20,"t":"ഇവരാണ് തങ്ങളുടെ ദേശങ്ങളിലും ജനതകളിലും വംശവും ഭാഷയുമനുസരിച്ച് ഹാമിന്റെ മക്കൾ.","p":1},{"v":21,"t":"ഷേമിനും മക്കളുണ്ടായി; അവൻ ഹെബ്രായരുടെയെല്ലാം പിതാവും യാഫെത്തിന്റെ മൂത്ത സഹോദരനുമായിരുന്നു.","p":1},{"v":22,"t":"ശേമിന്റെ മക്കൾ ഏലാം, അഷൂർ, അർപ്പക്ഷാദ്, ലൂദ്, ആരാം എന്നിവരും","p":1},{"v":23,"t":"ആരാമിന്റെ മക്കൾ ഊസ്, ഹൂൽ, ഗെതർ, മാഷ് എന്നിവരുമായിരുന്നു."},{"v":24,"t":"അർപ്പക്ഷാദ് ഷേലാഹിനും ഷേലാഹ് എബറിനും ജന്മംകൊടുത്തു.","p":1},{"v":25,"t":"എബറിന് രണ്ടു പുത്രന്മാർ ജനിച്ചു: ഒന്നാമത്തെ പേര് പേലെഗ്. കാരണം, അവന്റെ കാലത്താണ് ഭൂമി വിഭജിതമായത്. അവന്റെ സഹോദരന്റെ പേര് യോക്താൻ.","p":1},{"v":26,"t":"അവൻ അൽമോദാദ്, ശെലെഫ്, ഹസർവേത്ത്, യാറഹ്,","p":1},{"v":27,"t":"ഹദോറാം, ഊസാൽ, ദിക്ലാ,"},{"v":28,"t":"ഒബാൽ, അബിമായേൽ, ഷെബാ,"},{"v":29,"t":"ഓഫീർ, ഹവീലാ, യോബാബ് എന്നിവർക്ക് ജന്മംകൊടുത്തു. ഇവരൊക്കെയായിരുന്നു യോക്താ ന്റെ മക്കൾ."},{"v":30,"t":"അവർ പാർത്തിരുന്ന നാട്, മേഷാ തുടങ്ങി കിഴക്കൻ മലയായ സെഫാറിന്റെ ദിശയിലായിരുന്നു.","p":1},{"v":31,"t":"ഇവരാണ് തങ്ങളുടെ ദേശങ്ങളിലും ജനതകളിലും വംശവും ഭാഷയും അനുസരിച്ച് ഷേമിന്റെ മക്കൾ.","p":1},{"v":32,"t":"ഇവയാണ് തങ്ങളുടെ ഉത്പത്തിയനുസരിച്ച് ജനതകളിൽ നോഹയുടെ മക്കളുടെ വംശങ്ങൾ ഇവരിൽ നിന്നാണ് പ്രളയത്തിനുശേഷം ജനതകൾ ഭൂമിയിൽ വേർതിരിഞ്ഞത്","p":1}],"11":[{"h":"ബാബേൽഗോപുരം"},{"v":1,"t":"1 ഭൂമിമുഴുവനും ഒരേ ഭാഷയും ഒരേ പദാവലിയും ആയിരുന്നു.","p":1},{"v":2,"t":"അക്കാലത്ത് കിഴക്കുനിന്നു പുറ പ്പെട്ടവർ ഷീനാർദേശത്ത് ഒരു സമതലം കണ്ടെത്തി അവിടെ പാർപ്പുറപ്പിച്ചു.","p":1},{"v":3,"t":"അവർ പരസ്പരം പറഞ്ഞു: വരുവിൻ, നമുക്ക് ഇഷ്ടികയുണ്ടാക്കി തീയിൽചുട്ടെടുക്കാം. അങ്ങനെ അവർക്ക് ഇഷ്ടിക കല്ലിനുപകരവും കീല് കുമ്മായത്തിനു പകരവുമായി.","p":1},{"v":4,"t":"അവർ തുടർന്നുപറഞ്ഞു: വരുവിൻ, നമുക്ക് ഒരു പട്ടണവുംആകാശമുട്ടുന്ന ഒരു ഗോപുരവും പണിത് നമുക്കായി പേരു സമ്പാദിക്കാം. അതല്ലെങ്കിൽ, നാം ഭൂമുഖത്താകെത്താകെ ചിതറിപ്പോകും.","p":1},{"v":5,"t":"മനുഷ്യമക്കൾ നിർമ്മിച്ച നഗരവും ഗോപുരവും കാണാൻ കർത്താവു ഇറങ്ങിവന്നു.","p":1},{"v":6,"t":"കർത്താവു പറഞ്ഞു: നോക്കൂ, ഒരു ജനതയും അവർക്കെല്ലാം ഒറ്റ ഭാഷയും! ഇത് അവർ ചെയ്യാനിരിക്കുന്നതിന്റെ തുടക്കംമാത്രം. ചെയ്യാൻ ഉദ്യമിക്കുന്നതൊന്നും അവർക്കിനി അസാദ്ധ്യമായിരിക്കയില്ല.","p":1},{"v":7,"t":"വരുവീൻ, നമുക്ക് ഇറങ്ങിച്ചെന്ന് അവിടെവച്ച് അവരുടെ ഭാഷ പരസ്പരം ഗ്രഹിക്കാനാവാത്തവിധം കുഴച്ചുമറിക്കാം.","p":1},{"v":8,"t":"അങ്ങനെ കർത്താവു അവരെ അവിടെനിന്ന് ഭൂമുഖത്തെങ്ങും ചിതറിച്ചു. അതോടെ അവർ പട്ടണം പണിയുന്നത് ഉപേക്ഷിച്ചു.","p":1},{"v":9,"t":"ഭൂമിയിലാകെയുള്ള ഭാഷ കർത്താവു അവിടെവച്ച് കുഴച്ചുമറിച്ചതുകൊണ്ടാണ് ആ സ്ഥലത്തിന് ബാബേൽ എന്നു പേരുണ്ടായത്. അവിടെനിന്നാണ് കർത്താവു അവരെ ഭൂമുഖത്താകെ ചിതറിച്ചത്.","p":1},{"h":"ഷേം മുതൽ അബ്രാഹം വരെ"},{"v":10,"t":"ഇതാണ് ഷേമിന്റെ വംശാവലി: ഷേമിന് നൂറു വയസ്സായപ്പോൾ, പ്രളയത്തിനുശേഷം രണ്ടാം വർഷം അവൻ അർപ്പക്ഷാദിനെ ജനിപ്പിച്ചു.","p":1},{"v":11,"t":"അർപ്പക്ഷാദിന്റെ ജനനത്തിനുശേഷം അഞ്ഞൂറുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":12,"t":"മുപ്പത്തഞ്ചു വയസ്സായപ്പോൾ അർപ്പക്ഷാദ് ശേലാഹിനെ ജനിപ്പിച്ചു.","p":1},{"v":13,"t":"ശേലാഹിന്റെ ജനനത്തിനുശേഷം അർപ്പക്ഷാദ് നാനൂറ്റിമൂന്നു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":14,"t":"മുപ്പതുവയസ്സായപ്പോൾ എബർ ഷേലാഹിനെ ജനിപ്പിച്ചു.","p":1},{"v":15,"t":"എബറിന്റെ ജനനത്തിനുശേഷം നാനൂറ്റി മൂന്നുവർഷം ഷേലാഹ് ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":16,"t":"മുപ്പത്തിനാലു വയസ്സായപ്പോൾ ഏബർ പേലേഗിനെ ജനിപ്പിച്ചു.","p":1},{"v":17,"t":"പേലേഗിന്റെ ജനനത്തിനുശേഷം ഏബർ നാനൂറ്റിമുപ്പതുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":18,"t":"മുപ്പതുവയസ്സായപ്പോൾ പേലേഗ് റെവൂവിനെ ജനിപ്പിച്ചു.","p":1},{"v":19,"t":"റെവൂവിന്റെ ജനനത്തിനുശേഷം പേലേഗ് ഇരുനൂറ്റൊമ്പതുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":20,"t":"മുപ്പത്തിരണ്ടു വയസ്സായപ്പോൾ റെവൂ സെരൂഗിനെ ജനിപ്പിച്ചു.","p":1},{"v":21,"t":"സെരൂഗിന്റെ ജനനത്തിനുശേഷം റെവൂ ഇരുനൂറ്റേഴുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":22,"t":"മുപ്പതുവയസ്സായപ്പോൾ സെരൂഗ് നാഹോറിനെ ജനിപ്പിച്ചു.","p":1},{"v":23,"t":"നാഹോറിന്റെ ജനനത്തിനുശേഷം സെരൂഗ് ഇരുനൂറു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":24,"t":"ഇരുപത്തൊമ്പതു വയസ്സായപ്പോൾ നാഹോർ തെരാഹിനെ ജനിപ്പിച്ചു.","p":1},{"v":25,"t":"തെരാഹിന്റെ ജനനത്തിനുശേഷം നാഹോർ നൂറ്റിപ്പത്തൊമ്പതുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":26,"t":"എഴുപതുവയസ്സായപ്പോൾ തെരാഹ് അബ്രാമിനെയും നാഹോറിനെയും ഹാരാനെയും ജനിപ്പിച്ചു.","p":1},{"v":27,"t":"ഇവയാണ് തെരാഹിന്റെ വംശാവലി: തെരാഹ് അബ്രാമിനും നാഹോറിനും ഹാരാനും ജന്മംനല്കി. ഹാരാൻ ലോത്തിന് ജന്മംനല്കി.","p":1},{"v":28,"t":"ഹാരാൻ തന്റെ പിതാവായ തെരാഹിനുമുമ്പേ ജന്മനാടായ കല്ദായരുടെ ഊറിൽവച്ച് ചരമമടഞ്ഞു.","p":1},{"v":29,"t":"അബ്രാമും നാഹോറും തങ്ങൾക്കായി ഭാര്യമാരെ സ്വീകരിച്ചു. അബ്രാമിന്റെ ഭാര്യയുടെ പേര് സാറായി. നാഹോറിന്റെ ഭാര്യയുടെ പേര് മിൽക്ക; അവൾ ഹാരാന്റെ മകളായിരുന്നു. ഹാരാൻ മിൽക്കയുടെയും ഇസ്കായുടെയും പിതാവായിരുന്നു.","p":1},{"v":30,"t":"സാറായി വന്ധ്യയായിരുന്നു. അവൾക്ക് മക്കളുണ്ടായിരുന്നില്ല.","p":1},{"v":31,"t":"തെരാഹ് തന്റെ മകൻ അബ്രാമിനെയും പേരക്കിടാവും ഹാരാന്റെ മകനുമായ ലോത്തിനെയും അബ്രാമിന്റെ ഭാര്യയും തന്റെ മരുമകളുമായ സാറായിയെയുംകൂട്ടി അവരോടുകൂടെ കല്ദായരുടെ ഊരിൽനിന്ന് കാനാൻദേശത്തേക്ക് കാലനടയായി പുറപ്പെട്ട് ഹാരാൻവരെയെത്തി. അവിടെ അവർ വാസമുറപ്പിച്ചു.","p":1},{"v":32,"t":"തെരാഹിന്റെ ആയുസ്സ് ഇരുനൂറ്റഞ്ചുവർഷം ആയിരുന്നു. അവൻ ഹാരാനിൽവച്ച് മൃതിയടഞ്ഞു.","p":1}],"12":[{"h":"അബ്രാമിനെ വിളിക്കുന്നു"},{"v":1,"t":"കർത്താവു അബ്രാമിനോട് അരുളിച്ചെയ്തു: \"നിന്റെ ദേശത്തുനിന്നും സ്വജനത്തിൽനിന്നും പിതൃഭവനത്തിൽനിന്നും ഞാൻ കാണിച്ചുതരുന്ന നാട്ടിലേക്ക് പോവുക.","p":1},{"v":2,"t":"ഞാൻ നിന്നെ വലിയൊരു ജനതയാക്കും. നിന്നെ ഞാൻ അനുഗ്രഹിക്കും. നിന്റെ പേര് ഞാൻ ശ്രേഷ്ഠമാക്കും. അങ്ങനെ നീ ഒരനുഗ്രഹമായിരിക്കും.","p":1},{"v":3,"t":"നിന്നെ അനുഗ്രഹിക്കുന്നവനെ ഞാൻ അനുഗ്രഹിക്കും. നിന്നെ ശപിക്കുന്നവനെ ഞാൻ ശപിക്കും. നിന്നിലൂടെ ഭൂമിയിലെ വംശങ്ങളെല്ലാം അനുഗ്രഹീതമാകും.\"","p":1},{"v":4,"t":"കർത്താവു തന്നോട് പറഞ്ഞതന്നനുസരിച്ച് അബ്രാം പോയി. ലോത്തും അവനോടൊപ്പം പോയി. ഹാരോണിൽനിന്നു പുറപ്പെടുമ്പോൾ","p":1},{"v":5,"t":"അബ്രാം എഴുപത്തഞ്ചു വയസ്സു പ്രായമായിരുന്നു. അബ്രാം ഭാര്യ സാറായിയെയും സഹോദരപുത്രൻ ലോത്തിനെയും തങ്ങൾ നേടിയ മുഴുവൻ സമ്പത്തും ഹാരോൺ ദേശത്ത് തങ്ങൾ സംഘടിപ്പിച്ച ആളുകളെയും കൂടെക്കൂട്ടി. അനന്തരം കാനാൻ ദേശത്തേക്ക് പോകാൻ അവർ യാത്രയായി. അങ്ങനെ അവർ കാനാൻ ദേശത്തു വന്നുചേർന്നു."},{"v":6,"t":"അബ്രാം ആ നാട്ടിലൂടെ സഞ്ചരിച്ച് ഷെക്കെം പ്രദേശംവരെ, മോറെയിലെ ഓക്കുമരംവരെ എത്തി.അക്കാലത്ത് ആ ദേശത്തുണ്ടായിരുന്നത് കാനാൻകാരാണ്.","p":1},{"v":7,"t":"കർത്താവ് അബ്രാമിന് പ്രത്യക്ഷപ്പെട്ട് അരുളിച്ചെയ്തു: ഈ നാട് നിന്റെ സന്തതിക്കു ഞാൻ കൊടുക്കും. തനിക്ക് പ്രത്യക്ഷപ്പെട്ട കർത്താവിന് അവൻ അവിടെ ഒരു ബലിപീഠം പണിതു.","p":1},{"v":8,"t":"അവിടെനിന്ന് അവൻ ബേഥേലിനു കിഴക്കുള്ള മലയിലേക്കു നീങ്ങി ബേഥേലിനു കിഴക്കുംംആയിക്കു പടിഞ്ഞാറുമായി കൂടാരമടിച്ചു. അവിടെ കർത്താവിന് ഒരു ബലിപീഠം പണിത്, അവൻ കർത്താവിന്റെ നാമം വിളിച്ചപേക്ഷിച്ചു.","p":1},{"v":9,"t":"അവിടെനിന്ന് അബ്രാം നെഗെബിലേക്കു നേരെ പടിപടിയായി യാത്ര ചെയ്തു.","p":1},{"h":"അബ്രാം ഈജിപ്തിൽ"},{"v":10,"t":"ആ നാട്ടിൽ ഒരു ക്ഷാമം ഉണ്ടായി. അവിടെ കടുത്ത ക്ഷാമമായിരുന്നതിനാൽ അബ്രാം തത്കാലവാസത്തിന് ഈജിപ്തിലേക്ക് ഇറങ്ങിത്തിരിച്ചു.","p":1},{"v":11,"t":"ഈജിപ്തിനെ സമീപിച്ച്, അതിൽ പ്രവേശിക്കാറായപ്പോൾ അവൻ ഭാര്യ സാറായിയോടു പറഞ്ഞു: ഇതാ, നീ കാണാൻ അഴകുള്ള സ്ത്രീയാണെന്ന് എനിക്കറിയാം.","p":1},{"v":12,"t":"ഈജിപ്തുകാർ നിന്നെ കാണുന്ന മാത്രയിൽ, ഇവൾ അവന്റെ ഭാര്യയാണ് എന്നു പറഞ്ഞ് എന്നെ കൊന്നിട്ടു നിന്നെ ജീവിക്കാൻ അനുവദിക്കും.","p":1},{"v":13,"t":"നീ മൂലം എനിക്ക് നല്ലത് സംഭവിക്കേണ്ടതിന് നീ എന്റെ സഹോദരിയാണെന്നു തന്നെ പറയണം. അങ്ങനെ നീ മൂലം എന്റെ പ്രാണൻ നിലനില്ക്കും.","p":1},{"v":14,"t":"അബ്രാം ഈജിപ്തിൽ പ്രവേശിച്ചപ്പോൾ ഈജിപ്തുകാർ ആ സ്ത്രീയെ ശ്രദ്ധിച്ചു കാരണം, അവൾ അതീവസുന്ദരിയായിരുന്നു."},{"v":15,"t":"ഫറവോയുടെ പ്രഭുക്കന്മാർ അവളെ കാണുകയും അവളെക്കുറിച്ച് ഫറവോയോടു വർണ്ണിച്ചുപറയുകയും ചെയ്തു. ആ സ്ത്രീ ഫറവോയുടെ ഭവനത്തിലേക്ക് സ്വീകരിക്കപ്പെട്ടു.","p":1},{"v":16,"t":"അയാൾ അവളെപ്രതി അബ്രാമിനോട് നന്നായി പെരുമാറി. അങ്ങനെ അവന് ആടുമാടുകളും ആൺകഴുതകളും ദാസന്മാരും പരിചാരികമാരും പെൺകഴുതകളും ഒട്ടകങ്ങളും ലഭിച്ചു.","p":1},{"v":17,"t":"പക്ഷെ, കർത്താവ് അബ്രാമിന്റെ ഭാര്യ സാറായിയെ പ്രതി ഫറവോയെയും കുടുംബത്തെയും മഹാബാധകളാൽ പ്രഹരിച്ചു.","p":1},{"v":18,"t":"ഫറവോ അബ്രാമിനെ വിളിച്ചു പറഞ്ഞു: നീ എന്നോട് എന്താണീ ചെയ്തത്? അവൾ നിന്റെ ഭാര്യയാണെന്ന് എന്തുകൊണ്ട് എന്നോടു പറഞ്ഞില്ല?","p":1},{"v":19,"t":"ഞാനവളെ എന്റെ ഭാര്യയാക്കത്തക്കവിധം നീ എന്തിനാണ്, അവൾ എന്റെ സഹോദരിയാണ് എന്നു പറഞ്ഞത്? ഇപ്പോൾ ഇതാ, നിന്റെ ഭാര്യ; അവളെയുംകൊണ്ടു സ്ഥലവിടുക.","p":1},{"v":20,"t":"ഫറവോ അവനെക്കുറിച്ച് ആളുകൾക്കു കല്പനകൊടുത്തു. അവർ അവനെയും ഭാര്യയെയും അവനു സ്വന്തമായുണ്ടായിരുന്ന സകലത്തോടും കൂടെ പറഞ്ഞയച്ചു","p":1}],"13":[{"h":"അബ്രാം തിരികെ ബേഥേലിൽ"},{"v":1,"t":"അബ്രാം ഭാര്യയോടും സ്വന്തമായ സകലത്തോടും കൂടെ ഈജിപ്തിൽനിന്ന് നെഗെബിലേക്കു കയറിപ്പോയി ലോത്തും അവനോടുകൂടെയുണ്ടായിരുന്നു.","p":1},{"v":2,"t":"കന്നുകാലികൾ, വെള്ളി, സ്വർണ്ണം എന്നിവയാൽ അബ്രാം ഏറെ സമ്പന്നനായിരുന്നു."},{"v":3,"t":"അവൻ നെഗെബിൽനിന്നു യാത്രചെയ്ത് ബേഥേൽ വരെയും ബേഥേലിനും ആയിക്കുമിടയ്ക്ക്, മുമ്പ് തന്റെ കൂടാരം ഉണ്ടായിരുന്നതും മുമ്പ് ബലിപീഠം പണിതതുമായ സ്ഥലംവരെയുമെത്തിച്ചേർന്നു."},{"v":4,"t":"അവിടെ അബ്രാം കർത്താവിന്റെ നാമം വിളിച്ചപേക്ഷിച്ചു."},{"h":"അബ്രാമും ലോത്തും വഴിപിരിയുന്നു"},{"v":5,"t":"അബ്രാമിനോടൊപ്പം സഞ്ചരിച്ചിരുന്ന ലോത്തിനും ആടുമാടുകളും കൂടാരങ്ങളുമുണ്ടായിരുന്നു.","p":1},{"v":6,"t":"അവർക്ക് ഒന്നിച്ചുതാമസിക്കാൻ ആ ദേശം മതിയായില്ല. കാരണം, അവരുടെ കാലിസമ്പത്ത് ഏറെയായിരുന്നു. അവർ ഒന്നിച്ചുപാർക്കുകയെന്നത് അസാധ്യമായിരുന്നു.","p":1},{"v":7,"t":"മാത്രമല്ല, അബ്രാമിന്റെ കാലിമേയ്ക്കുന്നവരും ലോത്തിന്റെ കാലിമേയ്ക്കുന്നവരും തമ്മിൽ കലഹവുമുണ്ടായി. അക്കാലത്ത് കാനാന്യരും പെരിസ്യരും അന്നാട്ടിൽ പാർത്തിരുന്നു.","p":1},{"v":8,"t":"അബ്രാം ലോത്തിനോടു പറഞ്ഞു: ഞാനും നീയും തമ്മിലും എന്റെ ഇടയന്മാരും നിന്റെ ഇടയന്മാരും തമ്മിലും ഒരിക്കലും കലഹമുണ്ടാകാതിരിക്കട്ടെ. കാരണം, നമ്മൾ സഹോദരന്മാരാണ്."},{"v":9,"t":"ദേശമെല്ലാം നിന്റെ കണ്മുമ്പിലില്ലേ? നിനക്ക് എന്നെ വിട്ടുപോകാം. നീ ഇടത്തേക്കെങ്കിൽ ഞാൻ വലത്തേക്കു പോയിക്കൊള്ളാം; നീ വലത്തേക്കെങ്കിൽ ഞാൻ ഇടത്തേക്കു പോയിക്കൊള്ളാം."},{"v":10,"t":"ലോത്ത് കണ്ണുകളുയർത്തി ജോർദ്ദാൻസമതലം അപ്പാടെ കണ്ടു. കർത്താവ് സോദോമുംഗൊമോറയും നശിപ്പിക്കുന്നതിനുമുമ്പ് അതു മുഴുവൻ കർത്താവിന്റെ തോട്ടംപോലെയും ഈജിപ്തുദേശം പോലെയും നീരോട്ടമുള്ള പ്രദേശമായിരുന്നു. അത് സോവാരിലേക്കുള്ള ദിശയിലാണ്.","p":1},{"v":11,"t":"ജോർദ്ദാൻസമതലം മുഴുവൻ ലോത്ത് തനിക്കുവേണ്ടി തിരഞ്ഞെടുത്തു. അവൻ കിഴക്കോട്ടു യാത്രതിരിച്ചു. അങ്ങനെ അവർ തമ്മിൽ പിരിഞ്ഞു.","p":1},{"v":12,"t":"അബ്രാം കാനാൻദേശത്തു താമസമാക്കി. ലോത്ത് സമതലത്തിലെ നഗരങ്ങളിൽ പാർത്തു.","p":1},{"v":13,"t":"സോദോമിലെ ആളുകൾ കർത്താവിന്റെ മുമ്പിൽ കൊടിയ ദുഷ്ടരും പാപികളുമായിരുന്നു.","p":1},{"v":14,"t":"ലോത്ത് അവനിൽനിന്ന് വേർപിരിഞ്ഞശേഷം കർത്താവ് അബ്രാമിനോട് അരുളിച്ചെയ്തു: നീ ആയിരിക്കുന്ന സ്ഥലത്തുനിന്നുകൊണ്ട് കണ്ണകളുയർത്തി വടക്കോട്ടും തെക്കോട്ടും കിഴക്കോട്ടും പടിഞ്ഞാറോട്ടും നോക്കുക.","p":1},{"v":15,"t":"എന്തെന്നാൽ, നീ കാണുന്ന പ്രദേശമെല്ലാം നിനക്കും നിന്റെ സന്തതിക്കും എന്നേക്കുമായി ഞാൻ നൽകും.","p":1},{"v":16,"t":"നിന്റെ സന്തതിയെ ഞാൻ ഭൂമിയിലെ പൂഴിപോലെയാക്കും. ഭൂമിയിലെ പുഴി ആർക്കെങ്കിലും എണ്ണാനാവുമെങ്കിൽ നിന്റെ സന്തതിയെയും എണ്ണാം.","p":1},{"v":17,"t":"എഴുന്നേറ്റ് ദേശത്തിനു നെടുകേയും കുറുകെയും ഉലാത്തുക; അത് ഞാൻ നിനക്കു തരുന്നു.","p":1},{"v":18,"t":"അബ്രാം കൂടാരം മാറ്റി ഹെബ്രോണിലുള്ള മാമ്രേയുടെ ഓക്കു മരങ്ങൾക്കു സമീപം താമസമാക്കി. അവിടെ അവൻ കർത്താവിനു ഒരു ബലിപീഠം പണിതു.","p":1}],"14":[{"h":"അബ്രാമും മെൽക്കിസെദെക്കും"},{"v":1,"t":"ഷീനാർരാജാവായ അമ്റാഫേൽ, എല്ലാസർ രാജാവായ അരിയൊക്ക്, ഏലാം രാജാവായ കെദോർലാവോമർ, ഗോയിം രാജാവായ തിദാൽ എന്നിവർ, തങ്ങളുടെ കാലത്ത് .","p":1},{"v":2,"t":"സോദോം രാജാവായ ബേറാ, ഗൊമോറ രാജാവായ ബീർഷ, അദ്മാ രാജാവായ ഷീനാബ്, സെബോയിം രാജാവായ ഷെമെബർ, ബേലയുടെ, അതായത് സോവാറിന്റെ രാജാവ് എന്നിവരോടു യുദ്ധംചെയ്തു. ഇവർക്കെല്ലാവരും സിദ്ദീം താഴ്‌വരയിൽ അണിനിരന്നവരായിരുന്നു.","p":1},{"v":3,"t":"ഉപ്പു കടലായ സിദ്ധിമിന്റെ താഴ്‌വരയിൽ ഇവരെല്ലാം സഖ്യത്തിലായി.","p":1},{"v":4,"t":"ഇവർ പന്ത്രണ്ടു വർഷം കെദോർലാവോമറിനെ സേവിച്ചു; പതിമൂന്നാം വർഷം അവർ കലാപമുയർത്തി.","p":1},{"v":5,"t":"പതിനാലാം വർഷം കെദോർലാവോമറും കൂടെയുണ്ടായിരുന്ന രാജാക്കന്മാരും ചെന്ന് അഷ്‌തെരോത്ത് കർണായിമിൽ റാഫാഭകളെയും ഹാമിൽ സുസീമുകളെയും ഷാവേക്കിരിയാത്തായിമിൽ എമീമുകളെയും"},{"v":6,"t":"സേയീർമലകളിൽ ഹോരികളെയും അടിച്ചമർത്തി. അവർ മരുഭൂമിയുടെ അരികിലുള്ള എൽപാരാൻ വരെയെത്തി.","p":1},{"v":7,"t":"അവർ പിന്തിരിഞ്ഞ് എൻമിഷ്പാത്തിൽ അതായത്, കാദേഷിൽ ചെന്ന് അമലേക്കുകളുടെ നാടുകളെയും നശിപ്പിച്ചു; ആസ്സസോൻതാമാറിൽ പാർത്തിരുന്ന അമോര്യരെയും.","p":1},{"v":8,"t":"അപ്പോൾ സോദോംരാജാവ്, ഗൊമോറരാജാവ്, അദ്മാരാജാവ്, സെബോയിംരാജാവ്, ഷെമെബർ അതായത്, സോവാറിലെ രാജാവ് എന്നിവർ പുറപ്പെട്ട് സിദ്ദീം താഴ്‌വരയിൽ യുദ്ധത്തിനൊരുങ്ങി -","p":1},{"v":9,"t":"ഏലാം രാജാവായ കെദോർലാവോമർ, ഗോയിം രാജാവായ തിദാൽ, ഷീനാർരാജാവായ അമ്റാഫേൽ, എല്ലസാർ രാജാവായ അരിയൊക്ക് എന്നിവർക്കെതിരെ, നാലു രാജാക്കന്മാർ അഞ്ചുപേർക്കെതിരെ.","p":1},{"v":10,"t":"സിദ്ദീം താഴ്‌വര മുഴുവൻ കളിമൺ കുഴികളായിരുന്നു. പിന്തിരിഞ്ഞോടിയപ്പോൾ സോദോമിലെയും ഗൊമോറയിലെയും രാജാക്കന്മാർ അതിൽ വീണു. ശേഷിച്ചവർ മലയിലേക്കു ഓടിപ്പോയി.","p":1},{"v":11,"t":"സോദോമിലെയും ഗൊമോറയിലെയും സർവ സമ്പത്തും ഭക്ഷണസാധനങ്ങളും അവർ കവർന്നു കൊണ്ടുപോയി.","p":1},{"v":12,"t":"അബ്രാമിന്റെ സഹോദരപുത്രനായ ലോത്തിനെയും അവന്റെ സമ്പത്തോടുംകൂടെ അവർ പിടിച്ചുകൊണ്ടുപോയി. അവൻ അപ്പോൾ സോദോമിൽ പാർക്കുകയായിരുന്നു.","p":1},{"v":13,"t":"രക്ഷപ്പെട്ട ഒരുവൻ വന്ന് ഹെബ്രായനായ അബ്രാമിനെ വിവരമറിയിച്ചു. അവൻ അപ്പോൾ എഷ്കോലിന്റെയും ആനേറിന്റെയും സഹോദരൻ അമോര്യനായ മാമ്രേയുടെ ഓക്കുമരത്തോപ്പിനു സമീപം താമസിക്കുകയായിരുന്നു. അവർ അബ്രാമിന്റെ ഉടമ്പടിയിൽ പങ്കാളികളായിരുന്നു.","p":1},{"v":14,"t":"സഹോദരൻ തടവുകാരനാക്കപ്പെട്ടെന്ന് അബ്രാം കേട്ടപ്പോൾ തന്റെ വീട്ടിൽ ജനിച്ചുവളർന്നവരും പയറ്റി തെളിഞ്ഞ വരുമായ മുന്നൂറ്റിപ്പതിനെട്ടുപേരെ കൂട്ടി ദാൻവരെ അവരെ പിന്തുടർന്നു.","p":1},{"v":15,"t":"അവനും അവന്റെ ഭൃത്യരും രാത്രിയിൽ വിവിധഗണങ്ങളായിപ്പിരിഞ്ഞ് അവരെ ആക്രമിച്ച് ദമാസ്കസിനു വടക്കുള്ള ഹോബാവരെ അവരെ പിന്തുടർന്നു.","p":1},{"v":15,"t":"15 അവനും അവൻ്റെ സേവകരും രാത്രി വിവിധ ഗണങ്ങളായി","p":1},{"v":15,"t":"തിരിഞ്ഞ് അവരെ ആക്രമിച്ചു.ദമാസ്കസിന് വടക്കുള്ള ഹോബാ വരെ അവൻ അവരെ പിന്തുടർന്നു","p":1},{"v":16,"t":"അവൻ സർവ്വ സമ്പത്തും തിരികെ കൊണ്ടുവന്നു കൂടാതെ അവൻ്റെ സഹോദരൻ ലോകത്തിനെയും അവൻ്റെ സമ്പത്തും ഒപ്പം സ്ത്രീകളെയും ജനങ്ങളെയും തിരികെ കൊണ്ടുവന്നു","p":1},{"v":17,"t":"കെദൊർലാവോമെറെയും കൂടെയുണ്ടായിരുന്ന രാജാക്കന്മാരെയും തോല്പിച്ച് അവൻ മടങ്ങി വന്നശേഷം, അവനെ സന്ദർശിക്കാൻ സോദോംരാജാവ്, രാജാവിന്റെ താഴ്‌വര എന്നറിയപ്പെടുന്ന ഷാവേ താഴ്‌വരയിലേക്ക് പുറപ്പെട്ടു.","p":1},{"v":18,"t":"ശാലേംരാജാവായ മെൽക്കിസെദേക്ക് അപ്പവും വീഞ്ഞും കൊണ്ടുവന്നു. അദ്ദേഹം അത്യുന്നത ദൈവത്തിന്റെ പുരോഹിതനായിരുന്നു.","p":1},{"v":19,"t":"അദ്ദേഹം അബ്രഹാമിനെ ആശീർവദിച്ചുകൊണ്ട് പറഞ്ഞു:","p":1},{"v":19,"t":"ആകാശത്തിന്റെയും ഭൂമിയുടെയും നാഥനായ അത്യുന്നത ദൈവത്താൽ അബ്രാം അനുഗ്രഹീതൻ!","p":1},{"v":20,"t":"നിന്റെ എതിരാളികളെ നിന്റെ കൈയിലേല്പിച്ച അത്യുന്നത ദൈവം വാഴ്ത്തപ്പെട്ടവൻ!","p":1},{"v":20,"t":"അവൻ എല്ലാറ്റിന്റെയും ദശാംശം അദ്ദേഹത്തിനു കൊടുത്തു.","p":1},{"v":21,"t":"സോദോംരാജാവ് അബ്രാമിനോടു പറഞ്ഞു: ആളുകളെ എനിക്കു തരൂ; സമ്പത്ത് നീ എടുത്തുകൊള്ളുക.","p":1},{"v":22,"t":"അബ്രാം സോദോംരാജാവിനോടു പറഞ്ഞു: ആകാശത്തിന്റെയും ഭൂമിയുടെയും ഉടമയായ അത്യുന്നതദൈവം എന്ന കർത്താവിങ്കലേക്ക് ഞാൻ എന്റെ കരമുയർത്തുന്നു.","p":1},{"v":23,"t":"ഞാൻ അബ്രാമിനെ സമ്പന്നനാക്കി എന്നു നീ പറയാതിരിക്കാൻ ഒരു ചരടോ ചെരുപ്പിന്റെ വാറോ നിന്റേതായ ഒന്നുതന്നെയോ ഞാൻ എടുക്കുകയില്ല.","p":1},{"v":24,"t":"യുവാക്കൾ ഭക്ഷിച്ചതും എന്റെ കൂടെ വന്ന ആളുകളുടെ പങ്കുമൊഴികെ, ആനർ, എഷ്കോൽ, മാമ്രെ എന്നിവർ തങ്ങളുടെ പങ്ക് എടുത്തുകൊള്ളട്ടെ","p":1}],"15":[{"h":"ദൈവവും അബ്രാമും തമ്മിൽ ഉടമ്പടി"},{"v":1,"t":"ഈ സംഭവങ്ങൾക്കുശേഷം അബ്രാമിന് ദർശനത്തിൽ കർത്താവിന്റെ വചനം ഇപ്രകാരം ഭവിച്ചു: അബ്രാം, ഭയപ്പെടേണ്ട. ഞാൻ നിനക്കു പരിചയാണ്. നിന്റെ പ്രതിഫലം വളരെ വലുതായിരിക്കും.","p":1},{"v":2,"t":"അബ്രാം ചോദിച്ചു: എന്റെ നാഥനായ കർത്താവേ, അങ്ങ് എനിക്കെന്താണ് തരിക? ഞാൻ ഇപ്പോഴും സന്താനരഹിതനായിത്തന്നെ കഴിയുന്നു. ദമാസ്കസ്സുകാരൻ എലിയേസറാണ് എന്റെ വീടിന്റെ കാര്യസ്ഥൻ."},{"v":3,"t":"തുടർന്ന് അബ്രാം പറഞ്ഞു: നോക്കൂ, എനിക്കൊരു സന്താനത്തെ അങ്ങ് തന്നിട്ടില്ല. ഇതാ, എന്റെ ഭവനത്തിലെ ഒരംഗമായിരിക്കും എന്റെ അനന്തരാവകാശി.","p":1},{"v":4,"t":"അപ്പോൾ അവന് കർത്താവിന്റെ വചനം ഇപ്രകാരം ഉണ്ടാവുകയുണ്ടായി: അവനല്ല നിന്റെ അനന്തരാവകാശിയാകുന്നത്; പ്രത്യുത, നിന്റെ ഉള്ളിൽനിന്നു പുറപ്പെടുന്നവൻ തന്നെ നിന്റെ അനന്തരാവകാശിയാകും.","p":1},{"v":5,"t":"അവിടുന്ന് അവനെ പുറത്തേക്കു കൊണ്ടുവന്നിട്ട് പറഞ്ഞു: ആകാശത്തേക്കു നോക്കുക; നക്ഷത്രങ്ങളെ എണ്ണുക, അവയെ എണ്ണാൻ നിനക്കു കഴിയുമെങ്കിൽ! അവിടുന്ന് തുടർന്ന് അവനോടു പറഞ്ഞു: അതുപോലെയായിരിക്കും നിന്റെ സന്തതിയും.","p":1},{"v":6,"t":"അവൻ കർത്താവിൽ വിശ്വസിച്ചു; അത് അവിടുന്ന് അവന് നീതിയായി പരിഗണിക്കുകയും ചെയ്തു.","p":1},{"v":7,"t":"അവിടുന്ന് തുടർന്ന് അവനോട് അരുളിച്ചെയ്തു: ഈ നാട് നിനക്ക് അവകാശമായിത്തരാൻവേണ്ടി നിന്നെ കല്ദായരുടെ ഊറിൽനിന്നു കൂട്ടിക്കൊണ്ടുവന്ന കർത്താവാണു ഞാൻ.","p":1},{"v":8,"t":"അവൻ ചോദിച്ചു: എന്റെ നാഥനായ കർത്താവേ, ഇതു ഞാൻ അവകാശമാക്കുമെന്ന് ഞാൻ എങ്ങനെ അറിയും?","p":1},{"v":9,"t":"അവിടുന്ന് അവനോടു പറഞ്ഞു: മൂന്നു വയസ്സു പ്രായമുള്ള ഒരു പശുക്കിടാവ്, മൂന്നു വയസ്സു പ്രായമുള്ള ഒരു പെണ്ണാട്, മൂന്നു വയസ്സു പ്രായമുള്ള ഒരു മുട്ടാട് എന്നിവയെയും ഒരു ചെങ്ങാലിയെയും പ്രാവിൻ കുഞ്ഞിനെയും എനിക്കായി കൊണ്ടുവരുക.","p":1},{"v":10,"t":"അവൻ അവയെല്ലാം അവിടേക്കായി കൊണ്ടുവന്ന് അവ നെടുകെ പിളർന്ന് കഷ്ണങ്ങൾ നേർക്കുനേർ വെച്ചു. എന്നാൽ പക്ഷികളെ അവൻ പിളർന്നില്ല.","p":1},{"v":11,"t":"ജഡത്തിന്മേൽ റാഞ്ചൽ പക്ഷികൾ ഇറങ്ങിവന്നപ്പോൾ അബ്രാം അവയെ ആട്ടിയോടിച്ചു.","p":1},{"v":12,"t":"സൂര്യൻ അസ്തമിച്ചുകൊണ്ടിരുന്നപ്പോൾ അബ്രഹാമിന്റെമേൽ ഒരു ഗാഢനിദ്ര പതിച്ചു. ഇതാ, കൂരിരുളാർന്ന ഒരു ഭീതി അവന്റെമേൽ നിപതിക്കുന്നു.","p":1},{"v":13,"t":"അപ്പോൾ കർത്താവ് അബ്രാമിനോട് അരുളിച്ചെയ്തു: നീ ഇത് ഉറപ്പായും അറിഞ്ഞുകൊള്ളുക. നിന്റെ സന്തതി തങ്ങളുടേതല്ലാത്ത നാട്ടിൽ പ്രവാസികളായിരിക്കും. അവർ അക്കൂട്ടർക്ക് ദാസവേല ചെയ്യും; അവരാകട്ടെ നാന്നൂറു കൊല്ലം അവരെ കഷ്ടപ്പെടുത്തും.","p":1},{"v":14,"t":"എന്നാൽ അവർ സേവിക്കുന്ന ജനതയെ ഞാൻ വിധിക്കും; അതിനുശേഷം ധാരാളം സമ്പത്തുമായി അവർ പുറത്തുവരും.","p":1},{"v":15,"t":"നീയാകട്ടെ, സമാധാനത്തോടെ നിന്റെ പിതാക്കന്മാരോടു ചേരും. വാർദ്ധക്യത്തിൽ നീ സംസ്കരിക്കപ്പെടും.","p":1},{"v":16,"t":"നാലാംതലമുറയിൽ അവർ ഇങ്ങോട്ട് തിരിച്ചുപോരും. എന്തെന്നാൽ, അമോര്യരുടെ ദുഷ്ടത ഇനിയും പൂർത്തിയായിട്ടില്ല.","p":1},{"v":17,"t":"സൂര്യൻ അസ്തമിച്ചപ്പോൾ കനത്ത അന്ധകാരം ഉണ്ടായി ഇതാ, പുകയുന്ന തീച്ചുളയും ജ്വലിക്കുന്ന തീനാളവും ആ കഷ്ണങ്ങളുടെ നടുവിലൂടെ കടന്നുപോയി.","p":1},{"v":18,"t":"ആ ദിവസം തന്നെ കർത്താവ് അബ്രാമുമായി ഇപ്രകാരം ഉടമ്പടി ചെയ്തു നിന്റെ സന്തതിക്ക് ഈ നാടു ഞാൻ തന്നിരിക്കുന്നു;","p":1},{"h":"ഈജിപ്തുനദി മുതൽ മഹാനദിയായ യൂഫ്രട്ടീസ് നദിവരെയുള്ള"},{"v":19,"t":"കേന്യർ, കെനീസ്യർ, കദ്മോന്യർ,","p":1},{"v":19,"t":"ഹിത്യർ, പെരിസ്യർ, റഫായീം, അമോര്യർ, കാനാൻ","p":1},{"v":19,"t":"ന്യർ, ഗിർഗാശ്യർ, ജബൂസ്യർ എന്നിവരെത്തന്നെ..","p":1}],"16":[{"h":"ഹാഗാറും ഇസ്മായേലും"},{"v":1,"t":"അബ്രാമിന്റെ ഭാര്യ സാറായി പ്രസവിച്ചിരുന്നില്ല. അവൾക്കു ഹാഗാർ എന്നു പേരുള്ള ഈജിപ്തുകാരിയായ ഒരു പരിചാരിക ഉണ്ടായിരിന്നു.","p":1},{"v":2,"t":"സാറായി അബ്രാമിനോടു പറഞ്ഞു: ഇതാ, പ്രസവിക്കുന്നതിൽനിന്നു കർത്താവു എന്നെ തടഞ്ഞിരിക്കുന്നു. അങ്ങ് എന്റെ പരിചാരികയെ പ്രാപിക്കുക. ഒരുപക്ഷേ,അവളിൽനിന്നു ഞാൻ പുത്രലബ്ധയാകും. അബ്രാം സാറായിയുടെ വാക്ക് ശ്രവിച്ചു.","p":1},{"v":3,"t":"അബ്രാമിന്റെ കാനാൻ ദേശവാസം പത്തു വർഷം പിന്നിട്ടപ്പോൾ അബ്രാമിന്റെ ഭാര്യ സാറായി തന്റെ പരിചാരികയായ ഈജിപ്തുകാരി ഹാഗാറിനെ ഭർത്താവായ അബ്രാമിനു ഭാര്യയായി നൽകി.","p":1},{"v":4,"t":"അവൻ ഹാഗാറിനെ പ്രാപിക്കുകയും അവൾ ഗർഭം ധരിക്കുകയും ചെയ്തു. താൻ ഗർഭിണിയാണെന്നു കണ്ടപ്പോൾ തന്റെ യജമാനത്തി അവളുടെ ദൃഷ്ടികളിൽ വിലകെട്ടവളായിത്തീർന്നു.","p":1},{"v":5,"t":"അപ്പോൾ സാറായി അബ്രാമിനോടു പറഞ്ഞു: എന്റെ ദുരിതം നിങ്ങളുടെമേൽ ആയിരിക്കട്ടെ! ഞാനാണ് എന്റെ പരിചാരികയെ നിങ്ങളുടെ മാറിലേക്കുവിട്ടു തന്നത്. പക്ഷേ, അവൾ ഗർഭിണിയാണെന്നു കണ്ടപ്പോൾ, ഞാൻ അവളുടെ ദൃഷ്ടികളിൽ വിലകെട്ടവളായി എനിക്കും നിങ്ങൾക്കും മധ്യേ കർത്താവു ന്യായം വിധിക്കട്ടെ.","p":1},{"v":6,"t":"അബ്രാം സാറായിയോടു പറഞ്ഞു: ഇതാ, നിന്റെ പരിചാരിക നിന്റെ കയ്യിൽത്തന്നെയാണ്. നിന്റെ ദൃഷ്ടിയിൽ ശരിയായത് അവളോടു ചെയ്തുകൊള്ളുക. സാറായി അവളെ കഷ്ടപ്പെടുത്താൻ തുടങ്ങി. അപ്പോൾ അവൾ അവളുടെ മുമ്പിൽനിന്നു ഓടിപ്പോയി.","p":1},{"v":7,"t":"എന്നാൽ, കർത്താവിന്റെ ദൂതൻ മരുഭൂമിയിലുള്ള ഒരു നീരുറവയുടെ, ഷൂറിലേക്കുള്ള വഴിയിലുള്ള ഉറവയുടെ, അരികിൽ അവളെ കണ്ടെത്തി."},{"v":8,"t":"അവൻ ചോദിച്ചു: സാറായിയുടെ പരിചാരികയായ ഹാഗാർ, നീ എവിടെനിന്നു വരുന്നു? എങ്ങോട്ടുപോകുന്നു? അവൾ മറുപടി പറഞ്ഞു: ഞാൻ എന്റെ യജമാനത്തിയായ സാറായിയുടെ മുമ്പിൽനിന്നു ഓടിപ്പോവുകയാണ്."},{"v":9,"t":"കർത്താവിന്റെ ദൂതൻ അവളോടു പറഞ്ഞു: നിന്റെ യജമാനത്തിയുടെ അടുത്തേക്കു തിരിച്ചപോയി നീ അവളുടെ കാര്യങ്ങൾക്കു കീഴെ എളിമപ്പെടുക.","p":1},{"v":10,"t":"കർത്താവിന്റെ ദൂതൻ അവളോടു തുടർന്നുപറഞ്ഞു: എണ്ണിയാൽ തീരാത്തവണ്ണം അത്രയധികമായി നിന്റെ സന്തതിയെ ഞാൻ തീർച്ചയായും വർധിപ്പിക്കും."},{"v":11,"t":"കർത്താവിന്റെ ദൂതൻ അവളോടു പറഞ്ഞു: ഇതാ, നീ ഗർഭവതിയായിരിക്കുന്നു നീ ഒരു പുത്രനെ പ്രസവിക്കും. ഇസ്മായേൽ എന്നു നീ അവനു പേരിടണം. കാരണം, കർത്താവു നിന്റെ കഷ്ടത ശ്രവിച്ചിരിക്കുന്നു.","p":1},{"v":12,"t":"കാട്ടുക്കഴുതക്കൊത്ത മനുഷ്യനായിരിക്കും അവൻ. അവന്റെ കൈ എല്ലാവർക്കുമെതിരേയും എല്ലാവരുടെയും കൈ അവനെതിരേയും ആയിരിക്കും. തന്റെ എല്ലാ സഹോദരങ്ങൾക്കുമെതിരായി അവൻ വാസമുറപ്പിക്കും."},{"v":13,"t":"തന്നോടു സംസാരിച്ച കർത്താവിന് അവൾ അത്താ എൽ റോയി എന്നു പേരിട്ടു. കാരണം, എന്നെ കാണുന്നവനായ ദൈവത്തെ പിന്നീട് ഞാനും ഇവിടെവെച്ചുകണ്ടല്ലോ എന്ന് അവൾ പറഞ്ഞു.","p":1},{"v":14,"t":"അതുകൊണ്ട് ആ കിണറിനെ ബേർ-ലഹായ്-റോയി എന്നു വിളിച്ചു. അത് കാദേശിനും ബേരെദിനും ഇടയ്ക്കാണ്.","p":1},{"v":15,"t":"ഹാഗാർ അബ്രാമിനു ഒരു പുത്രനെ പ്രസവിച്ചു. ഹാഗാർ പ്രസവിച്ച തന്റെ പുത്രന് അബ്രാം, ഇസ്മായേൽ എന്നു പേരിട്ടു.","p":1},{"v":16,"t":"ഹാഗാർ അബ്രാമിനുവേണ്ടി ഇസ്മായേലിനെ പ്രസവിക്കുമ്പോൾ അബ്രാമിന് എൺപത്താറു വയസ്സായിരുന്നു.","p":1}],"17":[{"h":"ഉടമ്പടിയും പരിച്ഛേദനവും"},{"v":1,"t":"അബ്രാമിന് തൊണ്ണൂറ്റൊമ്പതു വയസ്സായപ്പോൾ കർത്താവു അബ്രാമിനു പ്രത്യക്ഷപ്പെട്ട് അവനോട് അരുളിച്ചെയ്തു: ഞാൻ സർവശക്തനായ ദൈവം ആകുന്നു. എന്റെ മുമ്പിൽ വ്യാപരിക്കുക. പൂർണ്ണനായിരിക്കുക.","p":1},{"v":2,"t":"എന്റെ ഉടമ്പടി എനിക്കും നിനക്കുമിടയിൽ ഞാൻ സ്ഥാപിക്കും. ഞാൻ നിന്നെ അത്യധികം വർധിപ്പിക്കും.","p":1},{"v":3,"t":"അപ്പോൾ അബ്രാം മുഖംമുട്ടേ കുമ്പിട്ടു. ദൈവം അവനോട് ഇപ്രകാരം അരുളിച്ചെയ്തു:"},{"v":4,"t":"ഇതാ, നിന്നോടുകൂടെ ഞാൻ എന്റെ ഉടമ്പടി ചെയ്യുന്നു. നീ ജനതതികളുടെ പിതാവായിത്തീരും.","p":1},{"v":5,"t":"ഇനിമേൽ നിന്റെ പേര് അബ്രാം എന്നല്ല വിളിക്കപ്പെടുകയില്ല; പ്രത്യുത, നിന്റെ പേര് അബ്രാഹം എന്നായിരിക്കും എന്തെന്നാൽ, ഞാൻ നിന്നെ ജനതകളുടെ പിതാവാക്കിയിരിക്കുന്നു.","p":1},{"v":6,"t":"ഞാൻ നിന്നെ അത്യധികം സന്താനപുഷ്ടിയുള്ളവനാക്കും. നിന്നെ ഞാൻ ജനതകളാക്കിയിരിക്കുന്നു. രാജാക്കന്മാർ നിന്നിൽ നിന്ന് പുറപ്പെടും.","p":1},{"v":7,"t":"ഞാൻ നിനക്കും നിനക്കുശേഷം നിന്റെ സന്തതിക്കും ദൈവമായിരിക്കേണ്ടതിന് ഞാനും നീയും തമ്മിലും നിനക്കുശേഷം നിന്റെ സന്തതിയും തമ്മിലുള്ള എന്റെ ഉടമ്പടി ഞാൻ ഉയർത്തിയിരിക്കുന്നു. അവരുടെ തലമുറകൾക്ക് ഇത് ശാശ്വത ഉടമ്പടിയായിരിക്കും.","p":1},{"v":8,"t":"നിന്റെ പ്രവാസത്തിന്റെ ദേശം, കാനാൻ ദേശം മുഴുവനും എന്നേക്കുമുളള അവകാശമായി നിനക്കും നിനക്കുശേഷം നിന്റെ സന്തതിക്കും ഞാൻ തരും; അവർക്കു ഞാൻ ദൈവമായിരിക്കുകയും ചെയ്യും.","p":1},{"v":9,"t":"ദൈവം അബ്രാഹത്തോടു അരുളിച്ചെയ്തു:നീ, നീയും നിനക്കുശേഷമുള്ള നിന്റെ സന്തതിയും അവരുടെ തലമുറകളും, എന്റെ ഉടമ്പടി പാലിക്കണം.","p":1},{"v":10,"t":"എനിക്കു നിങ്ങളോടും നിനക്കുശേഷം നിന്റെ സന്തതിയോടും ഉളളതും നിങ്ങൾ പാലിക്കേണ്ടതുമായ എന്റെ ഉടമ്പടി ഇതാണ്: നിങ്ങളുടെ പുരുഷന്മാരെല്ലാം പരിച്ഛേദനം ചെയ്യപ്പെടണം.","p":1},{"v":11,"t":"നിങ്ങൾ നിങ്ങളുടെ അഗ്രചർമം ഛേദിക്കണം. അത് ഞാനും നിങ്ങളുമായുള്ള ഉടമ്പടിയുടെ അടയാളമായിരിക്കും."},{"v":12,"t":"നിങ്ങളിൽ, നിങ്ങളുടെ തലമുറകളിൽ എട്ടു ദിവസം പ്രായമായ ഓരോ ആൺകുട്ടിയും, അവൻ നിന്റെ വീട്ടിൽ പിറന്നവനോ നിന്റെ സന്താനത്തിൽപ്പെടാത്ത, വിലയ്ക്കു വാങ്ങപ്പെട്ട പരദേശിയോ ആകട്ടെ, പരിച്ഛേദനം ചെയ്യപ്പെടണം.","p":1},{"v":13,"t":"നിന്റെ വീട്ടിൽ പിറന്നവനും നീ വിലയ്ക്കു വാങ്ങിയവനും നിശ്ചയമായും പരിച്ഛേദനം ചെയ്യപ്പെടണം. അങ്ങനെ എന്റെ ഉടമ്പടി നിങ്ങളുടെ ശരീരത്തിൽ ശാശ്വതമായി ഒരു ഉടമ്പടിയായിരിക്കും.","p":1},{"v":14,"t":"അഗ്രചർമം നീക്കം ചെയ്യപ്പെടാത്ത പുരുഷൻ അപരിച്ഛേദിതനാണ്. ആ വ്യക്തി തന്റെ ജനത്തിൽനിന്ന് വിച്ഛേദിക്കപ്പെടണം, എന്റെ ഉടമ്പടിയാണ് അവൻ ലംഘിച്ചിരിക്കുന്നത്.","p":1},{"h":"ഇസഹാക്ക്"},{"v":15,"t":"ദൈവം അബ്രാഹത്തോടു അരുൾച്ചെയ്തു: നിന്റെ ഭാര്യ സാറായിയെ ഇനിമേൽ സാറായി എന്നല്ല നീ വിളിക്കേണ്ടത്; മറിച്ച് അവളുടെ പേര് സാറാ എന്നായിരിക്കും.","p":1},{"v":16,"t":"ഞാൻ അവളെ അനുഗ്രഹിക്കും; അവളിൽനിന്നു ഞാൻ നിനക്കൊരു പുത്രനെ നൽകുകയും ചെയ്യും. അവളെ ഞാൻ അനുഗ്രഹിക്കും; അവൾ ജനതകളായിത്തീരും. ജനങ്ങളുടെ രാജാക്കന്മാർ അവളിൽനിന്നു ഉദ്ഭവിക്കും.","p":1},{"v":17,"t":"അപ്പോൾ അബ്രാഹം മുഖം മുട്ടേ കുമ്പിട്ടു; എന്നാൽ, അവൻ ചിരിച്ചുകൊണ്ട് ആത്മഗതം ചെയ്തു: നൂറു വയകാരന് ഒരു പുത്രൻ ജനിക്കുമോ? തൊണ്ണൂറു വയസ്സുകാരി സാറാ പ്രസവിക്കുമോ?","p":1},{"v":18,"t":"അപ്പോൾ അബ്രാഹം ദൈവത്തോടു പറഞ്ഞു: ഇസ്മായേൽ അങ്ങയുടെ മുമ്പിൽ ജീവിച്ചിരുന്നാൽ മതിയായിരുന്നു!"},{"v":19,"t":"ദൈവം അരുൾച്ചെയ്തു: നിന്റെ ഭാര്യ സാറാ തന്നെ നിനക്കൊരു പുത്രനെ പ്രസവിക്കും, നീ അവനു ഇസഹാക് എന്നു പേരു വിളിക്കണം. അവനുമായി ഞാൻ എന്റെ ഉടമ്പടി ഉറപ്പിക്കും; അവനുശേഷം അവന്റെ സന്തതിക്കും വേണ്ടിയുള്ള ശാശ്വത ഉടമ്പടി.","p":1},{"v":20,"t":"ഇസ്മായീലിന് വേണ്ടിയും ഞാൻ നിന്നെ ശ്രവിച്ചിരിക്കുന്നു. ഇതാ, ഞാൻ അവനെ അനുഗ്രഹിക്കുന്നു; അവൻ അത്യധികം പെരുകി വർധിക്കാൻ ഞാൻ ഇടയാക്കും. അവൻ പന്ത്രണ്ടു പ്രഭുക്കന്മാർക്കു ജന്മമേകും ; അവനെ ഞാൻ വലിയ ഒരു ജനതയാക്കി സ്ഥാപിക്കും.","p":1},{"v":21,"t":"എന്നാൽ, അടുത്തവർഷം ഇതേ സമയത്ത് സാറാ നിനക്കുവേണ്ടി പ്രസവിക്കുന്ന ഇസഹാക്കുമായാണ് എന്റെ ഉടമ്പടി ഞാൻ ഉയർത്തുന്നത്.","p":1},{"v":22,"t":"ദൈവം അബ്രാഹത്തോടു സംസാരിച്ചുകഴിഞ്ഞ് അവനെവിട്ട് ആരോഹണം ചെയ്തു.","p":1},{"v":23,"t":"ദൈവം അബ്രാഹത്തോടു ആവശ്യപ്പെട്ടതുപോലെ മകൻ ഇസ്മായേലിനെയും തന്റെ വീട്ടിൽ പിറന്നവരെയും താൻ വിലകൊടുത്തു വാങ്ങിയവരെയും തന്റെ ഭവനത്തിലുള്ള സകല പുരുഷന്മാരെയും കൊണ്ടു വന്ന് അവൻ ആ ദിവസംതന്നെ അവരുടെ അഗ്രചർമം പരിച്ഛേദനം ചെയ്തു.","p":1},{"v":24,"t":"അഗ്രചർമ്മം പരിച്ഛേദനം ചെയ്യപ്പെടുമ്പോൾ അബ്രാഹത്തിനു തൊണ്ണൂറ്റൊൻപതു വയസ്സായിരുന്നു.","p":1},{"v":25,"t":"അവന്റെ പുത്രൻ ഇസ്മായേലിന് അഗ്രചർമം പരിച്ഛേദനം ചെയ്യപ്പെടുമ്പോൾ പതിമൂന്നു വയസ്സായിരുന്നു.","p":1},{"v":26,"t":"ഒരേ ദിവസമാണ് അബ്രാഹവും മകൻ ഇസ്മായേലും പരിച്ഛേദനം ചെയ്യപ്പെട്ടത്.","p":1},{"v":27,"t":"അവന്റെ വീട്ടിലെ എല്ലാ പുരുഷന്മാരും, വീട്ടിൽ പിറന്നവരും പരദേശികളിൽനിന്ന് വിലയ്ക്കു വാങ്ങിയവരും, അവനോടൊപ്പം പരിച്ഛേദനം ചെയ്യപ്പെട്ടു.","p":1}],"18":[{"v":1,"t":"മാമ്രയുടെ ഓക്ക് മരങ്ങൾക്ക് സമീപം കർത്താവ് അവനു പ്രത്യക്ഷനായി ദിവസത്തിന് ചൂടേറിയപ്പോൾ അവൻ തന്റെ കൂടാരത്തിന്റെ വാതില്ക്കൽ ഇരിക്കുകയായിരുന്നു.","p":1},{"v":2,"t":"അവൻ കണ്ണുകളുയർത്തി നോക്കിയപ്പോൾ ഇതാ, മൂന്നാളുകൾ തനിക്കെതിരെ നില്ക്കുന്നു. അവരെ കണ്ടമാത്രയിൽ അവൻ അവരെ എതിരേൽക്കാൻ കൂടാരവാതില്കൽനിന്ന് ഓടിച്ചെന്ന്, നിലംപറ്റേ കുമ്പിട്ടു.","p":1},{"v":3,"t":"‘അവൻ പറഞ്ഞു: യജമാനനേ, അങ്ങയുടെ ദൃഷ്ടികളിൽ ഞാൻ പ്രീതികണ്ടെത്തിയെങ്കിൽ അങ്ങയുടെ ദാസനെ കടന്നുപോകരുതേ!.","p":1},{"v":4,"t":"കുറച്ചു വെള്ളം കൊണ്ടുവരട്ടെ. നിങ്ങളുടെ പാദങ്ങൾ കഴുകി മരച്ചുവട്ടിൽ വിശ്രമിച്ചാലും.","p":1},{"v":5,"t":"നിങ്ങളുടെ ഈ ദാസന്റെ അടുക്കൽ വന്നനിലയ്ക്ക് ഞാൻ കുറച്ച് അപ്പം കൊണ്ടുവരാം. നിങ്ങളുടെ ഹൃദയം ഉന്മേഷമുള്ളതാക്കി യാത്ര തുടരാം. അവർ പറഞ്ഞു: നീ പറഞ്ഞതുപോലെ ചെയ്തുകൊള്ളുക.","p":1},{"v":6,"t":"അബ്രഹാം കൂടാരത്തിൽ സാറായുടെ അടുത്തേക്ക് കുതിച്ചു. അവൻ പറഞ്ഞു: വേഗം മൂന്നു സെയാ നേരിയ മാവ് കുഴച്ച് അപ്പമുണ്ടാക്കുക.","p":1},{"v":7,"t":"അബ്രഹാം കാലിക്കൂട്ടത്തിലേക്ക് ഓടിച്ചെന്ന് ഇളയതും നല്ലതുമായ ഒരു കാലിക്കൂട്ടിയെ പിടിച്ച് വേലക്കാരനെ ഏൽപ്പിച്ചു. ഉടനെ അയാൾ അത് പാകംചെയ്യാൻ തുടങ്ങി.","p":1},{"v":8,"t":"അവൻ വെണ്ണയും പാലും പാകംചെയ്ത മാംസവും അവരുടെ മുമ്പിൽ വിളമ്പി. അവർ ഭക്ഷിച്ചു. അവനാകട്ടെ, മരച്ചുവട്ടിൽ അവരുടെ സമീപം നിന്നു.","p":1},{"v":9,"t":"അവർ അവനോട് ചോദിച്ചു: നിന്റെ ഭാര്യ സാറാ എവിടെ? ഇതാ, കൂടാരത്തിലുണ്ട്. അവൻ മറുപടി പറഞ്ഞു.","p":1},{"v":10,"t":"അവിടന്നു പറഞ്ഞു: വസന്തകാലത്ത് ഞാൻ തീർച്ചയായും നിന്റെയടുത്ത് മടങ്ങിവരും. അപ്പോൾ നിന്റെ ഭാര്യ സാറായ്ക്ക് ഒരു പുത്രനുണ്ടായിരിക്കും. അവന്റെ പുറകിലെ കൂടാരവാതില്കൽ സാറാ ഇത് കേൾക്കുന്നുണ്ടായിരുന്നു.","p":1},{"v":11,"t":"അബ്രഹവും സാറായും വൃദ്ധരും പ്രായംകഴിഞ്ഞവരുമായിരുന്നു; സാറായ്ക്ക് സ്ത്രീകളുടെ മുറ നിലച്ചുപോയിരുന്നു.","p":1},{"v":12,"t":"അതിനാൽ, സാറാ ചിരിക്കുകയും ഇപ്രകാരം ഉള്ളിൽ പറയുകയും ചെയ്തു: എല്ലാ കൊഴിഞ്ഞുതീർന്നപ്പോൾ എനിക്ക് ഇനിയും ദാമ്പത്യസുഖമോ? എന്റെ ഭർത്താവോ, വൃദ്ധൻ!","p":1},{"v":13,"t":"കർത്താവ് അബ്രഹത്തോടു ചോദിച്ചു: എന്തിനാണ് ‘ഞാൻ വൃദ്ധയായിരിക്കുന്നു; വാസ്തവത്തിൽ, ഞാൻ ഇനി പ്രസവിക്കുമോ’ എന്നു ചോദിച്ചുകൊണ്ട് സാറാ ചിരിക്കുന്നത്?","p":1},{"v":14,"t":"കർത്താവിന് അസാധ്യമായി എന്തെങ്കിലുമുണ്ടോ? നിശ്ചിതസമയത്ത് വസന്തകാലത്ത് ഞാൻ നിന്റെയടുത്ത് മടങ്ങിവരും. അപ്പോൾ സാറായ്ക്ക് ഒരു പുത്രനുണ്ടായിരിക്കും.","p":1},{"v":15,"t":"ഞാൻ ചിരിച്ചില്ല എന്ന് സാറ കള്ളം പറഞ്ഞു. എന്തെന്നാൽ, അവൾ ഭയന്നിരുന്നു. അവിടന്നുഊ പറഞ്ഞു: അല്ല, നീ ചിരിക്കുകതന്നെ ചെയ്തു."},{"h":"സോദോം-ഗോമോറായുടെ നാശം"},{"v":16,"t":"അനന്തരം ആ വ്യക്തികൾ അവിടെനിന്നെഴുന്നേറ്റ് സോദോമിനുനേരെ താഴേക്ക് നോക്കി. അവരെ യാത്രയാക്കാൻ അബ്രഹാം അവരോടൊപ്പം നടന്നു.","p":1},{"v":17,"t":"കർത്താവ് ആത്മഗതം ചെയ്തു: ഞാൻ ചെയ്യാൻ പോകുന്നത് അബ്രാഹത്തി നിന്ന് മറച്ചുവയ്കേണ്ടതുണ്ടോ?","p":1},{"v":18,"t":"അബ്രഹാം നിശ്ചയമായും മഹത്തും ശക്തവുമായ ഒരു ജനതയായിത്തീരും. ഭൂമിയിലെ ജനതകളെല്ലാം അവനിലൂടെ അനുഗ്രഹിക്കപ്പെടും.","p":1},{"v":19,"t":"ഞാൻ അവനെ തിരഞ്ഞെടുത്തിരിക്കുന്നത്, അവൻ തന്റെ മക്കളെയും പിൻമുറക്കാരെയും അനുശാസിക്കാനും അതുവഴി അവർ നീതിയും ന്യായവും പ്രവർത്തിച്ച് കർത്താവിന്റെ മാർഗ്ഗം പാലിക്കാനും. അങ്ങനെ കർത്താവ് അബ്രാത്തെക്കുറിച്ച് പറഞ്ഞിട്ടുള്ളവ അവനിൽ പൂർത്തിയാക്കാനുമാണ്.","p":1},{"v":20,"t":"കർത്താവ് പറഞ്ഞു: സോദോമിന്റെയും ഗോമോറായുടെയും രോദനം തീവ്രവും അവരുടെ പാപം അതീവ ഗുരുതരവുമാണ്.","p":1},{"v":21,"t":"അവർ പ്രവർത്തിച്ചിരിക്കുന്നതൊക്കെയും എന്റെ പക്കലെത്തിയ രോദനംപോലെ തന്നെയാണോ എന്നുകാണാൻ ഞാൻ ഇറങ്ങിച്ചെല്ലട്ടെ; അങ്ങനെയല്ലെങ്കിൽ എനിക്കറിയാമല്ലോ.","p":1},{"v":22,"t":"ആ വ്യക്തികൾ അവിടെനിന്നു തിരിഞ്ഞ് സോദോമിനുനേരെ നടന്നു. അബ്രഹാമാകട്ടെ, അപ്പോഴും കർത്താവിന്റെ മുമ്പിൽത്തന്നെ നിലകൊണ്ടു.","p":1},{"v":23,"t":"അബ്രഹാം അടുത്തെ ചെന്നു ചോദിച്ചു: ദുഷ്ടനോടൊപ്പം നീതിമാനെയും അങ്ങ് തുടച്ചുനീക്കുമോ?","p":1},{"v":24,"t":"ആ നഗരത്തിനുള്ളിൽ അമ്പതു നീതിമാന്മാരുള്ളപക്ഷവും, അങ്ങ് അതിനെ തുടച്ചുനീക്കുമോ?അവിടെയുള്ള ആ അമ്പതു നീതിമാന്മാരെപ്രതി ആ പ്രദേശത്തോട് ക്ഷമിക്കില്ലേ?","p":1},{"v":25,"t":"ദുഷ്ടനോടൊപ്പം നീതിമാനെയും സംഹരിക്കുക - ഇങ്ങനെയൊരു കാര്യം ചെയ്യുകയെന്നത് അങ്ങിൽനിന്ന് അകന്നിരിക്കട്ടെ. നീതിമാനും ദുഷ്ടനും ഒന്നുപോലെയകുകയെന്നതും അങ്ങിൽനിന്ന് അകന്നിരിക്കട്ടെ. ഭൂമി മുഴുവൻ്റെയും വിധികർത്താവ് നീതി പ്രവർത്തിക്കാതിരിക്കുമോ?","p":1},{"v":26,"t":"കർത്താവ് അരുൾചെയ്തു: സോദോമിൽ, ആ നഗരത്തിനുള്ളിൽ അമ്പതു നീതിമാന്മാരെ ഞാൻ കണ്ടെത്തുന്നപക്ഷം, അവരെപ്രതി ഞാൻ ആ പ്രദേശത്തോട് മുഴുവൻ ക്ഷമിക്കും,","p":1},{"v":27,"t":"അബ്രഹാം മറുപടിയായി പറഞ്ഞു: ഇതാ, ഞാൻ എന്റെ നാഥനോട് സംസാരിക്കാൻ തുനിഞ്ഞല്ലോ! ഞാനാകട്ടെ, പൊടിയും ചാരവും","p":1},{"v":28,"t":"ഒരുപക്ഷേ നീതിമാന്മാർ അമ്പതിന് അഞ്ചു കുറവു വന്നാൽ, ആ അഞ്ചിനെപ്രതി നഗരം മുഴുവൻ നശിപ്പിക്കുമോ? അവിടുന്നു അരുളിച്ചെയ്തു: നാൽപ്പത്തഞ്ചുപേരെ ഞാൻ അവിടെ കണ്ടെത്തുകയാണെങ്കിൽ നശിപ്പിക്കുകയില്ല.","p":1},{"v":29,"t":"അവിടത്തോടു തുടർന്നു സംസാരിക്കവേ അവൻ പറഞ്ഞു: ഒരുപക്ഷേ, അവിടെ നാല്പതുപേരെ മാത്രമേ കണ്ടെത്താനുള്ളൂ എങ്കിലോ? അവിടുന്നു അരുളിച്ചെയ്തു: ആ നാല്പതിനെപ്രതി ഞാൻ അതു ചെയ്യുകയില്ല.","p":1},{"v":30,"t":"അവൻ പറഞ്ഞു: എന്റെ യജമാനൻ കോപിക്കരുതേ! ഞാൻ പറഞ്ഞു കൊള്ളട്ടെ: ഒരുപക്ഷേ, അവിടെ മുപ്പതുപേരെ മാത്രമേ കണ്ടെത്താനുള്ളൂ എങ്കിലോ? അവിടുന്നു അരുളിച്ചെയ്തു: അവിടെ ഞാൻ മുപ്പതുപേരെ മാത്രമേ കണ്ടെത്തുകയുള്ളൂവെങ്കിൽ ഞാനതു ചെയ്യുകയില്ല.","p":1},{"v":31,"t":"അവൻ പറഞ്ഞു: ഇതാ, ഞാൻ എന്റെ യജമാനനോട് സംസാരിക്കാൻ തുനിഞ്ഞല്ലോ. ഒരുപക്ഷേ, ഇരുപതുപേരെ മാത്രമേ അവിടെ കണ്ടെത്തുന്നുള്ളൂ എങ്കിലോ? അവിടുന്നു അരുളിച്ചെയ്തു: ആ ഇരുപതുപേരെപ്രതി ഞാൻ നശിപ്പിക്കുകയില്ല.","p":1},{"v":32,"t":"അവൻ പറഞ്ഞു: എന്റെ യജമാനൻ കോപിക്കരുതേ! ഈ ഒരു പ്രാവശ്യം കൂടി ഞാൻ പറഞ്ഞുകൊള്ളട്ടെ: ഒരുപക്ഷേ, പത്തുപേരെ മാത്രമേ അവിടെ കണ്ടെത്തുന്നുള്ളൂ എങ്കിലോ? അവിടുന്നു അരുൾച്ചെയ്തു: ആ പത്തുപേരെപ്രതി ഞാൻ നശിപ്പിക്കുകയില്ല.","p":1},{"v":33,"t":"അബ്രാഹത്തോടു സംസാരിച്ചു കഴിഞ്ഞപ്പോൾ കർത്താവ് യാത്രയായി. അബ്രഹാവും സ്വസ്ഥാനത്തേക്കു മടങ്ങി","p":1}],"19":[{"h":"സോദോമിന്റെ പാപം"},{"v":1,"t":"വൈകുന്നേരം രണ്ടു ദൂതന്മാർ സോദോമിലെത്തി. ലോത്ത് നഗരവാതിൽക്കൽ ഇരിക്കുകയായിരുന്നു. അവരെക്കണ്ടപ്പോൾ ലോത്ത് എതിരേല്ക്കാനായിഎഴുന്നേറ്റ് നിലംപറ്റി മുഖംതാഴ്ത്തി വണങ്ങി.","p":1},{"v":2,"t":"അവൻ പറഞ്ഞു: എന്റെ യജമാനന്മാരെ, ഇതാ, നിങ്ങളുടെ ദാസന്റെ വീട്ടിലേക്കു വന്ന് രാപാർത്താലും; നിങ്ങളുടെ കാലുകൾ കഴുകിയാലും. എന്നിട്ടു രാവിലെ എഴുന്നേറ്റ് നിങ്ങളുടെ വഴിക്കു പോകാം. അപ്പോൾ അവർ പറഞ്ഞു: വേണ്ട, ഞങ്ങൾ തെരുവിൽ രാത്രി കഴിച്ചുകൊള്ളാം.","p":1},{"v":3,"t":"എന്നാൽ, അവൻ ഏറെ നിർബന്ധിച്ചപ്പോൾ അവർ അവന്റെ നേരെ തിരിഞ്ഞ് അവന്റെ വീട്ടിലേക്കു ചെന്നു. അവൻ അവർക്കു വിരുന്നൊരുക്കി; പുളിപ്പില്ലാത്ത അപ്പവും ചുട്ടു. അവർ ഭക്ഷിച്ചു.","p":1},{"v":4,"t":"അവർ കിടക്കുംമുമ്പേ നഗരത്തിലെ ആളുകൾ, യുവാക്കന്മാർ മുതൽ വൃദ്ധന്മാർ വരെ, അവസാനത്തെ ആളുൾപ്പെടെ സോദോമിലുള്ള എല്ലാ പുരുഷന്മാരുംകൂടി ആ വീടു വളഞ്ഞു.","p":1},{"v":5,"t":"അവർ ലോത്തിനെ വിളിച്ച് അവനോടു ചോദിച്ചു: ഈ രാത്രി നിന്റെയടുക്കൽ വന്ന ആളുകളെവിടെ? ഞങ്ങൾ അവരുമായി രമിക്കേണ്ടതിന് അവരെ ഞങ്ങളുടെയടുത്തു പുറത്തുകൊണ്ടുവരുക.","p":1},{"v":6,"t":"ലോത്ത് അവരുടെയടുത്തു വാതില്ക്കലേക്കു ചെന്നു. അവൻ പുറത്തുകടന്നു കതകടച്ചു.","p":1},{"v":7,"t":"അവൻ പറഞ്ഞു: അരുത്, എന്റെ സഹോദരന്മാരേ, തിന്മ ചെയ്യരുത്.","p":1},{"v":8,"t":"നോക്കൂ, പുരുഷനെ അറിയാത്ത രണ്ടു പെൺമക്കൾ എനിക്കുണ്ട്; ഞാൻ അവരെ നിങ്ങളുടെപക്കലേക്ക് പുറത്തുകൊണ്ടുവരാം; നിങ്ങൾക്കിഷ്ടമുള്ളതുപോലെ അവരോടു ചെയ്തുകൊള്ളുക. പക്ഷേ, ഈ ആളുകളോട് മാത്രം ഒന്നും ചെയ്യരുത്. എന്തെന്നാൽ, അവർ എന്റെ മേൽക്കൂരയുടെ തണലിൽ വന്നവരാണ്.","p":1},{"v":9,"t":"അവർ അവന് അലറി: മാറിനില്ക്കൂ! തുടർന്നു അവർ പറഞ്ഞു: വിപ്രവാസത്തിനു വന്നവൻ ന്യായം വിധിക്കാൻ മുതിരുന്നുവോ! ഇപ്പോൾ, അവരോടന്നതിനേക്കാൾ മോശമായി നിന്നോട് ഞങ്ങൾ പെരുമാറും. അവർ ലോത്തിനെ ശക്തിയോടെ തള്ളി, വാതിൽ തല്ലിപ്പൊളിക്കാൻ അടുത്തുചെന്നു.","p":1},{"v":10,"t":"അപ്പോൾ, ആ അതിഥികൾ തങ്ങളുടെ കൈനീട്ടി ലോത്തിനെ അടുത്തേക്കു വലിച്ച് വീട്ടിനുള്ളിലാക്കി വാതിലടച്ചു.","p":1},{"v":11,"t":"എന്നിട്ട് അവർ വീട്ടുവാതില്കലുണ്ടായിരുന്ന ആ പുരുഷന്മാരെ, ചെറിയവൻ മുതൽ വലിയവൻവരെ, അന്ധതയാൽ പ്രഹരിച്ചു; അവർ വാതിൽ കണ്ടെത്തനാവാതെ വലഞ്ഞു.","p":1},{"v":12,"t":"ആ അതിഥികൾ ലോത്തിനോട് ആരാഞ്ഞു: ഇവിടെ നിനക്ക് സ്വന്തക്കാർ വേറെയുണ്ടോ? മരുമകനോ നിന്റെ പുത്രന്മാരോ പുത്രിമാരോ ആരുമാകട്ടെ ഈ നഗരത്തിൽ നിനക്കുള്ളവരെ ഈ പ്രദേശത്തുനിന്നു പുറത്തുകൊണ്ടുപോകുവിൻ.","p":1},{"v":13,"t":"എന്തെന്നാൽ, ഈ പ്രദേശം ഞങ്ങൾ നശിപ്പിക്കാൻപോകുകയാണ്. കർത്താവിന്റെ മുമ്പിൽ അവയുടെ രോദനം വലുതാകയാൽ ഇവിടം നശിപ്പിക്കാൻ കർത്താവു ഞങ്ങളെ അയച്ചിരിക്കുന്നു.","p":1},{"v":14,"t":"ലോത്ത് പുറത്തുചെന്ന്, തന്റെ പുത്രിമാരെ വിവാഹം ചെയ്യാനിരുന്ന തന്റെ മരുമക്കളെ കാര്യമറിയിച്ചു അവൻ പറഞ്ഞു: എഴുന്നേറ്റ് ഇവിടം വിടുവിൻ എന്തെന്നാൽ, കർത്താവു ഈ നഗരം നശിപ്പിക്കാൻ പോകുകയാണ്. എന്നാൽ അവൻ്റെ മരുമക്കളുടെ ദൃഷ്ടിയിൽ അതൊരു തമാശ പോലെയായിരുന്നു.","p":1},{"h":"ലോത്ത് സോദോം വിടുന്നു"},{"v":15,"t":"നേരംപുലർന്നപ്പോൾ ദൂതന്മാർ ലോത്തിനോടു നിർബന്ധിച്ചുപറഞ്ഞു: എഴുന്നേല്ക്കു! നിന്റെ ഭാര്യയെയും ഇപ്പോഴുള്ള നിന്റെ രണ്ടു പെണൺമക്കളെയും കൂടെക്കൂട്ടുക. അല്ലെങ്കിൽ നഗരത്തിന്റെ ശിക്ഷയിൽ നീയും തുടച്ചുനീക്കപ്പെടും.","p":1},{"v":16,"t":"എന്നാൽ, മടിച്ചുനിന്നപ്പോൾഅയാളോടുള്ള കർത്താവിന്റെ അനുകമ്പ കൊണ്ട് ആ ആളുകൾ, അയാളുടെ കൈയിലും ഭാര്യയുടെ കൈയിലും രണ്ടു പുത്രിമാരുടെയും കൈയിലും മുറുകെപ്പിടിച്ച്, അയാളെ നഗരത്തിനുപുറത്തു കൊണ്ടുവിട്ടു.","p":1},{"v":17,"t":"അവരെ പുറത്തു കൊണ്ടുചെന്നാക്കുമ്പോൾ അവൻ പറഞ്ഞു: നിന്റെ പ്രാണനെപ്രതി തിടുക്കംകൂട്ടുക; നിന്റെ പിന്നിലേക്കു നോക്കരുത്; സമതലത്തിൽഒരിടത്തും നില്ക്കരുത്; മലയിലേക്ക് ഓടി രക്ഷപ്പെടുക; അല്ലെങ്കിൽ നീ തുടച്ചുനീക്കപ്പെടും.","p":1},{"v":18,"t":"ലോത്ത് അവരോടു പറഞ്ഞു: എന്റെ യജമാനന്മാരേ, അരുതേ!","p":1},{"v":19,"t":"ഇതാ, അങ്ങയുടെ ദാസൻ ഇപ്പോൾ അങ്ങയുടെ ദൃഷ്ടികളിൽ പ്രീതി കണ്ടെത്തിയിരിക്കുകയാണല്ലോ. മാത്രമല്ല, എന്റെ ജീവൻ സംരക്ഷിക്കാൻ എന്നോട് അങ്ങു ചെയ്ത കാരുണ്യം അങ്ങു വിശാലമാക്കുകയും ചെയ്തിരിക്കുന്നു. എന്നാൽ, ആപത്ത് എന്നെ പിടികൂടി ഞാൻ മരിക്കാതിരിക്കേണ്ടതിന്, മലയിലേക്ക് ഓടി രക്ഷപ്പെടാൻ എനിക്കു സാധിക്കുകയില്ല.","p":1},{"v":20,"t":"നോക്കൂ, ആ പട്ടണം ഓടിയെത്താൻമാത്രം സമീപസ്ഥലമാണ്, അതു ചെറുതുമാണ്. ഞാൻ അങ്ങോട്ട് ഓടി രക്ഷപ്പെട്ടുകൊള്ളട്ടെ, അതു ചെറുതാണല്ലോ; അങ്ങനെ എന്റെ ജീവൻ നിലനില്ക്കട്ടെ.","p":1},{"v":21,"t":"അവൻ അയാളോടു പറഞ്ഞു: ശരി, അക്കാര്യവും ഞാൻ അംഗീകരിക്കുന്നു. നീ പറഞ്ഞ പട്ടണം നശിപ്പിക്കുന്നത് ഞാൻ ഒഴിവാക്കിയിരിക്കുന്നു.","p":1},{"v":22,"t":"വേഗമാവട്ടെ; അങ്ങോട്ട് ഓടിരക്ഷപ്പെടുക. നീ അവിടെയെത്തുംവരെ എനിക്കൊന്നും ചെയ്യാനാവില്ലല്ലോ. അങ്ങനെ, ആ പട്ടണത്തിന് സോവാർ എന്നു പേരുണ്ടായി.സോദോം-ഗൊമോറായുടെ നാശം"},{"v":23,"t":"ലോത്ത് സോവാറിൽ എത്തിയപ്പോഴേക്കും ഭൂമിയുടെമേൽ സൂര്യൻ ഉദിച്ചിരുന്നു."},{"v":24,"t":"കർത്താവ് സോദോമിന്റെമേലും ഗൊമോറായുടെമേലും ആകാശത്തിൽനിന്ന്, കർത്താവിന്റെ പക്കൽനിന്ന്, ഗന്ധകവും അഗ്നിയും വർഷിച്ചു.","p":1},{"v":25,"t":"ആ പട്ടണങ്ങളെയും സമതലമുഴൂവനയും പട്ടണവാസികളേവരെയം മണ്ണിൽ മുളച്ചവയെയും അവിടന്ന് ഉന്മൂലനം ചെയ്തു."},{"v":26,"t":"അയാളുടെ ഭാര്യ പിന്നിൽനിന്ന് തിരിഞ്ഞുനോക്കി; അവൾ ഒരു ഉപ്പുതൂണാവുകയും ചെയ്തു.","p":1},{"v":27,"t":"അബ്രാഹം അതിരാവിലെ എഴുന്നേറ്റ്, കർത്താവിന്റെ മുമ്പിൽ താൻ നിന്ന സ്ഥലത്തേക്ക് ചെന്നു.","p":1},{"v":28,"t":"അവൻ സൊദോമിന്റെയുംഗൊമോറായുടെയും സമതലപ്രദേശം മുഴുവന്റെയും നേർക്ക് താഴേക്കുനോക്കി. ഇതാ, തീച്ചൂളയിലെ പുകയെന്നപോലെ ആ പ്രദേശത്തുനിന്നെല്ലാം പുക ഉയരുന്നത് അവൻ കണ്ടു. മോവാബ്യർ, അമ്മോന്യർ","p":1},{"v":29,"t":"ദൈവം സമതലപ്രദേശങ്ങളിലെ നഗരങ്ങൾ നശിപ്പിച്ചപ്പോൾ അബ്രാഹത്തെ ഓർത്തു. അതിനാൽ ലോത്ത് പാർത്തിരുന്ന നഗരങ്ങളെ ഉന്മൂലനം ചെയ്തപ്പോൾ വിനാശത്തിന്റെ നടുവിൽനിന്ന് ദൈവം ലോത്തിനെ ഒഴിവാക്കി."},{"v":30,"t":"സോവാറിൽ പാർക്കാൻ ഭയമായിരുന്നതുകൊണ്ട്, ലോത്ത് സോവാറിൽനിന്ന് മലയിൽ കയറി പാർത്തു. അവന്റെ രണ്ടു പുത്രിമാരും അവനോടൊപ്പം ഉണ്ടായിരുന്നു. അവനും അവന്റെ രണ്ടു പുത്രിമാരും ഒരു ഗുഹയിൽ പാർത്തു.","p":1},{"v":31,"t":"മൂത്തവൾ ഇളയവളോടു പറഞ്ഞു: നമ്മുടെ പിതാവിനു പ്രായമായി. നാട്ടുനടപ്പനുസരിച്ച് നമ്മെ പ്രാപിക്കാൻ ഒരു പുരുഷനും ഭൂമിയിലില്ല.","p":1},{"v":32,"t":"വരൂ, നമ്മുടെ പിതാവിനെ വീഞ്ഞുകുടിപ്പിച്ച് നമുക്ക് അവനോടൊന്നിച്ച് ശയിക്കാം; അങ്ങനെ നമുക്ക് നമ്മുടെ പിതാവിൽനിന്ന് സന്തതിയെ നിലനിർത്താം.","p":1},{"v":33,"t":"ആ രാത്രി അവർ തങ്ങളുടെ പിതാവിനെ വീഞ്ഞുകുടിപ്പിച്ചു; മൂത്തവൾ ചെന്ന് തന്റെ പിതാവിനോടുകൂടെ ശയിച്ചു. അവൾ കിടന്നപ്പോഴോ എഴുന്നേറ്റപ്പോഴോ അവൻ അറിഞ്ഞില്ല.","p":1},{"v":34,"t":"പിറ്റേന്ന് മൂത്തവൾ ഇളയവളോടു പറഞ്ഞു: നോക്കൂ, ഇന്നലെ ഞാൻ എന്റെ പിതാവിനോടുകൂടെ ശയിച്ചു. ഇന്നു രാത്രിയും നമുക്കവനെ വീഞ്ഞുകുടിപ്പിക്കാം. എന്നിട്ട്, നീ ചെന്ന് അവനോടുകൂടെ ശയിക്കുക. അങ്ങനെ നമുക്ക് നമ്മുടെ പിതാവിൽനിന്ന് സന്തതിയെ നിലനിർത്താം.","p":1},{"v":35,"t":"ആ രാത്രിയും അവർ തങ്ങളുടെ പിതാവിനെ വീഞ്ഞുകുടിപ്പിച്ചു. ഇളയവൾ എഴൂന്നേറ്റ് അവനോടുകൂടെ ശയിച്ചു. അവൾ കിടന്നപ്പോഴോ എഴുന്നേറ്റപ്പോഴോ അവൻ അറിഞ്ഞില്ല.","p":1},{"v":36,"t":"അങ്ങനെ ലോത്തിന്റെ രണ്ടു പുത്രിമാരും തങ്ങളുടെപിതാവിൽനിന്ന് ഗർഭംധരിച്ചു.","p":1},{"v":37,"t":"മൂത്തവൾ ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ മോവാബ് എന്ന് അവനു പേരിട്ടു. ഇന്നുവരെയും അവനെയാണ് മോവാബു കാരുടെ പിതാവായി കരുതുന്നത്.","p":1},{"v":38,"t":"ഇളയവളും ഒരു പുത്രനെ പ്രസവിച്ചു അവൾ അവന് ബെൻ - അമ്മി എന്ന് പേരിട്ടു ഇന്നുവരെയും അവനെയാണ് അമ്മോന്യരുടെ പിതാവായി കരുതുന്നത്","p":1}],"20":[{"h":"അബ്രഹവും അബിമെലെക്കും"},{"v":1,"t":"അബ്രഹാം അവിടെനിന്ന് നെഗേബ്പ്രദേശത്തേക്ക് യാത്രതിരിച്ച് കാദെഷിനുംഷൂറിനും ഇടയ്ക്ക് വാസമുറപ്പിച്ചു. അവൻ ഗരാറിൽ പ്രവാസിയായിക്കഴിഞ്ഞു. '","p":1},{"v":2,"t":"അബ്രഹാം ഭാര്യ സാറാ യെക്കുറിച്ച്, 'അവൾ എന്റെ സഹോദരിയാണ്' എന്നത്രെ പറഞ്ഞത്. ഗരാറിലെ രാജാവായ അബിമെലെക് സാറായെ വരുത്തി, സ്വന്തമാക്കി."},{"v":3,"t":"ആ രാത്രി സ്വപ്നത്തിൽ ദൈവം അബിമെലെക്കിനെ സമീപിച്ച് അവനോടു പറഞ്ഞു: നോക്കൂ, നീ സ്വന്തമാക്കിയിരിക്കുന്നസ്ത്രീനിമിത്തം നീ മരിക്കും. അവൾ ഭർത്തൃമതിയാണ്.","p":1},{"v":4,"t":"'അബിമെലെക് അവളെ സമീപിച്ചിട്ടില്ലായിരുന്നു. അവൻ ചോദിച്ചു: പ്രഭോ, നീതിനിഷ്ഠമായ ഒരു ജനതയെയും അങ്ങ് വധിക്കുമോ?","p":1},{"v":5,"t":"അവൾ എന്റെ സഹോദരിയാണ് എന്ന് അവൻതന്നെയല്ലേ എന്നോട് പറഞ്ഞത്? അവൻ എന്റെ സഹോദരനാണെന്ന് അവളും പറഞ്ഞു. പരമാർത്ഥഹൃദയത്തോടും നിർമലകരങ്ങളോടുകൂടിയുമാണ് ഞാൻ ഇതു ചെയ്തത്.","p":1},{"v":6,"t":"അപ്പോൾ ദൈവം അവനോടു സ്വപ്നത്തിൽ അരുളിച്ചെയ്തു: പരമാർത്ഥഹൃദയത്തോടെയാണ് നീ ഇതു ചെയ്തതെന്ന് എനിക്കും അറിയാം. എനിക്കെതിരായി പാപം ചെയ്യുന്നതിൽനിന്ന് ഞാൻ തന്നെയാണ് നിന്നെ തടഞ്ഞത്. അതുകൊണ്ടാണ് അവളെ തൊടാൻ നിന്നെ ഞാൻ അനുവദിക്കാതിരുന്നത്.","p":1},{"v":7,"t":"'ഇപ്പോൾ ആ മനുഷ്യന്റെ ഭാര്യയെ തിരിച്ചേല്പിക്കുക. കാരണം, അവൻ ഒരു പ്രവാചകനാണ്. അവൻ നിനക്കുവേണ്ടി പ്രാർത്ഥിക്കും, നീ ജീവിക്കുകയും ചെയ്യും; തിരിച്ചേല്പിക്കാത്തപക്ഷം, നീയും നിനക്കുള്ളവരോക്കെയും തീർച്ചയായും മരിക്കും എന്നറിഞ്ഞുകൊള്ളുക.","p":1},{"v":8,"t":"അബിമെലെക് അതിരാവിലെ എഴുന്നേറ്റ് തന്റെ സേവകരെമുഴുവൻ വിളിച്ച് ഇക്കാര്യങ്ങളെല്ലാം അവർ കേൾക്കെ വിവരിച്ചു; ആ ആളുകൾ ഏറെ ഭയപ്പെട്ടു.","p":1},{"v":9,"t":"അബിമെലെക് അബ്രഹാത്തെ വിളിച്ച് അവനോടു ചോദിച്ചു: നീ എന്താണു ഞങ്ങളോട് ചെയ്തത്? നിനക്കെതിരായി ഞാൻ എന്തു തെറ്റുവരുത്തിയിട്ടാണ് എന്റെയും എന്റെ രാജ്യത്തിന്റെ യുംമേൽ ഇത്ര വലിയ പാപം വരുത്തിവെച്ചത്? ചെയ്യരുതാത്ത പ്രവൃത്തികളാണ് നീ എന്നോട് ചെയ്തിരിക്കുന്നത്.","p":1},{"v":10,"t":"അബിമെലെക് അബ്രഹാമോട് വീണ്ടും ചോദിച്ചു: എന്തു കണ്ടിട്ടാണ് നീ ഇക്കാര്യം ചെയ്തത്?","p":1},{"v":11,"t":"അബ്രഹാം പ്രത്യുത്തരിച്ചു: ഈ നാട്ടിൽ ദൈവഭയംതീരെയില്ലെന്നും എന്റെ ഭാര്യനിമിത്തം അവർ എന്നെ കൊല്ലുമെന്നും ഞാൻ കരുതി.","p":1},{"v":12,"t":"വാസ്തവത്തിൽ, അവൾ എന്റെ സഹോദരിതന്നെയാണ് - എന്റെ പിതാവിന്റെ മകളത്രെ; പക്ഷേ, എന്റെ മാതാവിന്റെ മകളല്ല; അവൾ എനിക്കു ഭാര്യയുമായി.","p":1},{"v":13,"t":"എന്റെ പിതൃഭവനത്തിൽനിന്ന് ഇറങ്ങിപ്പുറപ്പെടാൻ ദൈവം എനിക്ക് ഇടവരുത്തിയപ്പോൾ ഞാൻ അവളോട് പറഞ്ഞു: നീ എന്നോടു കാണിക്കേണ്ട കാരുണ്യം ഇതാണ്: നമ്മൾ പോകുന്ന ദേശത്തെല്ലാം, 'ഇവൻ എന്റെ സഹോദരനാണ്' എന്ന് എന്നെക്കുറിച്ച് നീ പറയണം."},{"v":14,"t":"അപ്പോൾഅബിമെലെക് ആടുകളെയും ദാസന്മാരെയും പരിചാരിക്കാരെയും കൊണ്ടുവന്ന് അബ്രഹാമിനു കൊടുത്തു; അവന് ഭാര്യ സാറായെ തിരിച്ചുനൽകുകകയും ചെയ്തു."},{"v":15,"t":"അബിമെലെക് പറഞ്ഞു: ഇതാ, എന്റെ നാട് നിന്റെ മുമ്പിൽ; നിന്റെ ദൃഷ്ടികളിൽ നല്ല ഇടത്ത് പാർത്തുക്കൊള്ളുക.","p":1},{"v":16,"t":"സാറായോട് അവൻ പറഞ്ഞു: ഇതാ, ആയിരം വെള്ളിനാണയം നിന്റെ സഹോദരനു ഞാൻ കൊടുക്കുന്നു. അത് നിന്നോടൊപ്പുമുള്ളവർക്കും മറ്റെല്ലാവർക്കും, നിന്നെ സംബന്ധിച്ച്, നൈർമല്യത്തിനുള്ള സാക്ഷ്യം ആയിരിക്കും. നീ നിർദോഷയാണ്.","p":1},{"v":17,"t":"\"അബ്രഹാം ദൈവത്തോട് പ്രാർത്ഥിച്ചു; ദൈവം അബിമെലെക്കിനെയും അവന്റെ ഭാര്യയെയും അവന്റെ ദാസിമാരെയും സൗഖ്യപ്പെടുത്തി, അവർക്ക് സന്താനങ്ങൾ ജനിക്കുകയും ചെയ്തു. \"എന്തെന്നാൽ, അബ്രഹാമിന്റെ ഭാര്യ സാറായുടെ കാര്യത്തെപ്രതി കർത്താവ് അബിമെലെക്കിന്റെ അന്തപുരത്തിലെ ഓരോ ഗർഭപാത്രവും തീർത്തും അടച്ചി രുന്നു.","p":1}],"21":[{"h":"ഇസഹാക്കിന്റെ ജനനം"},{"v":1,"t":"അരുൾചെയ്തിരുന്നതുപോലെ കർത്താവ് സാറായെ സന്ദർശിച്ചു. കർത്താവ് അറിയിച്ചിരുന്നതുപോലെ സാറായോട് വർത്തിക്കുകയും ചെയ്തു.","p":1},{"v":2,"t":"ദൈവം അബ്രാഹത്തെ അറിയിച്ചിരുന്ന നിശ്ചിതസമയത്ത് സാറാ ഗർഭംധരിച്ചു; അവന്റെ വാർധക്യത്തിൽ, അവൾ ഒരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":3,"t":"അബ്രാഹം തനിക്കു ജനിച്ച പുത്രന്, സാറാ പ്രസവിച്ച പുത്രന്, ഇസഹാക്ക് എന്നു പേരിട്ടു.","p":1},{"v":4,"t":"ദൈവം അബ്രാഹത്തോടു കല്പിച്ചിരുന്നതുപോലെ, അവൻ തന്റെ പുത്രൻ ഇസഹാക്കിന് എട്ടാം ദിവസം പരിച്ഛേദനം നടത്തി.","p":1},{"v":5,"t":"പുത്രൻ ഇസഹാക്ക് ജനിച്ചപ്പോൾ അബ്രാഹത്തിന് നൂറ് വയസ്സായിരുന്നു.","p":1},{"v":6,"t":"സാറാ പറഞ്ഞു: ദൈവം എനിക്കു ചിരി ഉളവാക്കിയിരിക്കുന്നു; കേൾക്കുന്നവരെല്ലാം എന്നെപ്രതി ചിരിക്കും.","p":1},{"v":7,"t":"അവൾ തുടർന്നു: സാറാ കുഞ്ഞുങ്ങളെ മുലയൂട്ടുമെന്ന് ആരെങ്കിലും അബ്രാഹത്തോടു പറയുമായിരുന്നോ? എന്നാൽ ഞാൻ അവന്റെ വാർദ്ധക്യത്തിൽ ഒരു പുത്രനെ പ്രസവിച്ചിരിക്കുന്നു.","p":1},{"h":"ഇശ്മായേൽ പുറന്തള്ളപ്പെടുന്നു"},{"v":8,"t":"കുഞ്ഞ് വളർന്ന് മുലകുടിമാറി; ഇസഹാക്കിനെ മുലകുടിമാറ്റിയ ദിവസം അബ്രാഹം വലിയൊരു വിരുന്നുനടത്തി.","p":1},{"v":9,"t":"ഈജിപ്തുകാരി ഹാഗാറിന്റെ പുത്രനെ, അബ്രാഹത്തിനായി അവൾ ജന്മംകൊടുത്തവനെ, സാറാ കണ്ടു; അവൻ കളിക്കുകയായിരുന്നു.","p":1},{"v":10,"t":"അവൾ അബ്രാഹത്തോടു പറഞ്ഞു: ആ അടിമപ്പെണ്ണിനെയും അവളുടെ മകനെയും ഇറക്കിവിടുക. എന്റെ മകനോടൊപ്പം, ഇസഹാക്കിനോടൊപ്പം, ആ അടിമപ്പെണ്ണിന്റെ മകൻ അവകാശിയാകാൻ പാടില്ല.","p":1},{"v":11,"t":"തന്റെ പുത്രനെസംബന്ധിച്ച ഇക്കാര്യം അബ്രാഹത്തിന്റെ ദൃഷ്ടികളിൽ ഏറെ സങ്കടകരമായിരുന്നു.","p":1},{"v":12,"t":"എന്നാൽ, ദൈവം അബ്രാഹത്തോട് അരുൾചെയ്തു: കുട്ടിയെക്കുറിച്ചും നിന്റെ ദാസിയെക്കുറിച്ചും സാറാ നിന്നോടു പറയുന്നതൊന്നും നിന്റെ ദൃഷ്ടികളിൽ സങ്കടകരമാകാതിരിക്കട്ടെ. അവളുടെ സ്വരം നീ ശ്രവിക്കുക. കാരണം, നിന്റെ സന്തതി അറിയപ്പെടുന്നത് ഇസഹാക്കിലൂടെയായിരിക്കും.","p":1},{"v":13,"t":"ദാസിയുടെ പുത്രനെയും ഞാനൊരു ജനതയാക്കും; കാരണം, അവനും നിന്റെ സന്തതിയാണല്ലോ.","p":1},{"v":14,"t":"അബ്രാഹം അതിരാവിലെ എഴുന്നേറ്റ് അപ്പവും വെള്ളംനിറച്ച തുകൽസഞ്ചിയുമെടുത്ത് ഹാഗാറിനു നൽകി; കുട്ടിയെ തോളിൽ വച്ചുകൊടുത്ത് അവളെ പറഞ്ഞയച്ചു. അവൾ ബേർഷെബാ മരുപ്രദേശത്ത് അലഞ്ഞുനടന്നു.","p":1},{"v":15,"t":"തുകൽസഞ്ചിയിലെ വെള്ളം തീർന്നപ്പോൾ അവൾ കുട്ടിയെ കുറ്റിച്ചെടികളിലൊന്നിന്റെ ചുവട്ടിൽ ഉപേക്ഷിച്ചു.","p":1},{"v":16,"t":"കുട്ടിയുടെ മരണം ഞാൻ കാണാതിരിക്കട്ടെ എന്നു പറഞ്ഞ് അവൾ ഒരു അമ്പെയ്യത്തുദൂരം മാറി എതിർവശത്തേക്കു തിരിഞ്ഞിരുന്നു. അവിടെയിരുന്ന് അവൾ സ്വരമുയർത്തി കരഞ്ഞു.","p":1},{"v":17,"t":"അപ്പോൾ കുട്ടിയുടെ സ്വരം ദൈവം കേട്ടു. ദൈവത്തിന്റെ ദൂതൻ ആകാശത്തുനിന്ന് ഹാഗാറിനെ വിളിച്ച് അവളോടു ചോദിച്ചു: ഹാഗാർ, നിനക്കെന്തുപറ്റി? നീ ഭയപ്പെടേണ്ട. എന്തെന്നാൽ, ദൈവം കുട്ടിയുടെ സ്വരം, അവൻ ആയിരിക്കുന്ന ഇടത്തുനിന്ന്, കേട്ടിരിക്കുന്നു."},{"v":18,"t":"നീ എഴുന്നേറ്റ് കുട്ടിയെ എടുക്കുക; നിന്റെ കരംകൊണ്ട് അവനെ മുറുകെപ്പിടിക്കുക. ഞാൻ അവനെ വലിയൊരു ജനതയാക്കും.","p":1},{"v":19,"t":"ദൈവം അവളുടെ കണ്ണുതുറന്നു; അവൾ വെള്ളമുള്ള ഒരു കിണർ കണ്ടു. അവൾ ചെന്ന് തുകൽസഞ്ചിയിൽ വെള്ളംനിറച്ച്, കുട്ടിക്കു കുടിക്കാൻ കൊടുത്തു."},{"v":20,"t":"ദൈവം ആ കുട്ടിയോടുകൂടെയുണ്ടായിരുന്നു. അവൻ വളർന്നു; മരുഭൂമിയിൽ പാർത്തു; സമർത്ഥനായ വില്ലാളിയായിത്തീർന്നു.","p":1},{"v":21,"t":"അവൻ പാരാൻമരുഭൂമിയിൽ പാർത്തു. അവന്റെ അമ്മ അവനുവേണ്ടി ഈജിപ്തുദേശത്തുനിന്ന് ഒരു ഭാര്യയെ കണ്ടെത്തി.","p":1},{"h":"അബ്രാഹവും അബിമെലെക്കും തമ്മിലുള്ള ഉടമ്പടി"},{"v":22,"t":"അക്കാലത്ത് അബിമെലെക്കും അവന്റെ സൈന്യാധിപൻ ഫിക്കോലും അബ്രാഹത്തോട് ഇപ്രകാരം പറഞ്ഞു: നീ ചെയ്യുന്നതിലെല്ലാം ദൈവം നിന്നോടുകൂടെയുണ്ട്.","p":1},{"v":23,"t":"നീ എന്നോടും എന്റെ അനന്തരഗാമിയോടും പിൻതലമുറക്കാരോടും വ്യാജമായി വർത്തിക്കുകയില്ലെന്ന് ഇപ്പോൾ ദൈവത്തെക്കൊണ്ട് ഇവിടെവച്ച് എന്നോട് ശപഥം ചെയ്യണം. ഞാൻ നിന്നോടു ചെയ്ത കാരുണ്യ മനുസരിച്ച് എന്നോടും നീ പ്രവാസിയായി പാർத்துவരുന്ന ഈ നാടിനോടും പ്രവർത്തിക്കണം.","p":1},{"v":24,"t":"ഞാൻ ശപഥം ചെയ്യുന്നു, അബ്രാഹം പറഞ്ഞു.","p":1},{"v":25,"t":"പിന്നീട് അബിമെലെക്കിന്റെ ദാസന്മാർ പിടിച്ചെടുത്ത വെള്ളമുള്ള കിണറിനെ സംബന്ധിച്ച് അബ്രാഹം അബിമെലെക്കിനെ കുറ്റപ്പെടുത്തി.","p":1},{"v":26,"t":"അപ്പോൾ അബിമെലെക് പറഞ്ഞു: ആരാണ് ഇക്കാര്യം ചെയ്തതെന്ന് എനിക്കറിഞ്ഞുകൂടാ; നീയാകട്ടെ, എന്നെ അറിയിച്ചതുമില്ല; ഇന്നല്ലാതെ ഞാൻ ഇതേക്കുറിച്ചു കേട്ടിട്ടുമില്ല.","p":1},{"v":27,"t":"അബ്രാഹം അബിമെലെക്കിന് ആടാടുകളെ കൊണ്ടുവന്നുകൊടുത്തു; അവരിരുവരും ഒരു ഉടമ്പടിയുണ്ടാക്കി.","p":1},{"v":28,"t":"അബ്രാഹം ആട്ടിൻപറ്റത്തിലെ ഏഴു പെണ്ണാടുകളെ മാറ്റിനിർത്തി.","p":1},{"v":29,"t":"അബിമെലെക് അബ്രാഹത്തോടു ചോദിച്ചു: നീ മാറ്റിനിർത്തിയിരിക്കുന്ന ഈ ഏഴു പെണ്ണാടുകളുടെ അർത്ഥമെന്ത്?","p":1},{"v":30,"t":"അവൻ പറഞ്ഞു: ഈ ഏഴു പെണ്ണാടുകളെ എന്റെ കരങ്ങളിൽനിന്ന് സ്വീകരിക്കുകവഴി, ഞാനാണ് ഈ കിണർ കുഴിച്ചത് എന്നതിന് നീ തന്നെയായിരിക്കും എനിക്കുള്ള സാക്ഷി.","p":1},{"v":31,"t":"ആ സ്ഥലത്തിന് ബേർഷെബാ എന്നു പേരായി; കാരണം, അവിടെവച്ച് അവർ രണ്ടുപേരും ശപഥം ചെയ്തു.","p":1},{"v":32,"t":"അങ്ങനെ ബേർഷെബായിൽ വച്ച് അവർ ഒരു ഉടമ്പടിയുണ്ടാക്കി. അനന്തരം അബിമെലെകും സൈനാധിപനായ ഫിക്കോളും എഴുന്നേറ്റ് ഫിലിസ്ത്യരുടെ നാട്ടിലേക്കു തിരിച്ചുപോയി","p":1},{"v":33,"t":"അബ്രഹാം ബേർഷെബായിൽ ഒരു ഭാനുകവൃക്ഷം നട്ടുപിടിപ്പിക്കുകയും അവിടെവച്ച് കർത്താവിനെ നിത്യനായ ദൈവം എന്ന് വിളിക്കുകയും ചെയ്തു","p":1},{"v":33,"t":"32 അബ്രഹാം ഫിലിസ്ത്യരുടെ നാട്ടിൽ വളരെ കാലം വിപ്രവാസിയായിരുന്നു.","p":1}],"22":[{"h":"അബ്രാഹത്തിന്റെ ബലി"},{"v":1,"t":"ഈ സംഭവങ്ങൾക്കുശേഷം ദൈവം അബ്രാഹത്തെ പരീക്ഷിച്ചു. അവിടുന്ന് അവനെ വിളിച്ചു: അബ്രാഹം! 'ഇതാ ഞാൻ' അവൻ മറുപടി പറഞ്ഞു.","p":1},{"v":2,"t":"അവിടുന്നു പറഞ്ഞു: നിന്റെ പുത്രൻ, നീ സ്നേഹിക്കുന്ന നിന്റെ ഏകപുത്രൻ ഇസഹാക്കിനെ കൂട്ടിക്കൊണ്ട് മോരിയാദേശത്തേക്കു പോവുക. അവിടെ ഞാൻ നിന്നോടു പറയുന്ന മലകളിലൊന്നിന്റെ മുകളിൽ നീ അവനെ ഹോമയാഗമായി അർപ്പിക്കണം.","p":1},{"v":3,"t":"അബ്രാഹം അതിരാവിലെ ഉണർന്ന് കഴുതയ്ക്കു ജിനിയിട്ട് തന്നോടൊപ്പം രണ്ടു ബാല്യക്കാരെയും മകൻ ഇസഹാക്കിനെയുംകൂട്ടി ഹോമയാഗത്തിനുവേണ്ട വിറകും കീറി ദൈവം അവനോടു പറഞ്ഞ സ്ഥലത്തേക്ക് നടന്നുനീങ്ങി.","p":1},{"v":4,"t":"മൂന്നാംദിവസം അബ്രാഹം തന്റെ കണ്ണുകളുയർത്തി അകലെനിന്ന് ആ സ്ഥലം കണ്ടു.","p":1},{"v":5,"t":"തന്റെ ബാല്യക്കാരോട് അബ്രാഹം പറഞ്ഞു: കഴുതയുമായി നിങ്ങൾ ഇവിടെ തങ്ങുക. ഞാനും കുട്ടിയും അവിടം വരെ പോയി ആരാധിച്ചിട്ട് നിങ്ങളുടെ അടുത്തേക്ക് തിരിച്ചുവരാം.","p":1},{"v":6,"t":"അബ്രാഹം ഹോമയാഗത്തിനുള്ള വിറകെടുത്ത് മകൻ ഇസഹാക്കിന്റെമേൽ വെച്ചു കൊടുത്തു; തീയും കത്തിയും തന്റെ കയ്യിലും എടുത്തു. അവരിരുവരും ഒരുമിച്ചുനടന്നു.","p":1},{"v":7,"t":"ഇസഹാക്ക് തന്റെ പിതാവായ അബ്രാഹത്തോടു സംസാരിച്ചുതുടങ്ങി. എന്റെ പിതാവേ, എന്ന് അവൻ വിളിച്ചു. ഇതാ ഞാൻ, എന്റെ മകനേ! അവൻ വിളികേട്ടു. അവൻ ചോദിച്ചു: ഇതാ, തീയും വിറകും; എന്നാൽ, ദഹനബലിക്കുള്ള കുഞ്ഞാടെവിടെ?","p":1},{"v":8,"t":"അബ്രാഹം മറുപടി പറഞ്ഞു: എന്റെ മകനേ, ഹോമയാഗത്തിനുള്ള കുഞ്ഞാടിന്റെ കാര്യം ദൈവം തന്നെ നോക്കിക്കൊള്ളും. അവരിരുവരും ഒരുമിച്ചു നടന്നു.","p":1},{"v":9,"t":"ദൈവം അവനോടു പറഞ്ഞിരുന്ന സ്ഥലത്ത് അവരെത്തിയപ്പോൾ, അബ്രാഹം അവിടെ ബലിപീഠം പണിത്, വിറകടുക്കി; തന്റെ പുത്രൻ ഇസഹാക്കിനെ ബന്ധിച്ച് ബലിപീഠത്തിൽ വിറകിനുമേൽ കിടത്തി.","p":1},{"v":10,"t":"മകനെ ബലികഴിക്കാൻ അബ്രാഹം കൈനീട്ടി കത്തിയെടുത്തു.","p":1},{"v":11,"t":"എന്നാൽ, കർത്താവിന്റെ ദൂതൻ ആകാശത്തുനിന്ന് അവനെ വിളിച്ചു: അബ്രാഹം, അബ്രാഹം! 'ഇതാ ഞാൻ' അവൻ മറുപടിപറഞ്ഞു.","p":1},{"v":12,"t":"ദൂതൻ പറഞ്ഞു: കുട്ടിയുടെമേൽ കൈവെക്കരുത്; അവനെ ഒന്നും ചെയ്യരുത്. കാരണം, നീ ദൈവഭയമുള്ളവനാണെന്ന് ഇപ്പോൾ ഞാൻ അറിയുന്നു; നിന്റെ ഒരേയൊരു പുത്രനെ നീ എന്നിൽനിന്ന് ഒഴിവാക്കിയില്ല.","p":1},{"v":13,"t":"അബ്രാഹം തന്റെ കണ്ണുകളുയർത്തി നോക്കി. ഇതാ, പുറകിലായി കൂറ്റിച്ചെടികൾക്കിടയിൽ കൊമ്പ് കുടുങ്ങിക്കിടക്കുന്ന മൂട്ടാട്! അബ്രാഹം ചെന്ന് ആ മൂട്ടാടിനെയെടുത്ത് തന്റെ മകനുപകരം ഹോമയാഗമർപ്പിച്ചു.","p":1},{"v":14,"t":"അബ്രാഹം ആ സ്ഥലത്തിന് യാഹ്‌വെ-യിരെ എന്ന് പേരിട്ടു. അതാണ് കർത്താവിന്റെ മലയിൽ അവിടുന്ന് പ്രത്യക്ഷപ്പെടും എന്ന് ഇന്ന് പറയപ്പെടുന്നത്.","p":1},{"v":15,"t":"കർത്താവിന്റെ ദൂതൻ ആകാശത്തുനിന്ന് രണ്ടാമതും അബ്രാഹത്തെ വിളിച്ചു.","p":1},{"v":16,"t":"അവൻ പറഞ്ഞു: ഞാൻ എന്നെക്കൊണ്ട് ശപഥചെയ്യുന്നു, കർത്താവിന്റെ അരുളപ്പാട്: നിന്റെ ഒരേയൊരു പുത്രനെ ഒഴിവാക്കാതെ നീ ഇക്കാര്യം ചെയ്തയാൽ","p":1},{"v":17,"t":"ഞാൻ നിന്നെ തീർച്ചയായും അനുഗ്രഹിക്കും. നിന്റെ സന്തതിയെ ആകാശത്തിലെ നക്ഷത്രങ്ങൾപോലെയും കടൽത്തീരത്തെ മണൽത്തരികൾപോലെയും നിശ്ചയമായും ഞാൻ വർദ്ധിപ്പിക്കും. നിന്റെ സന്തതി ശത്രുക്കളുടെ കവാടം കൈവശപ്പെടുത്തും.","p":1},{"v":18,"t":"നീ എന്റെ സ്വരം ശ്രവിച്ചതുകൊണ്ട്, നിന്റെ സന്തതിമുഖാന്തരം ഭൂമിയിലെ എല്ലാ ജനതകളും തങ്ങളെത്തന്നെ അനുഗ്രഹിക്കും."},{"v":19,"t":"അബ്രാഹം തന്റെ ബാല്യക്കാരുടെ അടുത്ത് മടങ്ങിയെത്തി, അവർ എഴുനേറ്റ് ബേർഷെബായിലേക്ക് ഒരുമിച്ചുനടന്നു. അബ്രാഹം ബേർഷെബായിൽ പാർത്തു.","p":1},{"v":20,"t":"ഈ സംഭവങ്ങൾക്കുശേഷം അബ്രാഹത്തിന് ഇപ്രകാരം സന്ദേശം ലഭിച്ചു: ഇതാ, മിൽക്കായും നിന്റെ സഹോദരൻ നാഹോറിന് സന്താനങ്ങളെ പ്രസവിച്ചിരിക്കുന്നു.","p":1},{"v":21,"t":"അവർ ആദ്യജാതനായ ഊസ്, അവന്റെ സഹോദരൻ ബൂസ്, ആരാമിന്റെ പിതാവായ കെമൂവേൽ,","p":1},{"v":22,"t":"കേസെദ്, ഹാസോ, പിൽദാഷ്, ഇത്ലാഫ്, ബത്തൂവേൽ എന്നിവരാണ്.","p":1},{"v":23,"t":"ബത്തൂവേലാണ് റബേക്കായെ ജനിപ്പിച്ചത്. അബ്രാഹത്തിന്റെ സഹോദരനായ നാഹോറിന് മിൽക്കായിലുണ്ടായവരാണ് അവർ എട്ടുപേരും.","p":1},{"v":24,"t":"കൂടാതെ, റവൂമാ എന്നുപേരുള്ള അവന്റെ ഉപനാരിയും തേബഹ്, ഗഹം, തഹഷ്, മാക്കാഹ് എന്നിവരെ പ്രസവിച്ചു.","p":1}],"23":[{"h":"സാറായുടെ മരണം"},{"v":1,"t":"സാറാ നൂറ്റ ഇരുപത്തേഴു വർഷം ജീവിച്ചിരുന്നു; അതാണ് സാറായുടെ ജീവിതകാലം.","p":1},{"v":2,"t":"കിരിയാത്ത് അർബായിൽവെച്ച്, അതായത് കാനാൻദേശത്തുള്ള ഹെബ്രോനിൽവെച്ച്, സാറാ മരിച്ചു. സാറായെപ്രതി വിലപിക്കാനും കരയാനും അബ്രാഹം എത്തി.","p":1},{"v":3,"t":"മരിച്ചവളുടെ അടുക്കൽനിന്ന് എഴുന്നേറ്റ് അബ്രാഹം ഹിത്യരോട് ഇപ്രകാരം പറഞ്ഞു:","p":1},{"v":4,"t":"ഞാൻ നിങ്ങളുടെ ഇടയിൽ പ്രവാസിയും കുടികിടപ്പുകാരനുമാണ്. നിങ്ങളുടെ ഇടയിൽ ഉടമാവകാശത്തോടുകൂടിയ ഒരു ശ്മശാനം എനിക്ക് തരുക; എന്റെ മരിച്ചവളെ എന്റെ മുമ്പിൽനിന്ന് ഞാൻ മറവുചെയ്യട്ടെ."},{"v":5,"t":"ഹിത്യർ അബ്രാഹത്തോടു മറുപടിയായി ഇങ്ങനെ പറഞ്ഞു:","p":1},{"v":6,"t":"യജമാനനേ, ഞങ്ങളെ കേട്ടാലും. അങ്ങു ഞങ്ങളുടെയിടയിലെ ശക്തനായ പ്രഭുവാണ്. അങ്ങയുടെ മരിച്ചവളെ ഞങ്ങളുടെ ഏറ്റവും നല്ല കബറിടത്തിൽ അടക്കിക്കൊള്ളുക. ഞങ്ങളിൽ ഒരുവൻപോലും തന്റെ കബറിടം അങ്ങയുടെ മരിച്ചവളെ അടക്കാൻ അങ്ങേക്കു നിഷേധിക്കില്ല.","p":1},{"v":7,"t":"അബ്രാഹം എഴുന്നേറ്റ് നാട്ടുകാരായ ഹിത്യരെ വണങ്ങി.","p":1},{"v":8,"t":"അവൻ അവരോട് ഇപ്രകാരം പറഞ്ഞു: എന്റെ മരിച്ചവളെ സംസ്‌കരിക്കുന്നതിന് നിങ്ങൾക്കു മനസ്സുണ്ടെങ്കിൽ, എന്നെ ശ്രവിച്ച് സോഹാറിന്റെ പുത്രനായ എഫ്രോനെ എനിക്കുവേണ്ടി പോയിക്കാണണം.","p":1},{"v":9,"t":"അവന്റെ പറമ്പിന്റെ അതിർത്തിയിൽ അവനുള്ള മക്‌പെലാഗുഹ എനിക്കു നൽകട്ടെ; നിങ്ങളുടെയിടയിൽ ഉടമാവകാശത്തോടുകൂടിയ ഒരു കബറിടമായി എനിക്ക് മുഴുവൻവിലയ്ക്കും അവൻ അതു തരട്ടെ.","p":1},{"v":10,"t":"ഹിത്യരുടെ ഇടയിൽത്തന്നെ എഫ്രോൺ ഇരിപ്പുണ്ടായിരുന്നു. ഹിത്യരും തന്റെ നഗരവാതില്ക്കൽ വന്ന എല്ലാവരും കേൾക്കേ ഹിത്യനായ എഫ്രോൺ അബ്രാഹത്തോട് ഇങ്ങനെ പ്രതിവചിച്ചു:","p":1},{"v":11,"t":"അങ്ങനെയല്ല, പ്രഭോ, എന്നെ ശ്രവിച്ചാലും. ആ പറമ്പ് അങ്ങേക്കു ഞാൻ സമ്മാനിക്കുന്നു, അതിലുള്ള ഗുഹയും അങ്ങേക്ക് ഞാൻ തരുന്നു; എന്റെ ജനത്തിന്റെ കൺമുമ്പിൽവെച്ച് അങ്ങേക്കു ഞാനത് തരുന്നു. അങ്ങയുടെ മരിച്ചവളെ അടക്കിക്കൊള്ളുക.","p":1},{"v":12,"t":"അബ്രാഹം നാട്ടുകാർക്കു മുമ്പിൽ വണങ്ങി.","p":1},{"v":13,"t":"നാട്ടുകാർ കേൾക്കേ അവൻ എഫ്രോണോട് ഇങ്ങനെ പറഞ്ഞു: ദയവായി എന്നെ കേട്ടാലും; ഞാൻ പറമ്പിന്റെ വില തരുന്നു. എന്നിൽനിന്ന് സ്വീകരിച്ചാലും. എന്റെ മരിച്ചവളെ അവിടെ ഞാൻ സംസ്‌കരിക്കട്ടെ.","p":1},{"v":14,"t":"എഫ്രോൻ അബ്രാഹത്തോടു മറുപടിയായി പറഞ്ഞു:","p":1},{"v":15,"t":"പ്രഭോ, എന്നെ ശ്രവിച്ചാലും. നാനൂറു ഷെക്കൽ വെള്ളിയുടെ ഒരു തുണ്ടുഭൂമിയെന്നത് എനിക്കും അങ്ങയ്ക്കുമിടയിൽ എന്താണ്? അങ്ങയുടെ മരിച്ചവളെ സംസ്‌കരിച്ചുകൊള്ളുക.","p":1},{"v":16,"t":"അബ്രാഹം എഫ്രോനെ ശ്രവിച്ചു. ഹിത്യർ കേൾക്കേ എഫ്രോൻ പറഞ്ഞ നാനൂറു ഷെക്കൽ വെള്ളി, കച്ചവടക്കാരുടെയിടയിലെ നടപ്പനുസരിച്ച്, അബ്രാഹം എഫ്രോനിനു തൂക്കിക്കൊടുത്തു.","p":1},{"v":17,"t":"അങ്ങനെ അവൻ മമ്രേക്ക് അടുത്ത് മക്‌പെലയിലുള്ള എഫ്രോന്റെ പറമ്പും അവിടെയുണ്ടായിരുന്ന ഗുഹയും, പറമ്പിലും അതിന്റെ ചുറ്റുമതിലിലുമുള്ള എല്ലാ വൃക്ഷങ്ങളുമടക്കം കരാറുറപ്പിച്ചു;","p":1},{"v":18,"t":"ഹിത്യരുടെയും നഗരവാതിൽക്കൽ വന്നവരുടെയും സമക്ഷം അബ്രാഹത്തിന് അത് അവകാശമായിത്തീർന്നു.","p":1},{"v":19,"t":"അതിനുശേഷം അബ്രാഹം തന്റെ ഭാര്യ സാറായെ മമ്രേക്കു മുമ്പിൽ മക്‌പെലയിലെ പറമ്പിലുള്ള ഗുഹയിൽ, അതായത് കാനാൻദേശത്തെ ഹെബ്രോനിൽ, സംസ്‌കരിച്ചു.","p":1},{"v":20,"t":"അങ്ങനെ ആ പറമ്പും അതിലെ ഗുഹയും ഹിത്യരിൽനിന്ന് തനിക്ക് ഉടമാവകാശമുള്ള കബറിടമായി അബ്രാഹം ഉറപ്പിച്ചു.","p":1}],"24":[{"h":"ഇസഹാക്കും റബേക്കായും"},{"v":1,"t":"അബ്രാഹം പ്രായംചെന്ന്, വൃദ്ധനായി. കർത്താവ് എല്ലാറ്റിലും അബ്രാഹത്തെ അനുഗ്രഹിച്ചു.","p":1},{"v":2,"t":"തനിക്കുള്ള എല്ലാറ്റിന്റെയും കാര്യസ്ഥനായ തന്റെ ഭവനത്തിലെ മുതിർന്ന ഭൃത്യനോട് അബ്രാഹം പറഞ്ഞു: നിന്റെ കൈ എന്റെ തുടയുടെകീഴെ വയ്ക്കുക.","p":1},{"v":3,"t":"ഞാൻ പാർക്കുന്ന ഈ നാട്ടിലെ കാനാൻകാരുടെ പെൺമക്കളിൽനിന്ന് എന്റെ പുത്രനു ഭാര്യയെ തിരഞ്ഞെടുക്കുകയില്ലെന്ന് ആകാശത്തിന്റെ ദൈവവും ഭൂമിയുടെ ദൈവവുമായ കർത്താവിനെക്കൊണ്ട് നിന്നെ ഞാൻ സത്യംചെയ്യിക്കുന്നു.","p":1},{"v":4,"t":"എന്റെ നാട്ടിൽ, എന്റെ സഹജരുടെയടുക്കൽ ചെന്ന്, എന്റെ പുത്രൻ ഇസഹാക്കിന് നീ ഭാര്യയെ കൊണ്ടുവരണം.","p":1},{"v":5,"t":"അപ്പോൾ ആ ദാസൻ അവനോടു ചോദിച്ചു: ഒരുപക്ഷേ, ആ സ്ത്രീ എന്റെപിന്നാലെ ഈ നാട്ടിലേക്ക് വരാൻ തയ്യാറല്ലെങ്കിൽ അങ്ങു പുറപ്പെട്ടുപോന്ന ആ നാട്ടിലേക്ക് അങ്ങയുടെ പുത്രനെ ഞാൻ ഉറപ്പായും തിരിച്ചു കൊണ്ടുപോകണമോ?"},{"v":6,"t":"അബ്രാഹം അവനോടു പറഞ്ഞു: എന്റെ പുത്രനെ ഒരിക്കലും അങ്ങോട്ടു തിരിച്ചു കൊണ്ടുപോകാതിരിക്കാൻ നീ ശ്രദ്ധിക്കണം.","p":1},{"v":7,"t":"എന്റെ പിതൃഭവനത്തിൽനിന്നും ജന്മനാട്ടിൽനിന്നും എന്നെ കൊണ്ടുവന്നവനും എന്നോടു സംസാരിച്ചവനും നിന്റെ സന്തതിക്കു ഈ നാട് ഞാൻ നൽകുമെന്നു എന്നോടു വാഗ്ദാനം ചെയ്തവനുമായ ആകാശത്തിന്റെ ദൈവമായ കർത്താവുതന്നെ തന്റെ ദൂതനെ നിനക്കു മുമ്പെ അയയ്ക്കും; നീ അവിടെനിന്നു എന്റെ പുത്രന്നു ഒരു സ്ത്രീയെ കൊണ്ടുവരണം."},{"v":8,"t":"എന്നാൽ, ആ സ്ത്രീ നിന്റെ പിന്നാലെ വരാൻ തയ്യാറല്ലെങ്കിൽ എന്റെ ഈ ശപഥത്തിൽനിന്നു നീ മുക്തനായിരിക്കും; എന്റെ പുത്രനെ അങ്ങോട്ടു മടക്കരുതെന്നുമാത്രം.","p":1},{"v":9,"t":"അപ്പോൾ ഭൃത്യൻ തന്റെ യജമാനനായ അബ്രാഹാമിന്റെ തുടയുടെകീഴെ തന്റെ കൈവെച്ചു ആ കാര്യത്തെപ്രതി സത്യം ചെയ്തു.","p":1},{"v":10,"t":"അനന്തരം, ഭൃത്യൻ യജമാനന്റെ ഒട്ടകങ്ങളിൽനിന്നു പത്തു ഒട്ടകങ്ങളെയും കൊണ്ടു യാത്രയ്ക്കൊരുങ്ങി. യജമാനന്റെ എല്ലാ വിശിഷ്ടവസ്തുക്കളും അവന്റെ കൈവശമുണ്ടായിരുന്നു. അവൻ എഴുന്നേറ്റു നാഹോറിന്റെ പട്ടണമായ അറംനഹറായിമിലേക്കു പോയി.","p":1},{"v":11,"t":"സായംകാലത്തു, വെള്ളംകോരുന്നവർ വരുന്ന സമയത്തു അവൻ ഒട്ടകങ്ങളെ പട്ടണത്തിനുവെളിയിൽ വെള്ളമുള്ള ഒരു കിണറിനടുത്തു കിടത്തി.","p":1},{"v":12,"t":"എന്നിട്ടു, അവൻ പ്രാർത്ഥിച്ചു: എന്റെ യജമാനനായ അബ്രാഹാമിന്റെ ദൈവമായ കർത്താവേ, ഇന്ന് എനിക്കു ഇതു സാധിച്ചുതരേണമേ. എന്റെ യജമാനനായ അബ്രാഹത്തോടു കരുണചെയ്യേണമേ.","p":1},{"v":13,"t":"ഇതാ, ഞാൻ നീരുറയ്ക്കരുകിൽ നിൽക്കുകയാണ്; നഗരത്തിലെ ആളുകളുടെ പെൺകുട്ടികൾ വെള്ളംകോരാൻ പുറപ്പെട്ടിട്ടുണ്ട്.","p":1},{"v":14,"t":"എനിക്കു കുടിക്കാനായി നിന്റെ കുടം ചായ്ച്ചുതരിക എന്നു ഞാൻ പറയുമ്പോൾ, 'കുടിച്ചുകൊള്ളുക; നിന്റെ ഒട്ടകങ്ങൾക്കും ഞാൻ കുടിക്കാൻ കൊടുക്കാം' എന്നു ഏതു പെൺകുട്ടി പറയുന്നുവോ, അവളായിരിക്കും അങ്ങയുടെ ദാസനായ ഇസഹാക്കിനുവേണ്ടി അങ്ങ് നിശ്ചയിച്ചിട്ടുള്ളവൾ. എന്റെ യജമാനനോടു അങ്ങ് കരുണചെയ്തിരിക്കുന്നുവെന്നു അവൾമൂലം ഞാൻ അറിയും.","p":1},{"v":15,"t":"അവൻ പറഞ്ഞുതീരുംമുമ്പ്, ഇതാ, അബ്രാഹാമിന്റെ സഹോദരൻ നാഹോറിന്റെ ഭാര്യ മില്ക്കായുടെ പുത്രൻ ബെത്തൂവേലിനു ജനിച്ചവളായ റബേക്കാ വരുന്നു! അവളുടെ തോളിൽ ഒരു കുടമുണ്ടായിരുന്നു.","p":1},{"v":16,"t":"ആ പെൺകുട്ടി കാണാൻ അതിസുന്ദരിയും കന്യകയും പുരുഷനെ അറിയാത്തവളുമായിരുന്നു. അവൾ ഉറവയിലേക്കിറങ്ങി തന്റെ കുടംനിറച്ചു കയറിവന്നു.","p":1},{"v":17,"t":"ആ ഭൃത്യൻ അപ്പോൾ അവളുടെ അടുത്തെത്താൻ ഓടി. അവൻ പറഞ്ഞു: ദയവായി നിന്റെ കുടത്തിൽനിന്നു കുറച്ചു വെള്ളം എനിക്കു കുടിക്കാൻ തരിക.","p":1},{"v":18,"t":"പ്രഭോ, കുടിച്ചാലും, അവൾ പറഞ്ഞു.തിടുക്കത്തിൽ കുടം തന്റെ കരത്തിലേക്ക് താഴ്ത്തി അവൾ അവനു് കുടിക്കാൻ കൊടുത്തു.","p":1},{"v":19,"t":"അവൻ കുടിച്ചുകഴിഞ്ഞപ്പോൾ അവൾ പറഞ്ഞു: താങ്കളുടെ ഒട്ടകങ്ങൾക്കും അവ കുടിച്ചു തീരുവോളം ഞാൻ വെള്ളം കോരാം.","p":1},{"v":20,"t":"അവൾ വേഗം വെള്ളം തൊട്ടിയിലേക്കു പകർന്നു; വെള്ളംകോരാൻ വീണ്ടും കിണറ്റിലേക്കോടി; അവന്റെ ഒട്ടകങ്ങൾക്കെല്ലാം വെള്ളംകോരി."},{"v":21,"t":"അവൻ അവളെ സാകൂതം നോക്കിനിന്നു; തന്റെ വഴി കർത്താവു ശുഭമാക്കിയോ ഇല്ലയോ എന്നറിയാൻ അയാൾ നിശ്ശബ്ദനായിരുന്നു.","p":1},{"v":22,"t":"ഒട്ടകങ്ങൾ കുടിച്ചു കഴിഞ്ഞപ്പോൾ, അവൻ അവൾക്കുവേണ്ടി അര ഷെക്കെൽ തൂക്കമുള്ള ഒരു സ്വർണ്ണമൂക്കുത്തിയും പത്തു സ്വർണ്ണത്തൂക്കമുള്ള രണ്ടു കൈവളകളും എടുത്തു."},{"v":23,"t":"അവൻ പറഞ്ഞു: നീ ആരുടെ മകളാണെന്ന് എന്നെ അറിയിച്ചാലും. നിന്റെ പിതാവിന്റെ ഭവനത്തിൽ ഞങ്ങൾക്കു രാപാർക്കാൻ ഇടം കാണുമോ?","p":1},{"v":24,"t":"അവൾ അവനോടു പറഞ്ഞു: നാഹോറിനായി മില്ക്കാ പ്രസവിച്ച പുത്രൻ ബെത്തൂവേലിന്റെ മകളാണു് ഞാൻ.","p":1},{"v":25,"t":"അവൾ വീണ്ടും പറഞ്ഞു: ഞങ്ങളുടെ പക്കൽ വൈക്കോലും തീറ്റയും വേണ്ടുവോളമുണ്ട്; താമസിക്കാൻ ഇടവുമുണ്ടു്.","p":1},{"v":26,"t":"അയാൾ കുമ്പിട്ടു കർത്താവിനെ ആരാധിച്ചു.","p":1},{"v":27,"t":"എന്നിട്ടു പറഞ്ഞു: എന്റെ യജമാനനായ അബ്രാഹാമിന്റെ ദൈവമായ കർത്താവ് വാഴ്ത്തപ്പെട്ടവനാകട്ടെ! തന്റെ കാരുണ്യവും വിശ്വസ്തതയും അവിടുന്ന് എന്റെ യജമാനനിൽനിന്നു പിൻവലിച്ചിട്ടില്ല. എന്നെയാകട്ടെ, എന്റെ യജമാനന്റെ സഹോദരങ്ങളുടെ ഭവനത്തിലേക്ക് കർത്താവു് വഴിനയിക്കുകയും ചെയ്തിരിക്കുന്നു.","p":1},{"v":28,"t":"പെൺകുട്ടി ഓടിച്ചെന്നു തന്റെ അമ്മയുടെ വീട്ടുകാരെ ഇക്കാര്യങ്ങൾ യഥാക്രമം ധരിപ്പിച്ചു.","p":1},{"v":29,"t":"റബേക്കായ്ക്കു് ലാബാൻ എന്നു പേരുള്ള ഒരു സഹോദരനുണ്ടായിരുന്നു. ലാബാൻ പുറത്തു് ഉറവയുടെ അരികിലേക്ക്, ആ മനുഷ്യന്റെ അടുത്തേക്കു് ഓടി.","p":1},{"v":30,"t":"മൂക്കുത്തിയും വളകളും തന്റെ സഹോദരി റബേക്കായുടെ കൈകളിൽ കാണുകയും ആ മനുഷ്യൻ എന്നോടിങ്ങനെ സംസാരിച്ചു എന്ന അവളുടെ വാക്കുകൾ കേൾക്കുകയും ചെയ്തപ്പോൾ, അവൻ ആ മനുഷ്യന്റെ അടുത്തേക്കു ചെന്നു; അതാ, അയാൾ ഒട്ടകങ്ങളുടെ സമീപത്തു ഉറവയ്ക്കരികിൽ നിൽക്കുകയായിരുന്നു.","p":1},{"v":31,"t":"അവൻ പറഞ്ഞു: കർത്താവിനാൽ അനുഗൃഹീതനേ, വരിക. എന്താണു പുറത്തുനിൽക്കുന്നത്? വീടും ഒട്ടകങ്ങൾക്കുള്ള സ്ഥലവും ഞാൻ തന്നെ ഒരുക്കിയിട്ടുണ്ടു്.","p":1},{"v":32,"t":"അയാൾ വീട്ടിലേക്കു വന്നു. അവൻ ഒട്ടകങ്ങളെ അഴിച്ചുവിട്ടു ഒട്ടകങ്ങൾക്കു കച്ചിയും തീറ്റയും കൊടുത്തു; ഒപ്പം, അയാളുടെ കാലുകളും കൂടെയുള്ള ആളുകളുടെ കാലുകളും കഴുകാൻ വെള്ളവും.","p":1},{"v":33,"t":"എന്റെ മുമ്പിൽ ഭക്ഷണം വിളമ്പവേ, അയാൾ പറഞ്ഞു: എന്റെ ദൗത്യം പറയാതെ ഞാൻ ഭക്ഷണം കഴിക്കുകയില്ല. പറഞ്ഞുകൊള്ളുക, അവൻ പറഞ്ഞു.","p":1},{"v":34,"t":"അപ്പോൾ അയാൾ പറഞ്ഞു: അബ്രാഹത്തിന്റെ ഭൃത്യനാണു ഞാൻ.","p":1},{"v":35,"t":"കർത്താവ് എന്റെ യജമാനനെ സമൃദ്ധമായി അനുഗ്രഹിച്ചിരിക്കുന്നു. അദ്ദേഹം വലിയവനായിത്തീർന്നിരിക്കുന്നു. ആടുമാടുകളെയും വെള്ളിയും സ്വർണവും ദാസന്മാരെയും പരിചാരികമാരെയും ഒട്ടകങ്ങളെയും കഴുതകളെയും അവിടുന്ന് അദ്ദേഹത്തിനു കൊടുത്തിരിക്കുന്നു."},{"v":36,"t":"എന്റെ യജമാനന്റെ ഭാര്യ സാറാ അവളുടെ വാർദ്ധക്യത്തിൽ എന്റെ യജമാനന് ഒരു പുത്രനെ പ്രസവിച്ചു. തനിക്കുള്ളതെല്ലാം അദ്ദേഹം അവനാണു കൊടുത്തിരിക്കുന്നത്.","p":1},{"v":37,"t":"എന്റെ യജമാനൻ എന്നെക്കൊണ്ട് ഇങ്ങനെ സത്യംചെയ്യിച്ചിരിക്കുകയാണ്: ഞാൻ പാർക്കുന്ന നാട്ടിലെ കാനാൻകാരുടെ പുത്രിമാരിൽനിന്ന് എന്റെ മകന് വധുവിനെ നീ തിരഞ്ഞെടുക്കരുത്.","p":1},{"v":38,"t":"മറിച്ച്, എന്റെ പിതൃഭവനത്തിൽ, എന്റെ വംശക്കാരുടെപക്കൽ ചെന്ന് എന്റെ പുത്രന് ഭാര്യയെ കൊണ്ടുവരണം.","p":1},{"v":39,"t":"ഞാൻ എന്റെ യജമാനനോടു ചോദിച്ചു: ഒരുവേള, ആ സ്ത്രീ എന്റെ പിന്നാലെ വന്നില്ലെങ്കിലോ?","p":1},{"v":40,"t":"അദ്ദേഹം എന്നോടു പറഞ്ഞു: ഞാൻ ആരുടെ മുമ്പിൽ വ്യാപരിക്കുന്നുവോ ആ കർത്താവ് തന്റെ ദൂതനെ നിന്റെകൂടെ അയച്ച് നിന്റെ വഴി ശുഭമാക്കും. എന്റെ വംശക്കാരിൽനിന്ന്, എന്റെ പിതൃഭവനത്തിൽനിന്ന് എന്റെ പുത്രന് നീ ഒരു സ്ത്രീയെ കൊണ്ടുവരുകതന്നെ ചെയ്യും.","p":1},{"v":41,"t":"എന്റെ വംശജരുടെ അടുത്തു ചെല്ലുന്നതുകൊണ്ടുതന്നെ നീ എന്റെ പ്രതിജ്ഞയിൽനിന്ന് വിമുക്തനാകും. അവർ അവളെ നിനക്ക് വിട്ടുതന്നില്ലെങ്കിലും എന്റെ പ്രതിജ്ഞയിൽനിന്ന് നീ വിമുക്തനായിരിക്കും.","p":1},{"v":42,"t":"ഇന്ന് ഞാൻ ഉറവയ്ക്കരികിൽ വന്നപ്പോൾ പറഞ്ഞു: എന്റെ യജമാനനായ അബ്രാഹത്തിന്റെ ദൈവമായ കർത്താവേ, ഞാൻ സഞ്ചരിക്കുന്ന വഴി ശുഭമാക്കാൻ അങ്ങ് മനസ്സാകുന്നുവെങ്കിൽ,","p":1},{"v":43,"t":"ഇതാ, ഞാൻ ഈ നീരുറവയ്ക്കരികിൽ നിൽക്കുന്നു. വെള്ളംകോരാൻ വരുന്ന യുവതിയോട്, ദയവായി നിന്റെ കുടത്തിൽനിന്ന് എനിക്കല്പം വെള്ളം കുടിക്കാൻതരുക എന്ന് ഞാൻ പറയുമ്പോൾ,","p":1},{"v":44,"t":"കുടിച്ചുകൊള്ളുക; താങ്കളുടെ ഒട്ടകങ്ങൾക്കും ഞാൻ വെള്ളം കോരാം എന്ന് എന്നോടു പറയുന്നവളായിരിക്കും എന്റെ യജമാനന്റെ പുത്രന് കർത്താവ് നിശ്ചയിച്ചിട്ടുള്ള ഭാര്യ.","p":1},{"v":45,"t":"എന്റെ ഉള്ളിൽ ഞാനിതു പറഞ്ഞു...","p":1},{"v":45,"t":"വലതു വശം:","p":1},{"v":45,"t":"തീരുംമുമ്പ് ഇതാ, തോളിൽ കുടവുമായി റബേക്കാ പുറത്തേക്കു വരുന്നു; അവൾ ഉറവിൽ ഇറങ്ങിച്ചെന്ന് വെള്ളംകോരി. ഞാൻ അവളോട്, ദയവായി എനിക്ക് കുടിക്കാൻ തരുക എന്നുപറഞ്ഞു.","p":1},{"v":46,"t":"അവൾ ഉടനെ കുടം താഴ്ത്തിവെച്ചുകൊണ്ടു പറഞ്ഞു: കുടിച്ചോളൂ; താങ്കളുടെ ഒട്ടകങ്ങൾക്കും ഞാൻ കുടിക്കാൻ കൊടുക്കാം. ഞാൻ കുടിച്ചു; ഒട്ടകങ്ങൾക്കും അവൾ കുടിക്കാൻ കൊടുത്തു.","p":1},{"v":47,"t":"അപ്പോൾ, ഞാൻ അവളോട് അന്വേഷണാർഥംനീ ആരുടെ മകളാണ് എന്ന് ചോദിച്ചു. നാഹോറിന് മിൽക്കാ പ്രസവിച്ച പുത്രനായ ബത്തൂവേലിന്റെ മകളാണു ഞാൻ എന്ന് അവൾ പറഞ്ഞു. അപ്പോൾ ഞാൻ അവളുടെ മൂക്കിൽ മൂക്കുത്തിയും കൈകളിൽ വളകളും അണിയിച്ചു.","p":1},{"v":48,"t":"അതിനുശേഷം ഞാൻ കുമ്പിട്ടു കർത്താവിനെ ആരാധിച്ചു; എന്റെ യജമാനനായ അബ്രാഹത്തിന്റെ ദൈവമായ കർത്താവിനെ ഞാൻ വാഴ്ത്തി. കാരണം, എന്റെ യജമാനന്റെ സഹോദരപുത്രിയെ അദ്ദേഹത്തിന്റെ പുത്രനുവേണ്ടി കൊണ്ടുവരാൻ അവിടുന്ന് എന്നെ നേരായ മാർഗ്ഗത്തിൽ നയിച്ചു.","p":1},{"v":49,"t":"ഇപ്പോൾ അതുകൊണ്ട് എന്റെ യജമാനനോടു നിങ്ങൾ കാരുണ്യത്തോടെയും വിശ്വസ്തതയോടെയും പെരുമാറുമെങ്കിൽ എന്നോടു പറയുക; മറിച്ചാണെങ്കിലും എന്നോടു പറയുക. എനിക്ക് വലത്തോട്ടോ ഇടത്തോട്ടോ തിരിയാമല്ലോ.","p":1},{"v":50,"t":"അപ്പോൾ ലാബാനും ബത്തൂവേലും മറുപടിയായി പറഞ്ഞു: ഇക്കാര്യം കർത്താവിൽനിന്ന് വന്നതാണ്. ഞങ്ങൾക്ക് നിന്നോട് ദോഷമോ ഗുണമോ പറയാനാവില്ല.","p":1},{"v":51,"t":"ഇതാ, റബേക്കാ നിന്റെ മുമ്പിൽ; കൊണ്ടുപോയ്ക്കൊള്ളുക. കർത്താവ് അരുൾചെയ്തതുപോലെ അവൾ നിന്റെ യജമാനന്റെ മകനു ഭാര്യയാകട്ടെ.","p":1},{"v":52,"t":"അവരുടെ വാക്കുകൾ കേട്ടപ്പോൾ അബ്രാഹത്തിന്റെ ഭൃത്യൻ കർത്താവിനെ നിലംപറ്റെ വണങ്ങി.","p":1},{"v":53,"t":"അനന്തരം, ആ ഭൃത്യൻ വെള്ളിയാഭരണങ്ങളും സ്വർണ്ണാഭരണങ്ങളും വസ്ത്രങ്ങളും പുറത്തെടുത്ത് റബേക്കായ്ക്കു കൊടുത്തു; വിലപിടിപ്പുള്ള വസ്തുക്കൾ അവൻ അവളുടെ സഹോദരനും അമ്മയ്ക്കും കൊടുത്തു.","p":1},{"v":54,"t":"അവനും കൂടെയുണ്ടായിരുന്നവരും ഭക്ഷിക്കുകയും പാനംചെയ്യുകയും അവിടെ രാപ്പാർക്കുകയും ചെയ്തു; പുലർച്ചെ എഴുന്നേറ്റ് അവൻ പറഞ്ഞു: എന്റെ യജമാനന്റെ അടുത്തേക്ക് എന്നെ പറഞ്ഞയച്ചാലും.","p":1},{"v":55,"t":"അവളുടെ സഹോദരനും അമ്മയും പറഞ്ഞു: കുറച്ചുനാൾ, അല്ലെങ്കിൽ പത്തുദിവസം പെൺകുട്ടി ഞങ്ങളോടൊപ്പം പാർക്കട്ടെ. അതുകഴിഞ്ഞ് അവൾക്കു പോകാം.","p":1},{"v":56,"t":"അവൻ അവരോടു പറഞ്ഞു: എന്നെ വൈകിക്കരുത്, കർത്താവ് എന്റെ വഴി ശുഭമാക്കിയിരിക്കയാണ്","p":1},{"v":57,"t":"അവർ പറഞ്ഞു: നമുക്കു പെൺകുട്ടിയെ വിളിച്ച് അവളുടെ അഭിപ്രായംചോദിക്കാം.","p":1},{"v":58,"t":"അവർ റബേക്കായെ വിളിച്ച്, നീ ഈ മനുഷ്യനോടുകൂടെ പോകുന്നുവോ എന്നുചോദിച്ചു. ഞാൻ പോകുന്നു എന്ന് അവൾ മറുപടിപറഞ്ഞു.","p":1},{"v":59,"t":"അവർ അവരുടെ സഹോദരി റബേക്കായെയും അവളുടെ തോഴിയെയും അബ്രാഹത്തിന്റെ ഭൃത്യനെയും അവന്റെ ആളക്കാരെയും പറഞ്ഞയച്ചു.","p":1},{"v":60,"t":"റബേക്കായെ ആശീർവദിച്ചുകൊണ്ട് അവർ അവളോടു പറഞ്ഞു:","p":1},{"v":60,"t":"ഞങ്ങളുടെ സഹോദരീ,","p":1},{"v":60,"t":"നീ പതിനായിരത്തിന്റെ ആയിരങ്ങളായിത്തീരട്ടെ.","p":1},{"v":60,"t":"നിന്റെ സന്തതി, തന്നെ വെറുക്കുന്നവരുടെ കവാടം കൈവശമാക്കട്ടെ.","p":1},{"v":61,"t":"റബേക്കായും അവളുടെ ഭൃത്യകളും എഴുന്നേറ്റ് ഒട്ടകപ്പുറത്തു കയറി അയാളെ അനുഗമിച്ചു. അങ്ങനെ ആ ദാസൻ റബേക്കായെയും കൂട്ടി യാത്രയായി.","p":1},{"v":62,"t":"ആയിടയ്ക്ക് ഇസഹാക്ക് ബേർ-ല്ഹായ്-റോയിയുടെ സമീപത്തുനിന്നു വന്ന് നെഗെബ്ദേശത്തു താമസിക്കുകയായിരുന്നു.","p":1},{"v":63,"t":"വയലിൽ ധ്യാനിച്ച് സായാഹ്നം ചെലവഴിക്കാൻ ഇസഹാക്ക് പുറത്തിറങ്ങി. അവൻ ദൃഷ്ടികളുയർത്തിയപ്പോൾ കണ്ടു, ഇതാ, ഒട്ടകങ്ങൾ വരുന്നു.","p":1},{"v":64,"t":"റബേക്കാ കണ്ണുകൾ ഉയർത്തിയപ്പോൾ ഇസഹാക്കിനെ കണ്ട് ഒട്ടകപ്പുറത്തുനിന്നു വേഗമിറങ്ങി.","p":1},{"v":65,"t":"അവൾ ഭൃത്യനോടു ചോദിച്ചു: വയലിലൂടെ നമുക്കഭിമുഖമായി നടന്നുവരുന്ന ആ പുരുഷൻ ആരാണ്? ഭൃത്യൻ പറഞ്ഞു: അതെന്റെ യജമാനനാണ്. ഉടനെ അവൾ മൂടുപടമെടുത്ത് സ്വയം മറച്ചു.","p":1},{"v":66,"t":"താൻ ചെയ്ത എല്ലാക്കാര്യങ്ങളും ഭൃത്യൻ ഇസഹാക്കിനോടു വിവരിച്ചു.","p":1},{"v":67,"t":"ഇസഹാക്ക് തന്റെ അമ്മ സാറായുടെ കൂടാരത്തിലേക്കു റബേക്കായെ കൂട്ടിക്കൊണ്ടുവന്നു. അവൻ അവളെ സ്വീകരിച്ചു; അവൾ അവനു ഭാര്യയായിത്തീർന്നു. അവൻ അവളെ സ്നേഹിച്ചു. അങ്ങനെ തന്റെ അമ്മയുടെ മരണശേഷം ഇസഹാക്ക് സമാശ്വാസം കണ്ടെത്തി.","p":1}],"25":[{"h":"അബ്രാഹത്തിന്റെ ഇതരസന്തതികൾ"},{"v":1,"t":"അബ്രാഹം കെത്തൂറാ എന്നു പേരുള്ള ഒരു സ്ത്രീയെക്കൂടി വിവാഹം ചെയ്തിരുന്നു.","p":1},{"v":2,"t":"സിമ്രാൻ, യോക്ഷാൻ, മെദാൻ, മിദിയാൻ, ഇഷ്ബാക്ക്, ഷൂവാഹ് എന്നിവരെ അവൾ പ്രസവിച്ചു.","p":1},{"v":3,"t":"യോക്ഷാൻ ഷെബാനും ദെദാനും ജന്മംകൊടുത്തു. ദെദാന്റെ സന്തതികളായിരുന്നു അശ്ശൂറിം, ലത്തൂഷിം, ലവൂമിം എന്നിവർ,","p":1},{"v":4,"t":"മിദിയാന്റെ സന്തതികൾ ഏഫാ, ഏഫെർ, ഹനോക്, അബീദാ, എൽദായാ എന്നിവരാണ്; ഇവരെല്ലാവരുമായിരുന്നു കെത്തൂറായുടെ സന്തതികൾ.","p":1},{"v":5,"t":"അബ്രാഹം തനിക്കുണ്ടായിരുന്നതെല്ലാം ഇസഹാക്കിനു കൊടുത്തു;","p":1},{"v":6,"t":"തന്റെ ഉപനാരികളിലുണ്ടായ മക്കൾക്കും അബ്രാഹം സമ്മാനങ്ങൾ നൽകി; അവൻ ജീവിച്ചിരിക്കുമ്പോൾത്തന്നെ അവരെയെല്ലാം തന്റെ മകനായ ഇസഹാക്കിൽനിന്നു ദൂരെ കിഴക്കൻദേശത്തേക്ക് പറഞ്ഞയച്ചു.അബ്രാഹത്തിന്റെ മരണം","p":1},{"v":7,"t":"അബ്രാഹം പൂർത്തിയാക്കിയ ആയുഷ്‌കാലം നൂറ്റി എഴുപത്തഞ്ചുവർഷമായിരുന്നു.","p":1},{"v":8,"t":"അബ്രാഹം അന്ത്യശ്വാസം വലിച്ചു; വാർദ്ധക്യത്തിന്റെ തികവിൽ, വയോധികനും സംതൃപ്തനുമായി മരിച്ച് അവൻ തന്റെ ജനങ്ങളോട് ചേർന്നു.","p":1},{"v":9,"t":"അവന്റെ പുത്രന്മാരായ ഇസഹാക്കും ഇസ്മായേലും ഒന്നിച്ച് മമ്രേയ്ക്കടുത്ത് ഹിത്യനായ സോഹാറിന്റെ പുത്രൻ എഫ്രോന്റെ പറമ്പിലെ മക്പേലാഗുഹയിൽ അവനെ സംസ്കരിച്ചു.","p":1},{"v":10,"t":"ഹിത്യരിൽനിന്ന് അബ്രാഹം വിലയ്ക്ക് വാങ്ങിയതാണ് ആ പറമ്പ്. അവിടെയാണ് അബ്രാഹവും അവന്റെ ഭാര്യ സാറായും സംസ്കരിക്കപ്പെട്ടത്.","p":1},{"v":11,"t":"അബ്രാഹത്തിന്റെ മരണശേഷം അവന്റെ പുത്രൻ ഇസഹാക്കിനെ ദൈവം അനുഗ്രഹിച്ചു; ഇസഹാക് ബേർലഹായ്റോയിയുടെ സമീപത്ത് പാർത്തു.","p":1},{"h":"ഇസ്മായേലിന്റെ സന്തതികൾ"},{"v":12,"t":"അബ്രാഹത്തിനായി സാറായുടെ ഈജിപ്തുകാരി പരിചാരിക ഹാഗാർ പ്രസവിച്ച, അബ്രാഹത്തിന്റെ പുത്രൻ ഇസ്മായേലിന്റെ തലമുറകൾ ഇവയാണ്.","p":1},{"v":13,"t":"ജനനക്രമമനുസരിച്ച് ഇസ്മായേലിന്റെ മക്കളുടെ പേരുവിവരം: ഇസ്മായേലിന്റെ കടിഞ്ഞൂൽപുത്രനായ നെബാ യോത്ത്, കേദാർ, അദ്ബേൽ, മിബ്‌സാം,","p":1},{"v":14,"t":"മിഷ്‌മാ, ദുമാ, മസ്സാ,","p":1},{"v":15,"t":"ഹദാദ്, തേമാ, യത്തൂർ,","p":1},{"v":16,"t":"നഫീഷ്, കേദെമാ. ഇവരാണ് ഇസ്മായേലിന്റെ പുത്രന്മാർ. ഗ്രാമങ്ങളും താമസസ്ഥലങ്ങളുമനുസരിച്ച് അവരുടെ ജനതകളുടെ പന്ത്രണ്ടു പ്രഭുക്കന്മാരുടെ പേരുകളാണിവ.","p":1},{"v":17,"t":"ഇസ്മായേലിന്റെ ആയുഷ്‌കാലം നൂറ്റിമുപ്പത്തേഴു വർഷമായിരുന്നു; അവൻ അന്ത്യശ്വാസം വലിച്ച്, മറിച്ച് തന്റെ ജനങ്ങളോട് ചേർന്നു.","p":1},{"v":18,"t":"ഈജിപ്തിനുമുമ്പിൽ അസ്സീറിയായിലേക്കുള്ള ദിശയിൽ ഹവിലാമുതൽ ഷൂർവരെ അവർ കുടിപാർത്തു. അവൻ തന്റെ സഹോദരന്മാർക്കെല്ലാം മുൻപിൽ താമസിച്ചു.ഏസാവും യാക്കോബും","p":1},{"v":19,"t":"അബ്രാഹത്തിന്റെ പുത്രൻ ഇസഹാക്കിന്റെ തലമുറകൾ ഇവയാണ്; അബ്രാഹം ഇസഹാക്കിനു ജന്മം കൊടുത്തു.","p":1},{"v":20,"t":"പദാൻ ആരാമിൽനിന്നുള്ള അരാമായനായ ബെത്തൂവേലിന്റെ പുത്രിയും അരാമ്യനായ ലാബാന്റെ സഹോദരിയുമായ റബേക്കായെ ഭാര്യയായി സ്വീകരിക്കുമ്പോൾ ഇസഹാക്കിനു നാൽപതു വയസ്സായിരുന്നു.","p":1},{"v":21,"t":"ഇസഹാക് തന്റെ ഭാര്യയ്ക്കുവേണ്ടി കർത്താവിനോട് അപേക്ഷിച്ചു; കാരണം, അവൾ വന്ധ്യയായിരുന്നു. കർത്താവ് അവന്റെ യാചന കേൾക്കുകയും അവന്റെ ഭാര്യ റബേക്കാ ഗർഭംധരിക്കുകയും ചെയ്തു.","p":1},{"v":22,"t":"അവളുടെ ഉദരത്തിൽക്കിടന്ന് പുത്രന്മാർ മല്ലിട്ടപ്പോൾ അവൾ പറഞ്ഞു: ഇങ്ങനെയാണെങ്കിൽ എനിക്ക് ഇത് എന്തിനാണ്? അവൾ കർത്താവിന്റെ പക്കൽ ഇതെക്കുറിച്ച് അന്വേഷിക്കാൻ പോയി.","p":1},{"v":23,"t":"കർത്താവ് അവളോട് അരുൾചെയ്തു:","p":1},{"v":23,"t":"രണ്ടു ജാതികൾ നിന്റെ ഉദരത്തിൽ;","p":1},{"v":23,"t":"രണ്ടു ജനതകൾ നിന്റെ ഉള്ളിൽവെച്ചു വേർതിരിക്കപ്പെടും.","p":1},{"v":23,"t":"ഒരു ജനത മറ്റേ ജനതയെക്കാൾ ശക്തമാകും;","p":1},{"v":23,"t":"മൂത്തവൻ ഇളയവനെ സേവിക്കും.","p":1},{"v":24,"t":"അവളുടെ പ്രസവകാലം പൂർത്തിയായപ്പോൾ ഇതാ, അവളുടെ ഉദരത്തിൽ ഇരട്ടകൾ!","p":1},{"v":25,"t":"ഒന്നാമൻ പുറത്തുവന്നു. അവൻ ചെമന്നിരുന്നു; അവന്റെ ദേഹം മുഴുവൻ രോമക്കുപ്പായംപോലെയായിരുന്നു. അവർ അവന് ഏസാവ് എന്നു പേരിട്ടു.","p":1},{"v":26,"t":"അതിനുശേഷം അവന്റെ സഹോദരൻ പുറത്തുവന്നു. അവന്റെ കരം ഏസാവിന്റെ കുതികാലിൽ പിടിച്ചിരുന്നു. അവനെ യാക്കോബ് എന്ന് പേരുവിളിച്ചു. അവൾ അവരെ പ്രസവിച്ചപ്പോൾ ഇസഹാക്കിന് അറുപതു വയസ്സായിരുന്നു.","p":1},{"h":"ഏസാവ് കടിഞ്ഞൂലവകാശം വിൽക്കുന്നു"},{"v":27,"t":"കുട്ടികൾ വളർന്നപ്പോൾ, ഏസാവ് നായാട്ടിൽ സമർഥനും വനപ്രദേശമനുഷ്യനുമായിരുന്നു; യാക്കോബാകട്ടെ, കൂടാരങ്ങളിൽ പാർക്കുന്ന പ്രശാന്തനും.","p":1},{"v":28,"t":"നായാട്ടിറച്ചി തനിക്ക് രുചികരമാകയാൽ ഇസഹാക് ഏസാവിനെ സ്നേഹിച്ചു; എന്നാൽ, റബേക്കാ യാക്കോബിനെയാണു സ്നേഹിച്ചത്.","p":1},{"v":29,"t":"ഒരിക്കൽ, യാക്കോബ് പായസം പാചകംചെയ്യുകയായിരുന്നു. അപ്പോൾ ഏസാവ് വയലിൽനിന്നു വന്നു; അവൻ അവശനായിരുന്നു.","p":1},{"v":30,"t":"ഏസാവ് യാക്കോബിനോടു പറഞ്ഞു: ആ ചെമന്നുചെമന്നിരിക്കുന്നതിൽനിന്ന് എനിക്കു തിന്നാൻ തരുക. കാരണം, ഞാൻ അവശനായിരിക്കുന്നു. തന്മൂലം അവന് ഏദോം എന്നു പേരുണ്ടായി.","p":1},{"v":31,"t":"യാക്കോബ് പറഞ്ഞു: ഇപ്പോൾത്തന്നെ നിന്റെ കടിഞ്ഞൂലവകാശം എനിക്കു വില്ക്കുക.","p":1},{"v":32,"t":"ഏസാവ് പറഞ്ഞു: ഞാനിതാ ചാകാൻ പോകുന്നു; ഈ കടിഞ്ഞൂലവകാശം എനിക്കെന്തിന്?","p":1},{"v":33,"t":"യാക്കോബ് പറഞ്ഞു: ഇപ്പോൾത്തന്നെ എന്നോടു ശപഥംചെയ്യുക. ഏസാവ് അവനോടു ശപഥംചെയ്തു തന്റെ കടിഞ്ഞൂലവകാശം യാക്കോബിനു വിറ്റു.","p":1},{"v":34,"t":"യാക്കോബ് ഏസാവിന് അപ്പവും പയറുപായസവും നൽകി. തിന്നുകയും കുടിക്കുകയും ചെയ്തിട്ട് അവൻ എഴുന്നേറ്റുപോയി. അങ്ങനെ ഏസാവ് തന്റെ കടിഞ്ഞൂലവകാശം അവമതിച്ചു.","p":1}],"26":[{"h":"ഇസഹാക്കും അബിമെലക്കും"},{"v":1,"t":"നാട്ടിൽ ഒരു ക്ഷാമമുണ്ടായി. മുൻപൊരിക്കൽ അബ്രാഹത്തിന്റെ നാളുകളിലുണ്ടായ ക്ഷാമത്തിനുപുറമേയായിരുന്നു ഇത്. ഇസഹാക്ക് ഗരാറിലേക്ക്, ഫിലിസ്ത്യരുടെ രാജാവായ അബിമെലക്കിന്റെപക്കലേക്കു പോയി.","p":1},{"v":2,"t":"കർത്താവ് അവനു പ്രത്യക്ഷപ്പെട്ട് അരുൾചെയ്തിരുന്നു: ഈജിപ്തിലേക്ക് പോകരുത്; ഞാൻ നിന്നോടു പറയുന്ന നാട്ടിൽ കുടിപാർക്കുക.","p":1},{"v":3,"t":"ഈ നാട്ടിൽ തത്കാലവാസം ചെയ്യുക. ഞാൻ നിന്റെകൂടെയുണ്ടായിരിക്കും. നിന്നെ ഞാൻ അനുഗ്രഹിക്കുകയും ചെയ്യും. നിനക്കും നിന്റെ സന്തതിക്കുമായി ഈ ദേശമെല്ലാം ഞാൻ തരും. നിന്റെ പിതാവായ അബ്രാഹത്തോടു ചെയ്ത ശപഥം ഞാൻ ഉറപ്പിക്കും.","p":1},{"v":4,"t":"ആകാശത്തിലെ നക്ഷത്രങ്ങൾപോലെ നിന്റെ സന്തതിയെ ഞാൻ വർധിപ്പിക്കും. ഈ ദേശമെല്ലാം നിന്റെ സന്തതിക്കു ഞാൻ നൽകും. ഭൂമിയിലെ എല്ലാ ജനതകളും നിന്റെ സന്തതിയാൽ അനുഗ്രഹിക്കപ്പെടും.","p":1},{"v":5,"t":"കാരണം, അബ്രാഹം എന്റെ സ്വരം കേൾക്കുകയും എന്റെ അനുശാസനങ്ങളും കൽപനകളും പ്രമാണങ്ങളും പ്രബോധനങ്ങളും പാലിക്കുകയും ചെയ്തു.","p":1},{"v":6,"t":"അങ്ങനെ ഇസഹാക്ക് ഗരാറിൽ തന്നെ താമസിച്ചു.","p":1},{"v":7,"t":"അന്നാട്ടുകാർ അവന്റെ ഭാര്യയെക്കുറിച്ചു ചോദിച്ചപ്പോൾ, 'അവൾ എന്റെ സഹോദരിയാണ്' എന്ന് അവൻ പറഞ്ഞു. കാരണം, റബെക്കാ കാണാൻ അഴകുള്ളവളായതുകൊണ്ട് അവൾനിമിത്തം അന്നാട്ടുകാർ അവനെ കൊന്നുകളയാതിരിക്കേണ്ടതിന് 'അവൾ എന്റെ ഭാര്യയാണ്' എന്നു പറയാൻ അവൻ ഭയപ്പെട്ടു.","p":1},{"v":8,"t":"അവൻ കുറേക്കാലം അവിടെ താമസമാക്കി. ഒരിക്കൽ ഫിലിസ്ത്യരുടെ രാജാവായ അബിമെലക് ജാലകത്തിലൂടെ താഴേക്കു നോക്കിയപ്പോൾ, ഇതാ ഇസഹാക്ക് ഭാര്യ റബെക്കായെ പുണരുന്നതു കണ്ടു.","p":1},{"v":9,"t":"അബിമെലക് ഇസഹാക്കിനെ വിളിച്ചു പറഞ്ഞു: നോക്കൂ, അവൾ തീർച്ചയായും നിന്റെ ഭാര്യയാണ്. പിന്നെ എന്തുകൊണ്ടാണ്, ഇവൾ എന്റെ സഹോദരിയാണ് എന്നു നീ പറഞ്ഞത്? ഇസഹാക്ക് അവനോടു പറഞ്ഞു: അവൾമൂലം ഞാൻ മരിക്കാതിരിക്കേണ്ടതിനാണ് അങ്ങനെ പറഞ്ഞത്.","p":1},{"v":10,"t":"അബിമെലക് ചോദിച്ചു: ഇതെന്താണ് നീ ഞങ്ങളോടു ചെയ്തത്? ജനങ്ങളിലാരെങ്കിലും അബദ്ധവശാൽ നിന്റെ ഭാര്യയോടൊത്തു ശയിക്കുകയും അങ്ങനെ ഞങ്ങളുടെമേൽ നീ കുറ്റം വരുത്തുകയും ചെയ്യുമായിരുന്നു.","p":1},{"v":11,"t":"അതെത്തുടർന്ന്, അബിമെലക് എല്ലാ ജനങ്ങളോടും ഇപ്രകാരം കല്പിച്ചു: ഈ മനുഷ്യനെയോ അവന്റെ ഭാര്യയെയോ ആരെങ്കിലും തൊട്ടുപോയാൽ അവൻ നിശ്ചയമായും മരിക്കും.","p":1},{"v":12,"t":"ഇസഹാക്ക് ആ നാട്ടിൽ വിതയ്ക്കുകയും അക്കൊല്ലം തന്നെ നൂറുമേനി നേടുകയും ചെയ്തു. കർത്താവ് അവനെ അനുഗ്രഹിച്ചു.","p":1},{"v":13,"t":"അവൻ അഭിവൃദ്ധിപ്പെട്ട് വളരെ വലിയവനാകുന്നതുവരെ പടിപടിയായി വളർന്നുകൊണ്ടിരുന്നു.","p":1},{"v":14,"t":"അവന് സ്വന്തമായി ആടുമാടുകളും വലിയൊരു പരിചാരകവൃന്ദവും ഉണ്ടായിരുന്നു. അതുകൊണ്ട്, ഫിലിസ്ത്യർക്ക് അവനോട് അസൂയതോന്നി.","p":1},{"v":15,"t":"അവന്റെ പിതാവായ അബ്രാഹത്തിന്റെ കാലത്ത് പിതാവിന്റെ വേലക്കാർ കുഴിച്ച എല്ലാ കിണറുകളും ഫിലിസ്ത്യർ ഉപരോധിക്കുകയും പൂഴിയിട്ടു നികത്തുകയും ചെയ്തു.","p":1},{"v":16,"t":"അബിമെലക് ഇസഹാക്കിനോടു പറഞ്ഞു: ഞങ്ങളെ വിട്ടുപോവുക. എന്തെന്നാൽ, നീ ഞങ്ങളെക്കാൾ കൂടുതൽ ശക്തനായിരിക്കുന്നു.","p":1},{"v":17,"t":"ഇസഹാക്ക് അവിടുനിന്നു പോയി ഗരാർ നീർച്ചാലിനടുത്തു താവളമടിച്ച്, അവിടെ താമസമാക്കി.","p":1},{"v":18,"t":"തന്റെ പിതാവായ അബ്രാഹത്തിന്റെ കാലത്തു കുഴിച്ചതും അബ്രാഹത്തിന്റെ മരണശേഷം ഫിലിസ്ത്യർ ഉപരോധിച്ചതുമായ വെള്ളമുള്ള കിണറുകളെയെല്ലാം ഇസഹാക്ക് പുതുക്കിക്കുഴിച്ചു; തന്റെ പിതാവ് നൽകിയിരുന്ന പേരുകൾതന്നെ അവയ്ക്കു നൽകുകയും ചെയ്തു.","p":1},{"v":19,"t":"നീർച്ചാലിനടുത്തു കുഴിച്ചുകൊണ്ടിരിക്കേ, ഇസഹാക്കിന്റെ വേലക്കാർ നീരുറവുള്ള ഒരു കിണർ കണ്ടെത്തി.","p":1},{"v":20,"t":"അപ്പോൾ ഗരാറിലെ ഇടയന്മാർ, 'ഈ വെള്ളം ഞങ്ങളുടേതാണ്' എന്നു പറഞ്ഞ് ഇസഹാക്കിന്റെ ഇടയന്മാരുമായി തർക്കിച്ചു. അവൻ ആ വഴക്കിടിച്ചതിനാൽ അവൻ ആ കിണറിന് ഏസെക് എന്നു പേരിട്ടു.","p":1},{"v":21,"t":"അവർ മറ്റൊരു കിണർ കുഴിച്ചു. അതിനെപ്രതിയും അവർ തർക്കിച്ചു. അവൻ അതിന് സിത്നാ എന്നു വിളിച്ചു.","p":1},{"v":22,"t":"അവൻ അവിടെനിന്നു മുന്നോട്ടുനീങ്ങി വേറൊരു കിണർ കുഴിച്ചു. എന്നാൽ അതിന്റെ പേരിൽ അവർ കലഹിച്ചില്ല. അവൻ അതിന് രഹോബോത്ത് എന്നു പേരിട്ടുകൊണ്ടു പറഞ്ഞു: ഇപ്പോൾ കർത്താവ് ഞങ്ങൾക്ക് ഇടം വിശാലമാക്കിയിരിക്കുന്നതിനാൽ ഞങ്ങൾ ഭൂമിയിൽ പെരുകും.","p":1},{"v":23,"t":"അവിടെനിന്ന് അവൻ ബേർഷെബയിലേക്കു പോയി.","p":1},{"v":24,"t":"ആ രാത്രിയിൽ കർത്താവ് അവനു പ്രത്യക്ഷപ്പെട്ട് അരുൾചെയ്തു: നിന്റെ പിതാവായ അബ്രാഹത്തിന്റെ ദൈവമാണു ഞാൻ; നീ ഭയപ്പെടേണ്ട, എന്തെന്നാൽ ഞാൻ നിന്നോടുകൂടെയുണ്ട്. ഞാൻ നിന്നെ അനുഗ്രഹിക്കും; എന്റെ ദാസനായ അബ്രാഹത്തെപ്രതി നിന്റെ സന്തതിയെ ഞാൻ വർധിപ്പിക്കുകയും ചെയ്യും.","p":1},{"v":25,"t":"അവൻ അവിടെ ഒരു ബലിപീഠം പണിത്, കർത്താവിന്റെ നാമം വിളിച്ചപേക്ഷിച്ചു. അവൻ അവിടെ തന്റെ കൂടാരമടിച്ചു. ഇസഹാക്കിന്റെ ഭृत्यന്മാർ അവിടെ ഒരു കിണർ കുഴിച്ചു.","p":1},{"v":26,"t":"ഗരാറിൽനിന്ന് അബിമെലക് തന്റെ സ്നേഹിതനായ അഹുസ്സത്തും സേനാധിപനായ ഫികോളുമൊത്ത് അവന്റെ അടുത്തുചെന്നു.","p":1},{"v":27,"t":"ഇസഹാക്ക് അവരോടു ചോദിച്ചു: നിങ്ങളെന്തിനാണ് എന്റെ അടുക്കൽ വരുന്നത്? നിങ്ങൾ എന്നെ വെറുക്കുകയും നിങ്ങളുടെ ഇടയിൽനിന്ന് എന്നെ പുറത്താക്കുകയും ചെയ്തതാണല്ലോ.","p":1},{"v":28,"t":"അവർ പറഞ്ഞു: കർത്താവ് നിന്നോടുകൂടെയുണ്ടെന്ന് ഞങ്ങൾ വ്യക്തമായി കാണുന്നു. അതിനാൽ നമുക്കിടയിൽ, നിനക്കും ഞങ്ങൾക്കുമിടയിൽ, ഒരു പ്രതിജ്ഞയാകട്ടെ എന്നു ഞങ്ങൾ കരുതി. ഞങ്ങൾ നിന്നോട് ഒരു ഉടമ്പടിയുണ്ടാക്കാം.","p":1},{"v":29,"t":"ഞങ്ങൾ നിന്നെ ഉപദ്രവിക്കാതിരിക്കുകയും നിനക്കു നന്മമാത്രം ചെയ്യുകയും സമാധാനത്തിൽ നിന്നെ പറഞ്ഞയയ്ക്കുകയും ചെയ്തതുപോലെ നീയും ഞങ്ങളോടു തിന്മചെയ്യരുത്. നീ ഇപ്പോൾ കർത്താവിന്റെ അനുഗൃഹീതനാണ്.","p":1},{"v":30,"t":"അവൻ അവർക്കൊരു വിരുന്നൊരുക്കി. അവർ തിന്നുകയും കുടിക്കുകയും ചെയ്തു.","p":1},{"v":31,"t":"അവർ അതിരാവിലെ എഴുന്നേറ്റ് അന്യോന്യം ശപഥംചെയ്തു. ഇസഹാക്ക് അവരെ യാത്രയാക്കി. അവർ സമാധാനത്തോടെ അവനെ വിട്ടുപോയി.","p":1},{"v":32,"t":"അന്നുതന്നെ ഇസഹാക്കിന്റെ വേലക്കാർ വന്ന് തങ്ങൾ കുഴിച്ച കിണറിന്റെ കാര്യം അവനോടു വിവരിച്ചു: 'ഞങ്ങൾ വെള്ളം കണ്ടെത്തി' എന്ന് അവർ അവനെ അറിയിച്ചു.","p":1},{"v":33,"t":"അവൻ അതിനെ ഷേബാ എന്നു വിളിച്ചു.","p":1},{"h":"അതിനാൽ ഇന്നുവരെയും ആ പട്ടണത്തിന് ബേർഷെബാ എന്നാണ് പേര്"},{"v":34,"t":"നാല്പതു വയസ്സായപ്പോൾ ഏസാവ് ഹിത്യനായ ബേരിയുടെ പുത്രി യൂദിത്തിനെയും ഹിത്യനായ ഏലോണിന്റെ പുത്രി ബാസ്മത്തിനെയും വിവാഹം ചെയ്തു അവരാകട്ടെ ഇസഹാക്കിന്റെയും റബേക്കായുടെ മനസ്സിന് കൈയ്പായി തീർന്നു.","p":1}],"27":[{"v":1,"t":"ഇസഹാക്കിനു പ്രായമായതോടെ കണ്ണുകൾക്കു കാഴ്ചമങ്ങി. അദ്ദേഹം തന്റെ മൂത്ത മകൻ ഏസാവിനെ വിളിച്ച് അവനോടു പറഞ്ഞു: എന്റെ മകനേ. അവൻ വിളികേട്ടു: ഇതാ ഞാൻ.","p":1},{"v":2,"t":"അദ്ദേഹം പറഞ്ഞു: എനിക്കു വയസ്സായി. എന്റെ മരണദിവസം എനിക്കറിഞ്ഞുകൂടാ.","p":1},{"v":3,"t":"നിന്റെ ആയുധങ്ങളായ അമ്പും വില്ലുമെടുത്ത് വനത്തിൽ പോയി എനിക്കുവേണ്ടി ഇരയെ വേട്ടയാടുക.","p":1},{"v":4,"t":"മരിക്കുന്നതിനുമുമ്പ് എന്റെ ആത്മാവ് നിന്നെ അനുഗ്രഹിക്കേണ്ടതിന് രുചിയുള്ള ഭക്ഷണം എനിക്കിഷ്ടപ്പെട്ട രീതിയിൽ പാകംപെടുത്തി എന്റെയടുക്കൽ കൊണ്ടുവരിക; ഞാൻ ഭക്ഷിക്കട്ടെ.","p":1},{"v":5,"t":"ഇസഹാക്ക് പുത്രൻ ഏസാവിനോടു പറയുന്നത് റബെക്കാ കേൾക്കുന്നുണ്ടായിരുന്നു. ഏസാവ് വേട്ടയിറച്ചി കൊണ്ടുവരേണ്ടതിന് വയലിലേക്കു പോയി.","p":1},{"v":6,"t":"റബെക്കാ തന്റെ പുത്രൻ യാക്കോബിനോട് ഇപ്രകാരം പറഞ്ഞു: നിന്റെ പിതാവ് നിന്റെ സഹോദരൻ ഏസാവിനോട് ഇങ്ങനെ പറയുന്നതു ഇപ്പോൾ ഞാൻ കേട്ടു,","p":1},{"v":7,"t":"'എനിക്കായി വേട്ടയിറച്ചി കൊണ്ടുവന്ന് രുചികരമായ ഭക്ഷണം പാകംചെയ്യുക; ഞാൻ ഭക്ഷിച്ച്, എന്റെ മരണത്തിനുമുമ്പായി കർത്താവിന്റെ സന്നിധിയിൽ നിന്നെ അനുഗ്രഹിക്കട്ടെ'.","p":1},{"v":8,"t":"അതുകൊണ്ട്, എന്റെ മകനേ, ഞാൻ നിന്നോടു കല്പിക്കുന്നത് ഇപ്പോൾ അനുസരിക്കുക.","p":1},{"v":9,"t":"നീ ചെന്ന് ആട്ടിൻകൂട്ടത്തിൽ നിന്ന് രണ്ടു നല്ല കുഞ്ഞാടുകളെ എന്റെയടുക്കൽ പിടിച്ചുകൊണ്ടുവരിക. ഞാൻ നിന്റെ പിതാവിനുവേണ്ടി, അദ്ദേഹത്തിന് ഇഷ്ടപ്പെടുന്ന വിധത്തിൽ രുചികരമായവ പാകംചെയ്യാം.","p":1},{"v":10,"t":"നീ അത് നിന്റെ പിതാവിന്റെ അടുക്കൽ കൊണ്ടുചെല്ലണം. അപ്പോൾ അദ്ദേഹം അതു ഭക്ഷിക്കുകയും അതുവഴി മരണത്തിനുമുമ്പ് നിന്നെ അനുഗ്രഹിക്കുകയും ചെയ്യും.","p":1},{"v":11,"t":"യാക്കോബ് തന്റെ അമ്മ റബെക്കായോടു പറഞ്ഞു: നോക്കൂ, എന്റെ സഹോദരൻ ഏസാവ് രോമാവൃതനാണ്; ഞാനാകട്ടെ, രോമമില്ലാത്തവനും.","p":1},{"v":12,"t":"ഒരുപക്ഷേ, എന്റെ പിതാവ് എന്നെ തടവിനോക്കുകയും അദ്ദേഹത്തിന്റെ മുമ്പിൽ ഞാൻ പരിഹസിക്കുന്നവനെപ്പോലെ ആകുകയും ചെയ്താൽ, അനുഗ്രഹമല്ല ശാപമായിരിക്കും ഞാൻ എന്റെമേൽ വരുത്തിവെയ്ക്കുക.","p":1},{"v":13,"t":"അവന്റെ അമ്മ നോടു പറഞ്ഞു: എന്റെ മകനേ, നിന്റെ ശാപം എന്റെ മേലായിരിക്കട്ടെ! ഇപ്പോൾ എന്റെ സ്വരം ശ്രവിക്കുക. നീ പോയി അവയെ പിടിച്ചു എന്റെയടുത്തു കൊണ്ടുവരിക.","p":1},{"v":14,"t":"അവൻ പോയി അവയെ പിടിച്ചു അമ്മയുടെ അടുക്കൽ കൊണ്ടു വന്നു. അവന്റെ പിതാവിന് ഇഷ്ടപ്പെട്ട രുചികരമായ ഭക്ഷണം അവന്റെ അമ്മ തയ്യാറാക്കി.","p":1},{"v":15,"t":"റബെക്കാ തന്റെ മൂത്തമകൻ ഏസാവിന്റെതായി വീട്ടിൽ അവളുടെ പക്കൽ ഉണ്ടായിരുന്ന ഏറ്റവും നല്ല വസ്ത്രങ്ങളെടുത്ത് തന്റെ ഇളയമകൻ യാക്കോബിനെ ധരിപ്പിച്ചു;","p":1},{"v":16,"t":"ആട്ടിൻകുട്ടിയുടെ തോലുകൊണ്ട് അവന്റെ കൈകളും കഴുത്തിലെ മിനുസമുള്ള ഭാഗവും അവൾ പൊതിഞ്ഞു.","p":1},{"v":17,"t":"അവൾ പാകംചെയ്ത രുചികരമായ ഭക്ഷണവും അപ്പവും മകൻ യാക്കോബിന്റെ കൈവശം ഏൽപ്പിച്ചു.","p":1},{"v":18,"t":"അവൻ പിതാവിന്റെയടുക്കൽച്ചെന്നു വിളിച്ചു: പിതാവേ! അദ്ദേഹം വിളികേട്ടു: ഇതാ ഞാൻ; നീയാരാണ് മകനേ?","p":1},{"v":19,"t":"യാക്കോബ് തന്റെ പിതാവിനോടു പറഞ്ഞു: അങ്ങയുടെ കടിഞ്ഞൂൽപുത്രൻ ഏസാവാണ് ഞാൻ. അങ്ങ് എന്നോട് ആവശ്യപ്പെട്ടതുപോലെ ഞാൻ ചെയ്തിരിക്കുന്നു. എഴുന്നേറ്റിരുന്നാലും; അങ്ങയുടെ ആത്മാവ് എന്നെ അനുഗ്രഹിക്കേണ്ടതിന് എന്റെ വേട്ടയിറച്ചിയിൽനിന്ന് ഭക്ഷിച്ചാലും.","p":1},{"v":20,"t":"ഇസഹാക്ക് തന്റെ പുത്രനോടു ചോദിച്ചു: ഇതെങ്ങനെ എന്റെ മകനേ? ഇത്രവേഗം നിനക്ക് കണ്ടെത്താൻ കഴിഞ്ഞല്ലോ! അവൻ പറഞ്ഞു: അങ്ങയുടെ ദൈവമായ കർത്താവാണ് എനിക്കിതു സാധ്യമാക്കിയത്.","p":1},{"v":21,"t":"അപ്പോൾ ഇസഹാക്ക് യാക്കോബിനോടു പറഞ്ഞു: മകനേ, ഞാൻ നിന്നെ സ്പർശിക്കേണ്ടതിന് അടുത്തുവരിക; നീ എന്റെ മകൻ ഏസാവുതന്നെയല്ലേ?","p":1},{"v":22,"t":"യാക്കോബ് തന്റെ പിതാവായ ഇസഹാക്കിന്റെയടുത്തു ചെന്നു. അവനെ തടവിനോക്കിയിട്ട് അദ്ദേഹം പറഞ്ഞു: സ്വരം യാക്കോബിന്റെ സ്വരവും കൈകൾ ഏസാവിന്റെ കൈകളും!","p":1},{"v":23,"t":"അവന്റെ കൈകൾ സഹോദരനായ ഏസാവിന്റെ കൈകൾപോലെ രോമാവൃതമായിരുന്നതിനാൽ അദ്ദേഹം അവനെ തിരിച്ചറിഞ്ഞില്ല. അവനെ അദ്ദേഹം അനുഗ്രഹിച്ചു.","p":1},{"v":24,"t":"അദ്ദേഹം ചോദിച്ചു: എന്റെ മകൻ ഏസാവ് നീ തന്നെയോ? ഞാൻതന്നെ, അവൻ മറുപടി പറഞ്ഞു.","p":1},{"v":25,"t":"അദ്ദേഹം പറഞ്ഞു: എന്റെ മകന്റെ വേട്ടയിറച്ചിയിൽനിന്ന് ഞാൻ ഭക്ഷിച്ച്, എന്റെ ആത്മാവ് നിന്നെ അനുഗ്രഹിക്കുന്നതിനായി അത് എന്റെ അടുത്തുകൊണ്ടുവരിക. അവൻ അത് അദ്ദേഹത്തിന്റെ പക്കൽ കൊണ്ടുചെന്നു; അദ്ദേഹം ഭക്ഷിച്ചു. അവൻ അദ്ദേഹത്തിന് വീഞ്ഞും കൊണ്ടുചെന്നു; അദ്ദേഹം കുടിക്കുകയും ചെയ്തു.","p":1},{"v":26,"t":"അവൻ്റെ പിതാവായ ഇസഹാക്ക് അവനോട് പറഞ്ഞു എൻ്റെ മകനേ, നീ അടുത്തുവന്ന് എന്നെ ചുംബിക്കുക.","p":1},{"v":27,"t":"അവൻ അടുത്തൂചെന്ന് അദ്ദേഹത്തെ ചുംബിച്ചു. അവന്റെ വസ്ത്രത്തിന്റെ ഗന്ധമറിഞ്ഞിട്ട് അവനെ ആശീർവദിച്ചുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: നോക്കൂ, എന്റെ മകന്റെ ഗന്ധം കർത്താവ് അനുഗ്രഹിച്ച വയലിന്റെ ഗന്ധംപോലെ!","p":1},{"v":28,"t":"ആകാശത്തിൽനിന്നും ഭൗമഫലപുഷ്ടിയിൽനിന്നും ദൈവം നിനക്ക് നൽകട്ടെ; ധാന്യത്തിന്റെയും വീഞ്ഞിന്റെയും സമൃദ്ധിയും.","p":1},{"v":29,"t":"ജനങ്ങൾ നിന്നെ സേവിക്കട്ടെ. ജനപദങ്ങൾ നിന്നെ നമിക്കട്ടെ. നിന്റെ സഹോദരങ്ങൾക്ക് നീ അധികാരിയാകുക. നിന്റെ അമ്മയുടെ മക്കൾ നിന്നെ നമിക്കട്ടെ. നിന്നെ ശപിക്കുന്നവർ ശപ്തർ; നിന്നെ അനുഗ്രഹിക്കുന്നവർ അനുഗൃഹീതർ!","p":1},{"h":"ഏസാവ് അനുഗ്രഹം യാചിക്കുന്നു"},{"v":30,"t":"ഇസഹാക്ക് യാക്കോബിനെ അനുഗ്രഹിച്ചുകഴിഞ്ഞ് യാക്കോബ് തന്റെ പിതാവായ ഇസഹാക്കിന്റെ മുമ്പിൽനിന്നു പുറത്തുകടന്നമാത്രയിൽ അവന്റെ സഹോദരൻ ഏസാവ് നായാട്ടുകഴിഞ്ഞ് എത്തിച്ചേർന്നു.","p":1},{"v":31,"t":"അവനും രുചികരമായ ഭക്ഷണം തയ്യാറാക്കി തന്റെ പിതാവിന്റെ അടുക്കൽകൊണ്ടുവന്നിട്ട് പിതാവിനോടു പറഞ്ഞു: എന്റെ പിതാവ് എഴുന്നേറ്റ്, മകന്റെ നായാട്ടിറച്ചിയിൽ നിന്നു ഭക്ഷിക്കട്ടെ! അതുവഴി, അങ്ങയുടെ ആത്മാവ് എന്നെ അനുഗ്രഹിക്കട്ടെ.","p":1},{"v":32,"t":"നീ ആരാണ്? അവന്റെ പിതാവായ ഇസഹാക്ക് അവനോടു ചോദിച്ചു. അവൻ പറഞ്ഞു: അങ്ങയുടെ പുത്രൻ, അങ്ങയുടെ കടിഞ്ഞൂൽപുത്രൻ ഏസാവാണ് ഞാൻ.","p":1},{"v":33,"t":"ഇസഹാക്ക് സംഭ്രമിച്ചുപോയി - അതിഭീമമായ സംഭ്രമം! അവൻ ചോദിച്ചു: അപ്പോൾ, ഇരയെ നായാടി എനിക്കു കൊണ്ടുവന്ന അവൻ ആരാണ്? നീ വരുന്നതിനുമുമ്പേ ഞാൻ അതിൽനിന്നെല്ലാം ഭക്ഷിക്കുകയും അവനെ അനുഗ്രഹിക്കുകയും ചെയ്തല്ലോ. അവൻ അനുഗ്രഹിക്കപ്പെട്ടവൻതന്നെയായിരിക്കും.","p":1},{"v":34,"t":"ഏസാവ് പിതാവിന്റെ വാക്കുകൾ കേട്ടപ്പോൾ നിലവിളിച്ചു - അതിതിക്തമായ വൻനിലവിളി! അവൻ പിതാവിനോട് അപേക്ഷിച്ചു: എന്നെ അനുഗ്രഹിക്കുക, എന്റെ പിതാവേ, എന്നെയും.","p":1},{"v":35,"t":"അവൻ പറഞ്ഞു: നിന്റെ സഹോദരൻ ചതിയിൽ വന്ന് നിനക്കുള്ള അനുഗ്രഹം തട്ടിയെടുക്കുമല്ലോ.","p":1},{"v":36,"t":"ഏസാവ് പറഞ്ഞു: അതുകൊണ്ടു തന്നെയല്ലേ അവനെ യാക്കോബ് എന്നു വിളിക്കുന്നത്! ഇത് രണ്ടാംപ്രാവശ്യമാണ് അവൻ എന്റെ കുതികാൽ വെട്ടുന്നത്: എന്റെ കടിഞ്ഞൂലവകാശം അവൻ കൈക്കലാക്കി; ഇതാ ഇപ്പോൾ, എനിക്കുള്ള അനുഗ്രഹവും അവൻ തട്ടിയെടുത്തുതിരിക്കുന്നു. എനിക്കുവേണ്ടി ഒരനുഗ്രഹംപോലും അങ്ങു നീക്കിവച്ചിട്ടില്ലേ? അവൻ ചോദിച്ചു.","p":1},{"v":37,"t":"ഇസഹാക്ക് ഏസാവിനോടു മറുപടി പറഞ്ഞു: നോക്കൂ, ഞാൻ അവനെ നിന്റെ അധികാരിയായി അവരോധിച്ചിരിക്കുന്നു; അവന്റെ എല്ലാ സഹോദരങ്ങളെയും അവനു സേവകരായി ഞാൻ നൽകിയിരിക്കുന്നു. ധാന്യവും പുതുവീഞ്ഞുംകൊണ്ട് ഞാൻ അവനെ ശക്തിപ്പെടുത്തി. എന്റെ മകനേ, നിനക്കുവേണ്ടി എന്താണ് എനിക്കിനി ചെയ്യാൻ കഴിയുക?","p":1},{"v":38,"t":"അപ്പോൾ ഏസാവ് പിതാവിനോടു പറഞ്ഞു; എന്റെ പിതാവേ, ഒറ്റ അനുഗ്രഹമേ അങ്ങയുടെ പക്കലുള്ളൂ? എന്നെ അനുഗ്രഹിക്കണമേ, എന്റെ പിതാവേ, എന്നെയും. ഏസാവ് സ്വർമുയർത്തിക്കരഞ്ഞു.","p":1},{"v":39,"t":"അവന്റെ പിതാവ് ഇസഹാക്ക് അവനോട് മറുപടിയായി പറഞ്ഞു: ഇതാ! ഭൗമഫലപുഷ്ടിയിൽനിന്നും ഉന്നതാകാശത്തിന്റെ മഞ്ഞിൽനിന്നും അകലെയായിരിക്കും നിന്റെ വാസസ്ഥലം.","p":1},{"v":40,"t":"നിന്റെ വാളുകൊണ്ട് നീ ജീവിക്കും; നിന്റെ സഹോദരനെ നീ സേവിക്കും. എന്നാൽ നീ അസ്വസ്ഥനാകുമ്പോൾ അവന്റെ നുകം നിന്റെ ചുമലിൽനിന്ന് നീ തകർത്തെറിയും.","p":1},{"h":"യാക്കോബ് ലാബാന്റെ അടുക്കലേക്ക്"},{"v":41,"t":"തന്റെ പിതാവ് യാക്കോബിനെ അനുഗ്രഹിച്ചതുമൂലം ഏസാവ് യാക്കോബിനെ വെറുത്തു. അവൻ ആത്മഗതംചെയ്തു: പിതാവിനെപ്പറ്റി വിലപിക്കാനുള്ള ദിവസങ്ങൾ അടുത്തുവരുന്നുണ്ട്. അതുകഴിഞ്ഞ് ഞാൻ എന്റെ സഹോദരൻ യാക്കോബിനെ കൊല്ലും.","p":1},{"v":42,"t":"തന്റെ മൂത്തമകൻ ഏസാവിന്റെ വാക്കുകളെപ്പറ്റി റബെക്കായ്ക്ക് അറിവുകിട്ടി. അവൾ തന്റെ ഇളയമകൻ യാക്കോബിനെ വിളിച്ചുവരുത്തി പറഞ്ഞു: ഇതാ, നിന്റെ സഹോദരൻ ഏസാവ് നിന്നെ കൊല്ലാ൯ഒരുങ്ങി പ്രതികാരചിന്തയിലാണ്.","p":1},{"v":43,"t":"എന്റെ മകനേ, ഇപ്പോൾ എന്റെ സ്വരം ശ്രവിക്കുക. എഴുന്നേറ്റ് ഹാരാനിലേക്ക്, എന്റെ സഹോദരൻ ലാബാന്റെ അടുക്കലേക്ക് രക്ഷപ്പെട്ടുകൊള്ളുക.","p":1},{"v":44,"t":"നിന്റെ സഹോദരന്റെ രോഷമടങ്ങുവോളം നീ കുറച്ചുനാൾ അവനോടൊപ്പം താമസിക്കുക.","p":1},{"v":45,"t":"നിന്റെ സഹോദരനു നിന്നോടുള്ള കോപം അടങ്ങുകയും നീ ചെയ്തതൊക്കെ അവൻ മറക്കുകയും ചെയ്യട്ടെ. അപ്പോൾ ഞാൻ ആളയച്ച് നിന്നെ അവിടെനിന്നു കൊണ്ടുവരാം. ഒരേദിവസം നിങ്ങൾ രണ്ടുപേരും എനിക്കു നഷ്ടപ്പെടുന്നതെന്തിന്?","p":1},{"v":46,"t":"റബെക്കാ ഇസഹാക്കിനോടു പറഞ്ഞു: ഈ ഹിത്യസ്ത്രീകളോടൊപ്പമുള്ള ജീവിതം എനിക്കു മടുത്തു. ഇവരെപ്പോലെയുള്ള ഈ നാട്ടുകാരായ ഹിത്യസ്ത്രീകളിൽനിന്ന് ഒരുവളെ യാക്കോബും ഭാര്യയായി സ്വീകരിച്ചാൽ പിന്നെ എനിക്ക് എന്തിനാണ് ജീവിതം?","p":1}],"28":[{"v":1,"t":"ഇസഹാക്ക് യാക്കോബിനെ വിളിച്ച് അവനെ അനുഗ്രഹിച്ചു; അവനോടു കൽപിച്ചുകൊണ്ടു പറഞ്ഞു: കാനാനുസ്ത്രീകളിൽനിന്ന് നീ ഭാര്യയെ സ്വീകരിക്കരുത്.","p":1},{"v":2,"t":"നീ എഴുന്നേറ്റ്, പാദാൻആരാമിൽ നിന്റെ അമ്മയുടെ പിതാവായ ബെത്തുവേലിന്റെ വീട്ടിലേക്കു പോവുക. അവിടെനിന്ന്, നിന്റെ അമ്മയുടെ സഹോദരനായ ലാബാന്റെ പുത്രിമാരിലൊരാളെ നീ ഭാര്യയായി സ്വീകരിക്കുക.","p":1},{"v":3,"t":"സർവശക്തനായ തമ്പുരാൻ നിന്നെ അനുഗ്രഹിച്ച്, ഫലസമൃദ്ധമാക്കി വർധിപ്പിക്കട്ടെ; അങ്ങനെ നീ ജനങ്ങളുടെ ഒരു സമൂഹമായിതീരും.","p":1},{"v":4,"t":"ദൈവം അബ്രാഹത്തിനു നൽകിയ നിന്റെ വിപ്രവാസത്തിന്റെ ഈ നാട് നീ അവകാശപ്പെടുത്തേണ്ടതിന് അബ്രാഹത്തിന്റെ അനുഗ്രഹം നിനക്കും നിന്നോടൊപ്പം നിന്റെ സന്തതിക്കുമായി അവിടുന്ന് നൽകട്ടെ.","p":1},{"v":5,"t":"അങ്ങനെ ഇസഹാക്ക് യാക്കോബിനെ പറഞ്ഞയച്ചു. അവൻ പാദാൻആരാമിലുള്ള, അരാമായനായ ബെത്തുവേലിന്റെ മകനും യാക്കോബിന്റെയും ഏസാവിന്റെയും അമ്മ റബെക്കായുടെ സഹോദരനുമായ ലാബാന്റെ അടുക്കലേക്കു പോയി.","p":1},{"v":6,"t":"ഇസഹാക്ക് യാക്കോബിനെ അനുഗ്രഹിച്ചതും പാദാൻആരാമിൽനിന്ന് ഭാര്യയെ കണ്ടുപിടിക്കുന്നതിന് പറഞ്ഞയച്ചതും അവനെ അനുഗ്രഹിക്കവേ, കാനാന്യരിൽ നിന്ന് ഭാര്യയെ സ്വീകരിക്കരുതെന്ന് അവനോടു കൽപ്പിച്ചതും ഏസാവ് മനസ്സിലാക്കി.","p":1},{"v":7,"t":"യാക്കോബ് തന്റെ പിതാവിനെയും മാതാവിനെയും അനുസരിച്ച് പാദാൻആരാമിലേക്കു പോയി.","p":1},{"v":8,"t":"തന്റെ പിതാവായ ഇസഹാക്കിന്റെ ദൃഷ്ടികളിൽ കാനാൻ പുത്രിമാർ ദൂഷിച്ചവരാണെന്ന് ഏസാവ് കണ്ടു.","p":1},{"v":9,"t":"ഏസാവ് ഇസ്മായേലിന്റെ അടുത്തുചെന്ന് അബ്രാഹത്തിന്റെ പുത്രനായ ഇസ്മായേലിന്റെ മകളും നെബാ","p":1},{"h":"യാക്കോബിന്റെ സ്വപ്നം"},{"v":10,"t":"യാക്കോബ് ബേർഷെബയിൽനിന്നു പുറപ്പെട്ട് ഹാരാനിലേക്കു പോയി.","p":1},{"v":11,"t":"അവൻ ഒരു സ്ഥലത്തെത്തിയപ്പോൾ സൂര്യൻ അസ്തമിക്കുകയാൽ അവിടെ രാപ്പാർത്തു. ആ സ്ഥലത്തെ കല്ലുകളിലൊന്നെടുത്ത് തലയ്കൽ വച്ച് ആ സ്ഥലത്ത് അവൻ കിടന്നു.","p":1},{"v":12,"t":"അപ്പോൾ അവൻ സ്വപ്നംകണ്ടു: ഇതാ, ഭൂമിയിൽ ഉറപ്പിച്ച ഒരു കോവണി! അതിന്റെ മുകളറ്റം ആകാശത്ം മുട്ടിയിരുന്നു. ദൈവതൂതന്മാർ അതിലൂടെ കയറുകയും ഇറങ്ങുകയും ചെയ്തുകൊണ്ടിരുന്നു!","p":1},{"v":13,"t":"ഇതാ, അതിനുമുകളിലായി കർത്താവ് നിൽക്കുന്നു! അവിടുന്ന് അരുൾചെയ്തു: ഞാൻ നിന്റെ പിതാവായ അബ്രാഹത്തിന്റെ ദൈവമായ കർത്താവും ഇസഹാക്കിന്റെ ദൈവവുമാണ്. നീ കിടക്കുന്ന ഈ ഭൂമി നിനക്കും നിന്റെ സന്തതിക്കും ഞാൻ നൽകും.","p":1},{"v":14,"t":"നിന്റെ സന്തതി ഭൂമിയിലെ പൂഴിപോലെയാകും; പടിഞ്ഞാറോട്ടും കിഴക്കോട്ടും വടക്കോട്ടും തെക്കോട്ടും നീ വ്യാപിക്കും. മണ്ണിലെ വംശങ്ങളെല്ലാം നിന്നിലൂടെയും നിന്റെ സന്തതിയിലൂടെയും അനുഗ്രഹിക്കപ്പെടും.","p":1},{"v":15,"t":"ഇതാ, ഞാൻ നിന്നോടുകൂടെയുണ്ട്. നീ പോകുന്ന ഇടത്തെല്ലാം ഞാൻ നിന്നെ സംരക്ഷിക്കും; നിന്നെ ഈ മണ്ണിലേക്കുതന്നെ തിരിയെക്കൊണ്ടുവരും. എന്തെന്നാൽ, നിന്നോടു ഞാൻ പറഞ്ഞതു നിറവേറ്റുന്നതുവരെ ഞാൻ നിന്നെ കൈവിടുകയില്ല.","p":1},{"v":16,"t":"അപ്പോൾ യാക്കോബ് ഉറക്കത്തിൽനിന്നുണർന്നു. അവൻ പറഞ്ഞു: തീർച്ചയായും കർത്താവ് ഈ സ്ഥലത്തുണ്ട്; എന്നാൽ, ഞാൻ അതറിഞ്ഞില്ല.","p":1},{"v":17,"t":"ഭീതിപൂണ്ട് അവൻ പറഞ്ഞു: ഈ സ്ഥലം എത്ര ഭയാനകമാണ്! ഇത് ദൈവത്തിന്റെ ഭവനമല്ലാതെ മറ്റൊന്നുമല്ല; സ്വർഗത്തിന്റെ കവാടമാണിത്.","p":1},{"v":18,"t":"യാക്കോബ് അതിരാവിലെ എഴുന്നേറ്റ് തലയ്ക്കു കീഴെ വച്ചിരുന്ന കല്ലെടുത്ത് ഒരു തൂണായി കുത്തിനിർത്തി അതിന്റെ മുകളിൽ എണ്ണയൊഴിച്ചു.","p":1},{"v":19,"t":"അവൻ ആ സ്ഥലത്തിന് ബേഥേൽ എന്നുപേരിട്ടു; ലൂസ് എന്നായിരുന്നു ആ പട്ടണത്തിന്റെ ആദ്യത്തെ പേര്.","p":1},{"v":20,"t":"അതുകഴിഞ്ഞ് യാക്കോബ് ഒരു നേർച്ചനേർന്നുകൊണ്ടു പറഞ്ഞു: ദൈവം എന്നോടുകൂടെയുണ്ടായിരിക്കുകയും ഞാൻ സഞ്ചരിക്കുന്ന ഈ വഴിയിൽ എന്നെ സംരക്ഷിക്കുകയും എനിക്കു ഭക്ഷിക്കാൻ അപ്പവും ധരിക്കാൻ വസ്ത്രവും തരുകയും","p":1},{"v":21,"t":"എന്റെ പിതാവിന്റെ വീട്ടിലേക്ക് സമാധാനത്തോടെ ഞാൻ തിരിച്ചെത്തുകയും ചെയ്താൽ കർത്താവ് എനിക്കു ദൈവമായിത്തീരും.","p":1},{"v":22,"t":"തൂണായി ഞാൻ കുത്തിനിർത്തിയിരിക്കുന്ന ഈ കല്ല് ദൈവത്തിന്റെ ഭവനമായിരിക്കും. അവിടുന്ന് എനിക്കു തരുന്നതിന്റെയെല്ലാം ദശാംശം ഞാൻ അവിടത്തേക്കു സമർപ്പിക്കുകയും ചെയ്യും.","p":1}],"29":[{"h":"ലാബാന്റെ വീട്ടിൽ"},{"v":1,"t":"യാക്കോബ് യാത്രതുടർന്ന് പൗരസ്ത്യരുടെ ദേശത്തേക്കു സഞ്ചരിച്ചു.","p":1},{"v":2,"t":"അവൻ നോക്കിയപ്പോൾ ഇതാ, വയലിൽ ഒരു കിണർ! അവിടെ അതിനുമുന്നിലായി മൂന്ന് ആട്ടിൻപറ്റങ്ങൾ കിടക്കുന്നുണ്ടായിരുന്നു. കാരണം, ആ കിണറ്റിൽനിന്നാണ് അവർ ആടുകളെ കുടിപ്പിച്ചിരുന്നത്. കിണറിന്റെ വായ്ക്കല്ല് വലുതായിരുന്നു.","p":1},{"v":3,"t":"അവർ ആട്ടിൻപറ്റങ്ങളെയെല്ലാം അവിടെ ഒരുമിച്ചുകൂട്ടുമ്പോൾ, കിണറിന്റെ വായ്ക്കല്ല് ഉരുട്ടിമാറ്റി ആടുകൾക്കു വെള്ളംകൊടുത്തിരുന്നു; അതുകഴിഞ്ഞ് കല്ല് കിണറിന്റെമുകളിൽ യഥാസ്ഥാനം തിരികെവയ്ക്കുകയും ചെയ്തിരുന്നു.","p":1},{"v":4,"t":"യാക്കോബ് അവരോടു ചോദിച്ചു: എന്റെ സഹോദരന്മാരേ, നിങ്ങൾ എവിടെനിന്നാണ്? ഞങ്ങൾ ഹാറാനിൽ നിന്നാണ് എന്ന് അവർ മറുപടി പറഞ്ഞു.","p":1},{"v":5,"t":"അവൻ വീണ്ടും ചോദിച്ചു: നിങ്ങൾ നാഹോറിന്റെ മകൻ ലാബാനെ അറിയുമോ? അറിയാം എന്ന് അവർ പറഞ്ഞു.","p":1},{"v":6,"t":"അവനു ക്ഷേമമാണോ, അവൻ ചോദിച്ചു. ക്ഷേമമതന്നെ, അവർ പറഞ്ഞു: ഇതാ, അവന്റെ മകൾ റാഹേൽ ആടുകളുമായി വരുന്നു.","p":1},{"v":7,"t":"അവൻ പറഞ്ഞു: പകൽ ഇനിയും ഏറെയുണ്ടല്ലോ. ആടുകളെ ഒരുമിച്ചുകൂട്ടാനുള്ള നേരമായിട്ടില്ല. ആടുകൾക്കു വെള്ളംകൊടുത്തിട്ട് നിങ്ങൾ പോയി അവയെ മേയ്ക്കുക.","p":1},{"v":8,"t":"അവർ പറഞ്ഞു: ഞങ്ങൾക്ക് സാധിക്കുകയില്ല. ആട്ടിൻപറ്റങ്ങളെയെല്ലാം ഒരുമിച്ചുകൂട്ടുകയും കിണറിന്റെ വായ്ക്കല്ല് ഉരുട്ടി മാറ്റുകയും ചെയ്തിട്ടേ ഞങ്ങൾ ആടുകൾക്ക് വെള്ളം കൊടുക്കാറുള്ളൂ.","p":1},{"v":9,"t":"അവൻ അവരുമായി സംസാരിച്ചുകൊണ്ടിരിക്കേ, റാഹേൽ തന്റെ പിതാവിന്റെ ആടുകളുമായി വന്നു; എന്തെന്നാൽ, അവൾ ഇടയസ്ത്രീയായിരുന്നു.","p":1},{"v":10,"t":"തന്റെ മാതുലൻ ലാബാന്റെ മകൾ റാഹേലിനെയും അവന്റെ ആടുകളെയും കണ്ടപ്പോൾ യാക്കോബ് അടുത്തുചെന്ന് കിണറിന്റെ വായ്ക്കല്ല് ഉരുട്ടിമാറ്റുകയും ആടുകൾക്കു വെള്ളം കൊടുക്കുകയും ചെയ്തു.","p":1},{"v":11,"t":"പിന്നീട് യാക്കോബ് റാഹേലിനെ ചുംബിക്കുകയും ഉച്ചസ്വരംത്തിൽ കരയുകയും ചെയ്തു.","p":1},{"v":12,"t":"താൻ അവളുടെ പിതാവിന്റെ ബന്ധുവും റബെക്കായുടെ മകനുമാണെന്ന് യാക്കോബ് റാഹേലിനെ അറിയിച്ചു. അവൾ ഓടിച്ചെന്ന് പിതാവിനെ വിവരമറിയിച്ചു.","p":1},{"v":13,"t":"തന്റെ സഹോദരീപുത്രനായ യാക്കോബിന്റെ വാർത്ത കേട്ടപ്പോൾ ലാബാൻ അവനെ എതിരേൽക്കാൻ ഓടിയെത്തി. അവൻ അവനെ കെട്ടിപ്പിടിച്ചു ചുംബിച്ച് വീട്ടിലേക്കു കൂട്ടിക്കൊണ്ടുപോയി. അവൻ സംഭവിച്ചതെല്ലാം ലാബാനോടു വിവരിച്ചു.","p":1},{"v":14,"t":"ലാബാൻ അവനോടു പറഞ്ഞു: എന്റെ അസ്ഥിയും മാംസവും തന്നെയയാണല്ലോ നീ! ഒരു മാസക്കാലം അവൻ അവന്റെകൂടെ പാർത്തു.","p":1},{"v":15,"t":"ലാബാൻ യാക്കോബിനോടു പറഞ്ഞു: നീ എന്റെ ചാർച്ചക്കാരനായതുകൊണ്ട്, പ്രതിഫലമില്ലാതെ എനിക്കുവേണ്ടി പണിയെടുക്കേണ്ടതുണ്ടോ? നിന്റെ വേതനം എന്താണെന്നു എന്നോടു പറയുക.","p":1},{"v":16,"t":"ലാബാന് രണ്ടു പുത്രിമാരുണ്ടായിരുന്നു. മൂത്തവളുടെ പേര് ലെയാ, ഇളയവളുടെ പേര് റാഹേൽ.","p":1},{"v":17,"t":"ലെയായുടെ നയനങ്ങൾ മങ്ങിയവയായിരുന്നു; റാഹേലാകട്ടെ, രൂപഭംഗിയുള്ളവളും കാഴ്ചയ്ക്കു സുന്ദരിയും.","p":1},{"v":18,"t":"യാക്കോബ് റാഹേലിൽ അനുരക്തനായി. അവൻ ലാബാനോടു പറഞ്ഞു: അങ്ങയുടെ ഇളയമകളായ റാഹേലിനുവേണ്ടി ഏഴുകൊല്ലം ഞാൻ അങ്ങയെ സേവിക്കാം.","p":1},{"v":19,"t":"ലാബാൻ പറഞ്ഞു: അവളെ മറ്റാർക്കെങ്കിലും കൊടുക്കുന്നതിനെക്കാൾ നല്ലത് ഞാൻ അവളെ നിനക്കു തരുന്നതാണ്. എന്റെകൂടെ പാർത്തുകൊള്ളുക.","p":1},{"v":20,"t":"അങ്ങനെ റാഹേലിനുവേണ്ടി യാക്കോബ് ഏഴു കൊല്ലം പണിയടുത്തു. അവളോടുള്ള ഇഷ്ടംമൂലം അവന്റെ ദൃഷ്ടികളിൽ അവ ഏതാനും നാളുകൾപോലെയേ തോന്നിയുള്ളൂ.","p":1},{"v":21,"t":"അപ്പോൾ യാക്കോബ് ലാബാനോടു പറഞ്ഞു: എന്റെ ദിനങ്ങൾ പൂർത്തിയായതുകൊണ്ട് എന്റെ ഭാര്യയെ തരുക; ഞാൻ അവളെ പ്രാപിക്കട്ടെ.","p":1},{"v":22,"t":"ലാബാൻ ആ പ്രദേശത്തുള്ളവരെയെല്ലാം ഒരുമിച്ചുകൂട്ടി ഒരു വിരുന്നു നടത്തി.","p":1},{"v":23,"t":"വൈകുന്നേരമായപ്പോൾ അവൻ തന്റെ മകൾ ലെയായെ യാക്കോബിന്റെ അടുത്തേക്കു കൊണ്ടുവന്നു. അവൻ അവളെ പ്രാപിച്ചു.","p":1},{"v":24,"t":"തന്റെ മകൾ ലെയായ്ക്കു പരിചാരികയായി ലാബാൻ തന്റെ പരിചാരിക സിൽഫായെ കൊടുത്തു.","p":1},{"v":25,"t":"നേരം പുലർന്നപ്പോൾ അത് ലെയാ ആണെന്നുകണ്ട് അവൻ ലാബാനോടു ചോദിച്ചു: അങ്ങ് എന്നോട് എന്താണീ ചെയ്തത്? റാഹേലിനു വേണ്ടിയല്ലേ ഞാൻ അങ്ങയോടൊപ്പം പണിയെടുത്തത്? പിന്നെ അങ്ങ് എന്നെ ചതിച്ചതെന്തിന്?","p":1},{"v":26,"t":"ലാബാൻ പറഞ്ഞു: മൂത്തവൾക്കുമുമ്പേ ഇളയവളെ നൽകുക എന്നത് ഞങ്ങളുടെ നാട്ടിൽ ചെയ്യാറില്ല.","p":1},{"v":27,"t":"ഇവളുടെ ആഴ്ച പൂർത്തിയാക്കുക. ഇനിയും വേറെ ഏഴുവർഷംകൂടി നീ എന്നോടൊപ്പം വേലചെയ്താൽ അവളെയും വേതനമായി ഞങ്ങൾ നിനക്കു തരാം.","p":1},{"v":28,"t":"യാക്കോബ് അപ്രകാരം ചെയ്തു. അവളുടെ ആഴ്ച പൂർത്തിയായപ്പോൾ ലാബാൻ തന്റെ പുത്രി റാഹേലിനെയും അവനു ഭാര്യയായി നൽകി.","p":1},{"v":29,"t":"ലാബാൻ പുത്രി റാഹേലിനു പരിചാരികയായി തന്റെ പരിചാരിക ബിൽഹായെ നൽകി.","p":1},{"v":30,"t":"അവൻ റാഹേലിനെ പ്രാപിക്കുകയും ലെയായെക്കാൾ കൂടുതലായി റാഹേലിനെ ഇഷ്ടപ്പെടുകയും ചെയ്തു. തുടർന്ന് ഏഴുവർഷം കൂടി അവൻ അയാളോടൊപ്പം വേലചെയ്തു.","p":1},{"h":"യാക്കോബിന്റെ മക്കൾ"},{"v":31,"t":"ലെയാ വെറുക്കപ്പെടുന്നതായിക്കണ്ട് കർത്താവ് അവളുടെ ഗർഭപാത്രം തുറന്നു. റാഹേലാകട്ടെ, വന്ധ്യയായിരുന്നു.","p":1},{"v":32,"t":"ലെയാ ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ അവനു റൂബൻ എന്നു പേരിട്ടു. എന്തെന്നാൽ, കർത്താവ് എന്റെ കഷ്ടപ്പാടു കണ്ടിരിക്കുന്നു; ഇനി തീർച്ചയായും എന്റെ ഭർത്താവ് എന്നെ സ്നേഹിക്കും എന്ന് അവൾ പറഞ്ഞു.","p":1},{"v":33,"t":"അവൾ വീണ്ടും ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ പറഞ്ഞു: ഞാൻ വെറുക്കപ്പെടുന്നു എന്ന് കർത്താവ് കേട്ടതിനാൽ, അവിടുന്ന് എനിക്ക് ഇവനെയും നൽകിയിരിക്കുന്നു. അതുകൊണ്ട് അവൾ അവന് ശിമയോൻ എന്നു പേരിട്ടു.","p":1},{"v":34,"t":"അവൾ പിന്നെയും ഗർഭംധരിച്ചു, ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ പറഞ്ഞു: ഞാനവനു മൂന്നുപുത്രന്മാരെ പ്രസവിച്ചിരിക്കുന്നതിനാൽ ഇത്തവണ എന്റെ ഭർത്താവ് എന്നോട് അടുക്കുകതന്നെചെയ്യും. അതുകൊണ്ട് അവനെ ലേവി എന്നു പേരു വിളിച്ചു.","p":1},{"v":35,"t":"അവൾ വീണ്ടും ഗർഭംധരിക്കുകയും ഒരു പുത്രനെ പ്രസവിക്കുകയും ചെയ്തു. അവൾ പറഞ്ഞു: ഇപ്രാവശ്യം ഞാൻ കർത്താവിനെ സ്തുതിക്കും; അതുകൊണ്ട്, അവൾ അവനെ യൂദാ എന്ന് പേരു വിളിച്ചു. പിന്നീട് അവൾക്ക് പ്രസവിക്കാനായില്ല.","p":1}],"30":[{"v":1,"t":"താൻ യാക്കോബിന് മക്കളെ പ്രസവിക്കുന്നില്ലെന്ന് കണ്ടു റാഹേൽ തൻ്റെ സഹോദരിയോട് അസൂയാലുവായി അവൾ യാക്കോബിനോട് പറഞ്ഞു എനിക്ക് മക്കളെ തരുക അല്ലെങ്കിൽ ഞാൻ മരിക്കും.","p":1},{"v":2,"t":"യാക്കോബ് റാഹേലിനോട് കോപിച്ചു പറഞ്ഞു നിന്നിൽ നിന്ന് ഉദരഫലം തടഞ്ഞ ദൈവത്തിൻ്റെ സ്ഥാനത്താണോ ഞാൻ?","p":1},{"v":3,"t":"അവൾ പറഞ്ഞു ഇതാ എൻ്റെ ദാസി ബിൽഹാ അവളെ പ്രാപിക്കുക അവൾ എന്റെ മടിയിൽ പ്രസവിക്കട്ടെ. അങ്ങനെ അവളിലൂടെ ഞാനും പുത്രലബ്ധയാകും.","p":1},{"v":4,"t":"അവൾ തൻ്റെ പരിചാരിക ബിൽഹായെ അവന് ഭാര്യയായി നൽകി അവൻ അവളെ പ്രാപിച്ചു.","p":1},{"v":5,"t":"ബിൽഹാ ഗർഭം ധരിച്ച് യാക്കോബിന് ഒരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":6,"t":"അപ്പോൾ റാഹേൽ പറഞ്ഞു ദൈവം എന്നെ വിധിക്കുകയും എൻ്റെ സ്വരം കേട്ട് എനിക്കൊരു പുത്രനെ നൽകുകയും ചെയ്തിരിക്കുന്നു. അക്കാരണത്താൽ, അവൾ അവന് ദാൻ എന്നു പേരിട്ടു.","p":1},{"v":7,"t":"റാഹേലിന്റെ പരിചാരിക ബിൽഹാ വീണ്ടും ഗർഭംധരിച്ചു. യാക്കോബിന് അവൾ രണ്ടാമതൊരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":8,"t":"റാഹേൽ പറഞ്ഞു: എന്റെ സഹോദരിയുമായി കടുത്ത മത്സരം തന്നെ നടത്തി ഞാൻ ജയിച്ചിരിക്കുന്നു. അവൾ അവനെ നഫ്താലി എന്നുവിളിച്ചു.","p":1},{"v":9,"t":"തനിക്കു പ്രസവിക്കാനാകുന്നില്ലെന്നു കണ്ട് ലെയാ തന്റെ പരിചാരിക സിൽഫായെ കൊണ്ടുവന്ന് യാക്കോബിനു ഭാര്യയായി നൽകി.","p":1},{"v":10,"t":"ലെയായുടെ പരിചാരിക സിൽഫാ യാക്കോബിന് ഒരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":11,"t":"ഭാഗ്യമായി എന്നു പറഞ്ഞുകൊണ്ട് അവൾ അവന് ഗാദ് എന്നു പേരിട്ടു.","p":1},{"v":12,"t":"ലെയായുടെ പരിചാരിക സിൽഫാ യാക്കോബിന് രണ്ടാമതൊരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":13,"t":"ലെയാ പറഞ്ഞു: എന്റെ സന്തോഷം കാരണം പെൺകൊടികൾ എന്നെ സന്തോഷവതിയെന്നു വിളിക്കും. അവൾ അവന് ആശേർ എന്നു പേരിട്ടു.","p":1},{"v":14,"t":"ഗോതമ്പുകൊയ്ത്തുകാലത്ത് റൂബൻ വയലിൽ ചെന്നപ്പോൾ, ദുദായിപ്പഴം കാണുകയും അവ തന്റെ അമ്മ ലെയായ്ക്കു കൊണ്ടുവരുകയും ചെയ്തു. അപ്പോൾ റാഹേൽ ലെയായോട് പറഞ്ഞു: നിന്റെ പുത്രന്റെ ദുദായിപ്പഴത്തിൽനിന്ന് സദയം എനിക്കും തരുക.","p":1},{"v":15,"t":"അവൾ പറഞ്ഞു: എന്റെ ഭർത്താവിനെ നീ കൈയടക്കിവച്ചിരിക്കുന്നത് നിസ്സാരകാര്യമോ? എന്റെ മകന്റെ ദുദായിപ്പഴവും കൈവശപ്പെടുത്തണമോ? റാഹേൽ പറഞ്ഞു: അതുകൊണ്ട് നിന്റെ മകന്റെ ദുദായിപ്പഴത്തിനുപകരം അദ്ദേഹം ഈ രാത്രി നിന്റെ കൂടെ ശയിച്ചുകൊള്ളട്ടെ.","p":1},{"v":16,"t":"യാക്കോബ് വൈകുന്നേരം വയലിൽനിന്നു വന്നു. ലെയാ അവനെ കാണാൻ പുറത്തേക്കുചെന്ന് അവനോടു പറഞ്ഞു: എന്റെയടുത്ത് അങ്ങു വരണം; കാരണം, എന്റെ മകന്റെ ദുദായിപ്പഴം ഞാൻതന്നെ പ്രതിഫലമായി കൊടുത്ത് അങ്ങയെ വാങ്ങിയിരിക്കുകയാണ്. ആ രാത്രി അവൻ അവളോടുകൂടെ ശയിച്ചു.","p":1},{"v":17,"t":"ദൈവം ലെയായെ ശ്രവിച്ചു; അവൾ ഗർഭംധരിച്ച് യാക്കോബിന് അഞ്ചാമതൊരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":18,"t":"എന്റെ പരിചാരികയെ ഭർത്താവിനു കൊടുത്തതിന് ദൈവം എനിക്കു പ്രതിഫലം തന്നു എന്നു പറഞ്ഞ് അവൾ അവന് ഇസ്സാക്കർ എന്നു പേരിട്ടു.","p":1},{"v":19,"t":"ലെയാ വീണ്ടും ഗർഭം ധരിച്ചു; യാക്കോബിന് അവൾ ആറാമതൊരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":20,"t":"(തുടർച്ച): ലെയാ പറഞ്ഞു: ദൈവം എനിക്ക് നല്ല ഉപഹാരം സമ്മാനിച്ചിരിക്കുന്നു. ഇത്തവണ ഭർത്താവ് എന്നെ മാനിക്കും; കാരണം, അവനു ഞാൻ ആറു മക്കളെ പ്രസവിച്ചിരിക്കുന്നു. അവൾ അവന് സെബുലൂൺ എന്നു പേരിട്ടു.","p":1},{"v":21,"t":"അതിനുശേഷം അവൾ ഒരു പുത്രിയെ പ്രസവിച്ചു. അവൾ അവൾക്ക് ദീനാ എന്നു പേരിട്ടു.","p":1},{"v":22,"t":"ദൈവം റാഹേലിനെ സ്മരിച്ചു. അവിടുന്ന് അവളെ കേൾക്കുകയും അവളുടെ ഗർഭപാത്രം തുറക്കുകയും ചെയ്തു.","p":1},{"v":23,"t":"അവൾ ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ പറഞ്ഞു: എന്റെ അപമാനം ദൈവം നീക്കിക്കളഞ്ഞിരിക്കുന്നു.","p":1},{"v":24,"t":"കർത്താവ് എനിക്ക് ഒരു പുത്രനെക്കൂടി തരട്ടെ എന്നു പറഞ്ഞ് അവൾ അവന് ജോസഫ് എന്നു പേരിട്ടു.","p":1},{"h":"യാക്കോബിന്റെ സമ്പത്ത്"},{"v":25,"t":"റാഹേൽ ജോസഫിനെ പ്രസവിച്ചുകഴിഞ്ഞ്, യാക്കോബ് ലാബാനോടു പറഞ്ഞു: എന്നെ വിട്ടയച്ചാലും; ഞാൻ എന്റെ സ്ഥലത്തേക്കും ദേശത്തേക്കും പോകട്ടെ.","p":1},{"v":26,"t":"എന്റെ ഭാര്യമാരെയും കുട്ടികളെയും തന്നാലും; അവരെപ്രതിയാണല്ലോ ഞാൻ അങ്ങയെ സേവിച്ചത്. ഞാൻ പോകട്ടെ; അങ്ങയ്ക്കുവേണ്ടി ഞാൻ ചെയ്ത സേവനം അങ്ങയ്ക്ക് നന്നായി അറിയാമല്ലോ.","p":1},{"v":27,"t":"ലാബാൻ അവനോടു പറഞ്ഞു: നിന്റെ ദൃഷ്ടികളിൽ പ്രീതി കണ്ടെത്താൻ എനിക്കു കഴിഞ്ഞിരുന്നെങ്കിൽ! നീ മൂലമാണ് കർത്താവ് എന്നെ അനുഗ്രഹിച്ചത് എന്ന് ഞാൻ ഗണിച്ചറിഞ്ഞിരിക്കുന്നു.","p":1},{"v":28,"t":"അയാൾ തുടർന്നു പറഞ്ഞു: നിന്റെ വേതനം എന്നിൽനിന്ന് ഈടാക്കൂ; അതു ഞാൻ തരാം.","p":1},{"v":29,"t":"അവൻ അയാളോടു പറഞ്ഞു: ഞാൻ അങ്ങയെ എപ്രകാരം സേവിച്ചെന്നും അങ്ങയുടെ കന്നുകാലികൾ എന്റെകീഴിൽ എപ്രകാരമായിരുന്നുവെന്നും അങ്ങയ്ക്ക് നന്നായി അറിയാമല്ലോ.","p":1},{"v":30,"t":"എനിക്കുമുമ്പ് അങ്ങേക്ക് കുറച്ചുമാത്രം ഉണ്ടായിരുന്നത് ഇപ്പോൾ തീർച്ചയായും ഏറെ പെരുകിയിരിക്കുന്നു. എന്റെ ഓരോ ചുവടിനും കർത്താവ് അങ്ങയെ അനുഗ്രഹിച്ചിരിക്കുന്നു. ഇനി ഞാൻ എപ്പോഴാണ് എന്റെ ഭവനത്തിനായി എന്തെങ്കിലും ചെയ്യുക?","p":1},{"v":31,"t":"അയാൾ ചോദിച്ചു: ഞാൻ നിനക്ക് എന്തു തരണം? യാക്കോബ് പറഞ്ഞു: അങ്ങ് എനിക്ക് ഒന്നും തരേണ്ട. ഞാൻ പറയാൻപോകുന്ന ഈ കാര്യം അങ്ങ് ചെയ്താൽ, അങ്ങയുടെ ആടുകളെ ഞാൻ തുടർന്നും മേയിച്ച് കാത്തുകൊള്ളാം.","p":1},{"v":32,"t":"ഞാൻ എന്നുതന്നെ അങ്ങയുടെ ഓരോ ആട്ടിൻകൂട്ടത്തിലൂടെയും കടന്ന് ചെമ്മരിയാടുകളിൽ പുള്ളിയും പാണ്ടും ഉള്ള എല്ലാ ആടുകളെയും കറുത്ത ആടുകളെയും കോലാടുകളിൽ പാണ്ടും പുള്ളിയും ഉള്ളവയെയും വേർതിരിക്കാം. അവയായിരിക്കും എന്റെ വേതനം.","p":1},{"v":33,"t":"വരും നാളിൽ എന്റെ വേതനം അങ്ങയുടെ പരിഗണനയ്ക്കുവരുമ്പോൾ എന്റെ നീതി എനിക്ക് സാക്ഷ്യമായിരിക്കും. കോലാടുകളിൽ പുള്ളിയോ പാണ്ഡോ, ചെമ്മരിയാടുകളിൽ കറുപ്പോ ഇല്ലാത്തതായി എന്റെ പക്കലുള്ളതെല്ലാം കളവു മുതലായിരിക്കും.","p":1},{"v":34,"t":"ലാബാൻ പറഞ്ഞു: അതു, കൊള്ളാമല്ലോ, നീ പറഞ്ഞതുപോലെതന്നെയാകട്ടെ.","p":1},{"v":35,"t":"അന്നുതന്നെ അവൻ വരയും പാണ്ടുമുള്ള മുട്ടാടുകളെയും പുള്ളികളുള്ള എല്ലാ കോലാടുകളെയും അതിൽ പാണ്ടുകളുള്ള എല്ലാ വെള്ളുത്തതിനെയും ചെമ്മരിയാടുകളിൽ എല്ലാ കറുത്ത അതിനെയും വേർതിരിച്ച് അവയെ തന്റെ പുത്രന്മാരെ ഏൽപ്പിച്ചു.","p":1},{"v":36,"t":"തനിക്കും യാക്കോബിനും മധ്യേ അവൻ മൂന്നു ദിവസത്തെ വഴിയകലം നിർണയിച്ചു. യാക്കോബാകട്ടെ, ലാബാന്റെ അവശേഷിച്ച ആടുകളെ മേയിച്ചുകൊണ്ടിരുന്നു.","p":1},{"v":37,"t":"യാക്കോബ് ഇലവിന്റെയും ബദാമിന്റെയും അഴിഞ്ഞിലിന്റെയും പച്ചക്കമ്പുകൾ വെട്ടിയെടുത്ത് കമ്പുകളിലെ വെള്ളപ്പു കാണത്തക്കവിധം തൊലിയുരിഞ്ഞുനീക്കി,","p":1},{"v":38,"t":"താൻ തൊലിയുരിഞ്ഞുമാറ്റിയ കമ്പുകൾ ആടുകൾ വെള്ളം കുടിക്കുന്ന പാത്തികളിൽ ആടുകളുടെ മുമ്പിൽ അവൻ കുത്തിനിർത്തി. വെള്ളംകുടിക്കാൻ വരുമ്പോഴാണ് അവ ഇണചേർന്നിരുന്നത്.","p":1},{"v":39,"t":"ആടുകൾ ഈ കമ്പുകളുടെ മുമ്പിൽ ഇണചേർന്നു. അവ വരയും പുള്ളിയും പാണ്ടുമുള്ള കുഞ്ഞുങ്ങളെ പ്രസവിച്ചു.","p":1},{"v":40,"t":"ചെമ്മരിയാടുകളെയാകട്ടെ, യാക്കോബ് വേർതിരിച്ച് ലാബാന്റെ കൂട്ടത്തിലെ വരയുള്ളതും കറുത്തതുമായ എല്ലാ ആടുകളുടെയും നേരേ നിർത്തി. അവൻ അങ്ങനെ തനിക്കുവേണ്ടി പ്രത്യേകം ആടുകളെ സ്വന്തമാക്കി; അവയെ ലാബാന്റെ ആടുകളോടു ചേർക്കാതെ മാറ്റിനിർത്തി.","p":1},{"v":41,"t":"കൊഴുത്ത ആടുകൾ ഇണചേരുമ്പോഴെല്ലാം, അവ കമ്പുകളുടെ അരികിൽവെച്ച് ഇണചേരേണ്ടതിന്, യാക്കോബ് കമ്പുകൾ ആടുകൾ കാൺകേ പാത്തികളിൽ വച്ചിരുന്നു.","p":1},{"v":42,"t":"എന്നാൽ, മെലിഞ്ഞ ആടുകളുടെ കാര്യത്തിൽ അവൻ അതു ചെയ്തില്ല. അങ്ങനെ മെലിഞ്ഞവ ലാബാന്റേതും കൊഴുത്തവ യാക്കോബിന്റേതുമായി.","p":1},{"v":43,"t":"അവൻ അത്യധികം അഭിവൃദ്ധിപ്പെട്ടു. അവനു ധാരാളം ആടുകളും പരിചാരികമാരും ദാസന്മാരും ഒട്ടകങ്ങളും കഴുതകളും ഉണ്ടായി.","p":1}],"31":[{"h":"യാക്കോബ് ഒളിച്ചോടുന്നു"},{"v":1,"t":"ലാബാന്റെ മക്കൾ ഇങ്ങനെ പറയുന്നത് അവൻ കേട്ടു: നമ്മുടെ പിതാവിനുള്ളതെല്ലാം യാക്കോബ് കൈവശപ്പെടുത്തി. നമ്മുടെ പിതാവിന്റേതിൽനിന്നാണ് അവൻ ഈ മഹത്ത്വമെല്ലാം ഉണ്ടാക്കിയത്.","p":1},{"v":2,"t":"യാക്കോബ് ലാബാന്റെ മുഖം ശ്രദ്ധിച്ചു. ഇതാ അത് മുമ്പത്തെപ്പോലെയായിരുന്നില്ല","p":1},{"v":3,"t":"കർത്താവു യാക്കോബിനോട് അരുളച്ചെയ്തു: നിന്റെ പിതാക്കന്മാരുടെ നാട്ടിലേക്കും സഹജരുടെ അടുത്തേക്കും തിരിച്ചുപോവുക. ഞാൻ നിന്നോടുകൂടെ ഉണ്ടായിരിക്കും.","p":1},{"v":4,"t":"വയലിൽ, തന്റെ ആടുകളുടെ അടുത്തേക്ക് റാഹേലിനെയും ലെയായെയും യാക്കോബ് അയച്ചു വിളിച്ചു.","p":1},{"v":5,"t":"അവൻ അവരോടു പറഞ്ഞു: എന്നോടുള്ള നിങ്ങളുടെ പിതാവിന്റെ മുഖം മുമ്പത്തെപ്പോലെയല്ല എന്നു ഞാൻ കാണുന്നു. എന്നാൽ, എന്റെ പിതാവിന്റെ ദൈവം എന്റെകൂടെ ഉണ്ട്.","p":1},{"v":6,"t":"എന്റെ സർവ്വശക്തിയോടുകൂടെയാണ് നിങ്ങളുടെ പിതാവിനെ ഞാൻ സേവിച്ചതെന്ന് നിങ്ങൾ നന്നായി അറിയുന്നുണ്ടല്ലോ.","p":1},{"v":7,"t":"എന്നാൽ, നിങ്ങളുടെ പിതാവ് എന്നെ ചതിക്കുകയും പത്തു തവണ എന്റെ വേതനത്തിൽ മാറ്റം വരുത്തുകയും ചെയ്തു. പക്ഷേ, എനിക്ക് തിന്മ വരുത്താൻ ദൈവം അവനെ അനുവദിച്ചില്ല.","p":1},{"v":8,"t":"പുള്ളിയുള്ളവയായിരിക്കും നിന്റെ വേതനം എന്ന് അവൻ പറഞ്ഞാൽ എല്ലാ ആടും പുള്ളിയുള്ളതിനെ പ്രസവിക്കും; അതല്ല, വരയുള്ളവയായിരിക്കും നിന്റെ വേതനം എന്ന് അവൻ പറഞ്ഞാൽ, ആടുകളൊക്കെ വരയുള്ളതിനെ പ്രസവിക്കും!","p":1},{"v":9,"t":"അങ്ങനെ ദൈവം നിങ്ങളുടെ പിതാവിന്റെ കാലിസമ്പത്ത് അവനിൽനിന്നു പിടിച്ചെടുത്ത് എനിക്കു തന്നിരിക്കുകയാണ്.","p":1},{"v":10,"t":"ആടുകളുമായി ഇണചേരുന്ന മുട്ടാടുകളെല്ലാം വരയും പുള്ളിയും പൊട്ടുമുള്ളവയായിരുന്നുവെന്ന് ആടുകൾ ഇണചേരുങ്കാലത്ത് ഞാൻ സ്വപ്നത്തിൽ കണ്ണുയർത്തി കണ്ടു.","p":1},{"v":11,"t":"സ്വപ്നത്തിൽ ദൈവദൂതൻ എന്നെ യാക്കോബേ എന്നു വിളിച്ചു. ഇതാ ഞാൻ എന്നു ഞാൻ വിളികേട്ടു.","p":1},{"v":12,"t":"ദൂതൻ പറഞ്ഞു: നീ കണ്ണുകളുയർത്തി നോക്കുക. ആടുകളുമായി ഇണചേരുന്ന മുട്ടാടുകളെല്ലാം വരയും പുള്ളിയും പൊട്ടുമുള്ളവയാണ്. കാരണം, ലാബാൻ നിന്നോടു ചെയ്യുന്നതെല്ലാം ഞാൻ കണ്ടിരിക്കുന്നു.","p":1},{"v":13,"t":"ബേഥെലിലെ ദൈവമാണ് ഞാൻ. അവിടെ വച്ചാണ് തൂണ് അഭിഷേകംചെയ്ത് നീ എന്നോടു വ്രതംചെയ്തത്. എഴുന്നേറ്റ് ഇപ്പോൾ ഈ ദേശത്തുനിന്നു പുറപ്പെടുക. നിന്റെ ജന്മദേശത്തേക്ക് തിരിച്ചുപോവുക.","p":1},{"v":14,"t":"റാഹേലും ലെയായും അവനോടു മറുപടിയായി പറഞ്ഞു: നമ്മുടെ പിതാവിന്റെ വീട്ടിൽ എന്തെങ്കിലും ഓഹരിയോ അവകാശമോ നമുക്ക് ഇനി ഉണ്ടോ?","p":1},{"v":15,"t":"നമ്മളെ അന്യരായല്ലേ അവൻ കരുതുന്നത്? നമ്മെ വിറ്റിട്ട് അവൻ നമ്മുടെ പണം വിഴുങ്ങിക്കൊണ്ടിരിക്കുകയുമല്ലേ?","p":1},{"v":16,"t":"തീർച്ചയായും, നമ്മുടെ പിതാവിൽനിന്നു ദൈവം പിടിച്ചെടുത്ത സമ്പത്തെല്ലാം നമുക്കും നമ്മുടെ മക്കൾക്കും അവകാശപ്പെട്ടതാണ്. അതിനാൽ, ഇപ്പോൾ ദൈവം അങ്ങയോടു പറയുന്നതെല്ലാം ചെയ്യുക.","p":1},{"v":17,"t":"യാക്കോബ് എഴുന്നേറ്റ് തന്റെ പുത്രന്മാരെയും ഭാര്യമാരെയും ഒട്ടകപ്പുറത്തു കയറ്റി.","p":1},{"v":18,"t":"പദാൻആരാമിൽവച്ച് നേടിയെടുത്ത തന്റെ മുതൽകൂട്ടായ കാലിഗണത്തെ - താൻ സമ്പാദിച്ചിരുന്ന എല്ലാ കാലിക്കൂട്ടത്തെയും സകലമൃഗസമ്പത്തിനെയും - തന്റെ പിതാവായ ഇസഹാക്കിന്റെ അടുത്തേക്കു പോകാനായി അവൻ കാനാൻദേശത്തേക്ക് തെളിച്ചു.","p":1},{"v":19,"t":"അപ്പോൾ ലാബാൻ തന്റെ ആടുകളുടെ രോമംകത്രിക്കാൻ പോയിരിക്കുകയായിരുന്നു. ഇതിനിടെ റാഹേൽ തന്റെ പിതാവിന്റെ കുലവിഗ്രഹങ്ങളെല്ലാം കൈക്കലാക്കി.","p":1},{"v":20,"t":"താൻ ഒളിച്ചോടുകയാണെന്ന് അറിയിക്കാതെ യാക്കോബ് അരമായനായ ലാബാനെ കബളിപ്പിക്കുകയായിരുന്നു.","p":1},{"v":21,"t":"അവൻ തനിക്കുള്ള സകലതോടുംകൂടെ ഒളിച്ചോടുകയായിരുന്നു. അവൻ എഴുന്നേറ്റ്, ഗിലയാദ്മല ലക്ഷ്യമാക്കി നദി കടന്നു.","p":1},{"h":"ലാബാൻ പിന്തുടരുന്നു"},{"v":22,"t":"യാക്കോബ് ഒളിച്ചോടിയെന്ന് മൂന്നാംദിവസം ലാബാന് അറിവുകിട്ടി.","p":1},{"v":23,"t":"അയാൾ തന്റെ ചാർച്ചക്കാരെ തന്നോടൊപ്പം കൂട്ടി, ഏഴു ദിവസത്തെ വഴി അനുധാവനംചെയ്ത്, ഗിലയാദ്മലയിൽ അവന്റെ പിന്നാലെ ഒപ്പമെത്തി.","p":1},{"v":24,"t":"എന്നാൽ, ആ രാത്രിയിൽ സ്വപ്നത്തിൽ ദൈവം അരമായനായ ലാബാന്റെ അടുത്തുവന്ന് അവനോടു പറഞ്ഞു: നല്ലതോ ചീത്തയോ ആയ ഒന്നും യാക്കോബിനോട് ഉരിയാടാതിരിക്കാൻ നിനക്ക് കരുതലുണ്ടാകണം.","p":1},{"v":25,"t":"ലാബാൻ യാക്കോബിനെ മറികടന്നു. യാക്കോബ് മലയിൽ കൂടാരമടിച്ചിരിക്കെ, ലാബാനും തന്റെ ചാർച്ചക്കാരോടൊത്ത് ഗിലയാദ്മലയിൽ കൂടാരമടിച്ചു.","p":1},{"v":26,"t":"ലാബാൻ യാക്കോബിനോടു ചോദിച്ചു: നീ എന്താണു ചെയ്തത്? നീ എന്നെ കബളിപ്പിച്ചു. വാളാൽ നേടിയ തടവുകാരെപ്പോലെ നീ എന്റെ പെൺമക്കളെ പിടിച്ചുകൊണ്ടുപോകുന്നു!","p":1},{"v":27,"t":"എന്തുകൊണ്ടാണ് നീ പലായനം ചെയ്തത് രഹസ്യമാക്കിവച്ചതും എന്നെ കൊള്ളയടിച്ചതും എന്നോടു വെളിപ്പെടുത്താതിരുന്നതും? ഞാൻ ആഹ്ലാദത്തോടെ, പാട്ടുകളോടും തപ്പു-കിന്നരങ്ങളോടുംകൂടെ നിന്നെ യാത്രയാക്കുമായിരുന്നുവല്ലോ.","p":1},{"v":28,"t":"എന്റെ പുത്രന്മാരെയും പുത്രിമാരെയും ചുംബിക്കുന്നതിന് നീ എന്നെ അനുവദിച്ചില്ല. നീ ഇപ്പോൾ പ്രവർത്തിച്ചത് ബുദ്ധിശൂന്യമായിപ്പോയി.","p":1},{"v":29,"t":"നിങ്ങൾക്ക് ഉപദ്രവം ചെയ്യാൻ എന്റെ കരം ശക്തമാണ്. എന്നാൽ, 'നല്ലതോ ചീത്തയോ ആയ ഒന്നും യാക്കോബിനോട് ഉരിയാടാതിരിക്കാൻ നിനക്ക് കരുതലുണ്ടാകണം’എന്ന് നിങ്ങളുടെ പിതാവിൻ്റെ ദൈവം കഴിഞ്ഞ രാത്രി എന്നോട് പറഞ്ഞു","p":1},{"v":30,"t":"നീ ഇപ്പോൾ നിർബന്ധമായും പോകുന്നത് നിന്റെ പിതൃഭവനത്തെ തീവ്രമായി അഭിലഷിക്കുന്നതുകൊണ്ടാണെങ്കിൽ, പിന്നെന്തിനാണ് എന്റെ ദേവന്മാരെ കട്ടെടുത്തത്?","p":1},{"v":31,"t":"അപ്പോൾ യാക്കോബ് ലാബാനോടു മറുപടിയായി പറഞ്ഞു: എനിക്കു ഭയമായിരുന്നു. എന്തെന്നാൽ, അങ്ങയുടെ പുത്രിമാരെ അങ്ങ് എന്നിൽനിന്ന് അകറ്റിയേക്കുമെന്നു ഞാൻ വിചാരിച്ചു.","p":1},{"v":32,"t":"അങ്ങയുടെ ദേവന്മാരെ ആരുടെകൂടെ അങ്ങ് കണ്ടെത്തുന്നുവോ അവൻ പിന്നെ ജീവിച്ചിരിക്കില്ല. നമ്മുടെ ചാർച്ചക്കാരുടെ മുമ്പിൽവച്ച് എന്റെ പക്കലുള്ളവ അങ്ങ് പരിശോധിച്ച് അങ്ങയുടേത് എടുത്തുകൊള്ളുക. എന്നാൽ റാഹേൽ അവ മോഷ്ടിച്ചിട്ടുണ്ടെന്ന് യാക്കോബ് അറിഞ്ഞില്ല.","p":1},{"v":33,"t":"ലാബാൻ യാക്കോബിന്റെ കൂടാരത്തിലും ലെയായുടെ കൂടാരത്തിലും രണ്ടു ദാസിമാരുടെയും കൂടാരത്തിലും ചെന്നു; എന്നാൽ അവ കണ്ടെത്തിയില്ല. ലെയായുടെ കൂടാരത്തിൽനിന്നു പുറത്തുകടന്ന് അവൻ റാഹേലിന്റെ കൂടാരത്തിലേക്കു ചെന്നു.","p":1},{"v":34,"t":"റാഹേൽ വിഗ്രഹങ്ങളെടുത്ത് ഒരു ഒട്ടകക്കാണത്തിലിട്ട് അതിന്മേൽ കയറിയിരുന്നു. ലാബാൻ കൂടാരത്തിലെല്ലാം അവ തിരഞ്ഞിട്ടും കണ്ടെത്തിയില്ല.","p":1},{"v":35,"t":"അപ്പോൾ റാഹേൽ തന്റെ പിതാവിനോടു പറഞ്ഞു: എന്റെ യജമാനന്റെ കണ്ണുകളിൽ കോപമരുതേ! അങ്ങയുടെമുമ്പിൽ എനിക്ക് എഴുന്നേൽക്കാനാവില്ല. എനിക്കിപ്പോൾ മാസമുറയാണ്. അവൻ തിരഞ്ഞെങ്കിലും വിഗ്രഹങ്ങൾ കണ്ടെത്തിയില്ല.","p":1},{"v":36,"t":"അപ്പോൾ യാക്കോബിന് അരിശമായി; അവൻ ലാബാനോടു കയർത്തു. യാക്കോബ് ലാബാനോടു മറുപടിയായി പറഞ്ഞു: എന്നെ ക്രോധത്തോടെ പിന്തുടരാൻ എന്റെ അതിക്രമമെന്താണ്? എന്റെ തെറ്റെന്താണ്?","p":1},{"v":37,"t":"എന്റെ സാധനങ്ങളെല്ലാം അങ്ങ് തഴുകിപ്പരിശോധിച്ചു; എന്നിട്ട്, അങ്ങയുടെ വീട്ടുവകസാധനങ്ങളിൽ എന്തെല്ലാമാണ് അങ്ങ് കണ്ടെത്തിയത്? എന്റെ ചാർച്ചക്കാരുടെയും അങ്ങയുടെ ചാർച്ചക്കാരുടെയും മുമ്പിൽ ഇവിടെ നിരത്തി വയ്ക്കുക. നമ്മൾ ഇരുവർക്കുമിടയിൽ അവർ വിധി പറയട്ടെ.","p":1},{"v":38,"t":"ഈ ഇരുപതു വർഷവും ഞാൻ അങ്ങയോടൊപ്പമായിരുന്നു. അങ്ങയുടെ ചെമ്മരിയാടുകൾക്കും അങ്ങയുടെ കോലാടുകൾക്കും ഗർഭഛിദ്രം സംഭവിച്ചിട്ടില്ല. അങ്ങയുടെ ആട്ടിൻപറ്റത്തിലെ മുട്ടാടുകളെ ഞാൻ ഭക്ഷിച്ചിട്ടുമില്ല.","p":1},{"v":39,"t":"കാട്ടുമൃഗങ്ങൾ കടിച്ചു കീറിയവയെ ഞാൻ അങ്ങയുടെയടുത്തു കൊണ്ടുവന്നിട്ടില്ല. ആ നഷ്ടം ഞാൻതന്നെ വഹിച്ചു. രാത്രിയിൽ കളവുപോയതിനും പകൽ കളവുപോയതിനും അങ്ങ് എന്റെ കയ്യിൽനിന്നുതന്നെ അത് ഈടാക്കിയിരുന്നു.","p":1},{"v":40,"t":"പകൽ ഉഷ്ണവും രാത്രി ശൈത്യവും എന്നെ കാർന്നുതിന്നു. ഉറക്കം എന്റെ കണ്ണുകളിൽനിന്ന് ഓടിയകന്നു. അതായിരുന്നു എന്റെ സ്ഥിതി.","p":1},{"v":41,"t":"എന്റെ ഈ ഇരുപതു വർഷവും ഞാൻ അങ്ങയുടെ വീട്ടിലായിരുന്നു. പതിനാലു വർഷം അങ്ങയുടെ രണ്ടു പെൺമക്കൾക്കുവേണ്ടിയും ആറു വർഷം ആടുകൾക്കുവേണ്ടിയും ഞാൻ വേലചെയ്തു. പത്തു തവണ അങ്ങ് എന്റെ കൂലിയിൽ മാറ്റംവരുത്തി.","p":1},{"v":42,"t":"എന്റെ പിതാവിന്റെ ദൈവം, അബ്രാഹത്തിന്റെ ദൈവവും ഇസഹാക്കിന്റെ ഭീതിയുമായവൻ, എന്റെ ഭാഗത്തില്ലായിരുന്നുവെങ്കിൽ ഇപ്പോൾ അങ്ങ് എന്നെ വെറുംകൈയോടെ പറഞ്ഞയയ്ക്കുമായിരുന്നു. എന്റെ കഷ്ടപ്പാടും എന്റെ ഉള്ളംകൈയുടെ അധ്വാനവും ദൈവം കണ്ടു. അതുകൊണ്ടാണ് കഴിഞ്ഞരാത്രി അവിടുന്ന് അങ്ങയെ ശകാരിച്ചത്.","p":1},{"h":"ലാബാനുമായി ഉടമ്പടി"},{"v":43,"t":"ലാബാൻ യാക്കോബിനോടു മറുപടിയായി പറഞ്ഞു: ഈ പെൺമക്കൾ എന്റെ പുത്രിമാരും ഈ കുട്ടികൾ എന്റെ കുട്ടികളും ഈ ആട്ടിൻപറ്റം എന്റെ ആട്ടിൻപറ്റവുമാണ്. നീ കാണുന്നതൊക്കെ എന്റേതാണ്. എന്റെ ഈ പെൺമക്കൾക്കുവേണ്ടിയാകട്ടെ, അവർ പ്രസവിച്ച കുട്ടികൾക്കുവേണ്ടിയാകട്ടെ, ഞാൻ എന്താണ് ഇന്ന് ചെയ്യേണ്ടത്?","p":1},{"v":44,"t":"ആകയാൽ ഇപ്പോൾ വരിക, നമുക്കൊരു ഉടമ്പടിയുണ്ടാക്കാം - ഞാനും നീയും തമ്മിൽ. അത് എനിക്കും നിനക്കും മധ്യേ ഒരു സാക്ഷ്യമായിരിക്കട്ടെ.","p":1},{"v":45,"t":"അപ്പോൾ യാക്കോബ് ഒരു കല്ലെടുത്ത്, അത് ഒരു തൂണായി ഉയർത്തി.","p":1},{"v":46,"t":"കല്ലുകൾ പെറുക്കിക്കൂട്ടുവിൻ യാക്കോബ് തന്റെ ചാർച്ചക്കാരോടു പറഞ്ഞു. അവർ കല്ലുകളെടുത്ത് ഒരു കുമ്പാരം കൂട്ടി. അവിടെ ആ കുമ്പാരത്തിന്മേൽ അവർ ഭക്ഷണം കഴിച്ചു.","p":1},{"v":47,"t":"ലാബാൻ അതിനെ യെഗാർസാഹദൂത്ത എന്നുവിളിച്ചു. യാക്കോബ് അതിനെ ഗലേദ് എന്നും.","p":1},{"v":48,"t":"ഈ കുമ്പാരം ഇന്ന് എനിക്കും നിനക്കും മധ്യേ സാക്ഷ്യമായിരിക്കും, ലാബാൻ പറഞ്ഞു. അതുകൊണ്ട്, ഗലേദ് എന്ന് അതിനു പേരിട്ടു.","p":1},{"v":49,"t":"അതാണ് മിസ്പാ. എന്തെന്നാൽ, ഒരുവൻ തന്റെ അയൽക്കാരനിൽനിന്ന് മറയുമ്പോൾ, കർത്താവ് എനിക്കും നിനക്കും മധ്യേ കാവലായിരിക്കട്ടെ എന്ന് അവൻ പറഞ്ഞിരുന്നു.","p":1},{"v":50,"t":"എന്റെ പുത്രിമാരെ നീ പീഡിപ്പിക്കുകയോ എന്റെ പുത്രിമാർക്കുപുറമേ നീ വേറെ ഭാര്യമാരെ സ്വീകരിക്കുകയോ ചെയ്താൽ, ആരും നമ്മോടൊപ്പമില്ലെങ്കിലും, ദൈവം എനിക്കും നിനക്കും മധ്യേ സാക്ഷിയായുണ്ടെന്ന് കണ്ടാലും.","p":1},{"v":51,"t":"ലാബാൻ യാക്കോബിനോടു പറഞ്ഞു: എനിക്കും നിനക്കും മധ്യേ ഞാൻ ഉയർത്തിയിരിക്കുന്ന കുമ്പാരം ഈ സ്തംഭവും ഇതാ!","p":1},{"v":52,"t":"ദ്രോഹലക്ഷ്യത്തോടെ നിന്റെ അടുത്തേക്ക് ഞാൻ ഈ കൂമ്പാരം കടക്കാതിരിക്കാനും","p":1},{"v":52,"t":"എന്റെ അടുത്തേക്ക് ഈ കൂമ്പാരവും സ്തംഭവും നീ കടക്കാതിരിക്കാനും ഈ കുമ്പാരം ഒരു സാക്ഷ്യമാണ്; ഈ സ്തംഭവും സാക്ഷ്യമാണ്.","p":1},{"v":53,"t":"അബ്രാഹത്തിന്റെ ദൈവം, നാഹോറിന്റെ ദൈവം, അവരുടെ പിതാവിന്റെ ദൈവം നമുക്കുമധ്യേ ന്യായവിധി നടത്തട്ടെ. യാക്കോബും തന്റെ പിതാവായ ഇസഹാക്കിന്റെ ഭീതിയായവനെക്കൊണ്ട് സത്യംചെയ്തു.","p":1},{"v":54,"t":"മലമുകളിൽ യാക്കോബ് ബലി സമർപ്പിച്ചു; അപ്പം ഭക്ഷിക്കാൻ തന്റെ ചാർച്ചക്കാരെ ക്ഷണിക്കുകയും ചെയ്തു. അവർ അപ്പം ഭക്ഷിച്ചശേഷം മലമുകളിൽ രാപാർത്തു.","p":1}],"32":[{"v":1,"t":"ലാബാൻ പ്രഭാതത്തിൽ ഉണർന്ന് തന്റെ പേരക്കുട്ടികളെയും പെൺമക്കളെയും ചുംബിക്കുകയും അവരെ അനുഗ്രഹിക്കുകയും ചെയ്തു. എന്നിട്ട് ലാബാൻ നടന്ന് സ്വന്തം സ്ഥലത്തേക്കു തിരിച്ചുപോയി.","p":1},{"v":2,"t":"യാക്കോബാകട്ടെ, തന്റെ വഴിക്കും നടന്നു. അപ്പോൾ ദൈവത്തിന്റെ ദൂതന്മാർ അവനെ കണ്ടുമുട്ടി.","p":1},{"v":3,"t":"അവരെ കണ്ടപ്പോൾ യാക്കോബു പറഞ്ഞു: ഇതു ദൈവത്തിന്റെ പാളയമാണ്. ആ സ്ഥലത്തിന് അവൻ മഹനായിം എന്നു പേരുവിളിച്ചു.","p":1},{"v":4,"t":"യാക്കോബ് തന്റെ സഹോദരനായ ഏസാവിന്റെ അടുത്തേക്ക്, സെയീർനാട്ടിൽ ഏദോമിന്റെ വയലിലേക്ക്, തനിക്കുമുമ്പേ ദൂതന്മാരെ അയച്ചു.","p":1},{"v":5,"t":"അവൻ ഇപ്രകാരം അവരോടു നിർദേശിച്ചു: എന്റെ യജമാനനായ ഏസാവിനോടു നിങ്ങൾ ഇങ്ങനെ പറയണം, 'അങ്ങയുടെ ദാസനായ യാക്കോബ് ഇപ്രകാരം പറയുന്നു: ലാബാന്റെകൂടെ താൽക്കാലവാസിയായിരുന്ന ഞാൻ ഇതുവരെയും അവിടെയായിരുന്നു.","p":1},{"v":6,"t":"എനിക്ക് കാള, കഴുത, ആട്, ദാസൻ, പരിചാരിക എന്നിവ ഉണ്ടായിട്ടുണ്ട്. എന്റെ യജമാനനോടു വിവരിക്കുന്നതിനും അങ്ങയുടെ ദൃഷ്ടികളിൽ ദയ കണ്ടെത്തുന്നതിനും വേണ്ടിയാണ് ഞാൻ ആളയയ്ക്കുന്നത്'.","p":1},{"v":7,"t":"ദൂതന്മാർ യാക്കോബിന്റെ പക്കൽ, 'ഞങ്ങൾ അങ്ങയുടെ സഹോദരനായ ഏസാവിന്റെയടുക്കൽചെന്നു; അവൻതന്നെ നാനൂറ് ആളുകളുടെ അകമ്പടിയോടെ അങ്ങയെ സ്വീകരിക്കാൻ വരുന്നുണ്ട്' എന്നു പറഞ്ഞുകൊണ്ടു തിരിച്ചുവന്നു.","p":1},{"v":8,"t":"യാക്കോബ് വളരെയധികം ഭയപ്പെട്ടു; അവനു വേവലാതിയായി. തന്റെകൂടെയുണ്ടായിരുന്ന ആളുകളെയും ആടുമാടുകളെയും ഒട്ടകങ്ങളെയും അവൻ രണ്ടു സംഘമായി തിരിച്ചു.","p":1},{"v":9,"t":"ഏസാവ് ഒന്നാമത്തെ സംഘത്തിലെത്തി അതിനെ ആക്രമിക്കുന്നപക്ഷം, ശേഷിക്കുന്ന സംഘം സുരക്ഷിതമായിരിക്കുമല്ലോ എന്ന് അവൻ ചിന്തിച്ചു.","p":1},{"v":10,"t":"യാക്കോബു പറഞ്ഞു: എന്റെ പിതാവായ അബ്രാഹത്തിന്റെ ദൈവമേ, എന്റെ പിതാവായ ഇസഹാക്കിന്റെ ദൈവമേ, 'നിന്റെ നാട്ടിലേക്കും നിന്റെ സഹജരുടെ അടുത്തേക്കും തിരിയെപ്പോകുക, നിനക്കു ഞാൻ എല്ലാം ശുഭമാക്കും' എന്ന് എന്നോടരുളച്ചെയ്ത കർത്താവേ,","p":1},{"v":11,"t":"'അങ്ങയുടെ ദാസനോട് അങ്ങ് ചെയ്ത സകല കൃപകൾക്കും സകല വിശ്വസ്തതയ്ക്കും ഞാൻ ഒട്ടും അർഹനല്ല. കേവലം എന്റെ ഒരു വടിയുമായാണ് ഞാൻ ഈ ജോർദാൻ കടന്നത്. ഇപ്പോൾ ഇതാ ഞാൻ രണ്ടു സംഘമായിത്തീർന്നിരിക്കുന്നു.","p":1},{"v":12,"t":"എന്റെ സഹോദരന്റെ കൈയിൽനിന്ന്, ഏസാവിന്റെ കൈയിൽനിന്ന്, എന്നെ സദയം രക്ഷിക്കണമേ. കാരണം, ഞാൻ അവനെ ഭയപ്പെടുന്നു. അവൻ വന്ന് അമ്മയോടും മക്കളോടുമൊപ്പം എന്നെ കൊല്ലാൻ ഇടവരുത്തരുതേ.","p":1},{"v":13,"t":"മാത്രമല്ല, 'ഞാൻ തീർച്ചയായും നിനക്കു ശുഭം വരുത്തും; നിന്റെ സന്തതിയെ പെറുപ്പമൂലം എണ്ണാനാവാത്ത കടൽമണൽത്തരിപോലെ ആക്കിത്തീർക്കും' എന്ന് അങ്ങ് അരുളച്ചെയ്തിട്ടുണ്ടല്ലോ.","p":1},{"v":14,"t":"ആ രാത്രി അവൻ അവിടെ കഴിഞ്ഞുകൂടി. പിന്നെ, തന്റെ കൈവശമുള്ളതിൽനിന്ന് അവൻ തന്റെ സഹോദരൻ ഏസാവിനുവേണ്ടിയുള്ള കാഴ്ച എടുത്തു:","p":1},{"v":15,"t":"ഇരുനൂറു പെൺകോലാട്, ഇരുപത് ആൺകോലാട്, ഇരുനൂറു പെൺചെമ്മരിയാട്, ഇരുപത് ആൺചെമ്മരിയാട്,","p":1},{"v":16,"t":"കറവയുള്ള മുപ്പത് ഒട്ടകം, അവയുടെ കിടാങ്ങൾ, നാൽപതു പശു, പത്തു കാള, ഇരുപതു പെൺകഴുത, പത്ത് ആൺകഴുത എന്നിവ.","p":1},{"v":17,"t":"ഈ ഓരോ കൂട്ടത്തെയും അവൻ തന്റെ ഭൃത്യന്മാരുടെ കൈവശം വെവ്വേറെ കൊടുത്തേൽപ്പിച്ചു. അവൻ തന്റെ ഭൃത്യന്മാരോടു പറഞ്ഞു: എനിക്കുമുമ്പേ നടന്നുനീങ്ങുവിൻ. കൂട്ടങ്ങൾ തമ്മിൽ അൽപം അകലമിട്ടിരിക്കണം.","p":1},{"v":18,"t":"ഏറ്റവും മുമ്പേ പോയവനെ അവൻ ഇപ്രകാരം ചുമതലപ്പെടുത്തി: എന്റെ സഹോദരൻ ഏസാവ് നിന്നെ കണ്ടുമുട്ടുമ്പോൾ അവൻ നിന്നോട് ഇങ്ങനെ അന്വേഷിക്കും: നീ ആരുടെ ആളാണ്, നീ എവിടേക്കു പോകുന്നു, നിന്റെ മുമ്പിലുള്ള ഇതെല്ലാം ആരുടേതാണ്?","p":1},{"v":19,"t":"അപ്പോൾ നീ പറയണം: അങ്ങയുടെ ദാസനായ യാക്കോബിന്റേതാണ്. എന്റെ യജമാനനായ ഏസാവിനു കൊടുത്തയച്ചിരിക്കുന്ന കാഴ്ചവസ്തുവാണിത്. അതാ, അവനും ഞങ്ങളുടെ പിന്നാലെയുണ്ട്.","p":1},{"v":20,"t":"തുടർന്ന് അവൻ രണ്ടാമത്തവനെയും മൂന്നാമത്തവനെയും കൂട്ടങ്ങൾക്കുപിമ്പേ നടന്നിരുന്ന എല്ലാവരെയും ഇപ്രകാരം ചുമതലപ്പെടുത്തി: നിങ്ങൾ ഏസാവിനെ കണ്ടുമുട്ടുമ്പോൾ ഇതുപോലെതന്നെ അവനോടു...കാര്യം പറയണം.","p":1},{"v":21,"t":"\"ഇതാ, അങ്ങയുടെ ദാസനായ യാക്കോബ് ഞങ്ങൾക്കു പിന്നാലെയുണ്ട്\" എന്നുകൂടി നിങ്ങൾ പറയണം. അങ്ങനെ, എനിക്കുമുമ്പേ നീങ്ങുന്ന കാഴ്ചവസ്തുക്കൊണ്ട് അവന്റെ മുഖം ഞാൻ മറയ്ക്കട്ടെ; അതു കഴിഞ്ഞ് ഞാൻ അവനെ നേരിൽക്കാണും; ഒരുപക്ഷേ, അവൻ എന്നെ സ്വീകരിക്കും എന്ന് അവൻ പറഞ്ഞു.","p":1},{"v":22,"t":"അങ്ങനെ കാഴ്ചവസ്തു അവനുമുമ്പേ കടന്നുപോയി. അവനാകട്ടെ, ആ രാത്രി പാളയത്തിൽ പാർത്തു.","p":1},{"h":"യാക്കോബിന്റെ മല്പിടുത്തം"},{"v":23,"t":"അവൻ രാത്രിയിൽ ഉണർന്ന് തന്റെ രണ്ടു ഭാര്യമാരെയും തന്റെ രണ്ടു പരിചാരികമാരെയും തന്റെ പതിനൊന്നു മക്കളെയും കൂട്ടിക്കൊണ്ട് യാബ്ബോക്കിന്റെ കടവു കടന്നു.","p":1},{"v":24,"t":"അവൻ അവരെയെടുത്ത് പുഴയ്ക്കക്കരെ കടത്തിവിട്ടു. തനിക്കുണ്ടായിരുന്നതെല്ലാം അവൻ അക്കരെയെത്തിച്ചു.","p":1},{"v":25,"t":"യാക്കോബു മാത്രം അവശേഷിച്ചു. അപ്പോൾ ഒരാൾ പ്രഭാതം വിടരുന്നതുവരെ അവനുമായി മല്പിടുത്തം നടത്തി.","p":1},{"v":26,"t":"അവനോടു ജയിക്കില്ലെന്നു കണ്ടപ്പോൾ അയാൾ യാക്കോബിന്റെ എളിയീൽ ഇടിച്ചു. അവനുമായുള്ളയാളുടെ മല്പിടുത്തത്തിനിടയിൽ യാക്കോബിന്റെ എളിക്കുഴ തെറ്റി.","p":1},{"v":27,"t":"അയാൾ പറഞ്ഞു: എന്നെ വിട്ടയച്ചാലും; കാരണം, പ്രഭാതം വിടരുകയാണ്. അവൻ പറഞ്ഞു: എന്നെ അനുഗ്രഹിച്ചിട്ടല്ലാതെ അങ്ങയെ ഞാൻ വിട്ടയയ്ക്കുകയില്ല.","p":1},{"v":28,"t":"അയാൾ അവനോടു ചോദിച്ചു: നിന്റെ പേരെന്താണ്? അവൻ പറഞ്ഞു: യാക്കോബ്.","p":1},{"v":29,"t":"അപ്പോൾ അയാൾ പറഞ്ഞു: ഇനിമേൽ നിന്റെ പേര് യാക്കോബ് എന്നല്ല, പ്രത്യുത, ഇസ്രായേൽ എന്നു പറയപ്പെടും. കാരണം, നീ ദൈവത്തോടും മനുഷ്യരോടും മല്ലിട്ട് ജയിച്ചിരിക്കുന്നു.","p":1},{"v":30,"t":"അപ്പോൾ യാക്കോബ് ജിജ്ഞാസയോടെ അഭ്യർത്ഥിച്ചു: അങ്ങയുടെ പേര് വെളിപ്പെടുത്തിയാലും. അതിന് അയാൾ പറഞ്ഞു: നീ എന്റെ പേര് അന്വേഷിക്കുന്നതെന്തിന്? എന്നിട്ട്, അവിടെവെച്ച് അയാൾ യാക്കോബിനെ അനുഗ്രഹിച്ചു.","p":1},{"v":31,"t":"അപ്പോൾ യാക്കോബ് ഉദ്ഘോഷിച്ചു: ഈ സ്ഥലത്തിന്റെ പേര് പെനിയേൽ എന്നാണ്; കാരണം, ദൈവത്തെ ഞാൻ മുഖാമുഖം കണ്ടു. എന്നിട്ടും എന്റെ ജീവൻ സുരക്ഷിതമായിരിക്കുന്നു!","p":1},{"v":32,"t":"അവൻ പെനുവേൽ കടന്നപ്പോഴേക്കും സൂര്യൻ ഉദിച്ചിരുന്നു. അവനാകട്ടെ, തന്റെ എളിമൂലം മുളന്തുകയായിരുന്നു.","p":1},{"v":33,"t":"അവിടുന്ന് യാക്കോബിന്റെ എളിക്കൂഴിയിൽ, തുടയുടെ സ്‌നായുഭാഗത്ത്, ഇടിച്ചതുകൊണ്ട് ഇസ്രായേല്യർ ഇന്നും തുടയുടെ സ്‌നായു ഭക്ഷിക്കാറില്ല.","p":1}],"33":[{"h":"ഏസാവിനെ കണ്ടുമുട്ടുന്നു"},{"v":1,"t":"യാക്കോബ് തന്റെ കണ്ണുകളുയർത്തി നോക്കി: ഇതാ, ഏസാവ് അയാളോടൊപ്പം നാന്നൂറു പുരുഷന്മാരുമായി വരുന്നു. അപ്പോൾ യാക്കോബ് മക്കളെ ലെയായുടെ പക്കലും റാഹേലിന്റെ പക്കലും രണ്ടു പരിചാരികമാരുടെ പക്കലുമായി വേർതിരിച്ചു.","p":1},{"v":2,"t":"അവൻ പരിചാരികമാരെയും അവരുടെ മക്കളെയും മുന്നിലും, ലെയായെയും അവളുടെ മക്കളെയും അതിനുപുറകിലും, റാഹേലിനെയും ജോസഫിനെയും ഏറ്റവും പുറകിലും നിർത്തി.","p":1},{"v":3,"t":"എന്നിട്ട്, അവൻ അവരുടെ മുമ്പേ നീങ്ങി. തന്റെ സഹോദരന്റെ അടുത്തെത്തുവോളം അവൻ ഏഴു തവണ നിലംമുട്ടേ കുമ്പിട്ടു.","p":1},{"v":4,"t":"ഏസാവാകട്ടെ, അവനെ സ്വീകരിക്കാനായി ഓടിവന്നു; അവനെ ആലിംഗനംചെയ്തു; അവന്റെ കഴുത്തിൽവീണ് അവനെ ചുംബിച്ചു; അവർ കരഞ്ഞു.","p":1},{"v":5,"t":"അയാൾ തന്റെ കണ്ണുകളുയർത്തിയപ്പോൾ സ്ത്രീകളെയും കുട്ടികളെയും കണ്ടു. അപ്പോൾ അയാൾ ചോദിച്ചു: ഇവർ നിന്റെ ആരാണ്? അവൻ പറഞ്ഞു: ദൈവം അങ്ങയുടെ ദാസനു ചെയ്ത ഔദാര്യമാണ് ഈ കുട്ടികൾ.","p":1},{"v":6,"t":"അപ്പോൾ പരിചാരികമാർ, അവരും അവരുടെ മക്കളും, അടുത്തുചെന്ന് വണങ്ങി.","p":1},{"v":7,"t":"തുടർന്ന് ലെയായും അവളുടെ മക്കളും അടുത്തുചെന്ന് വണങ്ങി. അതിനുശേഷം ജോസഫും റാഹേലും അടുത്തുചെന്ന് വണങ്ങി.","p":1},{"v":8,"t":"അവൻ ചോദിച്ചു: ഞാൻ കണ്ടുമുട്ടിയ ആ സംഘമെല്ലാം നിന്റെ ആരാണ്? യാക്കോബു പറഞ്ഞു: എന്റെ യജമാനന്റെ ദൃഷ്ടികളിൽ പ്രീതി സമ്പാദിക്കാൻ വേണ്ടിയുള്ളതാണ്.","p":1},{"v":9,"t":"ഏസാവു പറഞ്ഞു: എന്റെ സഹോദരാ, എനിക്കതു വേണ്ടത്രയുണ്ട്; നിന്റേത് നിനക്കുതന്നെയിരിക്കട്ടെ.","p":1},{"v":10,"t":"യാക്കോബ് പറഞ്ഞു: അരുതേ! അങ്ങയുടെ ദൃഷ്ടികളിൽ ഞാൻ പ്രീതി കണ്ടെത്തിയിട്ടുണ്ടെങ്കിൽ, എന്റെ കയ്യിൽനിന്ന് എന്റെ കാഴ്ചവസ്തു സ്വീകരിക്കണം. കാരണം, തീർച്ചയായും ദൈവത്തിന്റെ മുഖം കണ്ടാലെന്നപോലെയാണ് ഞാൻ അങ്ങയുടെ മുഖം കണ്ടത്; അങ്ങ് എന്നിൽ സംപ്രീതനാകുകയും ചെയ്തിരിക്കുന്നു.","p":1},{"v":11,"t":"ദൈവം എന്നോട് ഔദാര്യം കാണിച്ചിരിക്കുന്നതിനാലും എനിക്ക് എല്ലാം ഉള്ളതിനാലും അങ്ങയ്ക്കായി എത്തിച്ചിരിക്കുന്ന എന്റെ കാഴ്ച സ്വീകരിച്ചാലും. അവൻ അയാളെ നിർബന്ധിച്ചപ്പോൾ അയാൾ അതു സ്വീകരിച്ചു.","p":1},{"v":12,"t":"അയാൾ പറഞ്ഞു: നമുക്കു യാത്രയാകാം; നമുക്കു പുറപ്പെടാം. ഞാൻ നിന്റെ മുമ്പേ നടക്കാം.","p":1},{"v":13,"t":"അവൻ അയാളോടു പറഞ്ഞു:എന്റെ യജമാനനേ, കുട്ടികളൊക്കെ ക്ഷീണിച്ചിരിക്കുകയാണെന്ന് അങ്ങേക്കറിയാമല്ലോ. കരവയുള്ള ആടുമാടുകളും എന്റെ ചുമതലയിലുണ്ട്. ഒരു ദിവസത്തേക്കാണെങ്കിലും കൂടുതലായി ഓടിച്ചാൽ ആട്ടിൻപറ്റംമുഴുവൻ ചത്തുപോകും.","p":1},{"v":14,"t":"എന്റെ യജമാനൻ അങ്ങേ ദാസനുമുമ്പേ പോയാലും. ഞാനാകട്ടെ, സെയീരിലേക്ക്, എന്റെ യജമാനന്റെ അടുത്തേക്കു വന്നെത്തുന്നതുവരെ, എന്റെ മുമ്പിലുള്ള കന്നുകാലികളുടെ നടപ്പിനൊത്ത്, കുട്ടികളുടെ നടപ്പിനൊത്ത്, സാവകാശം മുന്നേറാം.","p":1},{"v":15,"t":"എന്റെകൂടെയുള്ള ജനത്തിൽനിന്ന് കുറേപ്പേരെ ഞാൻ നിന്റെകൂടെ നിർത്താം എന്ന് ഏസാവ് പറഞ്ഞപ്പോൾ അവൻ ചോദിച്ചു: അതെന്തിനാണ്? ഞാൻ എന്റെ യജമാനന്റെ ദൃഷ്ടികളിൽ ദയ കണ്ടെത്തുന്നല്ലോ.","p":1},{"v":16,"t":"ഏസാവ് അന്നുതന്നെ തന്റെ വഴിക്കു സെയീരിലേക്കു തിരിയെപ്പോയി.","p":1},{"v":17,"t":"യാക്കോബാകട്ടെ, സുക്കോത്തിലേക്കു നീങ്ങി. പിന്നെ തനിക്ക് ഒരു വീട് പണിതു; തന്റെ കാലിക്കൂട്ടത്തിന് കൂടുകളും കെട്ടി. അതുകൊണ്ടാണ് ആ സ്ഥലത്തെ സുക്കോത്ത് എന്നു പേരുവിളിക്കുന്നത്.","p":1},{"v":18,"t":"യാക്കോബ് പാദാൻആരാമിൽനിന്നു പുറപ്പെട്ട് കാനാൻദേശത്തുള്ള ഷെക്കെംപട്ടണത്തിൽ സുരക്ഷിതനായി എത്തിച്ചേർന്നു. അവിടെ നഗരത്തിനുമുമ്പിലായി പാളയമടിച്ചു.","p":1},{"v":19,"t":"തന്റെ കൂടാരമടിച്ച വയൽഭാഗം ഷെക്കെമിന്റെ പിതാവായ ഹാ മോറിന്റെ മക്കളിൽനിന്ന്, നൂറു ഖെസീഥായ്ക്ക് അവൻ വാങ്ങി.","p":1},{"v":20,"t":"അവൻ അവിടെ ഒരു ബലിപീഠം സ്ഥാപിച്ചു. അതിനെ ഏൽ-ഏലൊഹെയ്-ഇസ്രായേൽ എന്നു വിളിച്ചു.","p":1}],"34":[{"h":"ദീനായുടെ മാനഭംഗം"},{"v":1,"t":"യാക്കോബിനുവേണ്ടി ലെയാ പ്രസവിച്ച മകൾ ദീനാ ആ നാട്ടിലെ പെൺകുട്ടികളെ കാണാനിറങ്ങി.","p":1},{"v":2,"t":"നാടിന്റെ പ്രഭുവായ ഹാമോർ എന്ന ഹിവ്യന്റെ മകൻ ഷെക്കെം അവളെ കണ്ടു. അവൻ അവളെ പിടികൂടി അവളോടൊത്തു ശയിച്ച് പീഡിപ്പിച്ചു.","p":1},{"v":3,"t":"ഒപ്പം, അവന്റെ ആത്മാവ് യാക്കോബിന്റെ മകളായ ദീനയിൽ ലയിച്ചു. അവൻ ആ പെൺകുട്ടിയെ പ്രണയിച്ചു. അവൻ ആ പെൺകുട്ടിയോട് ഹൃദയപൂർവം സംസാരിച്ചു.","p":1},{"v":4,"t":"ഷെക്കെം തന്റെ പിതാവായ ഹാമോറിനോട് ഇപ്രകാരം പറഞ്ഞു: ഈ തരുണിയെ എനിക്കു ഭാര്യയാക്കിത്തരണം.","p":1},{"v":5,"t":"തന്റെ മകളായ ദീനായെ അവൻ കളങ്കിതയാക്കി എന്നു യാക്കോബു കേട്ടു. അവന്റെ പുത്രന്മാർ അവന്റെ കാലിക്കൂട്ടത്തോടൊപ്പം വയലിലായിരുന്നു. അവർ വരുന്നതുവരെ യാക്കോബ് സംയമനംപാലിച്ചു.","p":1},{"v":6,"t":"അപ്പോൾ, ഷെക്കെമിന്റെ പിതാവായ ഹാ മോർ യാക്കോബിനോട് സംസാരിക്കാനായി അവന്റെ അടുത്തേക്ക് തിരിച്ചു","p":1},{"v":7,"t":"കേട്ടമാത്രയിൽ, യാക്കോബിന്റെ പുത്രന്മാരും വയലിൽ നിന്ന് വന്നെത്തി. അവർ രോഷം കൊണ്ടു. യാക്കോബിന്റെ മകളുമൊത്തു ശയിച്ചതുവഴി ഇസ്രായേലിൽ മ്ലേച്ഛകൃത്യം ചെയ്തുകൊണ്ട് അവൻ അവരെ അതീവം കുപിതരാക്കി. അപ്രകാരം ചെയ്യപ്പെടാൻപാടില്ലായിരുന്നു.","p":1},{"v":8,"t":"അപ്പോൾ ഹാമോർ അവരോട് ഇപ്രകാരം പറഞ്ഞു: ഷെക്കെം എന്റെ മകനാണ്. അവന്റെ ആത്മാവ് നിങ്ങളുടെ പുത്രിയിൽ അനുരക്തമാണ്. അവളെ അവനു ഭാര്യയായി നൽകിയാലും.","p":1},{"v":9,"t":"ഞങ്ങളുമായി വിവാഹബന്ധത്തിലേർപ്പെടുവിൻ. നിങ്ങളുടെ പെൺമക്കളെ ഞങ്ങൾക്കു തരുവിൻ; ഞങ്ങളുടെ പെൺമക്കളെ നിങ്ങൾക്കായും സ്വീകരിക്കുവിൻ.","p":1},{"v":10,"t":"നിങ്ങൾ ഞങ്ങളുടെകൂടെ പാർക്കുവിൻ. ഈ നാടു നിങ്ങളുടെ മുൻപിലുണ്ടല്ലോ. അതിൽ വസിച്ച്, അതിനെ പ്രയോജനപ്പെടുത്തി, സമ്പാദ്യമുണ്ടാക്കുവിൻ.","p":1},{"v":11,"t":"തുടർന്ന് അവളുടെ പിതാവിനോടും സഹോദരന്മാരോടുമായി ഷെക്കെം പറഞ്ഞു: നിങ്ങളുടെ ദൃഷ്ടികളിൽ ഞാൻ പ്രീതി കണ്ടെത്തട്ടെ. നിങ്ങൾ എന്നോടു പറയുന്നതു ഞാൻ തരാം.","p":1},{"v":12,"t":"സ്ത്രീധനവും സമ്മാനവും എന്റെമേൽ അധികമായി വർധിപ്പിച്ചുകൊള്ളുവിൻ. നിങ്ങൾ എന്നോട് ആവശ്യപ്പെടുന്നതെന്തായാലും ഞാൻ തരുന്നതാണ്. പെൺകുട്ടിയെ ഭാര്യയായി എനിക്കു നൽകിയാൽമതി.","p":1},{"v":13,"t":"തങ്ങളുടെ സഹോദരി ദീനായെ ഷെക്കെം കളങ്കിതയാക്കിയതുകൊണ്ട് യാക്കോബിന്റെ മക്കൾ അവനോടും അവന്റെ പിതാവായ ഹാമോറിനോടും വഞ്ചനാപൂർവം മറുപടിപറഞ്ഞു.","p":1},{"v":14,"t":"അവർ അവനോടു പറഞ്ഞു: അഗ്രചർമം ഞങ്ങൾക്ക് അപമാനമായതുകൊണ്ട്, അതുള്ള ഒരാൾക്ക് ഞങ്ങളുടെ സഹോദരിയെ നൽകുക എന്ന ഇക്കാര്യം ചെയ്യുക ഞങ്ങൾക്കു സാധ്യമല്ല.","p":1},{"v":15,"t":"എന്നാൽ ഇങ്ങനെമാത്രം ഞങ്ങൾ നിങ്ങളോടു സമ്മതിക്കാം: നിങ്ങൾക്കിടയിലെ ഓരോ പുരുഷനും ഞങ്ങളെപ്പോലെയാകണം അതായത്, പരിച്ഛേദനം ചെയ്യപ്പെടണം.","p":1},{"v":16,"t":"അപ്പോൾ ഞങ്ങളുടെ പുത്രിമാരെ ഞങ്ങൾ നിങ്ങൾക്കു തരാം. നിങ്ങളുടെ പുത്രിമാരെ ഞങ്ങൾക്കായി സ്വീകരിക്കുകയും ചെയ്യാം. ഞങ്ങൾ നിങ്ങളോടൊത്തു വസിക്കുകയും നമ്മൾ ഒറ്റജനമായിത്തീരുകയും ചെയ്യും.","p":1},{"v":17,"t":"പരിച്ഛേദനം ചെയ്യുന്നതിൽ നിങ്ങൾ ഞങ്ങളെ കേൾക്കാത്തപക്ഷം, ഞങ്ങളുടെ മകളെയുംകൊണ്ട് ഞങ്ങൾ പോകും.","p":1},{"v":18,"t":"അവരുടെ വാക്കുകൾ ഹാമോറിന്റെ ദൃഷ്ടികളിലും ഹാമോറിന്റെ മകൻ ഷെക്കെമിന്റെ ദൃഷ്ടികളിലും ആകർഷകമായിരുന്നു.","p":1},{"v":19,"t":"അക്കാര്യം ചെയ്യാൻ ആ ചെറുപ്പക്കാരൻ അമാന്തിച്ചില്ല. കാരണം, യാക്കോബിന്റെ മകളിൽ അവൻ അനുരക്തനായിരുന്നു. തന്റെ പിതൃഭവനംമുഴുവനിലും അവൻ മതിക്കപ്പെട്ടവനായിരുന്നു.","p":1},{"v":20,"t":"ഹാമോറും സ്വപുത്രൻ ഷെക്കെമും തങ്ങളുടെ നഗര കവാടത്തിൽച്ചെന്ന് തങ്ങളുടെ പട്ടണത്തിലെ ആളുകളോട് ഇപ്രകാരം പറഞ്ഞു:","p":1},{"v":21,"t":"ഈ ആളുകൾ നമ്മോട് സൗഹാർദത്തിലാണ്. അവർ ഈ നാട്ടിൽ പാർത്ത്, അതു പ്രയോജനപ്പെടുത്തട്ടെ. നോക്കൂ, നാട് അവരുടെ മുൻപിൽ ഇരുമടങ്ങ് വിസ്തൃതമാണല്ലോ. അവരുടെ പുത്രിമാരെ നമുക്കു ഭാര്യമാരായി നമ്മൾ സ്വീകരിക്കും. നമ്മുടെ പുത്രിമാരെ നമ്മൾ അവർക്കു നൽകുകയും ചെയ്യും.","p":1},{"v":22,"t":"എന്നാൽ, ഇങ്ങനെമാത്രമാണ് ആ ആളുകൾ നമ്മോടൊത്തു വസിക്കാനും ഒറ്റജനമായിത്തീരാനും സമ്മതിച്ചിട്ടുള്ളത്: അതായത്, അവർ പരിച്ഛേദിതരായിരിക്കുന്നപോലെ, നമ്മുടെ ഓരോ പുരുഷനും പരിച്ഛേദിതനാകണം.","p":1},{"v":23,"t":"അവരുടെ കാലിക്കൂട്ടവും അവരുടെ സമ്പാദ്യവും അവരുടെ മൃഗസമ്പത്തുമുഴുവനും നമ്മുടേതാവില്ലേ? ആകയാൽ, നമുക്ക് അവരോടു സമ്മതിക്കാം. എങ്കിൽ, അവർ നമ്മുടെ കൂടെ താമസിക്കും.","p":1},{"v":24,"t":"അവന്റെ നഗരകവാടം കടന്ന എല്ലാവരും ഹാമോറിനെയും അവന്റെ മകൻ ഷെക്കെമിനെയും അനുസരിച്ചു; അങ്ങനെ, അവന്റെ നഗര കവാടം കടന്ന എല്ലാവരും, ഓരോ പുരുഷനും, പരിച്ഛേദനം ചെയ്യപ്പെട്ടു.","p":1},{"v":25,"t":"മൂന്നാംദിവസം അവർ വേദനിച്ചിരിക്കേ, യാക്കോബിന്റെ രണ്ടു പുത്രന്മാർ, ദീനായുടെ സഹോദരന്മാർ, ശിമയോനും ലേവിയും താന്താങ്ങളുടെ വാളെടുത്ത് അപ്രതിരോധ്യരായി നഗരത്തിൽ കടന്ന് ഓരോ പുരുഷനെയും വധിച്ചു.","p":1},{"v":26,"t":"ഹാമോറിനെയും അവന്റെ മകൻ ഷെക്കെമിനെയും അവർ വാളിന്റെ വായ്ത്തലയ്ക്ക് ഇരയാക്കി. ഷെക്കെമിന്റെ വീട്ടിൽനിന്നു ദീനായെ വീണ്ടെടുത്ത് അവർ പുറത്തുകടന്നു.","p":1},{"v":27,"t":"തങ്ങളുടെ സഹോദരിയെ അവർ കളങ്കിതയാക്കിയതിനാൽ വധിക്കപ്പെട്ടവരുടെയിടയിലൂടെ യാക്കോബിന്റെ മക്കൾ വന്ന് നഗരം കൊള്ളയടിച്ചു.","p":1},{"v":28,"t":"അവരുടെ ആടുമാടുകളെയും അവരുടെ കഴുതകളെയും നഗരത്തിലും വയലിലുമുണ്ടായിരുന്നവയും അവർ എടുത്തുകൊണ്ടുപോയി.","p":1},{"v":29,"t":"അവരുടെ സർവസമ്പത്തും വീട്ടുവകകളൊക്കെയും അവർ കൊള്ളയടിക്കുകയും അവരുടെ ഓരോ കുഞ്ഞിനെയും അവരുടെ സ്ത്രീകളെയും ബന്ധനസ്ഥരാക്കുകയും ചെയ്തു.","p":1},{"v":30,"t":"അപ്പോൾ യാക്കോബ് ശിമയോനോടും ലേവിയോടും പറഞ്ഞു: തദേശവാസികൾക്കിടയിൽ - കാനാന്യർക്കിടയിലും പെരീസ്യർക്കിടയിലും - എന്നെ അപഹാസ്യനാക്കുംവിധം നിങ്ങൾ എന്നെ കുഴപ്പത്തിലാക്കിയിരിക്കുന്നു. ഞാൻ ആളെണ്ണം കുറഞ്ഞവനാണ്. അവർ എനിക്കെതിരേ സംഘടിച്ച് എന്നെ ആക്രമിക്കും. അപ്പോൾ ഞാൻ, ഞാനും എന്റെ കുടുംബവും, നിർമാർജനം ചെയ്യപ്പെടും.","p":1},{"v":31,"t":"അപ്പോൾ അവർ ചോദിച്ചു: ഞങ്ങളുടെ സഹോദരിയെ അവൻ ഒരു വേശ്യകണക്കേ ആക്കാമെന്നോ?","p":1}],"35":[{"h":"യാക്കോബ് വീണ്ടും ബേഥേലിൽ"},{"v":1,"t":"ദൈവം യാക്കോബിനോട് അരുൾചെയ്തു: എഴുന്നേറ്റ് ബേഥേലിലേക്കു കയറി അവിടെ പാർക്കുക. നിന്റെ സഹോദരനായ ഏസാവിന്റെ മുൻപിൽനിന്നു നീ പളായനം ചെയ്തപ്പോൾ നിനക്കു പ്രത്യക്ഷപ്പെട്ട ദൈവത്തിന് അവിടെ ഒരു ബലിപീഠമുണ്ടാക്കുക.","p":1},{"v":2,"t":"അതുകൊണ്ട്, യാക്കോബ് തന്റെ കുടുംബത്തോടും കൂടെയുണ്ടായിരുന്ന എല്ലാവരോടുമായി പറഞ്ഞു: നിങ്ങളുടെ ഇടയിലുള്ള അന്യദേവന്മാരെ ദൂരെക്കളയുവിൻ; നിങ്ങളെത്തന്നെ ശുദ്ധീകരിപ്പിൻ; നിങ്ങളുടെ വസ്ത്രങ്ങൾ മാറുവിൻ.","p":1},{"v":3,"t":"നമുക്ക് എഴുന്നേറ്റ് ബേഥേലിലേക്കു കയറാം. എന്റെ കഷ്ടതയുടെ ദിനത്തിൽ എനിക്ക് ഉത്തരമരുളിയ ദൈവത്തിന് ഞാൻ അവിടെ ഒരു ബലിപീഠം പണിയട്ടെ; ഞാൻ പ്രയാണംചെയ്ത വഴിയിൽ അവിടുന്ന് എന്നോടുകൂടെയുണ്ടായിരുന്നു.","p":1},{"v":4,"t":"തങ്ങളുടെ കൈവശമുണ്ടായിരുന്ന എല്ലാ അന്യദേവന്മാരെയും തങ്ങളുടെ കർണാഭരണങ്ങളും അവർ യാക്കോബിനു നൽകി. യാക്കോബ് അവ ഷെക്കെമിനടുത്തുള്ള ഓക്കുമരത്തിന്റെ ചുവട്ടിൽ കുഴിച്ചുമൂടി.","p":1},{"v":5,"t":"അവർ യാത്രതിരിച്ചു; അവർക്കു ചുറ്റുമുള്ള നഗരങ്ങളുടെമേൽ ദൈവീകമായ ഭീതിയുണ്ടായി. അതുകൊണ്ട് യാക്കോബിന്റെ മക്കളെ അവർ പിന്തുടർന്നില്ല.","p":1},{"v":6,"t":"അങ്ങനെ യാക്കോബ്, അവനും അവനോടുകൂടെയുണ്ടായിരുന്ന ജനമുഴുവനും, കാനാൻനാട്ടിലെ ലൂസിൽ വന്നുചേർന്നു; അതുതന്നെയാണ് ബേഥേൽ.","p":1},{"v":7,"t":"അവിടെ അവൻ ഒരു ബലിപീഠം പണിയുകയും ആ സ്ഥലത്തിന് ഏൽ ബേഥേൽ എന്ന് പേരിടുകയും ചെയ്തു. കാരണം, സ്വന്തം സഹോദരന്റെ മുൻപിൽനിന്ന് ഒളിച്ചോടിയപ്പോൾ ദൈവം തന്നെത്തന്നെ അവനു വെളിപ്പെടുത്തിയത് അവിടെവച്ചാണ്.","p":1},{"v":8,"t":"റബെക്കാക്കായുടെ പരിചാരികയായ ദബോറ മരണമടഞ്ഞു. ബേഥേലിന്റെ താഴ്‌വരയിലുള്ള ഓക്കുമരത്തിൻകീഴെ അവൾ സംസ്‌കരിക്കപ്പെട്ടു. അലോൺ ബാക്കൂത്ത് എന്ന് അതിന് പേരുവിളിക്കുകയും ചെയ്തു.","p":1},{"v":9,"t":"പാദാൻആരാമിൽനിന്നു യാക്കോബു പോന്നപ്പോൾ ദൈവം അവനു വീണ്ടും പ്രത്യക്ഷപ്പെട്ട്, അവനെ അനുഗ്രഹിച്ചു.","p":1},{"v":10,"t":"ദൈവം അവനോട് അരുൾചെയ്തു: യാക്കോബ് എന്നാണ് നിന്റെ പേര്, ഇനിമേൽ നിന്റെ പേര് യാക്കോബ് എന്നല്ല വിളിക്കപ്പെടുന്നത്. പ്രത്യുത, നിന്റെ പേര് ഇസ്രായേൽ എന്നായിരിക്കും. അവിടുന്ന് അവന്റെ പേര് ഇസ്രായേൽ എന്നു വിളിച്ചു.","p":1},{"v":11,"t":"ദൈവം അവനോട് അരുൾചെയ്തു: ഞാനാണ് സർവശക്തനായ തമ്പുരാൻ. നീ സന്താനമുള്ളവനായി പെരുകുക. ജനതയും ജനതകളുടെ സമൂഹവും നിന്നിൽനിന്ന് ഉദ്ഭവിക്കും; രാജാക്കന്മാർ നിന്റെ അരക്കെട്ടിൽനിന്ന് പുറപ്പെടും.","p":1},{"v":12,"t":"അബ്രാഹത്തിനും ഇസഹാക്കിനും ഞാൻ നൽകിയ നാട് നിനക്കു ഞാൻ തരും; നിനക്കുശേഷം നിന്റെ സന്തതിക്കും ഞാൻ ആ നാടു നൽകും.","p":1},{"v":13,"t":"അനന്തരം, അവനുമായി സംസാരിച്ച സ്ഥലത്ത്, അവനുമുകളിൽനിന്ന് ദൈവം ആരോഹണം ചെയ്തു.","p":1},{"v":14,"t":"അവിടുന്നു തന്നോടു സംസാരിച്ച സ്ഥലത്ത് യാക്കോബ് ഒരു സ്തംഭം നാട്ടി, ഒരു ശിലാസ്തംഭം. അതിന്മേൽ അവൻ ഒരു പാനീയബലിയർപ്പിക്കുകയും എണ്ണയൊഴിക്കുകയും ചെയ്തു.","p":1},{"v":15,"t":"ദൈവം തന്നോടു സംസാരിച്ച ആ സ്ഥലത്തിന് യാക്കോബ് ബേഥേൽ എന്നു പേരുവിളിച്ചു.","p":1},{"h":"റാഹേലിന്റെ മരണം"},{"v":16,"t":"ബേഥേലിൽനിന്ന് അവർ നീങ്ങി എഫ്രാത്തായായിൽ എത്താൻ ഒരു കിബ്‌റാ ദൂരം കൂടിയുള്ളപ്പോൾ റാഹേൽ പ്രസവിച്ചു. അവളുടെ പ്രസവത്തിൽ അവൾ തീവ്രവേദനകൊണ്ടു.","p":1},{"v":17,"t":"അവൾ തന്റെ പ്രസവത്തിൽ തീവ്രവേദനകൊണ്ടപ്പോൾ സുതികർമിണി അവളോടു പറഞ്ഞു: ഭയപ്പെടേണ്ട; എന്തെന്നാൽ, നിനക്ക് ഇതും ഒരു പുത്രൻതന്നെ.","p":1},{"v":18,"t":"എന്നാൽ, അവൾ മരിക്കുകയായിരുന്നുവെന്നതുകൊണ്ട്, അവളുടെ ആത്മാവു വേർപിരിയവേ, അവൾ അവനെ ബെൻ-ഓനി എന്നു പേരുവിളിച്ചു. എന്നാൽ, അവന്റെ പിതാവ് അവനെ ബെഞ്ചമിൻ എന്നാണ് വിളിച്ചത്.","p":1},{"v":19,"t":"റാഹേൽ നിര്യാതയായി ബെത്‌ലെഹെം എന്ന എഫ്രാത്തിലേക്കുള്ള വഴിയിൽ അവൾ സംസ്‌കരിക്കപ്പെട്ടു.","p":1},{"v":20,"t":"അവളുടെ കല്ലറമേൽ യാക്കോബ് ഒരു സ്തംഭം നാട്ടി. ഇന്നുവരെയും അതാണ് റാഹേലിന്റെ കബറിടസ്തംഭം.","p":1},{"v":21,"t":"ഇസ്രായേൽ നീങ്ങി ഏദെർഗോപുരത്തിനപ്പുറത്ത് കൂടാരമടിച്ചു.","p":1},{"v":22,"t":"ഇസ്രായേൽ ആ നാട്ടിൽ പാർത്തിരുന്നപ്പോൾ റൂബൻ പോയി തന്റെ പിതാവിന്റെ ഉപനാരിയായ ബിൽഹായുമൊത്തു ശയിച്ചു; ഇസ്രായേൽ അതു കേൾക്കാനിടയാവുകയും ചെയ്തു.","p":1},{"h":"യാക്കോബിന്റെ പുത്രന്മാർ"},{"v":22,"t":"യാക്കോബിനു പന്ത്രണ്ടു പുത്രന്മാരുണ്ടായിരുന്നു.","p":1},{"v":23,"t":"ലെയായുടെ പുത്രന്മാർ: യാക്കോബിന്റെ കടിഞ്ഞൂൽ പുത്രൻ റൂബൻ, ശിമയോൻ, ലേവി, യൂദാ, ഇസ്സാക്കർ, സെബുലൂൺ.","p":1},{"v":24,"t":"റാഹേലിന്റെ പുത്രന്മാർ: ജോസഫ്, ബെഞ്ചമിൻ.","p":1},{"v":25,"t":"റാഹേലിന്റെ പരിചാരി കയായ ബിൽഹായുടെ പുത്രന്മാർ: ദാൻ, നഫ്താലി.","p":1},{"v":26,"t":"ലെയായുടെ പരിചാരികയായ സിൽഫായുടെ പുത്രന്മാർ: ഗാദ്, ആഷേർ. യാക്കോബിന് പാദാൻ ആരാമിൽവച്ചു ജനിച്ച പുത്രന്മാരാണ് ഇവർ.","p":1},{"h":"ഇസഹാക്കിന്റെ മരണം"},{"v":27,"t":"അബ്രാഹവും ഇസഹാക്കും തത്കാലവാസം നടത്തിയിരുന്ന കിരിയാത്-അർബായിലെ മാമ്രേയിൽ, അതായത് ഹെബ്രോണിൽ, തന്റെ പിതാവായ ഇസഹാക്കിന്റെ അടുത്തേക്ക് യാക്കോബു വന്നു.","p":1},{"v":28,"t":"ഇസഹാക്കിന്റെ ആയുഷ്‌കാലം നൂറ്റെൺപതു വർഷമായിരുന്നു.","p":1},{"v":29,"t":"ഇസഹാക്ക് വൃദ്ധനും ആയുഷ്‌കാലം തികഞ്ഞവനുമായി അന്ത്യശ്വാസംവലിച്ചു. അവൻ മരിച്ച് സ്വന്തം ജനങ്ങളോട് ചേർന്നു. അവന്റെ മക്കളായ ഏസാവും യാക്കോബും അവനെ സംസ്‌കരിച്ചു.","p":1}],"36":[{"h":"ഏസാവ് ഏദോമ്യരുടെ പിതാവ്"},{"v":1,"t":"ഏസാവിന്റെ അതായത്, ഏദോമിന്റെ വംശാവലി ഇതാണ്:","p":1},{"v":2,"t":"കാനാന്യസ്ത്രീകളിൽനിന്നാണ് ഏസാവ് തനിക്കു ഭാര്യമാരെ സ്വീകരിച്ചത് - ഹിത്യനായ ഏലോനിന്റെ മകൾ ആദാ, ഹിവ്യനായ സിബിയോന്റെ മകളായ ആനായുടെ പുത്രി ഒഹോലിബാമാ,","p":1},{"v":3,"t":"ഇസ്മായേലിന്റെ മകളും നെബായോത്തിന്റെ സഹോദരിയുമായ ബസ്മത്ത് എന്നിവരായിരുന്നു അവർ.","p":1},{"v":4,"t":"ആദാ ഏസാവിനായി എലിഫാസിനെ പ്രസവിച്ചു; ബസ്മത്ത് റവുവേലിനെയും പ്രസവിച്ചു.","p":1},{"v":5,"t":"ഒഹോലിബാമാ യവൂഷിനെയും യാലാമിനെയും കോറഹിനെയും പ്രസവിച്ചു. ഇവരാണ് കാനാൻദേശത്ത് ഏസാവിനു പിറന്ന മക്കൾ.","p":1},{"v":6,"t":"ഏസാവ് തന്റെ ഭാര്യമാരെയും പുത്രീപുത്രന്മാരെയും വീട്ടിലുള്ള എല്ലാ ആളുകളെയും തന്റെ കാലിക്കൂട്ടവും സകല മൃഗസമ്പത്തും കാനാൻദേശത്തു താൻ നേടിയ സകല സമ്പാദ്യവും എടുത്ത് സ്വസഹോദരനായ യാക്കോബിൽനിന്നകലെ ഒരു നാട്ടിലേക്കു പോയി.","p":1},{"v":7,"t":"കാരണം, ഒന്നിച്ച് പാർക്കാൻ വയ്യാത്തവിധം അത്ര അധികമായിരുന്നു അവരുടെ സമ്പാദ്യം. അവരുടെ കാലിക്കൂട്ടങ്ങൾമൂലം അവരെ സംവഹിക്കാൻ അവരുടെ തത്കാലവാസഭൂമി അപര്യാപ്തമായിരുന്നു.","p":1},{"v":8,"t":"അതുകൊണ്ട്, ഏസാവ് സെയ്‌ർമലയിൽ താമസമാക്കി. ഏസാവുതന്നെയാണ് ഏദോം.","p":1},{"v":9,"t":"സെയിർമലയിലെ ഏദോമ്യരുടെ പിതാവായ ഏസാവിന്റെ വംശാവലി ഇതാണ്.","p":1},{"v":10,"t":"ഏസാവിന്റെ പുത്രന്മാരുടെ പേരുകൾ ഇവയാണ്: ഏസാവിന്റെ ഭാര്യ ആദായുടെ മകൻ എലിഫാസ്, ഏസാവിന്റെ ഭാര്യ ബസ്മത്തിന്റെ മകൻ റവുവേൽ.","p":1},{"v":11,"t":"എലിഫാസിന്റെ പുത്രന്മാരായിരുന്നു തേമാൻ, ഓമർ, സെഫോ, ഗത്താം, കെനസ് എന്നിവർ.","p":1},{"v":12,"t":"ഏസാവിന്റെ മകൻ എലിഫാസിന് തിമ്നാ എന്നൊരു ഉപനാരിയുണ്ടായിരുന്നു. അവൾ എലിഫാസിനായി അമലേക്കിനെ പ്രസവിച്ചു. ഇവരാണ് ഏസാവിന്റെ ഭാര്യയായ ആദായുടെ പുത്രന്മാർ.","p":1},{"v":13,"t":"റവുവേലിന്റെ പുത്രന്മാരാണ് നഹത്ത്, സേറഹ്, ഷമ്മാ, മിസ്സാ എന്നിവർ; ഏസാവിന്റെ ഭാര്യ ബസ്മത്തിന്റെ മക്കളാണ് ഇവർ.","p":1},{"v":14,"t":"സിബിയോന്റെ പുത്രിയായ ആനായുടെ മകളും ഏസാവിന്റെ ഭാര്യയുമായ ഒഹോലിബാമായുടെ പുത്രന്മാർ ഇവരാണ് - അവൾ ഏസാവിനായി യവൂഷിനെയും യാലാമിനെയും കോറഹിനെയും പ്രസവിച്ചു.","p":1},{"v":15,"t":"ഏസാവിന്റെ മക്കളുടെ പ്രഭുക്കന്മാർ ഇവരാണ്: ഏസാവിന്റെ ആദ്യജാതനായ എലിഫാസിന്റെ മക്കൾ തേമാൻപ്രഭു, ഓമർപ്രഭു, സെഫോപ്രഭു, കെനസ്പ്രഭു,","p":1},{"v":16,"t":"കോറഹ്പ്രഭു, ഗത്താംപ്രഭു, അമലേക്പ്രഭു. ഇവരാണ് ഏദോംനാട്ടിൽ എലിഫാസിന്റെ പ്രഭുക്കന്മാർ. ആദായുടെ പുത്രന്മാരാണിവർ.","p":1},{"v":17,"t":"ഏസാവിന്റെ മകനായ റവുവേലിന്റെ പുത്രന്മാർ: നഹത്ത്പ്രഭു, സേറഹ്പ്രഭു, ഷമ്മാപ്രഭു, മിസ്സാപ്രഭു. ഇവയാണ് ഏദോംനാട്ടിൽ റവുവേലിന്റെ പ്രഭുക്കന്മാർ. ഇവർ ഏസാവിന്റെ ഭാര്യ ബസ്മത്തിന്റെ മക്കളാണ്.","p":1},{"v":18,"t":"ഏസാവിന്റെ ഭാര്യ ഒഹോലിബാമായുടെ പുത്രന്മാർ ഇവരാണ്: യവൂഷ്പ്രഭു, യാലാംപ്രഭു, കോറഹ്പ്രഭു. ഇവരാണ് ഏസാവിന്റെ ഭാര്യയും ആനായുടെ മകളുമായ ഒഹോലിബാമായുടെ പ്രഭുക്കന്മാർ.","p":1},{"v":19,"t":"ഇവരാണ് ഏസാവിന്റെ അതായത്, ഏദോമിന്റെ പുത്രന്മാർ. അവരുടെ പ്രഭുക്കന്മാർ ഇവർതന്നെ.","p":1},{"v":20,"t":"ഇവർ അന്നാട്ടിൽ പാർത്തിരുന്നവരും സെയ്‌ർ എന്ന ഹോര്യന്റെ പുത്രന്മാരുമാണ്: ലോത്താൻ, ഷൊബാൽ, സിബയോൻ, ആനാ,","p":1},{"v":21,"t":"ദീഷോൻ, ഏസെർ, ദീഷാൻ. ഏദോംനാട്ടിലെ സെയ്‌റിന്റെ പുത്രന്മാരും ഹോര്യകുലങ്ങളുമാണ് ഇവർ.","p":1},{"v":22,"t":"ലോത്താന്റെ പുത്രന്മാരായിരുന്നു ഹോറിയും ഹേമാമും. ലോത്താന്റെ സഹോദരിയായിരുന്നു തിമ്നാ.","p":1},{"v":23,"t":"ഷൊബാലിന്റെ പുത്രന്മാർ അൽവാൻ, മനഹത്ത്, ഏബാൽ, ഷെഫോ, ഓനാം എന്നിവർ.","p":1},{"v":24,"t":"സിബയോന്റെ പുത്രന്മാർ ഇവ","p":1},{"v":24,"t":"രാണ്: ആയ്യാ, ആനാ. തന്റെ പിതാവായ സിബയോന്റെ കഴുതകളെ മേയ്ക്കുമ്പോൾ മരുഭൂമിയിൽ ചൂടു ഉറവകൾ കണ്ടെത്തിയ ആനാ ഇവൻതന്നെ.","p":1},{"v":25,"t":"ആനായുടെ മക്കൾ ഇവരാണ്: ദീഷോനും ആനായുടെ പുത്രി ഒഹോലിബാമായും.","p":1},{"v":26,"t":"ദീഷാന്റെ പുത്രന്മാർ ഹെമ്ദാൻ, എഷ്‌ബാൻ, ഇത്രാൻ, കെരാൻ എന്നിവരായിരുന്നു.","p":1},{"v":27,"t":"ഏസെറിന്റെ പുത്രന്മാർ ഇവരാണ്: ബിൽഹാൻ, സാവാൻ, അക്കാൻ.","p":1},{"v":28,"t":"ദീഷാന്റെ പുത്രന്മാർ ഊസ്, അരാൻ എന്നിവരാണ്.","p":1},{"v":29,"t":"ഹോര്യകുലങ്ങൾ ഇവയാണ്: ലോത്താൻകുലം, ഷൊബാൻകുലം, സിബയോൻകുലം, ആനാകുലം,","p":1},{"v":30,"t":"ദീഷോൻകുലം, ഏസെർകുലം, ദീഷാൻകുലം. സെയ്‌ർനാട്ടിൽ ഹോര്യകുലങ്ങൾ, അവരുടെ നേതാക്കൾക്കനുസരിച്ച്, ഇവയാണ്.","p":1},{"v":31,"t":"ഇസ്രായേല്യർക്ക് രാജഭരണം ഉണ്ടാകുന്നതിനുമുമ്പ് ഏദോംനാടു ഭരിച്ച രാജാക്കന്മാർ ഇവരായിരുന്നു:","p":1},{"v":32,"t":"ബെയോറിന്റെ മകനായ ബേല ഏദോമിൽ ഭരിച്ചു. അവന്റെ പട്ടണത്തിന്റെ പേര് ദിൻഹാബാ എന്നായിരുന്നു.","p":1},{"v":33,"t":"ബേല മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് ബോസ്രായിൽനിന്നുള്ള സേറഹിന്റെ മകൻ യോബാബ് ഏദോമിൽ ഭരിച്ചു.","p":1},{"v":34,"t":"യോബാബ് മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് തേമാന്യദേശത്തുനിന്നുള്ള ഹൂഷാം രാജാവായി.","p":1},{"v":35,"t":"ഹൂഷാം മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് ബദാദിന്റെ പുത്രനായ ഹദാദ് രാജാവായി. അവൻ മൊവാബുദേശത്തുവച്ച് മിദിയാനെ തോൽപ്പിച്ചു. അവന്റെ പട്ടണത്തിന്റെ പേര് അവിത് എന്നായിരുന്നു.","p":1},{"v":36,"t":"ഹദാദ് മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് മസ്റേക്കയിലെ സംലാ രാജാവായി.","p":1},{"v":37,"t":"സംലാ മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് റഹോബോത്ത് ഹന്നാറിലെ സാവുൾ രാജാവായി.","p":1},{"v":38,"t":"സാവുൾ മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് അക്ബോറിന്റെ മകനായ ബാൽ ഹാനാൻ രാജാവായി.","p":1},{"v":39,"t":"അക്ബോറിന്റെ മകനായ ബാൽ ഹാനാൻ മരിച്ചപ്പോൾ ഹദാർ അവന്റെ സ്ഥാനത്തു രാജാവായി. അവന്റെ പട്ടണത്തിന്റെ പേര് പാവു എന്നായിരുന്നു. അവന്റെ ഭാര്യയുടെ പേര് മെഹേത്തബേൽ എന്നായിരുന്നു; അവൾ മത്രേദിന്റെ പുത്രിയും മെസാഹാബിന്റെ പൗത്രിയുമായിരുന്നു.","p":1},{"v":40,"t":"തങ്ങളുടെ വംശങ്ങളും സ്ഥലങ്ങളും പേരുകളുമനുസരിച്ച് ഏസാവിന്റെ കുലനാമങ്ങൾ ഇവയാണ്: തിമ്നാകുലം, അൽവാകുലം, യത്തെത്ത്കുലം,","p":1},{"v":41,"t":"ഒഹോലിബാമാകുലം, ഏലാകുലം, പിനോൻകുലം,","p":1},{"v":42,"t":"കെനസ്കുലം, തേമാൻകുലം, മിബ്‌സാർകുലം,","p":1},{"v":43,"t":"മഗ്ദീയേൽകുലം, ഈറാംകുലം. തങ്ങളുടെ അവകാശമായ നാട്ടിലെ താമസസ്ഥലമനുസരിച്ച് ഏദോമിന്റെ കുലങ്ങൾ ഇവയായിരുന്നു. ഏദോമ്യരുടെ പൂർവികനാണ് ഏസാവ്.","p":1}],"37":[{"v":1,"t":"യാക്കോബ് തന്റെ പിതാവിന്റെ വിപ്രവാസ നാടായിരുന്ന കാനാൻദേശത്തു വാസമുറപ്പിച്ചു.","p":1},{"v":2,"t":"ഇതാണു യാക്കോബിന്റെ വംശചരിത്രം. ജോസഫ് പതിനേഴു വയസ്സുള്ളപ്പോൾ തന്റെ സഹോദരന്മാരോടൊപ്പം ആടുമേയ്ക്കുകയായിരുന്നു. അവൻ തന്റെ പിതാവിന്റെ ഭാര്യമാരായ ബിൽഹായുടെയും സിൽഫായുടെയും മക്കളുടെ കൂടെ സഹായിയായിരുന്നു. അവരെപ്പറ്റിയുള്ള ദുർവാർത്ത ജോസഫ് പിതാവിന്റെ പക്കലെത്തിച്ചു.","p":1},{"v":3,"t":"ജോസഫിനെ ഇസ്രായേൽ തന്റെ മറ്റെല്ലാ മക്കളെക്കാൾ അധികം സ്നേഹിച്ചിരുന്നു. കാരണം, തന്റെ വാർദ്ധക്യത്തിലെ മകനായിരുന്നു അവൻ. കൈയുള്ള ഒരു നീളനങ്കി അദ്ദേഹം അവനുവേണ്ടി ഉണ്ടാക്കി.","p":1},{"v":4,"t":"തങ്ങളുടെ പിതാവ് അവനെ അവന്റെ സഹോദരന്മാർ എല്ലാവരെക്കാൾ സ്നേഹിക്കുന്നു എന്ന് അവന്റെ സഹോദരന്മാർ കണ്ടു. അതുകൊണ്ട്, അവർ അവനെ വെറുത്തു. അവനോടു സൗമ്യമായി സംസാരിക്കാൻ അവർക്കു കഴിഞ്ഞില്ല.","p":1},{"v":5,"t":"ജോസഫിന് ഒരു സ്വപ്നമുണ്ടായി. അവൻ അത് തന്റെ സഹോദരന്മാരോടു വിവരിച്ചപ്പോൾ അവർ അവനെ വീണ്ടും കൂടുതൽ വെറുത്തു.","p":1},{"v":6,"t":"അവൻ അവരോടു പറഞ്ഞു: എനിക്കുണ്ടായ ഈ സ്വപ്നം കേട്ടാലും:","p":1},{"v":7,"t":"ഇതാ, നമ്മൾ പാടത്ത് കറ്റകൾ കെട്ടുകയായിരുന്നു. അപ്പോൾ ഇതാ, എന്റെ കറ്റ എഴുന്നേറ്റു; മാത്രമല്ല, അതു നിവർന്നുനിന്നു. ഇതാ, നിങ്ങളുടെ കറ്റകൾ ചുറ്റുംവന്ന് എന്റെ കറ്റയെ താണുവണങ്ങി.","p":1},{"v":8,"t":"അവന്റെ സഹോദരന്മാർ അവനോടു ചോദിച്ചു: നീ ഞങ്ങളുടെമേൽ രാജാവായിരിക്കുമെന്നുതന്നെയോണോ? അതോ, നീ ഞങ്ങളിൽ ആധിപത്യം സ്ഥാപിക്കുമെന്നുതന്നെയാണോ? അവന്റെ സ്വപ്നങ്ങളും വാക്കുകളും കാരണം അവർ അവനെ വീണ്ടും കൂടുതലായി വെറുത്തു.","p":1},{"v":9,"t":"അവനു വീണ്ടും മറ്റൊരു സ്വപ്നമുണ്ടായി. അവൻ അത് തന്റെ സഹോദരന്മാരോടു വർണ്ണിച്ചു. അവൻ പറഞ്ഞു: നോക്കൂ, ഞാൻ വേറൊരു സ്വപ്നം കണ്ടു. ഇതാ, സൂര്യനും ചന്ദ്രനും പതിനൊന്നു നക്ഷത്രങ്ങളും എന്നെ താണുവണങ്ങുന്നു.","p":1},{"v":10,"t":"അവൻ ഇത് തന്റെ പിതാവിനോടും തന്റെ സഹോദരന്മാരോടും വർണ്ണിച്ചപ്പോൾ അവന്റെ പിതാവ് അവനെ ശകാരിച്ചുകൊണ്ട് അവനോടു ചോദിച്ചു: ഇതെന്തു സ്വപ്നമാണ് നീ കണ്ടത്? ഞങ്ങൾ, ഞാനും നിന്റെ അമ്മയും നിന്റെ സഹോദരന്മാരും, നിന്നെ നിലപറ്റി താണുവണങ്ങാൻ വരുകതന്നെ വേണമെന്നോ?","p":1},{"v":11,"t":"അവന്റെ സഹോദരന്മാർക്ക് അവനോട് അസൂയയായി. അവന്റെ പിതാവാകട്ടെ, ഇക്കാര്യം ശ്രദ്ധയിൽവച്ചു.","p":1},{"v":12,"t":"അവന്റെ സഹോദരന്മാർ തങ്ങളുടെ പിതാവിന്റെ ആടുകളെ മേയ്ക്കാൻ ഷെക്കെമിൽ പോയി.","p":1},{"v":13,"t":"ഇസ്രായേൽ ജോസഫിനോടു പറഞ്ഞു: നിന്റെ സഹോദരന്മാർ ഷെക്കെമിൽ മേയ്ക്കുകയല്ലേ? വരൂ, അവരുടെ അടുത്തേക്ക് നിന്നെ ഞാനയയ്ക്കാം. അവൻ അദ്ദേഹത്തോടു പറഞ്ഞു: ഇതാ ഞാൻ!","p":1},{"v":14,"t":"അപ്പോൾ അദ്ദേഹം അവനോടു പറഞ്ഞു: നീ പോയാലും! നിന്റെ സഹോദരന്മാരുടെ ക്ഷേമവും ആട്ടിൻപറ്റത്തിന്റെ ക്ഷേമവും അന്വേഷിക്കുക. എന്നിട്ട് എന്റെ പക്കൽ വിവരമെത്തിക്കണം. അദ്ദേഹം അവനെ ഹെബ്രോൻ താഴ്‌വരയിൽനിന്നു യാത്രയാക്കി. അവൻ ഷെക്കെമിലേക്കു പോയി.","p":1},{"v":15,"t":"അവൻ അതാ, വയലിൽ അലയുകയായിരുന്നു. അപ്പോൾ ഒരാൾ അവനെ കണ്ടു. അയാൾ അവനോടു തിരക്കി: നീ എന്താണ് അന്വേഷിക്കുന്നത്?","p":1},{"v":16,"t":"അവൻ പറഞ്ഞു: ഞാൻ എന്റെ സഹോദരന്മാരെ അന്വേഷിക്കുകയാണ്. അവർ എവിടെയാണ് മേയ്ക്കുന്നത് എന്ന് എന്നോടു ദയയോടെ പറയുക.","p":1},{"v":17,"t":"അയാൾ പറഞ്ഞു: അവർ ഇവിടെനിന്നു നീങ്ങി. കാരണം, നമുക്ക് ദോത്താനിലേക്കു പോകാം എന്ന് അവർ പറയുന്നതു ഞാൻ കേട്ടു. തന്റെ സഹോദരന്മാരുടെ പുറകേ ജോസഫും പോയി. ദോത്താനിൽ അവൻ അവരെ കണ്ടുമുട്ടി.","p":1},{"v":18,"t":"ദൂരെവച്ചുതന്നെ അവർ അവനെ കണ്ടു. അവൻ അവരുടെ അടുത്തെത്തുംമുമ്പേ, അവനെ വധിക്കാൻ അവർ ഗൂഢാലോചന നടത്തി.","p":1},{"v":19,"t":"അവർ പരസ്പരം പറഞ്ഞു: അതാ വരുന്നു, സ്വപ്നങ്ങളുടെ വിദ്വാൻ","p":1},{"v":20,"t":"വരുവിൻ, ഇപ്പോൾത്തന്നെ നമുക്ക് അവനെ കൊല്ലാം, എന്നിട്ട് അവനെ കുഴികളിലൊന്നിൽ എറിയാം; ഒരു ദുഷ്ടമൃഗം അവനെ തിന്നുവെന്ന് പറയുകയും ചെയ്യാം. അവന്റെ സ്വപ്നങ്ങൾക്കു എന്തു സംഭവിക്കുമെന്നു നമുക്കു കാണാമല്ലോ.","p":1},{"v":21,"t":"റൂബൻ ഇതു കേട്ടു. അയാൾ അവനെ അവരുടെ കൈയിൽനിന്നു രക്ഷിച്ചു. അയാൾ പറഞ്ഞു: നമുക്കു ജീവൻ നശിപ്പിക്കേണ്ട.","p":1},{"v":22,"t":"അവനെ അവരുടെ കൈയിൽനിന്നു രക്ഷിച്ച് അവന്റെ പിതാവിന് തിരിച്ചേൽപ്പിക്കേണ്ടതിന്, റൂബൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ രക്തംചിന്തരുത്. അവനെ നിങ്ങൾ മരുഭൂമിയിലെ ഈ കുഴിയിൽ തള്ളിയിടുക. എന്നാൽ, അവന്റെമേൽ നിങ്ങൾ കൈവയ്ക്കരുത്.","p":1},{"v":23,"t":"അതിനാൽ, ജോസഫ് തന്റെ സഹോദരന്മാരുടെ അടുത്തെത്തിയപ്പോൾ, അവർ ജോസഫിൽനിന്ന് അവന്റെ അങ്കി - അവന്റെ മേലുണ്ടായിരുന്ന കൈനീളൻ അങ്കിതന്നെ - ഊരിയെടുത്തു.","p":1},{"v":24,"t":"എന്നിട്ട് അവർ അവനെ എടുത്ത് ആ കുഴിയിലേക്കെറിഞ്ഞു. അതു വെള്ളമില്ലാത്ത പൊട്ടക്കിണറായിരുന്നു.","p":1},{"v":25,"t":"അവർ ഭക്ഷണം കഴിക്കാനിരുന്നപ്പോൾ തങ്ങളുടെ കണ്ണുകളുയർത്തി നോക്കി. അപ്പോൾ അതാ, ഗിലയാദിൽനിന്ന് ഇസ്മായേല്യരുടെ ഒരു കച്ചവട സംഘം വരുന്നു. തങ്ങളുടെ ഒട്ടകങ്ങൾ സംവഹിച്ചിരുന്ന സുഗന്ധപശയും പരിമള ദ്രവ്യങ്ങളും കുന്തിരുക്കവും ഈജിപ്തിലേക്ക് കൊണ്ടുപോകാനായി അവർ നടന്നു നീങ്ങുകയായിരുന്നു","p":1},{"v":26,"t":"അപ്പോൾ യൂദാ തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: നമ്മുടെ സഹോദരനെ കൊന്ന് അവന്റെ രക്തം നാം മറച്ചുവെച്ചതുകൊണ്ട് എന്തു ലാഭം?","p":1},{"v":27,"t":"വരുവിൻ, നമുക്കവനെ ഇസ്‌മായേല്യർക്കു വിൽക്കാം. നമ്മുടെ കൈ അവനെതിരേ വേണ്ടാ. കാരണം, അവൻ നമ്മുടെ സഹോദരനാണ്, നമ്മുടെതന്നെ മാംസം. അവന്റെ സഹോദരന്മാർ അത് അനുസരിച്ചു.","p":1},{"v":28,"t":"അവർ ജോസഫിനെ കുഴിയിൽനിന്നു വലിച്ചുകയറ്റിയപ്പോഴേക്കും മിദിയാൻകാരായ ആ കച്ചവടക്കാർ കടന്നുവന്നു. ആ ഇസ്‌മായേല്യർക്ക് ഇരുപതു വെള്ളിക്കാശിന് ജോസഫിനെ വിറ്റു. അവർ ജോസഫിനെ ഈജിപ്തിലേക്കു കൊണ്ടുപോയി.","p":1},{"v":29,"t":"കുഴിയുടെ അടുത്തേക്ക് റൂബൻ തിരിച്ചുചെന്നപ്പോൾ അതാ, ജോസഫ് കുഴിയിൽ ഉണ്ടായിരുന്നില്ല. അയാൾ തന്റെ വസ്ത്രം വലിച്ചുകീറി;","p":1},{"v":30,"t":"സഹോദരന്മാരുടെ അടുത്തു മടങ്ങിയെത്തി. അയാൾ പറഞ്ഞു: കുട്ടി അവിടെ ഇല്ലല്ലോ. ഞാൻ, ഞാനിനി എങ്ങോട്ടു പോകും!","p":1},{"v":31,"t":"അവർ ജോസഫിന്റെ അങ്കിയെടുത്തു; ഒരു മുട്ടാടിനെ അറുത്ത്, അങ്കി രക്തത്തിൽ മുക്കി.","p":1},{"v":32,"t":"അവർ കൈനീളൻ അങ്കി കൊടുത്തയച്ചു; അത് അവരുടെ പിതാവിന്റെയടുക്കൽ എത്തിച്ചവർ പറഞ്ഞു: ഇതു ഞങ്ങൾ കണ്ടെത്തി. ഈ കുപ്പായം അങ്ങയുടെ മകന്റേതാണോ അല്ലയോ എന്നു പരിശോധിച്ചാലും.","p":1},{"v":33,"t":"അദ്ദേഹം അതു തിരിച്ചറിഞ്ഞു. അദ്ദേഹം പറഞ്ഞു: എന്റെ മകന്റെ കുപ്പായം! ഏതോ ദുഷ്ടമൃഗം ജോസഫിനെ തീർച്ചയായും കടിച്ചുകീറി തിന്നതുതന്നെ!","p":1},{"v":34,"t":"യാക്കോബ് തന്റെ വസ്ത്രം വലിച്ചുകീറി; അരയിൽ ചാക്കുടുത്തു; വളരെനാൾ തന്റെ മകനെക്കുറിച്ചു വിലപിച്ചു.","p":1},{"v":35,"t":"അദ്ദേഹത്തിന്റെ പുത്രീപുത്രന്മാരെല്ലാവരും അദ്ദേഹത്തെ ആശ്വസിപ്പിക്കാൻ ശ്രമിച്ചു. എന്നാൽ, ആശ്വസിപ്പിക്കപ്പെടാൻ വിസമ്മതിച്ചുകൊണ്ട് അദ്ദേഹം ഇങ്ങനെ പറഞ്ഞു: വിലപിച്ചുകൊണ്ടുതന്നെ എന്റെ മകന്റെയടുത്തേക്ക്, പാതാളത്തിലേക്ക് ഞാൻ ഇറങ്ങും. അദ്ദേഹം തന്റെ മകനെയോർത്തു കരഞ്ഞു.","p":1},{"v":36,"t":"മിദിയാൻകാരാകട്ടെ, അവനെ ഈജിപ്തിൽ ഫറവോയുടെ ഒരു ഉദ്യോഗസ്ഥനും കാവൽപ്പടയുടെ നായകനുമായ പൊത്തിഫറിനു വിറ്റു.","p":1}],"38":[{"v":1,"t":"അക്കാലത്ത് യൂദാ തന്റെ സഹോദരന്മാരിൽ നിന്ന് അകന്ന് ഹീറോ എന്ന് പേരുള്ള ഒരു അദുല്ലാംകാരൻ്റെ അടുത്തേക്ക് ഇറങ്ങിത്തിരിച്ചു","p":1},{"v":2,"t":"യൂദാ അവിടെ ഷുവാ എന്നു പേരുള്ള ഒരു കാനാൻകാരന്റെ മകളെ കണ്ടു. അവളെ അവൻ സ്വന്തമാക്കി, അവളെ പ്രാപിച്ചു.","p":1},{"v":3,"t":"അവൾ ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അയാൾ അവൻ ഏർ എന്നു പേരിട്ടു.","p":1},{"v":4,"t":"അവൾ വീണ്ടും ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ അവന് ഓനാൻ എന്നു പേരിട്ടു.","p":1},{"v":5,"t":"അതെത്തുടർന്ന് അവൾ വീണ്ടും ഒരു മകനെ പ്രസവിച്ചു. അവൾ അവന് ഷേലാ എന്നു പേരിട്ടു. അവൾ അവനെ പ്രസവിക്കുമ്പോൾ അയാൾ കെസീബിൽ ആയിരുന്നു.","p":1},{"v":6,"t":"യൂദാ തന്റെ കടിഞ്ഞൂൽപുത്രനായ ഏറിനുവേണ്ടി ഒരു ഭാര്യയെ കൊണ്ടുവന്നു. താമാർ എന്നായിരുന്നു അവളുടെ പേര്.","p":1},{"v":7,"t":"എന്നാൽ, യൂദായുടെ കടിഞ്ഞൂൽപുത്രനായ ഏർ കർത്താവിന്റെ മുൻപിൽ ദുഷിച്ചവനാനായിരുന്നു. കർത്താവ് അവനെ മരണത്തിനിരയാക്കി.","p":1},{"v":8,"t":"അപ്പോൾ യൂദാ ഓനാനോട് പറഞ്ഞു: നിന്റെ സഹോദരന്റെ ഭാര്യയെ പ്രാപിച്ച് അവൾക്കു പ്രതിഭർത്താവായി നിന്റെ സഹോദരനുവേണ്ടി സന്താനത്തെ വളർത്തുക.","p":1},{"v":9,"t":"സന്തതി തന്റേതായിരിക്കില്ലെന്ന് അറിയാമായിരുന്ന ഓനാൻ തന്റെ സഹോദരനു സന്താനത്തെ നൽകാതിരിക്കാൻ, തന്റെ സഹോദരഭാര്യയെ പ്രാപിച്ചപ്പോൾ നിലത്തേക്ക് ബീജം സ്രവിപ്പിച്ചു.","p":1},{"v":10,"t":"അവൻ ചെയ്തത് കർത്താവിന്റെ ദൃഷ്ടികളിൽ തിന്മയായിരുന്നു; അവനെയും അവിടുന്ന് മരണത്തിനിരയാക്കി.","p":1},{"v":11,"t":"അപ്പോൾ യൂദാ തന്റെ മരുമകളായ താമാറിനോടു പറഞ്ഞു: എന്റെ മകൻ ഷേലാ വളരുന്നതുവരെ നിന്റെ പിതാവിന്റെ വീട്ടിൽ ഒരു വിധവയായി പാർക്കുക. എന്തെന്നാൽ, അവൻ ആത്മഗതംചെയ്തു: സഹോദരന്മാരെപ്പോലെ ഇവനും മരിക്കരുതല്ലോ! താമാർ പോയി തന്റെ പിതാവിന്റെ വീട്ടിൽ താമസിച്ചു.","p":1},{"v":12,"t":"നാളുകളേറെക്കഴിഞ്ഞപ്പോൾ യൂദായുടെ ഭാര്യ, ഷുവായുടെ മകൾ, മരിച്ചു. ദുഃഖാചരണകാലം കഴിഞ്ഞ് യൂദാ തന്റെ സുഹൃത്ത് അതുല്ലാംകാരൻ ഹീറായുടെകൂടെ തിമ്നായിലേക്ക്, തന്റെ ആടുകളുടെ രോമം കത്രിക്കുന്നവരുടെ അടുത്തേക്കുപോയി.","p":1},{"v":13,"t":"ആരോ താമാറിനെ ഇപ്രകാരം അറിയിച്ചു: അതാ, നിന്റെ അമ്മായിയപ്പൻ തന്റെ ആടുകളുടെ രോമംമുറിക്കാൻ തിമ്നായിലേക്കു പോകുന്നുണ്ട്.","p":1},{"v":14,"t":"ഷേലാ വളർന്നിട്ടും അവന് അവൾ ഭാര്യയായി നൽകപ്പെട്ടില്ല എന്നു കണ്ട് അവൾ തന്റെമേലുണ്ടായിരുന്ന വിധവാവസ്ത്രങ്ങൾ മാറ്റി, ഒരു മൂടുപടംകൊണ്ടു മൂടി. സ്വയംമറച്ച് അവൾ തിമ്നായിലേക്കുള്ള വഴിയിൽ എനായീംകവാടത്തിങ്കൽ ഇരുന്നു.","p":1},{"v":15,"t":"യൂദാ അവളെ കണ്ടു. അവൾ മുഖം മൂടി യിരുന്നതുകൊണ്ട് അവളെ ഒരു വേശ്യയായി അവൻ കരുതി.","p":1},{"v":16,"t":"വഴിയിലേക്ക്, അവളുടെനേർക്കു കുനിഞ്ഞ് അവൻ പറഞ്ഞു: വന്നാലും, ഞാൻ നിന്നെ പ്രാപിക്കട്ടെ. തന്റെ മരുമകളാണ് അവളെന്ന് അവൻ അറിഞ്ഞില്ല. അവൾ ചോദിച്ചു: താങ്കൾ എന്നെ പ്രാപിക്കുന്നതിന് എനിക്ക് എന്തുതരും?","p":1},{"v":17,"t":"അവൻ പറഞ്ഞു: ആട്ടിൻകൂട്ടത്തിൽനിന്ന് ഒരു ആട്ടിൻകുട്ടിയെ ഞാൻ കൊടുത്തയയ്ക്കാം. അവൾ ചോദിച്ചു: താങ്കൾ കൊടുത്തയയ്ക്കുന്നതുവരെ ഒരു ഈടുതരുമോ?","p":1},{"v":18,"t":"അവൻ ചോദിച്ചു: ഞാൻ നിനക്കു തരേണ്ട ഈട് എന്താണ്? അവൾ പറഞ്ഞു: താങ്കളുടെ മുദ്രമോതിരവും വളയും കയ്യിലെ വടിയും. അവൾക്ക് അവൻ അവ കൊടുക്കുകയും അവളെ പ്രാപിക്കുകയുംചെയ്തു. അങ്ങനെ അവൾ അവനിൽനിന്നു ഗർഭംധരിച്ചു.","p":1},{"v":19,"t":"അവൾ എഴുന്നേറ്റുപോയി, തന്റെമേലുണ്ടായിരുന്ന മൂടുപടം മാറ്റി വിധവാവസ്ത്രങ്ങൾ ധരിച്ചു.","p":1},{"v":20,"t":"താൻ ഈടുകൊടുത്തവ ആ സ്ത്രീയുടെ കയ്യിൽനിന്നു തിരിച്ചുഎടുക്കാൻ, അതുല്ലാംകാരനായ തന്റെ സ്നേഹിതന്റെ കയ്യിൽ യൂദാ ഒരു ആട്ടിൻകുട്ടിയെ കൊടുത്തയച്ചു. എന്നാൽ, അവളെ അവൻ കണ്ടെത്തിയില്ല.","p":1},{"v":21,"t":"അവൻ അവളുടെ സ്ഥലത്തെ ആളുകളോട് ഇപ്രകാരം അന്വേഷിച്ചു: എനായിമിലെ വഴിവക്കിലുണ്ടായിരുന്ന വേശ്യ എവിടെ? അവർ പറഞ്ഞു: ഇവിടെ ഒരു വേശ്യയുണ്ടായിരുന്നില്ല.","p":1},{"v":22,"t":"അവൻ യൂദായുടെ പക്കൽ തിരിച്ചുചെന്നു പറഞ്ഞു: ഞാൻ അവളെ കണ്ടെത്തിയില്ല. അവിടെ ഒരു വേശ്യയുണ്ടായിരുന്നില്ല എന്നാണ് അവിടുത്തെ ആളുകൾ പറഞ്ഞത്.","p":1},{"v":23,"t":"യൂദാ പറഞ്ഞു: അവൾ അവ സ്വന്തമായി എടുത്തുകൊള്ളട്ടെ. നമ്മൾ പരിഹാസ്യരാകരുതല്ലോ. ഇതാ, ഞാൻ ഈ ആട്ടിൻകുട്ടിയെ കൊടുത്തയച്ചു. നീയാകട്ടെ, അവളെ കണ്ടെത്തിയുമില്ല.","p":1},{"v":24,"t":"ഏകദേശം മൂന്നുമാസം കഴിഞ്ഞപ്പോൾ, യൂദായ്ക്ക് ഇപ്രകാരം അറിയിപ്പുകിട്ടി: നിന്റെ മരുമകൾ താമാർ വേശ്യാവൃത്തിനടത്തി. മാത്രമല്ല, അവളിപ്പോൾ വേശ്യാവൃത്തിയിലൂടെ ഗർഭിണിയുമാണ്.","p":1},{"v":25,"t":"അപ്പോൾ യൂദാ പറഞ്ഞു: അവളെ പുറത്തിറക്കുക, അവൾ ദഹിപ്പിക്കപ്പെടട്ടെ! അവളെ പുറത്തുകൊണ്ടുവന്നപ്പോൾ അവൾ, ഇവ ആരുടേതാണോ അയാളിലൂടെയാണ് ഞാൻ ഗർഭിണിയായത് എന്ന് തന്റെ അമ്മായിയപ്പനോടു പറയാനായി ആളയച്ചു. അവൾ പറഞ്ഞു: ദയചെയ്ത്, ഈ മുദ്രമോതിരവും വളയും വടിയും ആരുടേതെന്നു തിരിച്ചറിഞ്ഞാലും.","p":1},{"v":26,"t":"അവ തിരിച്ചറിഞ്ഞിട്ട് യൂദാ പറഞ്ഞു: അവൾ എന്നെക്കാൾ നീതിമതിയാണ്. ഞാൻ അവളെ എന്റെ മകൻ ഷേലായ്ക്കു കൊടുത്തില്ലെന്നതുതന്നെ കാരണം. അവൻ. അവളെ പിന്നീട് ഒരിക്കലും അറിഞ്ഞില്ല.","p":1},{"v":27,"t":"അവളുടെ പ്രസവത്തിന്റെ സമയത്ത് അവളുടെ ഉദരത്തിൽ ഇതാ, ഇരട്ടകൾ!","p":1},{"v":28,"t":"അവൾ പ്രസവിക്കവേ, ഒരുത്തൻ ഒരു കൈ നീട്ടി. ഇവൻ ആദ്യം പുറത്തുവന്നു എന്നു പറഞ്ഞുകൊണ്ട് സൂതികർമിണി പിടിച്ച് അവന്റെ കൈയിൽ ചുവന്ന ഒരു ചരട് കെട്ടി.","p":1},{"v":29,"t":"അവൻ തന്റെ കൈ പിൻവലിച്ചപ്പോൾ അതാ, അവന്റെ സഹോദരൻ പുറത്തുവന്നു. നീ എങ്ങനെ നിനക്കൊരു വഴി ഭേദിച്ചുണ്ടാക്കി എന്നു ചോദിച്ചുകൊണ്ട് അവൾ അവന് പേരെസ് എന്നു പേരിട്ടു.","p":1},{"v":30,"t":"പിന്നീട് കൈയിൽ ചുവന്ന ചരടുള്ള അവന്റെ സഹോദരൻ പുറത്തുവന്നു. അവന് സേറഹ് എന്നു പേരിട്ടു.","p":1}],"39":[{"v":1,"t":"ജോസഫ് ഈജിപ്തിലേക്ക് നയിക്കപ്പെട്ടു. അവനെ അവിടേക്കു കൊണ്ടുവന്ന ഇസ്‌മായേല്യരുടെ കൈയിൽനിന്ന് ഫറവോയുടെ ഉദ്യോഗസ്ഥനും കാവൽപ്പടയുടെ നായകനുമായ പൊത്തിഫർ എന്ന ഈജിപ്തുകാരൻ അവനെ വാങ്ങി.","p":1},{"v":2,"t":"കർത്താവ് ജോസഫിന്റെകൂടെ ഉണ്ടായിരുന്നു. അവൻ ഐശ്വര്യവാനായിരുന്നു. ഈജിപ്തുകാരനായ തന്റെ യജമാനന്റെ വീട്ടിലായിരുന്നു അവൻ.","p":1},{"v":3,"t":"കർത്താവ് അവന്റെകൂടെ ഉണ്ടെന്നും അവൻ ചെയ്യുന്നതെല്ലാം കർത്താവ് അവന്റെ കരംവഴി മംഗളകരമാക്കുന്നു എന്നും അവന്റെ യജമാനൻ കണ്ടു.","p":1},{"v":4,"t":"ജോസഫ് അയാളുടെ ദൃഷ്ടികളിൽ പ്രീതികണ്ടെത്തി. അവൻ അയാളെ ശുശ്രൂഷിച്ചു. അയാൾ അവനെ തന്റെ ഭവനത്തിന്റെമേൽ നിയോഗിക്കുകയും തനിക്കുള്ളതെല്ലാം അവന്റെ കൈയിൽ ഏൽപ്പിക്കുകയും ചെയ്തു.","p":1},{"v":5,"t":"ജോസഫിനെ ആ ഈജിപ്തുകാരൻ തന്റെ വീട്ടിലും തനിക്കുള്ള എല്ലാറ്റിൻമേലും ചുമതലപ്പെടുത്തിയപ്പോൾമുതൽ അവനെപ്രതി കർത്താവ് അയാളുടെ ഭവനത്തെ അനുഗ്രഹിച്ചു. അയാളുടെ വീട്ടിലും വയലിലുമായി അയാൾക്കുണ്ടായിരുന്ന എല്ലാറ്റിലും കർത്താവിന്റെ അനുഗ്രഹമുണ്ടായി.","p":1},{"v":6,"t":"അയാൾ തനിക്കുണ്ടായിരുന്നതെല്ലാം ജോസഫിന്റെ കൈയിലാണ് വിട്ടുകൊടുത്തിരുന്നത്. താൻ കഴിക്കുന്ന ഭക്ഷണത്തെക്കുറിച്ചല്ലാതെ, തന്നോടൊപ്പമുണ്ടായിരുന്ന മറ്റൊന്നിനെക്കുറിച്ചും അയാൾ ശ്രദ്ധിച്ചിരുന്നില്ല. ജോസഫ് രൂപഭംഗിയുള്ളവനും കാഴ്ചയ്ക്കു സുന്ദരനുമായിരുന്നു.","p":1},{"v":7,"t":"കുറച്ചുനാൾ കഴിഞ്ഞപ്പോൾ അവന്റെ യജമാനന്റെ ഭാര്യ ജോസഫിൽ നോട്ടമിട്ടു. അവൾ പറഞ്ഞു: എന്റെകൂടെ ശയിക്കുക.","p":1},{"v":8,"t":"പക്ഷേ, അവൻ വഴങ്ങിയില്ല. അവൻ തന്റെ യജമാനന്റെ ഭാര്യയോടു പറഞ്ഞു: നോക്കൂ, ഞാൻ ഉള്ളതുകൊണ്ട് എന്റെ യജമാനൻ വീട്ടിലുള്ള ഒന്നിനെക്കുറിച്ചും ശ്രദ്ധിക്കാറില്ല. അദ്ദേഹത്തിനുള്ളതെല്ലാം എന്റെ കൈയിൽ അദ്ദേഹം ഏൽപ്പിച്ചിരിക്കുകയാണ്.","p":1},{"v":9,"t":"എന്നെക്കാൾ വലിയവനായി ആരും ഈ ഭവനത്തിലില്ല. നിങ്ങളെയല്ലാതെ, മറ്റൊന്നും അദ്ദേഹം എന്നിൽനിന്നു മാറ്റി നിർത്തിയിട്ടില്ല. അതു നിങ്ങൾ അദ്ദേഹത്തിന്റെ ഭാര്യയായതുകൊണ്ടാണ്. ഞാൻ എങ്ങനെയാണ് ഈ വലിയ തിന്മ പ്രവർത്തിച്ച് ദൈവത്തിനെതിരെ പാപം ചെയ്യുന്നത്?","p":1},{"v":10,"t":"അനുദിനം അവൾ ജോസഫിനോട് ഇവിധം പറഞ്ഞുകൊണ്ടിരുന്നെങ്കിലും അവളോടുകൂടെ ശയിക്കുന്നതിലോ അവളോടൊപ്പം ആയിരിക്കുന്നതിലോ അവൻ അവളെ അനുസരിച്ചില്ല.","p":1},{"v":11,"t":"അങ്ങനെയിരിക്കേ, ഒരു ദിവസം അവൻ തന്റെ ജോലിചെയ്യാനായി വീട്ടിലേക്കു വന്നു. വീട്ടുകാരആരും അവിടെ, വീട്ടിലില്ലായിരുന്നു.","p":1},{"v":12,"t":"അപ്പോൾ, എന്റെകൂടെ ശയിക്കുക എന്നു പറഞ്ഞുകൊണ്ട് അവനെ അവൾ അവന്റെ മേലങ്കിയിൽ കടന്നുപിടിച്ചു. എന്നാൽ, തന്റെ മേലങ്കി അവളുടെ കൈയിൽ വിട്ടിട്ട് അവൻ പുറത്തേക്ക് ഓടിപ്പോയി.","p":1},{"v":13,"t":"അവന്റെ കുപ്പായം തന്റെ കൈയിൽ വിട്ടിട്ട് അവൻ പുറത്തേക്ക് ഓടിപ്പോയെന്നു കണ്ടപ്പോൾ,","p":1},{"v":14,"t":"അവൾ തന്റെ ഭവനാംഗങ്ങളെ വിളിച്ച് അവരോടു പറഞ്ഞു: നോക്കൂ, നമ്മെ അപമാനിക്കാൻ ഒരു ഹെബ്രായനെ അദ്ദേഹം നമുക്കായി കൊണ്ടുവന്നിരിക്കുന്നു! എന്നോടൊത്തു ശയിക്കാൻ അവൻ എന്നെ സമീപിച്ചു. എന്നാൽ ഞാൻ വലിയ സ്വരത്തിൽ അലറി.","p":1},{"v":15,"t":"ഞാൻ സ്വരമുയർത്തുന്നതും അലറിവിളിക്കുന്നതും കേട്ടപ്പോൾ അവൻ തന്റെ മേലങ്കി എന്റെയരികിൽ ഉപേക്ഷിച്ചിട്ട് പുറത്തേക്കുകടന്നു രക്ഷപ്പെട്ടു.","p":1},{"v":16,"t":"അവന്റെ യജമാനൻ വീട്ടിലേക്കു വരുവോളം അവൾ ആ കുപ്പായം തന്റെപക്കൽ സൂക്ഷിച്ചു.","p":1},{"v":17,"t":"അവൾ അവനോട് അതേകാര്യങ്ങൾ ഇപ്രകാരം പറഞ്ഞു: അങ്ങ് നമുക്കായി കൊണ്ടുവന്ന ആ ഹെബ്രായാദാസൻ എന്നോടു ശൃംഗരിക്കാൻ വന്നു.","p":1},{"v":18,"t":"എന്നാൽ, ഞാൻ സ്വരമുയർത്തുകയും അലറിവിളിക്കുകയും ചെയ്തപ്പോൾ അവൻ തന്റെ മേലങ്കി എന്റെ അരികിൽ ഉപേക്ഷിച്ചിട്ട് പുറത്തേക്ക് ഓടിപ്പോയി.","p":1},{"v":19,"t":"ഇപ്രകാരമുള്ള കാര്യങ്ങളാണ് അങ്ങയുടെ ദാസൻ എന്നോടു ചെയ്തത് എന്നു ഭാര്യ തന്നോടു പറഞ്ഞ വാക്കുകൾ അവന്റെ യജമാനൻ കേട്ടപ്പോൾ അയാളുടെ കോപം ജ്വലിച്ചു.","p":1},{"v":20,"t":"ജോസഫിന്റെ യജമാനൻ അവനെ പിടിച്ച്, രാജാവിന്റെ തടവുകാരെ ബന്ധിച്ചിരുന്ന സ്ഥലത്ത് കാരാഗൃഹത്തിലാക്കി. അങ്ങനെ അവൻ അവിടെ കാരാഗൃഹത്തിലായി.","p":1},{"v":21,"t":"കർത്താവ് ജോസഫിന്റെ കൂടെയുണ്ടായിരുന്നു. അവിടുന്ന് അവനോടു കാരുണ്യം കാണിച്ചു; അവന് കാരാഗൃഹാധിപന്റെ ദൃഷ്ടികളിൽ അവിടുന്ന് പ്രീതി നൽകുകയും ചെയ്തു.","p":1},{"v":22,"t":"കാരാഗൃഹത്തിലുണ്ടായിരുന്ന തടവുകാരെയെല്ലാം കാരാഗൃഹാധിപൻ ജോസഫിന്റെ കയ്യിലേൽപ്പിച്ചു; അവിടെയുള്ള എല്ലാ തൊഴിലാടപാടുകളും അവനാണ് ചെയ്തിരുന്നത്.","p":1},{"v":23,"t":"അവൻ കൈകാര്യം ചെയ്ത ഒന്നിനും കാരാഗൃഹാധിപന്റെ മേൽനോട്ടം വേണ്ടി വന്നില്ല; കാരണം, അവന്റെ കൂടെ കർത്താവ് ഉണ്ടായിരുന്നു. അവൻ ചെയ്യുന്നത് കർത്താവു ശുഭമാക്കിയിരുന്നു.","p":1}],"40":[{"h":"തടവുകാരുടെ സ്വപ്നങ്ങൾ"},{"v":1,"t":"കുറച്ചുനാൾ കഴിഞ്ഞ്, ഈജിപ്തുരാജാവിന്റെ പാനപാത്രവാഹകനും പാചകക്കാരനും തങ്ങളുടെ യജമാനനായ ഈജിപ്തുരാജാവിനെതിരേ തെറ്റുചെയ്തു.","p":1},{"v":2,"t":"ഫറവോ തന്റെ രണ്ട് ഉദ്യോഗസ്ഥരോട്, പാനപാത്രവാഹക പ്രമാണിയോടും പാചക പ്രമാണിയോടും, കുപിതനായി.","p":1},{"v":3,"t":"അദ്ദേഹം അവരെ കാവൽപ്പടനായകന്റെ വീട്ടിലെ തടങ്കലിൽ, ജോസഫ് തടവിലാക്കപ്പെട്ടിരുന്നിടമായ കാരാഗൃഹത്തിൽ, അടച്ചു.","p":1},{"v":4,"t":"കാവൽപ്പടനായകൻ ജോസഫിനെ അവരോടുകൂടെ ആക്കി. അവൻ അവരെ പരിചരിച്ചു. ദിവസങ്ങളോളം അവർ തടങ്കലിലായിരുന്നു.","p":1},{"v":5,"t":"കാരാഗൃഹത്തിൽ തടവുകാരായിരുന്ന അവരിരുവരും, ഈജിപ്തുരാജാവിന്റെ പാനപാത്രവാഹകനും പാചക്കാരനും, ഒരു രാത്രിയിൽ അതതിന്റെ വ്യാഖ്യാനമുള്ള ഓരോ സ്വപ്നം കണ്ടു.","p":1},{"v":6,"t":"ജോസഫ് രാവിലെ അവരുടെയടുക്കൽ ചെന്ന് അവരെ കണ്ടു. ഇതാ, അവർ വിഷാദമൂകരായിരുന്നു.","p":1},{"v":7,"t":"തന്നോടൊപ്പം തന്റെ യജമാനന്റെ വീട്ടിലെ തടങ്കലിൽ കഴിയുന്നവരും ഫറവോയുടെ ഉദ്യോഗസ്ഥരുമായ അവരോട് അവൻ ഇപ്രകാരം ആരാഞ്ഞു: ഇന്നെന്താ നിങ്ങളുടെ മുഖം മ്ലാനമായിരിക്കുന്നത്?","p":1},{"v":8,"t":"അവർ അവനോടു പറഞ്ഞു: ഞങ്ങൾ സ്വപ്നം കണ്ടു; അതു വ്യാഖ്യാനിക്കാൻ ആരുമില്ല. ജോസഫ് അവരോടു പറഞ്ഞു: വ്യാഖ്യാനങ്ങൾ ദൈവത്തിന്റേതല്ലേ? എന്നോടു വിവരിച്ചാലും!","p":1},{"v":9,"t":"പാനപാത്രവാഹകപ്രമാണി തന്റെ സ്വപ്നം ജോസഫിനോടു വിവരിച്ചു. അയാൾ അവനോടു പറഞ്ഞു: എന്റെ സ്വപ്നത്തിൽ ഇതാ, എന്റെ മുൻപിൽ ഒരു മുന്തിരിച്ചെടി!","p":1},{"v":10,"t":"മുന്തിരിച്ചെടിയിൽ മൂന്നു ശാഖകൾ! അതു മൊട്ടിട്ട ഉടനെ പുഷ്പിച്ച് അതിന്റെ കുലകളിൽ മുന്തിരിപ്പഴങ്ങൾ പാകമായി.","p":1},{"v":11,"t":"ഫറവോയുടെ പാനപാത്രം എന്റെ കയ്യിൽ ഉണ്ടായിരുന്നു. ഞാൻ മുന്തിരിപ്പഴങ്ങളെടുത്ത് അവ ഫറവോയുടെ പാനപാത്രത്തിലേക്കു പിഴിഞ്ഞു. എന്നിട്ട് പാനപാത്രം ഫറവോയുടെ കയ്യിൽ കൊടുത്തു.","p":1},{"v":12,"t":"ജോസഫ് അയാളോടു പറഞ്ഞു: അതിന്റെ വ്യാഖ്യാനം ഇതാണ്: മൂന്നു ശാഖകൾ മൂന്നു ദിവസങ്ങളാണ്.","p":1},{"v":13,"t":"മൂന്നു ദിവസത്തിനകം ഫറവോ താങ്കളുടെ ശിരസ്സുയർത്തും; താങ്കളെ ഉദ്യോഗത്തിൽ പുനഃസ്ഥാപിക്കും. അദ്ദേഹത്തിന്റെ പാനപാത്രവാഹകനായിരുന്ന മുൻപത്തെ രീതിയനുസരിച്ചുതന്നെ, ഫറവോയുടെ പാനപാത്രം താങ്കൾ അദ്ദേഹത്തിന്റെ കയ്യിൽ കൊടുക്കും.","p":1},{"v":14,"t":"താങ്കൾക്കു ശ്രേയസ്സുണ്ടാകുമ്പോൾ താങ്കളോടൊപ്പം എന്നെയും ഓർത്ത് എന്നോടു കാരുണ്യം കാണിച്ചാലും! എന്നെപ്പറ്റി ഫറവോയെ ഓർമ്മിപ്പിക്കുകയും ഈ ഭവനത്തിൽനിന്ന് എന്നെ പുറത്തുകൊണ്ടുവരികയും ചെയ്യണം.","p":1},{"v":15,"t":"എന്തെന്നാൽ, സത്യത്തിൽ ഹെബ്രായരുടെ നാട്ടിൽനിന്ന് തട്ടിയെടുക്കപ്പെട്ടവനാണു ഞാൻ. ഇവിടെയും ഞാൻ ഒന്നും ചെയ്തിട്ടില്ല, അവരെന്നെ ഈ കുഴിയിൽ ഇട്ടിരിക്കുന്നത്.","p":1},{"v":16,"t":"വ്യാഖ്യാനം നന്നായിരിക്കുന്നെന്ന് പാചകപ്രമാണി കണ്ടു. അയാൾ ജോസഫിനോടു പറഞ്ഞു: ഞാനും എന്റെ സ്വപ്നത്തിൽ ആയിരുന്നപ്പോൾ ഇതാ, എന്റെ തലയിൽ മൂന്നു കുട്ട നിറയെ അപ്പം!","p":1},{"v":17,"t":"ഏറ്റവും മുകളിലെ കുട്ടയിൽ, പാചകക്കാരൻ ഫറവോയ്ക്കു വേണ്ടി തയ്യാറാക്കിയ എല്ലാത്തരം ഭക്ഷണവുമുണ്ടായിരുന്നു. എന്നാൽ, എന്റെ തലയിലെ കുട്ടയിൽനിന്ന് പക്ഷിക്കൂട്ടം അവ കൊത്തിത്തിന്നുകൊണ്ടിരുന്നു.","p":1},{"v":18,"t":"അപ്പോൾ ജോസഫ് മറുപടിയായി പറഞ്ഞു, അതിന്റെ വ്യാഖ്യാനം ഇതാണ്: മൂന്നു കുട്ടകൾ മൂന്നു ദിവസങ്ങൾതന്നെ.","p":1},{"v":19,"t":"മൂന്നു ദിവസത്തിനകം ഫറവോ നിന്റെ ശിരസ്സ് നിന്റെമേൽനിന്ന് ഉയർത്തും; നിന്നെ മരത്തിൽ കെട്ടിത്തൂക്കും. പക്ഷിക്കൂട്ടം നിന്റെമേൽനിന്ന് നിന്റെ മാംസം തിന്നുകയും ചെയ്യും.","p":1},{"v":20,"t":"മൂന്നാംദിവസം ഫറവോയുടെ പിറന്നാളായിരുന്നു. തന്റെ എല്ലാ ദാസർക്കുമായി അദ്ദേഹം ഒരു വിരുന്നൊരുക്കി. പാനപാത്രവാഹകപ്രമാണിയുടെ ശിരസ്സും പാചകപ്രമാണിയുടെ ശിരസ്സും തന്റെ ദാസർക്കിടയിൽ അദ്ദേഹം ഉയർത്തി.","p":1},{"v":21,"t":"പാനപാത്രവാഹകപ്രമാണിയെ തന്റെ പാനപാത്രവാഹകസ്ഥാനത്ത് അദ്ദേഹം തിരിയെ നിയമിച്ചു; അയാൾ പാനപാത്രം ഫറവോയുടെ കയ്യിൽ കൊടുത്തു.","p":1},{"v":22,"t":"എന്നാൽ, പാചകപ്രമാണിയെ അദ്ദേഹം തൂക്കിക്കൊന്നു. അത് ജോസഫ് അവരോടു വ്യാഖ്യാനിച്ചതുപോലെതന്നെ ആയിരുന്നു.","p":1},{"v":23,"t":"എന്നാൽ, പാനപാത്രവാഹകപ്രമാണി ജോസഫിനെ ഓർമ്മിച്ചില്ല; അയാൾ അവനെ മറന്നുകളഞ്ഞു.","p":1}],"41":[{"h":"ഫറവോയുടെ സ്വപ്നം"},{"v":1,"t":"രണ്ടുവർഷക്കാലം കഴിഞ്ഞപ്പോൾ, ഫറവോ ഒരു സ്വപ്നം കണ്ടു: ഇതാ, അദ്ദേഹം നൈൽതീരത്തു നിൽക്കുന്നു.","p":1},{"v":2,"t":"അപ്പോഴതാ, കാഴ്ചയ്ക്ക് അഴകുള്ള, ശരീരക്കൊഴുത്ത, ഏഴു പശുക്കൾ നദിയിൽനിന്നു കയറിവരുന്നു; അവ ഞാങ്ങണമധ്യേ മേയുന്നു.","p":1},{"v":3,"t":"അതിനുപിന്നാലെ ഇതാ, കാഴ്ചയ്ക്കു വിരൂപമായ, ശരീരമെലിഞ്ഞ, വേറെ ഏഴു പശുക്കൾ നദിയിൽനിന്നു കയറിവരുന്നു; നദിതീരത്ത് അവ മറ്റു പശുക്കളുടെ അരികിൽ വന്നുനിൽക്കുന്നു.","p":1},{"v":4,"t":"എന്നിട്ട് കാഴ്ചയ്ക്കു വിരൂപമായ, ശരീരമെലിഞ്ഞ പശുക്കൾ കാഴ്ചയ്ക്ക് അഴകുള്ള, കൊഴുത്ത ഏഴു പശുക്കളെ വിഴുങ്ങിക്കളയുന്നു. അപ്പോൾ ഫറവോ ഉണർന്നു.","p":1},{"v":5,"t":"അദ്ദേഹം രണ്ടാമതും ഉറങ്ങുകയും സ്വപ്നംകാണുകയും ചെയ്തു: ഇതാ, പുഷ്ടിയും അഴകുമുള്ള ഏഴു ധാന്യക്കതിരുകൾ ഒരേ തണ്ടിൽ വളർന്നുപൊങ്ങുന്നു.","p":1},{"v":6,"t":"അവയ്ക്കു പിന്നാലെ അതാ, ശുഷ്കിച്ചതും കിഴക്കൻകാറ്റിൽ ഉണങ്ങിക്കരിഞ്ഞതുമായ ഏഴു കതിരുകൾകൂടി മുളച്ചുപൊങ്ങുന്നു.","p":1},{"v":7,"t":"ശോഷിച്ച ഏഴു കതിരുകൾ പുഷ്ടിയും സമൃദ്ധിയുമുള്ള കതിരുകളെ വിഴുങ്ങുന്നു. ഫറവോ ഉറക്കമുണർന്നപ്പോൾ, ഇതാ, സ്വപ്നംമാത്രം!","p":1},{"v":8,"t":"പ്രഭാതമായപ്പോൾ അദ്ദേഹത്തിന്റെ ആത്മാവ് അസ്വസ്ഥമായി. ഈജിപ്തിലെ എല്ലാ മന്ത്രവാദികളെയും അവിടുത്തെ എല്ലാ ജ്ഞാനികളെയും ആളയച്ചു വിളിച്ച് ഫറവോ തന്റെ സ്വപ്നം അവരോടു വിവരിച്ചു. എന്നാൽ, ഫറവോയ്ക്ക് അവ വ്യാഖ്യാനിച്ചുകൊടുക്കാൻ ആരുമുണ്ടായില്ല.","p":1},{"v":9,"t":"അപ്പോൾ പാനപാത്രവാഹകപ്രമാണി ഫറവോയോട് ഇപ്രകാരം പറഞ്ഞു: എന്റെ തെറ്റുകൾ ഇന്ന് ഞാൻ ഓർക്കാൻ ഇടയാകുന്നു.","p":1},{"v":10,"t":"ഫറവോ തന്റെ ദാസന്മാരോടു കുപിതനായപ്പോൾ എന്നെയും പാചകപ്രമാണിയെയും കാവൽസേനാനായകന്റെ വീട്ടിലെ തടങ്കലിൽ ഇട്ടിരുന്നല്ലോ.","p":1},{"v":11,"t":"ഒരു രാത്രി ഞാനും അവനും സ്വപ്നം കണ്ടു; വ്യാഖ്യാനം സംബന്ധിച്ച് വ്യത്യസ്തയുള്ള ഓരോ സ്വപ്നമാണ് ഞങ്ങൾ കണ്ടത്.","p":1},{"v":12,"t":"അവിടെ കാവൽസേനാനായകന്റെ ദാസനായ ഒരു ഹെബ്രായാ യുവാവ് ഞങ്ങളുടെകൂടെ ഉണ്ടായിരുന്നു. ഞങ്ങളുടെ സ്വപ്നങ്ങൾ അവനോടു വിവരിച്ചപ്പോൾ അവൻ ഞങ്ങൾക്ക് അവ വ്യാഖ്യാനിച്ചുതന്നു; ഓരോരുത്തരോടും അവനവന്റെ സ്വപ്നത്തിനൊത്താണ് അവൻ വ്യാഖ്യാനിച്ചത്.","p":1},{"v":13,"t":"അവൻ ഞങ്ങൾക്ക് വ്യാഖ്യാനിച്ചുതന്നപോലെതന്നെ സംഭവിച്ചു. എന്നെ എന്റെ ഉദ്യോഗത്തിൽ പുനഃസ്ഥാപിച്ചു; അയാളെ തൂക്കിലിടുകയുംചെയ്തു.","p":1},{"v":14,"t":"അപ്പോൾ ഫറവോ ജോസഫിനെ ആളയച്ചു വിളിച്ചു; അവർ അവനെ കുഴിയിൽനിന്നു തിടുക്കത്തിൽ പുറത്തുകൊണ്ടുവന്നു. അവൻ ക്ഷൗരം ചെയ്ത് തന്റെ വസ്ത്രങ്ങൾമാറി ഫറവോയുടെ പക്കൽ വന്നു.","p":1},{"v":15,"t":"ഫറവോ ജോസഫിനോടു പറഞ്ഞു: ഞാനൊരു സ്വപ്നം കണ്ടു; എന്നാൽ, ആരും അതു വ്യാഖ്യാനിക്കുന്നില്ല. നീ സ്വപ്നം കേട്ടു വ്യാഖ്യാനിക്കാറുണ്ടെന്ന് നിന്നെക്കുറിച്ച് ഞാൻ കേട്ടിരിക്കുന്നു.","p":1},{"v":16,"t":"ജോസഫ് ഫറവോയോട് ഇപ്രകാരം പ്രത്യുത്തരിച്ചു: ഞാനല്ല, ദൈവം ഫറവോയുടെ സമാധാനത്തിന്നുകൂട്ടുന്ന ഉത്തരം നൽകും.","p":1},{"v":17,"t":"ഫറവോ ജോസഫിനോടു പറഞ്ഞു: എന്റെ സ്വപ്നത്തിൽ ഇതാ, ഞാൻ നൈൽതീരത്തു നിൽക്കുകയായിരുന്നു.","p":1},{"v":18,"t":"അപ്പോഴതാ, ശരീരം കൊഴുത്ത, രൂപഭംഗിയുള്ള ഏഴു പശുക്കൾ നദിയിൽനിന്നു കയറിവന്നു; അവ ഞാങ്ങണമധ്യേ മേഞ്ഞു.","p":1},{"v":19,"t":"അവയ്ക്കുപിന്നാലെ ഇതാ, താഴ്ന്നയിനവും തീർത്തും വിരൂപവും ശരീരം മെലിഞ്ഞതുമായ മറ്റ് ഏഴു പശുക്കളും കയറിവന്നു; അവയെപ്പോലെ വികൃതമായവ ഈജിപ്തുനാട്ടിലെങ്ങും ഞാൻ കണ്ടിട്ടില്ല.","p":1},{"v":20,"t":"ശോഷിച്ചു വികൃതമായ ആ പശുക്കൾ ആദ്യത്തെ ഏഴു കൊഴുത്ത പശുക്കളെ വിഴുങ്ങിക്കളഞ്ഞു.","p":1},{"v":21,"t":"എന്നാൽ, അവ അവയുടെ ഉള്ളിലെത്തിയിട്ടും അവ ഉദരത്തിലെത്തിയെന്ന് ആർക്കും തിരിച്ചറിയാൻ കഴിയുമായിരുന്നില്ല; കാരണം, കാഴ്ചയിൽ അവ ആദ്യത്തെപ്പോലെതന്നെ വികൃതമായിരുന്നു. അപ്പോൾ ഞാൻ ഉണർന്നു.","p":1},{"v":22,"t":"വീണ്ടും, എന്റെ സ്വപ്നത്തിൽ ഞാൻ കണ്ടു: ഇതാ, ഒരേ തണ്ടിൽ വളർന്നുനില്ക്കുന്ന പുഷ്ടിയും അഴകുമുള്ള ഏഴു കതിരുകൾ!","p":1},{"v":23,"t":"ഇതാ, അവയ്ക്കുശേഷം മുളച്ചുവരുന്ന ഫലശൂന്യവും ശുഷ്കിച്ചതും കിഴക്കൻകാറ്റിൽ ഉണങ്ങിക്കരിഞ്ഞതുമായ ഏഴു കതിരുകൾ!","p":1},{"v":24,"t":"ശുഷ്കിച്ച കതിരുകൾ ഏഴു നല്ല കതിരുകളെ വിഴുങ്ങിക്കളഞ്ഞു. ഞാൻ മന്ത്രവാദികളോടു പറഞ്ഞു; എന്നാൽ, അത് എനിക്കുവേണ്ടി വിശദീകരിക്കാൻ ആരുമുണ്ടായിരുന്നില്ല.","p":1},{"v":25,"t":"അപ്പോൾ ജോസഫ് ഫറവോയോടു പറഞ്ഞു: ഫറവോയുടെ സ്വപ്നം ഒന്നുതന്നെ! ദൈവം ചെയ്യാൻപോകുന്നതെന്തെന്ന് അവിടുന്ന് ഫറവോയ്ക്കു വെളിപ്പെടുത്തിയിരിക്കുന്നു.","p":1},{"v":26,"t":"ഏഴു നല്ല പശുക്കൾ ഏഴു വർഷങ്ങളാണ്; ഏഴു നല്ല കതിരുകളും ഏഴു വർഷങ്ങൾതന്നെ; സ്വപ്നം ഒന്നുതന്നെ.","p":1},{"v":27,"t":"അവയ്ക്കു പിന്നാലെ കയറിവന്ന മെലിഞ്ഞവയും വിരൂപികളുമായ ഏഴു പശുക്കളും ഏഴു വർഷങ്ങളാണ്. പതിരുനിറഞ്ഞതും കിഴക്കൻകാറ്റിൽ ഉണങ്ങിക്കരിഞ്ഞതുമായ ഏഴു കതിരുകൾ അഞ്ചെട്ടു ഏഴു വർഷങ്ങളാണ്.","p":1},{"v":28,"t":"ഞാൻ ഫറവോയോടു പറഞ്ഞ കാര്യം ഇതാണ്: ദൈവം ചെയ്യാൻപോകുന്നതെന്തെന്ന് അവിടുന്ന് ഫറവോയ്ക്കു കാണിച്ചുതന്നിരിക്കുന്നു.","p":1},{"v":29,"t":"ഇതാ, ഈജിപ്തുനാടു മുഴുവനിലും വൻ സുഭിക്ഷത്തിൻ്റെ ഏഴു വർഷങ്ങളാണു വരുന്നത്.","p":1},{"v":30,"t":"അവയ്ക്കുശേഷം ക്ഷാമത്തിന്റെ ഏഴു വർഷങ്ങൾ ഉയർന്നു വരും; ഈജിപ്തുനാട്ടിലെ സകലസമൃദ്ധിയും വിസ്മൃതമാകും; ക്ഷാമം നാടിനെ കാർന്നെടുക്കും","p":1},{"v":31,"t":"പിന്നാലെ വരുന്ന ആ ക്ഷാമത്തിനു മുമ്പിൽ നാട്ടിലെ സമൃദ്ധി അറിയപ്പെടുകയേയില്ല; കാരണം, അത് അതിരൂക്ഷമായിരിക്കും.","p":1},{"v":32,"t":"ഫറവോയ്ക്ക് സ്വപ്നം തുടർച്ചയായി രണ്ടു തവണ ഉണ്ടായത് ദൈവത്തിന്റെ ഭാഗത്തുനിന്ന് ഇക്കാര്യം ഉറപ്പിച്ചെന്നും ദൈവം അതു നിവർത്തിക്കാൻ തിടുക്കപ്പെടുന്നെന്നും ഉള്ളതുകൊണ്ടാണ്.","p":1},{"v":33,"t":"അതുകൊണ്ട്, ഇപ്പോൾ ഫറവോ വിവേകിയും ബുദ്ധിമാനുമായ ഒരാളെ കണ്ടെത്തി അവനെ ഈജിപ്തുദേശത്തിനുമേൽ നിയമിക്കട്ടെ.","p":1},{"v":34,"t":"രാജ്യത്ത് മേൽനോട്ടക്കാരെ നിയമിച്ച് സമൃദ്ധിയുടെ ഏഴു വർഷങ്ങളിലും ഈജിപ്തുദേശത്തുനിന്ന് അഞ്ചിലൊന്നു ശേഖരിക്കാൻ ഫറവോ നടപടിയെടുക്കട്ടെ.","p":1},{"v":35,"t":"വരാൻപോകുന്ന ഈ നല്ല വർഷങ്ങളുടെ ഭക്ഷ്യവിഭവ മുഴുവൻ അവർ ശേഖരിക്കട്ടെ. ഫറവോയുടെ കരത്തിൻ കീഴിൽ അവർ ഗോതമ്പു സമാഹരിക്കുകയും ഭക്ഷ്യവിഭവം നഗരങ്ങളിൽ സൂക്ഷിച്ചുവെക്കുകയും ചെയ്യട്ടെ.","p":1},{"v":36,"t":"ഈജിപ്തുനാട്ടിൽ ഉണ്ടാകാൻപോകുന്ന ഏഴു ക്ഷാമവർഷങ്ങളിലേക്കുള്ള രാജ്യത്തിന്റെ കരുതൽ ഭക്ഷ്യവിഭവമായിരിക്കും അത്. അങ്ങനെ, നാട് പട്ടിണികൊണ്ടു നശിക്കാതിരിക്കും.","p":1},{"h":"ജോസഫ് ഈജിപ്തിന്റെ മേലുദ്യോഗസ്ഥൻ"},{"v":37,"t":"ഫറവോയുടെ ദൃഷ്ടികളിലും അവന്റെ സേവകരെല്ലാവരുടെയും ദൃഷ്ടികളിലും ഇക്കാര്യം നല്ലതായിരുന്നു.","p":1},{"v":38,"t":"ഫറവോ തന്റെ സേവകരോടു പറഞ്ഞു: ഇവനെപ്പോലെ ദൈവത്തിന്റെ ചൈതന്യം തന്നിലുള്ള ഒരാളെ നമുക്കു കണ്ടെത്താനാകുമോ?","p":1},{"v":39,"t":"എന്നിട്ട് ഫറവോ ജോസഫിനോടു പറഞ്ഞു: ദൈവം നിന്നെ ഇവയെല്ലാം അറിയിച്ചുകഴിഞ്ഞിരിക്കെ, നിന്നെപ്പോലെ ബുദ്ധിമാനും ജ്ഞാനിയുമായി ആരുമില്ല.","p":1},{"v":40,"t":"നീ എന്റെ ഭവനത്തിന് മേലാളനായിരിക്കും എന്റെ ജനം മുഴുവൻ നിൻ്റെ വാക്ക് അനുസരിക്കും സിംഹാസനം സംബന്ധിച്ച് മാത്രം ഞാൻ നിന്നെക്കാൾ വലിയവൻ ആയിരിക്കും","p":1},{"v":41,"t":"ഫറവോ ജോസഫിനോട് തുടർന്ന് പറഞ്ഞു നോക്കൂ ഈജിപ്ത് രാജ്യം മുഴുവന്റെയും മേൽ നിന്നെ ഞാൻ നിയമിച്ചിരിക്കുന്നു","p":1},{"v":42,"t":"ഫറവോ മുദ്രമോതിരം തന്റെ കയ്യിൽനിന്ന് ഊരിയെടുത്ത് ജോസഫിന്റെ കയ്യിലിട്ടുകൊടുത്തു. അവനെ പട്ടുവസ്ത്രങ്ങൾ ധരിപ്പിച്ചു; അവന്റെ കഴുത്തിൽ ഒരു സ്വർണ്ണമാല അണിയിക്കുകയും ചെയ്തു.","p":1},{"v":43,"t":"അദ്ദേഹം തനിക്കുണ്ടായിരുന്ന രണ്ടാം രഥത്തിൽ അവനെ എഴുന്നള്ളിച്ചു. 'അവ്‌റേക്' എന്ന് അവർ അവനുമുമ്പേ വിളിച്ചുപറഞ്ഞുകൊണ്ടിരുന്നു. അങ്ങനെ അദ്ദേഹം അവനെ ഈജിപ്തുരാജ്യം മുഴുവന്റെയുംമേൽ നിയമിച്ചു.","p":1},{"v":44,"t":"ഫറവോ ജോസഫിനോടു പറഞ്ഞു: ഞാൻ ഫറവോയാണ്. നിന്നെക്കൂടാതെ ഈജിപ്തുദേശത്തെങ്ങും ഒരുവനും തന്റെ കയ്യോ കാലോ ഉയർത്തുകയില്ല.","p":1},{"v":45,"t":"ഫറവോ ജോസഫിനെ സാഫ്നത്ത് ഫാനെയ് എന്ന് പേരു വിളിച്ചു; ഓനിലെ പുരോഹിതനായ പൊത്തിഫെറായുടെ മകൾ അസ്‌നത്തിനെ അവന് ഭാര്യയായി കൊടുക്കുകയും ചെയ്തു. ജോസഫ് ഈജിപ്തുരാജ്യത്ത് പര്യടനംനടത്തി.","p":1},{"v":46,"t":"ഈജിപ്തിലെ രാജാവായ ഫറവോയുടെ മുൻപിൽ സ്ഥാനീയനായപ്പോൾ ജോസഫിനു മുപ്പതു വയസ്സായിരുന്നു. ഫറവോയുടെ മുൻപിൽനിന്നു പുറപ്പെട്ട് ജോസഫ് ഈജിപ്തുരാജ്യംമുഴുവൻ സഞ്ചരിച്ചു.","p":1},{"v":47,"t":"സുഭിക്ഷത്തിൻ്റ ഏഴുവർഷം ഭൂമി സമൃദ്ധിയുളവാക്കി.","p":1},{"v":48,"t":"ഈജിപ്തുദേശത്തുണ്ടായിരുന്ന ഏഴുവർഷത്തെ ഭക്ഷ്യവിഭവമെല്ലാം അവൻ ശേഖരിച്ചു. നഗരങ്ങളിൽ ഭക്ഷ്യം സംഭരിച്ചുവെച്ചു. നഗരത്തിനുചുറ്റുമുള്ള വയലുകളിലെ ഭക്ഷ്യം അതിനുള്ളിൽത്തന്നെ സൂക്ഷിച്ചു.","p":1},{"v":49,"t":"അളവെടുപ്പിന് അതീതമായതിനാൽ അളവു നിർത്തിവെക്കുന്നതുവരെ, ജോസഫ് കടൽമണൽപോലെ ധാന്യം ധാരാളമായി കൂമ്പാരംകൂട്ടി.","p":1},{"v":50,"t":"ക്ഷാമവർഷം വരുന്നതിനുമുമ്പ് ജോസഫിന് രണ്ടു പുത്രന്മാർ ജനിച്ചു. ഓനിന്റെ പുരോഹിതനായ പൊത്തിഫെറായുടെ മകൾ അസ്‌നത്താണ് അവനുവേണ്ടി അവരെ പ്രസവിച്ചത്.","p":1},{"v":51,"t":"'എന്റെ എല്ലാ കഷ്ടപ്പാടും പിതൃഭവനം സമസ്തവും മറക്കാൻ ദൈവം ഇടയാക്കിയിരിക്കുന്നു' എന്ന അർത്ഥത്തിൽ ജോസഫ് തന്റെ കടിഞ്ഞൂൽപുത്രന് മനാസ്സെ എന്നു പേരിട്ടു.","p":1},{"v":52,"t":"രണ്ടാമന്, 'എന്റെ കഷ്ടതകളുടെ നാട്ടിൽ ദൈവം എന്നെ സന്താനപുഷ്ടിയുള്ളവനാക്കിയിരിക്കുന്നു' എന്ന അർത്ഥത്തിൽ എഫ്രായിം എന്നു പേരിട്ടു.","p":1},{"v":53,"t":"ഈജിപ്തുദേശത്തു നിലനിന്ന സമൃദ്ധിയുടെ ഏഴുവർഷങ്ങൾ അവസാനിച്ചു.","p":1},{"v":54,"t":"ജോസഫ് പറഞ്ഞതുപോലെ ക്ഷാമത്തിന്റെ ഏഴുവർഷങ്ങൾ ആരംഭിച്ചു. എല്ലാ നാടുകളിലും ക്ഷാമമുണ്ടായി; എന്നാൽ, ഈജിപ്തുദേശത്തെങ്ങും ആഹാരമുണ്ടായിരുന്നു.","p":1},{"v":55,"t":"പിന്നീട്, ഈജിപ്തുനാട്ടിലെല്ലാം ക്ഷാമമായപ്പോൾ ജനം ഫറവോയുടെയടുക്കൽ ആഹാരത്തിനായി കേണപേക്ഷിച്ചു. ഫറവോ ഈജിപ്തുകാരോടെല്ലാമായി പറഞ്ഞു: ജോസഫിന്റെ അടുത്തേക്കു പോകുവിൻ; അവൻ നിങ്ങളോടു പറയുന്നതു ചെയ്യുവിൻ!","p":1},{"v":56,"t":"ഭൂമുഖത്തെല്ലാം ക്ഷാമമുണ്ടായി. അപ്പോൾ ജോസഫ് ധാന്യപ്പുരകളെല്ലാം തുറന്ന് അവയിലുണ്ടായിരുന്ന ധാന്യം ഈജിപ്തുകാർക്ക് വിതരണംചെയ്തു. ഈജിപ്തുദേശത്ത് പട്ടിണി രൂക്ഷമായിരുന്നു.","p":1},{"v":57,"t":"ജോസഫിന്റെപക്കൽനിന്ന് ധാന്യം വാങ്ങാൻ ഭൂമിമുഴുവൻ ഈജിപ്തിലേക്കു വന്നു. കാരണം, എല്ലാ നാട്ടിലും ക്ഷാമം കൊടുമ്പിരിക്കൊണ്ടിരുന്നു.","p":1}],"42":[{"h":"ജോസഫിന്റെ സഹോദരന്മാർ ഈജിപ്തിലേക്ക്"},{"v":1,"t":"ഈജിപ്തിൽ ധാന്യമുണ്ടെന്ന് യാക്കോബു മനസ്സിലാക്കി. അപ്പോൾ യാക്കോബ് തന്റെ മക്കളോടു പറഞ്ഞു: നിങ്ങളെന്താണു പരസ്പരം നോക്കിനിൽക്കുന്നത്?","p":1},{"v":2,"t":"തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: ഇതാ, ഈജിപ്തിൽ ധാന്യമുണ്ടെന്നു ഞാൻ കേട്ടു. അവിടെ ചെന്ന് നമുക്കുവേണ്ടി ധാന്യം വാങ്ങുവിൻ! അങ്ങനെ നാം ജീവിക്കട്ടെ; നമ്മൾ മരിക്കാതിരിക്കട്ടെ.","p":1},{"v":3,"t":"ഈജിപ്തിൽനിന്നു ധാന്യം വാങ്ങാനായി ജോസഫിന്റെ പത്തു സഹോദരന്മാർ ഇറങ്ങിത്തിരിച്ചു.","p":1},{"v":4,"t":"'അവനെന്തെങ്കിലും അപകടം പിണഞ്ഞെങ്കിലോ' എന്നു പറഞ്ഞ് യാക്കോബ്, ജോസഫിന്റെ സഹോദരനായ ബെഞ്ചമിനെ അവന്റെ സഹോദരന്മാരുടെകൂടെ അയച്ചില്ല.","p":1},{"v":5,"t":"അങ്ങനെ, ധാന്യം വാങ്ങാൻ പോകുന്നവരുടെ കൂട്ടത്തിൽ ഇസ്രായേലിന്റെ മക്കളും പോയി. കാരണം, കാനാൻദേശത്തും ക്ഷാമമായിരുന്നു.","p":1},{"v":6,"t":"ജോസഫായിരുന്നു ആ നാട്ടിലെ മേലധികാരി. അവനാണു നാട്ടുകാർക്കെല്ലാം ധാന്യം വിറ്റിരുന്നത്. ജോസഫിന്റെ സഹോദരന്മാർ വന്ന് നിലംപറ്റേ മുഖംതാഴ്ത്തി അവനെ വണങ്ങി.","p":1},{"v":7,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരെ കണ്ടപ്പോൾ തിരിച്ചറിഞ്ഞു. പക്ഷേ, അവൻ അപരിചിതനെന്നപോലെ അവരോടു പെരുമാറുകയും പരുഷമായി അവരോടു സംസാരിക്കുകയും ചെയ്തു. അവൻ അവരോടു ചോദിച്ചു: നിങ്ങൾ എവിടെനിന്നു വരുന്നു? അവർ പറഞ്ഞു: ഭക്ഷ്യധാന്യം വാങ്ങാൻ കാനാൻദേശത്തുനിന്ന്.","p":1},{"v":8,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരെ തിരിച്ചറിഞ്ഞെങ്കിലും അവർ അവനെ തിരിച്ചറിഞ്ഞില്ല.","p":1},{"v":9,"t":"അവരെക്കുറിച്ച് താൻ കണ്ട സ്വപ്നങ്ങൾ ജോസഫ് ഓർത്തു. അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ ചാരന്മാരാണ്; നാടിന്റെ ബലക്ഷയം കണ്ടുപിടിക്കാനാണ് നിങ്ങൾ വന്നിരിക്കുന്നത്","p":1},{"v":10,"t":"അവർ അവനോടു പറഞ്ഞു: അല്ല, എന്റെ യജമാനനേ, അങ്ങയുടെ ദാസന്മാർ വന്നിരിക്കുന്നത് ഭക്ഷ്യധാന്യം വാങ്ങാനാണ്.","p":1},{"v":11,"t":"ഞങ്ങളെല്ലാവരും ഒരാളുടെ മക്കളാണ്; ഞങ്ങൾ സത്യസന്ധരാണ്. അങ്ങയുടെ ദാസന്മാർ ചാരന്മാരല്ല.","p":1},{"v":12,"t":"അവൻ അവരോടു പറഞ്ഞു: അല്ല, തീർച്ചയായും നാടിന്റെ ബലക്ഷയം കണ്ടുപിടിക്കാനാണു നിങ്ങൾ വന്നിരിക്കുന്നത്.","p":1},{"v":13,"t":"അപ്പോൾ അവർ പറഞ്ഞു: അങ്ങയുടെ ദാസന്മാരായ ഞങ്ങൾ പന്ത്രണ്ടു സഹോദരന്മാരാണ്; കാനാൻദേശത്തുള്ള ഒരാളുടെ പുത്രന്മാർ. ഇതാ, ഇളയവൻ ഇന്ന് ഞങ്ങളുടെ പിതാവിന്റെകൂടെയുണ്ട്; എന്നാൽ ഒരുവൻ ഇല്ലാതായി.","p":1},{"v":14,"t":"ജോസഫ് അവരോടു പറഞ്ഞു: അതുകൊണ്ടുതന്നെയാണ് നിങ്ങൾ ചാരന്മാരാണെന്ന് ഞാൻ നിങ്ങളോടു പറഞ്ഞത്.","p":1},{"v":15,"t":"ഇതിനാൽ നിങ്ങൾ പരിശോധിക്കപ്പെടും: നിങ്ങളുടെ ഇളയ സഹോദരൻ ഇവിടെ വന്നിട്ടല്ലാതെ, ഫറവോയുടെ ജീവനാണേ, നിങ്ങൾ ഇവിടം വിട്ടുപോവുകയില്ല.","p":1},{"v":16,"t":"നിങ്ങളുടെ സഹോദരനെ കൊണ്ടുവരാനായി നിങ്ങളിൽനിന്ന് ഒരുവനെ അയക്കുവിൻ. അപ്പോൾ നിങ്ങളാകട്ടെ, തടവിലായിരിക്കും. അങ്ങനെ നിങ്ങളുടെ വാക്കുകൾ സത്യമോ എന്നു തെളിയിക്കപ്പെടട്ടെ. അങ്ങനെയല്ലെങ്കിൽ, ഫറവോയുടെ ജീവനാണേ, നിങ്ങൾ തീർച്ചയായും ചാരന്മാരാണ്.","p":1},{"v":17,"t":"അവൻ അവരെ മൂന്നു ദിവസം തടങ്കലിൽ സൂക്ഷിച്ചു.","p":1},{"v":18,"t":"മൂന്നാംദിവസം ജോസഫ് അവരോടു പറഞ്ഞു: ഇതു ചെയ്യുവിൻ; എങ്കിൽ നിങ്ങൾ ജീവിക്കും. ദൈവത്തെ ഭയപ്പെടുന്നവനാണ് ഞാൻ.","p":1},{"v":19,"t":"നിങ്ങൾ സത്യസന്ധരാണെങ്കിൽ നിങ്ങളുടെ ഒരു സഹോദരൻ കാരാഗൃഹത്തിൽ ബന്ധനസ്ഥനായാൽ മതി. നിങ്ങൾ പോയി വീടുകളിലെ പട്ടിണിക്ക് ധാന്യമെത്തിക്കുവിൻ!","p":1},{"v":20,"t":"നിങ്ങളുടെ ഇളയ സഹോദരനെ എന്റെയടുക്കൽ കൊണ്ടുവരുവിൻ. അപ്പോൾ നിങ്ങളുടെ വാക്കുകൾ സത്യസന്ധമെന്നു തെളിയും; നിങ്ങൾക്കു മരിക്കേണ്ടി വരികയുമില്ല. അവർ അപ്രകാരം ചെയ്തു.","p":1},{"v":21,"t":"അവർ തമ്മിൽത്തമ്മിൽ പറഞ്ഞു: കഷ്ടം! നമ്മുടെ സഹോദരൻ നമ്മോടു കേണപേക്ഷിച്ചപ്പോൾ അവന്റെ സങ്കടം കണ്ടിട്ടും ചെവികൊടുക്കാതിരുന്ന നമ്മൾ അവനെപ്രതി അപരാധികളാണ്. അതുകൊണ്ടാണ് നമുക്ക് ഈ ദുരിതം വന്നിരിക്കുന്നത്.","p":1},{"v":22,"t":"അപ്പോൾ റൂബൻ ഇപ്രകാരം പ്രത്യുത്തരിച്ചു: കുട്ടിക്കെതിരേ തെറ്റുചെയ്യരുതെന്ന് ഞാൻ നിങ്ങളോടു പറഞ്ഞതല്ലേ? എന്നാൽ നിങ്ങൾ കേട്ടില്ല. ഇതാ, അവന്റെ രക്തംതന്നെ പക വീട്ടുകയാണ്","p":1},{"v":23,"t":"ജോസഫിന് അതു മനസ്സിലാകുന്നുണ്ടെന്ന് അവർ കരുതിയില്ല; കാരണം, അവർക്കിടയിൽ ഒരു ദ്വിഭാഷിയുണ്ടായിരുന്നു.","p":1},{"v":24,"t":"അവൻ അവരിൽനിന്നു വിട്ടുമാറി കരഞ്ഞു; അവരുടെപക്കൽ തിരിച്ചെത്തി അവരോടു സംസാരിച്ചു. തുടർന്ന്, അവരുടെ കൂട്ടത്തിൽനിന്ന് ശിമയോനെ പിടിച്ച് അവരുടെ കൺമുമ്പിൽവെച്ചു ബന്ധിച്ചു.","p":1},{"v":25,"t":"ഓരോരുത്തന്റെ ചാക്കിലും അവനവന്റെ പണം തിരിയെവയ്ക്കാനും യാത്രയ്ക്കുവേണ്ടത് അവർക്കു കൊടുക്കാനും ജോസഫ് കൽപ്പിച്ചപ്രകാരം, അവരുടെ ഭാണ്ഡളിൽ അവർ ഗോതമ്പു നിറച്ചു. അങ്ങനെയാണ് അവൻ അവരോടു ചെയ്തത്.","p":1},{"v":26,"t":"ധാന്യം തങ്ങളുടെ കഴുതകളുടെ പുറത്തുകയറ്റി അവർ അവിടെനിന്നു യാത്രതിരിച്ചു.","p":1},{"v":27,"t":"വഴിയമ്പലത്തിൽവെച്ച് ഒരുവൻ കഴുതയ്ക്കു തീറ്റ കൊടുക്കാൻ ചാക്കു തുറന്നപ്പോൾ തന്റെ പണം കണ്ടു; ഇതാ, അത് ചാക്കുകെട്ടിന്റെ വായ്ഭാഗത്ത്!","p":1},{"v":28,"t":"അവൻ തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: എന്റെ പണം തിരിച്ചെത്തിരിക്കുന്നു! ഇതാ, അത് എന്റെ കെട്ടിൽത്തന്നെയുണ്ട്! അപ്പോൾ അവരുടെ ഹൃദയം ഇടിഞ്ഞുപോയി അവർ ഭയംകൊണ്ട് വിറച്ച്, പരസ്പരം പറഞ്ഞു: എന്താണ് ദൈവം നമ്മോട് ഈ ചെയ്തിരിക്കുന്നത്!","p":1},{"v":29,"t":"കാനാൻദേശത്ത് തങ്ങളുടെ പിതാവായ യാക്കോബിന്റെയടുക്കൽ വന്നെത്തിയപ്പോൾ തങ്ങൾക്കു സംഭവിച്ചതെല്ലാം അവർ അദ്ദേഹത്തോട് ഇപ്രകാരം വിവരിച്ചു:","p":1},{"v":30,"t":"ദേശാധിപനായ ആൾ ഞങ്ങളോടു പരുഷമായി സംസാരിച്ചു; നാടിനെ ഒറ്റുനോക്കാനെത്തിയവരായി അയാൾ ഞങ്ങളെ കണക്കാക്കി.","p":1},{"v":31,"t":"ഞങ്ങൾ അയാളോടു പറഞ്ഞു: ഞങ്ങൾ സത്യസന്ധരാണ്, ചാരന്മാരല്ല.","p":1},{"v":32,"t":"ഞങ്ങൾ പന്ത്രണ്ടു സഹോദരന്മാരാണ്; ഞങ്ങളുടെ പിതാവിന്റെ മക്കൾ. ഒരാൾ ഇല്ലാതായി; ഇളയവൻ ഇന്ന് കാനാൻദേശത്തു ഞങ്ങളുടെ പിതാവിന്റെകൂടെയുണ്ട്.","p":1},{"v":33,"t":"അപ്പോൾ, ദേശാധിപനായ ആൾ ഞങ്ങളോടു പറഞ്ഞു: നിങ്ങൾ സത്യസന്ധരാണോ എന്ന് ഇതുകൊണ്ട് ഞാൻ മനസ്സിലാക്കും: നിങ്ങളുടെ സഹോദരനൊരാളെ എന്റെയടുക്കൽ നിർത്തുവിൻ. നിങ്ങളുടെ ഭവനങ്ങളിലെ പട്ടിണിക്കു വേണ്ടത് എടുത്തുകൊണ്ടു പോകുവിൻ.","p":1},{"v":34,"t":"പിന്നെ നിങ്ങളുടെ ഇളയസഹോദരനെ എന്റെയടുക്കൽ കൊണ്ടുവരുവിൻ. അപ്പോൾ നിങ്ങൾ ചാരന്മാരല്ലെന്നും സത്യസന്ധരാണെന്നും എനിക്കു ബോധ്യമാകും. നിങ്ങളുടെ സഹോദരനെ ഞാൻ നിങ്ങൾക്കു വിട്ടുതരുന്നതുമാണ് നിങ്ങൾക്കു ഈ നാട് പ്രയോജനപ്പെടുത്തുകയുമാകാം.","p":1},{"v":35,"t":"അവർ തങ്ങളുടെ ചാക്കുകളഴിക്കുമ്പോ അതാ, ഓരോരുത്തരുടെയും പണക്കിഴി അവനവൻ്റെ ചാക്കിൽ! അവരും അവരുടെ പിതാവും അവരുടെ പോണ കിഴികൾ കണ്ടു ഭയപ്പെട്ടു","p":1},{"v":36,"t":"അവരുടെ പിതാവായ യാക്കോബ് അവരോടു പറഞ്ഞു: നിങ്ങൾ എന്നെ അനപത്യനാക്കിയിരിക്കുന്നു. ജോസഫ് ഇല്ലാതായി; ശിമയോനും ഇല്ല. ഇനി നിങ്ങൾ ബെഞ്ചമിനെയും കൊണ്ടുപോകും. എല്ലാം എനിക്ക് എതിരായി സംഭവിക്കുന്നു.","p":1},{"v":37,"t":"റൂബൻ തന്റെ പിതാവിനോട് ഇപ്രകാരം പറഞ്ഞു: ഞാൻ അവനെ അങ്ങയുടെപക്കൽ തിരിയെ കൊണ്ടുവന്നില്ലെങ്കിൽ എന്റെ മക്കളെ രണ്ടുപേരെയും അങ്ങേക്കു കൊല്ലാം. അവനെ എന്റെ കൈയിലേല്പിക്കുക, ഞാൻ അവനെ അങ്ങയുടെ അടുത്തു തിരിയെക്കൊണ്ടുവരുന്നതാണ്.","p":1},{"v":38,"t":"അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്റെ മകൻ നിങ്ങളുടെ കൂടെ വരുകയില്ല. കാരണം, അവന്റെ സഹോദരൻ മൃതനായി. ഇനി ഇവൻ മാത്രമേ ശേഷിച്ചിട്ടുള്ളൂ. നിങ്ങൾ പോകുന്ന വഴിയിൽ അവന് ആപത്തു സംഭവിച്ചാൽ നിങ്ങൾ എന്റെ വാർദ്ധക്യത്തെ കഠിനദുഃഖത്തിൽ പാതാളത്തിലേക്കു തള്ളിവിടുകയായിരിക്കും.","p":1}],"43":[{"h":"ബെഞ്ചമിനും ഈജിപ്തിലേക്ക്"},{"v":1,"t":"നാട്ടിൽ ക്ഷാമം കൊടുമ്പിരിക്കൊണ്ടു.","p":1},{"v":2,"t":"ഈജിപ്തിൽനിന്ന് കൊണ്ടുവന്ന ധാന്യം അവർ ഭക്ഷിച്ചുതീർന്നപ്പോൾ അവരുടെ പിതാവ് അവരോടു പറഞ്ഞു: നിങ്ങൾ തിരിച്ചുപോയി നമുക്കുവേണ്ടി കുറച്ചുകൂടി ഭക്ഷ്യധാന്യം വാങ്ങിക്കൊണ്ടുവരുവിൻ.","p":1},{"v":3,"t":"അപ്പോൾ യൂദാ അദ്ദേഹത്തോട് ഇപ്രകാരം പറഞ്ഞു: സഹോദരൻ നിങ്ങളോടൊപ്പം ഇല്ലാത്തപക്ഷം നിങ്ങൾ എന്റെ മുഖം ദർശിക്കുകയില്ല എന്ന് അയാൾ ഞങ്ങൾക്ക് കർശനമായി താക്കീതു നൽകിയിട്ടുണ്ട്.","p":1},{"v":4,"t":"സഹോദരനെ ഞങ്ങളോടുകൂടെ അയയ്ക്കുമെങ്കിൽ, ഞങ്ങൾ പോയി അങ്ങേക്കായി ഭക്ഷ്യധാന്യം വാങ്ങിക്കൊണ്ടുവരാം.","p":1},{"v":5,"t":"അങ്ങ് അയയ്ക്കുന്നില്ലെങ്കിൽ, ഞങ്ങൾ പോകുന്നില്ല. കാരണം, സഹോദരൻ നിങ്ങളോടൊപ്പം ഇല്ലാത്തപക്ഷം, നിങ്ങൾ എന്റെ മുഖം ദർശിക്കുകയില്ല എന്ന് അയാൾ ഞങ്ങളോടു പറഞ്ഞിട്ടുണ്ട്.","p":1},{"v":6,"t":"അപ്പോൾ ഇസ്രായേൽ ചോദിച്ചു: നിങ്ങൾക്ക് ഒരു സഹോദരൻ കൂടിയുണ്ടെന്ന് അയാളോടു വിശദീകരിച്ച് എന്തിനാണ് നിങ്ങളെന്നെ ദ്രോഹിച്ചത്?","p":1},{"v":7,"t":"അവർ പറഞ്ഞു: അയാൾ ഞങ്ങളെയും വീട്ടുകാരെയുംകുറിച്ച്, 'നിങ്ങളുടെ പിതാവ് ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നോ, നിങ്ങൾക്ക് ഒരു സഹോദരനുണ്ടോ' എന്നിങ്ങനെ വിശദമായി ചോദ്യംചെയ്തു. അപ്പോൾ ഞങ്ങൾക്ക് അയാളോട് ഇക്കാര്യങ്ങൾ ഇവ്വിധം വിശദീകരിക്കേണ്ടിവന്നു. നിങ്ങളുടെ സഹോദരനെ കൂട്ടിക്കൊണ്ടുവരുവിൻ എന്ന് അയാൾ പറയുമെന്ന് ഞങ്ങൾക്ക് എന്തെങ്കിലും അറിവുണ്ടായിരുന്നോ","p":1},{"v":8,"t":"അപ്പോൾ, യൂദാ തന്റെ പിതാവായ ഇസ്രായേലിനോടു പറഞ്ഞു: ഞങ്ങൾ തയ്യാറായി യാത്രയാകേണ്ടതിന് കുട്ടിയെ എന്നോടൊപ്പം അയച്ചാലും. അങ്ങനെ നമ്മൾ, അങ്ങും ഞങ്ങളും ഞങ്ങളുടെ കുഞ്ഞുങ്ങളും, ജീവനോടെയിരിക്കട്ടെ; നമ്മൾ മരിക്കാതിരിക്കട്ടെ.","p":1},{"v":9,"t":"ഞാൻതന്നെ അവനു ജാമ്യം നിൽക്കാം. എന്റെ കൈയിൽനിന്ന് അങ്ങേക്ക് അവനെ ആവശ്യപ്പെടാം. അവനെ ഞാൻ അങ്ങയുടെപക്കൽ തിരിയെ കൊണ്ടുവന്ന് അങ്ങയുടെമുമ്പിൽ ഹാജരാക്കുന്നില്ലെങ്കിൽ, എക്കാലവും ഞാൻ അങ്ങയോടു തെറ്റുകാരനായിരിക്കും.","p":1},{"v":10,"t":"ഞങ്ങൾ ഇത്രയും വൈകാതിരുന്നെങ്കിൽ, ഞങ്ങളിപ്പോൾ രണ്ടാംപ്രാവശ്യം പോയി തിരിച്ചെത്തുമായിരുന്നു.","p":1},{"v":11,"t":"അപ്പോൾ, അവരുടെ പിതാവായ ഇസ്രായേൽ അവരോടു പറഞ്ഞു: അങ്ങനെയെങ്കിൽ ഇതു ചെയ്യുക, നാടിന്റെ വിശിഷ്ടോൽപ്പന്നങ്ങളിൽനിന്ന് കുറച്ചു തൈലം, കുറച്ചു തേൻ, സുഗന്ധദ്രവ്യങ്ങൾ, മീറാ, ബോഡനണ്ടി, ബദാംപരിപ്പ് എന്നിവ നിങ്ങളുടെ ഭാണ്ഡങ്ങളിലെടുത്ത് അദ്ദേഹത്തിനു കാഴ്ചയായി കൊണ്ടുചെല്ലുക.","p":1},{"v":12,"t":"നിങ്ങളുടെ കൈയിൽ ഇരുമടങ്ങ് പണവും എടുത്തുകൊള്ളണം; നിങ്ങളുടെ കെട്ടുകളിൽ വായ്ഭാഗത്തു തിരിയെവെച്ചിരുന്ന പണവും നിങ്ങളുടെ കൈയിൽ തിരിച്ചു കൊണ്ടുപോകണം. ഒരുപക്ഷേ, അതൊരു നോട്ടപ്പിശകായിരിക്കും.","p":1},{"v":13,"t":"നിങ്ങൾ എഴുന്നേറ്റ് നിങ്ങളുടെ സഹോദരനെയും കൂടെക്കൂട്ടി അദ്ദേഹത്തിന്റെ അടുത്തേക്കു മടങ്ങിച്ചെല്ലുവിൻ.","p":1},{"v":14,"t":"അദ്ദേഹത്തിന്റെമുമ്പിൽ സർവശക്തനായ തമ്പുരാൻ നിങ്ങളോട് അനുകമ്പ കാണിക്കട്ടെ. അങ്ങനെ അദ്ദേഹം നിങ്ങളുടെ മറ്റേ സഹോദരനെയും ബെഞ്ചമിനെയും നിങ്ങൾക്കു വിട്ടുതരട്ടെ. ഞാനാകട്ടെ, അനപത്യനെന്നപോലെ പുത്രവിരഹമനുഭവിക്കുന്നു!","p":1},{"v":15,"t":"അവർ എഴുന്നേറ്റ് കാഴ്ചവസ്തുക്കൾ സംവഹിച്ച്, ഇരട്ടിപ്പണവും കൈയിലെടുത്ത് ബെഞ്ചമിനോടൊത്ത് ഈജിപ്തിലേക്ക് ഇറങ്ങിത്തിരിച്ചു. അവർ ജോസഫിന്റെമുമ്പിൽ സന്നിഹിതരായി.","p":1},{"v":16,"t":"ജോസഫ് ബെഞ്ചമിനെ അവരോടുകൂടെ കണ്ടു. അപ്പോൾ അവൻ തന്റെ വീട്ടുകാര്യസ്ഥനോടു പറഞ്ഞു: ഈ ആളുകളെ വീട്ടിലേക്കു കൊണ്ടുപോകുവിൻ. ഒരു മൃഗത്തെ കൊന്നു തയ്യാറാക്കുവിൻ. എന്തെന്നാൽ, എന്റെകൂടെയായിരിക്കും ഈ ആളുകൾ ഉച്ചഭക്ഷണം കഴിക്കുന്നത്.","p":1},{"v":17,"t":"ജോസഫ് പറഞ്ഞപോലെ അയാൾ ചെയ്തു. അയാൾ ആ ആളുകളെ ജോസഫിന്റെ വീട്ടിലേക്കു കൊണ്ടുപോയി.","p":1},{"v":18,"t":"ജോസഫിന്റെ വീട്ടിലേക്ക് ആനയിക്കപ്പെടുന്നത് കൊണ്ട് അവർക്കു ഭയമായി. അവർ പറഞ്ഞു: കഴിഞ്ഞ തവണ നമ്മുടെ കെട്ടുകളിൽ തിരിയെവെച്ച പണത്തെച്ചൊല്ലി നമ്മുടെമേൽ ചാടിവീഴുന്നതിനും നമ്മെ കീഴ്‌പ്പെടുത്തുന്നതിനും നമ്മെയും നമ്മുടെ കഴുതകളെയും അടിമകളായി പിടിക്കുന്നതിനുവേണ്ടിയാണ് നമ്മെ കൊണ്ടെത്തിച്ചിരിക്കുന്നത്.","p":1},{"v":19,"t":"അതുകൊണ്ട്, അവർ ജോസഫിന്റെ വീട്ടുകാര്യസ്ഥനെ സമീപിച്ച് വീട്ടുവാതിൽക്കൽവെച്ച് അയാളോടു സംസാരിച്ചു.","p":1},{"v":20,"t":"അവർ പറഞ്ഞു: അയ്യോ യജമാനനേ, കഴിഞ്ഞ തവണ ഭക്ഷ്യധാന്യം വാങ്ങുന്നതിന് ഞങ്ങൾ ഇവിടെ വന്നിരുന്നു എന്നത് ശരിയാണ്.","p":1},{"v":21,"t":"എന്നാൽ, ഞങ്ങൾ വഴിയമ്പലത്തിൽ ചെന്ന് ഞങ്ങളുടെ കെട്ടുകൾ അഴിച്ചപ്പോൾ, അതാ, ഓരോരുത്തരുടെയും പണം, ഞങ്ങളുടെ തുക അതേപടി, അവനവന്റെ കെട്ടിന്റെ വായ്ഭാഗത്തുണ്ടായിരുന്നു! ഞങ്ങൾ അത് ഞങ്ങളുടെ കൈവശം തിരിയെക്കൊണ്ടുവന്നിട്ടുണ്ട്.","p":1},{"v":22,"t":"ഭക്ഷ്യധാന്യം വാങ്ങാൻ വേറെ പണവും ഞങ്ങളുടെ കൈവശം കരുതിയിട്ടുണ്ട്. പണം ഞങ്ങളുടെ കെട്ടുകളിൽ തിരിയെവെച്ചത് ആരെന്ന് ഞങ്ങൾക്കറിഞ്ഞുകൂടാ.","p":1},{"v":23,"t":"അപ്പോൾ അയാൾ പറഞ്ഞു: നിങ്ങൾക്ക് സമാധാനം! നിങ്ങൾ ഭയപ്പെടേണ്ട. നിങ്ങളുടെ ദൈവം, നിങ്ങളുടെ പിതാവിന്റെ ദൈവമാണ് നിങ്ങളുടെ കെട്ടുകളിൽ നിങ്ങൾക്കായി നിധി നിക്ഷേപിച്ചത്. നിങ്ങളുടെ പണം എന്റെ പക്കൽ എത്തിയിട്ടുള്ളതാണ്. അയാൾ ശിമയോനെ അവരുടെയടുത്തേക്ക് കൊണ്ടുവന്നു.","p":1},{"v":24,"t":"അനന്തരം അയാൾ അവരെ ജോസഫിന്റെ വീട്ടിനുള്ളിൽ കൊണ്ടുചെന്ന് അവർക്കു വെള്ളം കൊടുത്തു; അവർ തങ്ങളുടെ കാലുകൾ കഴുകി. അയാൾ അവരുടെ കഴുതകൾക്ക് തീറ്റയും കൊടുത്തു.","p":1},{"v":25,"t":"ഉച്ചയ്ക്ക് ജോസഫ് വരുമ്പോഴേക്ക് അവർ കാഴ്ച ഒരുക്കിവെച്ചു. കാരണം, അവിടെയായിരിക്കും തങ്ങൾ ഭക്ഷണം കഴിക്കുകയെന്ന് അവർ കേട്ടിരുന്നു.","p":1},{"v":26,"t":"ജോസഫ് വീട്ടിലേക്കു വന്നപ്പോൾ അവർ അവനുവേണ്ടി തങ്ങളുടെ കൈവശമുണ്ടായിരുന്ന കാഴ്ച വീട്ടിലേക്കു കൊണ്ടുചെന്നു; അവർ അവനെ നിലംപറ്റേ വണങ്ങി.","p":1},{"v":27,"t":"അവൻ അവരോട് കുശലമന്വേഷിച്ചുകൊണ്ട് ചോദിച്ചു: ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നെന്നു നിങ്ങൾ പറഞ്ഞ നിങ്ങളുടെ വൃദ്ധനായ പിതാവിന് സുഖംതന്നെയോ?","p":1},{"v":28,"t":"അവർ പറഞ്ഞു: അങ്ങയുടെ ദാസനായ ഞങ്ങളുടെ പിതാവിന് സുഖംതന്നെ. അദ്ദേഹം ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നു. അവർ കുനിഞ്ഞ് അവനെ വണങ്ങി.","p":1},{"v":29,"t":"അവൻ കണ്ണുകളുയർത്തി നോക്കിയപ്പോൾ തന്റെ സഹോദരൻ ബെഞ്ചമിനെ, തന്റെതന്നെ അമ്മയുടെ മകനെ, കണ്ടു. അവൻ ചോദിച്ചു: ഇവനാണോ നിങ്ങൾ എന്നോടു പറഞ്ഞ നിങ്ങളുടെ ഇളയ സഹോദരൻ? തുടർന്ന് അവൻ പറഞ്ഞു: എന്റെ മകനേ, ദൈവം നിന്നോടു കനിവു കാണിക്കട്ടെ.","p":1},{"v":30,"t":"ജോസഫ് തിടുക്കംകൂട്ടി; കാരണം, സഹോദരനെപ്രതി അവന്റെ ഉള്ളം തുടിച്ചു. അവൻ കരയാൻ വെമ്പി ഉൾമുറിയിലേക്ക് പ്രവേശിച്ച് അവിടെ അവൻ കരഞ്ഞു.","p":1},{"v":31,"t":"പിന്നെ അവൻ മുഖം കഴുകി പുറത്തുവന്ന്, തന്നെത്തന്നെ നിയന്ത്രിച്ചുകൊണ്ട് പറഞ്ഞു: ഭക്ഷണം വിളമ്പുവിൻ.","p":1},{"v":32,"t":"അവനും അവർക്കും പിന്നെ അവനോടൊത്തു ഭക്ഷണം കഴിക്കുന്ന ഈജിപ്തുകാർക്കും അവർ വിളമ്പിയത് പ്രത്യേകംപ്രത്യേകമായാണ്. ഹെബ്രായാരോടൊത്തു ഭക്ഷണംകഴിക്കുന്നത് ഈജിപ്തുകാർക്കു നിഷിദ്ധമായിരുന്നതുകൊണ്ട് ഈജിപ്തുകാർക്ക് അതിനു കഴിയുമായിരുന്നില്ല.","p":1},{"v":33,"t":"അവന്റെ മുമ്പിൽ അവർ ഇരുന്നത് മൂത്തവൻ തന്റെ മൂപ്പനുസരിച്ചും ഇളയവൻ തന്റെ ഇളപ്പമനുസരിച്ചുമാണ്. ആ ആളുകൾ അന്യോന്യം വിസ്മയംപ്രകടിപ്പിച്ചു.","p":1},{"v":34,"t":"അവൻ തന്റെ മുമ്പിലുണ്ടായിരുന്ന പങ്കുകൾ അവർക്കായി വീതിച്ചു. എന്നാൽ, ബെഞ്ചമിന്റെ പങ്ക് എല്ലാവരുടെയും പങ്കുകളെക്കാൾ അഞ്ചുമടങ്ങ് അധികമായിരുന്നു. അവർ അവനോടൊപ്പം പാനംചെയ്തുല്ലസിച്ചു.","p":1}],"44":[{"h":"സഹോദരന്മാർക്ക് അഗ്നി പരീക്ഷ"},{"v":1,"t":"അവൻ തന്റെ വീട്ടുകാര്യസ്ഥനോട് ഇപ്രകാരം കൽപ്പിച്ചു: അവർക്കു സംവഹിക്കാൻ സാധിക്കുന്നത്ര ഭക്ഷ്യധാന്യം അവരുടെ കെട്ടുകളിൽ നിറയ്ക്കുവിൻ. ഓരോരുത്തന്റെയും പണം അവനവന്റെ കെട്ടിന്റെ വായ്ഭാഗത്തു വെയ്ക്കുകയും വേണം.","p":1},{"v":2,"t":"ഇളയവന്റെ കെട്ടിന്റെ വായ്ഭാഗത്ത് എന്റെ പാനപാത്രം, വെള്ളിപ്പാനപാത്രം, അവന്റെ ധാന്യവിലയായ പണത്തിന്റെകൂടെ വെയ്ക്കുക. ജോസഫ് പറഞ്ഞ വാക്കനുസരിച്ച് അയാൾ പ്രവർത്തിച്ചു.","p":1},{"v":3,"t":"രാവിലെ വെട്ടം വീണപ്പോൾ, അവർ - അവരും അവരുടെ കഴുതകളും - യാത്രയാക്കപ്പെട്ടു.","p":1},{"v":4,"t":"അവർ നഗരംവിട്ട് ദൂരത്തായില്ല, അപ്പോൾ ജോസഫ് തന്റെ വീട്ടുകാര്യസ്ഥനോടു പറഞ്ഞു: എഴുന്നേറ്റ് ആ ആളുകളുടെ പിന്നാലെ പായുക. അവരെ മറികടന്നിട്ട് അവരോടു പറയണം: നിങ്ങൾ നന്മയ്ക്കുപകരം തിന്മചെയ്തത് എന്തുകൊണ്ട്?","p":1},{"v":5,"t":"ഇതിൽനിന്നല്ലേ എന്റെ യജമാനൻ പാനംചെയ്യുന്നത്? ഇതുകൊണ്ടുതന്നെയല്ലേ അദ്ദേഹം ഗണിച്ചറിയുന്നത്? നിങ്ങൾ ചെയ്തതു ദുഷ്കൃത്യമായിപ്പോയി.","p":1},{"v":6,"t":"അവരെ മറികടന്നിട്ട് അവൻ അവരോട് ഇക്കാര്യങ്ങൾ പറഞ്ഞു.","p":1},{"v":7,"t":"അപ്പോൾ അവർ അവനോടു പറഞ്ഞു: എന്താണ് എന്റെ യജമാനൻ ഇത്തരം വാക്കുകൾ സംസാരിക്കുന്നത്? ഇത്തരമൊരു കാര്യം ചെയ്യാൻ താങ്കളുടെ ദാസന്മാർക്ക് ഇടയാകാതിരിക്കട്ടെ!","p":1},{"v":8,"t":"നോക്കൂ, ഞങ്ങളുടെ കെട്ടുകളുടെ വായ്ഭാഗത്ത് ഞങ്ങൾ കണ്ടെത്തിയ പണം കാനാൻദേശത്തുനിന്നു ഞങ്ങൾ താങ്കളുടെ അടുത്തു തിരിയെകൊണ്ടുവന്നല്ലോ? അപ്പോൾ പിന്നെ ഞങ്ങൾ താങ്കളുടെ യജമാനന്മാരുടെ വീട്ടിൽനിന്ന് വെള്ളിയോ പൊന്നോ എങ്ങനെ മോഷ്ടിക്കും?","p":1},{"v":9,"t":"അത് താങ്കളുടെ ദാസരിൽ ആരുടെപക്കൽ കണ്ടെത്തപ്പെടുന്നുവോ അവൻ മരിക്കണം; ഞങ്ങളെല്ലാവരും എന്റെ യജമാനന് അടിമകളായിരിക്കുകയും ചെയ്യും.","p":1},{"v":10,"t":"അവൻ പറഞ്ഞു: ഇപ്പോഴും നിങ്ങൾ പറയുന്നപോലെയാവട്ടെ. അത് ആരുടെപക്കൽ കാണപ്പെടുന്നുവോ അവൻ എനിക്ക് അടിമയാകും; നിങ്ങൾ നിരപരാധരായിരിക്കും.","p":1},{"v":11,"t":"അപ്പോൾ ഓരോരുത്തരും തിടുക്കപ്പെട്ട് അവനവന്റെ കെട്ട് നിലത്തിറക്കി; ഓരോരുത്തനും അവനവന്റെ കെട്ടഴിച്ചു.","p":1},{"v":12,"t":"അപ്പോൾ അവൻ മൂത്തവനിൽ ആരംഭിച്ച് ഇളയവനിൽ അവസാനിക്കുംവിധം പരിശോധിച്ചു; ബെഞ്ചമിന്റെ കെട്ടിൽ ചഷകം കണ്ടെത്തുകയും ചെയ്തു.","p":1},{"v":13,"t":"അവർ തങ്ങളുടെ വസ്ത്രം വലിച്ചുകീറി; ഓരോരുത്തനും അവനവന്റെ കഴുതപ്പുറത്ത് ചുമടുകയറ്റി, പട്ടണത്തിലേക്ക് മടങ്ങി.","p":1},{"v":14,"t":"യൂദാ അവന്റെ സഹോദരന്മാരോടൊത്ത് ജോസഫിന്റെ വീട്ടിലേക്കു ചെന്നു. അവൻ അപ്പോഴും അവിടെ ഉണ്ടായിരുന്നു. അവർ അവന്റെമുമ്പിൽ നിലംപറ്റെ വീണു.","p":1},{"v":15,"t":"ജോസഫ് അവരോടു ചോദിച്ചു: ഇതെന്തു പ്രവൃത്തിയാണു നിങ്ങൾ ചെയ്തത്? എന്നെപ്പോലൊരാൾക്ക് തീർച്ചയായും ഗണിച്ചറിയാനാകുമെന്ന് നിങ്ങൾക്കറിഞ്ഞുകൂടേ?","p":1},{"v":16,"t":"അപ്പോൾ യൂദാ പറഞ്ഞു: ഞങ്ങൾ എന്താണ് യജമാനനോടു പറയേണ്ടത്? എന്താണ് സംസാരിക്കേണ്ടത്? എങ്ങനെയാണ് സ്വയം സാധൂകരിക്കേണ്ടത്? ദൈവം അങ്ങയുടെ ദാസരുടെ കുറ്റം കണ്ടുപിടിച്ചിരിക്കുന്നു. ഇതാ, ഞങ്ങൾ യജമാനന് അടിമകളാണ്; ഞങ്ങളും ആരുടെ കൈവശം പാനപാത്രം കണ്ടുപിടിക്കപ്പെട്ടുവോ അവനും.","p":1},{"v":17,"t":"എന്നാൽ, അവൻ പറഞ്ഞു: ഞാൻ അതു ചെയ്യാൻ ഇടയാകാതിരിക്കട്ടെ! ആരുടെ കൈവശം പാനപാത്രം കണ്ടുപിടിക്കപ്പെട്ടുവോ, അവൻമാത്രം എനിക്ക് അടിമയായിരിക്കും. നിങ്ങൾ സമാധാനമായി നിങ്ങളുടെ പിതാവിന്റെ അടുത്തേക്കു പൊയ്ക്കൊള്ളുവിൻ.","p":1},{"v":18,"t":"അപ്പോൾ യൂദാ അവന്റെ അടുത്തുചെന്നു പറഞ്ഞു: അല്ലയോ എന്റെ യജമാനനേ, അങ്ങയുടെ ദാസൻ ഒരു വാക്കുകൂടി യജമാനന്റെ ചെവികളിൽ ഉണർത്തിച്ചുകൊള്ളട്ടെ! അങ്ങയുടെ ദാസന്റെനേരേ അങ്ങയുടെ കോപം ജ്വലിക്കാതിരിക്കട്ടെ. എന്തെന്നാൽ, ഫറവോ എങ്ങനെയോ അതുപോലെയാണ് അങ്ങ്.","p":1},{"v":19,"t":"എന്റെ യജമാനൻ അങ്ങയുടെ ദാസന്മാരോട് ഇപ്രകാരം തിരക്കിയിരുന്നു: നിങ്ങൾക്കു പിതാവോ സഹോദരനോ ഉണ്ടോ?","p":1},{"v":20,"t":"അപ്പോൾ, ഞങ്ങൾ എന്റെ യജമാനനോട്, ഞങ്ങൾക്കു വൃദ്ധനായ പിതാവും വാർദ്ധക്യത്തിലെ മകനായ ഒരു ഇളയവനുമുണ്ട്; അവന്റെ സഹോദരൻ മരിച്ചുപോയി, അവന്റെ അമ്മയുടേതായി അവൻമാത്രമേ ശേഷിച്ചിട്ടുള്ളൂ; അവന്റെ പിതാവ് അവനെ സ്നേഹിക്കുകയും ചെയ്യുന്നു എന്നു പറഞ്ഞിരുന്നു.","p":1},{"v":21,"t":"അപ്പോഴാണ് അങ്ങ് അങ്ങയുടെ ദാസരോട്, അവനെ എന്റെയടുത്തു കൂട്ടിക്കൊണ്ടുവരുക; എനിക്കവനെ നേരിട്ടുകാണണം എന്നു പറഞ്ഞത്.","p":1},{"v":22,"t":"അപ്പോൾ ഞങ്ങൾ യജമാനനോട്, ബാലന് തന്റെ പിതാവിനെ വിട്ടുപോരാൻ വയ്യാ, അവൻ തന്റെ പിതാവിനെ പിരിഞ്ഞാൽ അദ്ദേഹം മരിച്ചുപോകും എന്ന് ഉണർത്തുകയുണ്ടായി.","p":1},{"v":23,"t":"നിങ്ങളുടെ ഇളയ സഹോദരൻ നിങ്ങളോടുകൂടെ വരുന്നില്ലെങ്കിൽ നിങ്ങൾ എന്റെ മുഖം ഇനി കാണുകയുണ്ടാവുകയില്ല എന്ന് അങ്ങ് അങ്ങയുടെ ദാസന്മാരോട് പറഞ്ഞു.","p":1},{"v":24,"t":"പിന്നെ സംഭവിച്ചത് ഇതാണ്: ഞങ്ങൾ അങ്ങയുടെ ദാസനായ എന്റെ പിതാവിന്റെ അടുത്തെത്തി, എന്റെ യജമാനന്റെ വാക്കുകൾ ഞങ്ങൾ അദ്ദേഹത്തോടു വിവരിച്ചു.","p":1},{"v":25,"t":"തിരിച്ചുപോയി നമുക്കായി കുറച്ചു ഭക്ഷ്യധാന്യം വാങ്ങിക്കൊണ്ടുവരുവിൻ എന്ന് പിന്നീട് ഞങ്ങളുടെ പിതാവ് പറഞ്ഞപ്പോൾ","p":1},{"v":26,"t":"ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾക്ക് പോകാൻ വയ്യാ; എന്നാൽ, ഞങ്ങളുടെ ഇളയസഹോദരൻ ഞങ്ങളോടൊത്തുണ്ടെങ്കിൽ ഞങ്ങൾ പോകാം. കാരണം, ഞങ്ങളുടെ ഇളയസഹോദരൻ ഞങ്ങളോടൊത്തില്ലെങ്കിൽ ഞങ്ങൾക്ക് അദ്ദേഹത്തിന്റെ മുഖം കാണാൻ സാധിക്കുകയില്ല.","p":1},{"v":27,"t":"അപ്പോൾ അങ്ങയുടെ ദാസനായ, എന്റെ പിതാവ് ഞങ്ങളോടു പറഞ്ഞു: എന്റെ ഭാര്യ എനിക്കുവേണ്ടി രണ്ടു പ്രസവിച്ചു എന്ന് നിങ്ങൾക്കറിയാമല്ലോ.","p":1},{"v":28,"t":"ഒരുവൻ എന്നെ വിട്ടുപോയി. അപ്പോൾ ഞാൻ പറഞ്ഞു: തീർച്ചയായും വന്യമൃഗം ചീന്തിക്കീറിയതുതന്നെ. പിന്നെ ഞാൻ അവനെ ഇതുവരെ കണ്ടിട്ടില്ല.","p":1},{"v":29,"t":"ഇവനെക്കൂടി നിങ്ങൾ എന്റെ മുമ്പിൽനിന്ന് കൊണ്ടുപോവുകയും അവന് ആപത്ത് പിണയുകയും ചെയ്താൽ നിങ്ങൾ എന്റെ വാർദ്ധക്യം ദുരിതത്തോടെ പാതാളത്തിലേക്ക് ആഴ്ത്തുകയായിരിക്കും","p":1},{"v":30,"t":"ഇപ്പോഴാകട്ടെ, അങ്ങയുടെ ദാസനായ, എന്റെ പിതാവിന്റെ അടുത്തേക്കു ഞാൻ ചെല്ലുമ്പോൾ ആ ബാലൻ ഞങ്ങളോടൊത്തുണ്ടാകില്ല; അദ്ദേഹത്തിന്റെ ജീവനോ അവന്റെ ജീവനോടു ബന്ധിക്കപ്പെട്ടുമിരിക്കുന്നു.","p":1},{"v":31,"t":"ബാലനില്ല എന്ന് അദ്ദേഹം കാണുന്നവേളയിൽ അദ്ദേഹം മരിക്കും. അങ്ങനെ അങ്ങയുടെ ദാസന്മാർ അങ്ങയുടെ ദാസനായ ഞങ്ങളുടെ പിതാവിന്റെ വാർദ്ധക്യം ദുഃഖസാന്ദ്രതയിൽ പാതാളത്തിലേക്ക് ആഴ്ത്തുകയായിരിക്കും","p":1},{"v":32,"t":"മാത്രമല്ല, ബാലനെ ഞാൻ അങ്ങയുടെപക്കൽ തിരിച്ചെത്തിക്കുന്നില്ലെങ്കിൽ ജീവിതകാലമുഴുവൻ ഞാൻ എന്റെ പിതാവിനോടു കുറ്റക്കാരനായിരിക്കും എന്നു പറഞ്ഞ് ബാലനുവേണ്ടി എന്റെ പിതാവിന്റെപക്കൽ അങ്ങയുടെ ദാസൻ ജാമ്യംനിന്നിട്ടുമുണ്ട്.","p":1},{"v":33,"t":"അതിനാൽ ഇപ്പോൾ ബാലനുപകരം അങ്ങയുടെ ദാസൻ എന്റെ യജമാനന് അടിമയായി കഴിഞ്ഞുകൊള്ളട്ടെ; ബാലൻ അവന്റെ സഹോദരന്മാരുടെ കൂടെ തിരിച്ചുപോവുകയും ചെയ്യട്ടെ.","p":1},{"v":34,"t":"ബാലൻ എന്നോടൊപ്പമില്ലാതെ ഞാൻ എങ്ങനെ എന്റെ പിതാവിന്റെയടുത്തു ചെല്ലും? എന്റെ പിതാവിനെ പിടികൂടുന്ന ദുരന്തം കാണാൻ എനിക്ക് ഇടയാകരുതല്ലോ.","p":1}],"45":[{"h":"ജോസഫ് സ്വയം വെളിപ്പെടുത്തുന്നു"},{"v":1,"t":"തന്റെ ചുറ്റും നിലകൊണ്ടിരുന്ന എല്ലാവരുടെയുംമുമ്പിൽ സ്വയം നിയന്ത്രിക്കാൻ ജോസഫിനു കഴിഞ്ഞില്ല. അതുകൊണ്ട്, അവൻ വിളിച്ചുപറഞ്ഞു: എല്ലാവരും എന്റെപക്കൽനിന്നു പുറത്തു പോകുവിൻ. അതിനാൽ ജോസഫ് തന്റെ സഹോദരന്മാർക്ക് തന്നെത്തന്നെ വെളിപ്പെടുത്തിയപ്പോൾ ഒരാൾപോലും അവനോടുകൂടെ നിന്നിരുന്നില്ല.","p":1},{"v":2,"t":"അവൻ സ്വരമുയർത്തി കരഞ്ഞു. ഈജിപ്തുകാർ അതു കേട്ടു; ഫറവോയുടെ ഭവനവും കേട്ടു.","p":1},{"v":3,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: ഞാൻ ജോസഫാണ്. എന്റെ പിതാവ് ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നുവോ? അവനോടു മറുപടിപറയാൻ അവന്റെ സഹോദരന്മാർക്കു സാധിച്ചില്ല; അവന്റെ മുമ്പിൽ അവർ പരിഭ്രമിച്ചുപോയിരുന്നു.","p":1},{"v":4,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: എന്റെയടുത്തേക്കു വന്നാലും. അവർ അടുത്തുചെന്നു. അപ്പോൾ അവൻ പറഞ്ഞു: നിങ്ങൾ ഈജിപ്തിലേക്കു വിറ്റ നിങ്ങളുടെ സഹോദരൻ ജോസഫാണു ഞാൻ.","p":1},{"v":5,"t":"എന്നാലിപ്പോൾ എന്നെ ഇവിടെക്കു വിറ്റതോർത്ത് നിങ്ങൾ നഷ്ടധൈര്യരാകേണ്ട; നിങ്ങളോടുതന്നെ കുപിതരാകുകയുംവേണ്ട. കാരണം, അതിജീവനത്തിനായി ദൈവമാണ് എന്നെ നിങ്ങൾക്കുമുമ്പേ ഇങ്ങോട്ടയച്ചത്.","p":1},{"v":6,"t":"എന്തെന്നാൽ, നാട്ടിൽ ക്ഷാമം ഇതു രണ്ടാം വർഷമാണ്; ഉഴവും കൊയ്ത്തുമില്ലാത്ത അഞ്ചുവർഷങ്ങൾ ഇനിയുമുണ്ട്.","p":1},{"v":7,"t":"നിങ്ങൾക്ക് ഭൂമിയിൽ ഒരു ശിഷ്ടഭാഗം നിലനിർത്താനും നിങ്ങൾക്ക് മഹാവിമോചനത്തിനുവേണ്ടി ജീവൻ സംരക്ഷിക്കാനുമായി ദൈവം എന്നെ നിങ്ങൾക്കുമുമ്പേ അയച്ചതാണ്.","p":1},{"v":8,"t":"അതുകൊണ്ടുതന്നെ നിങ്ങളല്ല എന്നെ ഇങ്ങോട്ടയച്ചത്, പിന്നെയോ, ദൈവമാണ്. അവിടുന്ന് എന്നെ ഫറവോയ്ക്കു പിതാവും അദ്ദേഹത്തിന്റെ വീടിനുമുഴുവനും നാഥനും ഈജിപ്തുദേശത്തിനുമുഴുവനും ഭരണാധിപനുമാക്കിയിരിക്കുന്നു.","p":1},{"v":9,"t":"നിങ്ങൾ വേഗം എന്റെ പിതാവിന്റെയടുത്തുചെന്ന് അദ്ദേഹത്തോടു പറയുക: അങ്ങയുടെ മകൻ ജോസഫ് ഇപ്രകാരം പറയുന്നു, ദൈവം എന്നെ ഈജിപ്തിനുമുഴുവൻ നാഥനാക്കിയിരിക്കുന്നു. എന്റെയടുത്തുവരണം, ഒട്ടും വൈകരുതേ!","p":1},{"v":10,"t":"അങ്ങേക്കു ഗോഷെൻ പ്രദേശത്തു പാർക്കാം. അങ്ങ് എന്റെയടുത്തായിരിക്കും; അങ്ങയോടൊപ്പം, അങ്ങയുടെ മക്കളും മക്കളുടെ മക്കളും അങ്ങയുടെ ആടുമാടുകളും അങ്ങയ്ക്കുള്ള സകലതും.","p":1},{"v":11,"t":"അവിടെ അങ്ങയെ ഞാൻ പോറ്റിക്കൊള്ളാം. എന്തെന്നാൽ, ക്ഷാമം അഞ്ചുകൊല്ലത്തേക്കുകൂടിയുണ്ട്. അങ്ങും അങ്ങയുടെ കുടുംബവും അങ്ങേക്കുള്ളവരും ദാരിദ്ര്യമനുഭവിക്കരുതല്ലോ.","p":1},{"v":12,"t":"ഇതാ, എന്റെ അധരംതന്നെയാണു നിങ്ങളോടു സംസാരിക്കുന്നതെന്ന് നിങ്ങളുടെ നയനങ്ങളും എന്റെ സഹോദരനായ ബെഞ്ചമിന്റെ നയനങ്ങളും കണ്ടുകൊണ്ടിരിക്കുകയാണല്ലോ.","p":1},{"v":13,"t":"ഈജിപ്തിലെ എന്റെ സർവപ്രതാപവും നിങ്ങൾ കണ്ടതുമെല്ലാം പിതാവിനോടു നിങ്ങൾ വിവരിക്കുമല്ലോ. വേഗം എന്റെ പിതാവിനെ ഇവിടേക്ക് കൊണ്ടുവരണം.","p":1},{"v":14,"t":"അവൻ തന്റെ സഹോദരനായ ബെഞ്ചമിന്റെ കഴുത്തിൽവീണു കരഞ്ഞു. ബെഞ്ചമിനും അവന്റെ കഴുത്തിൽചാഞ്ഞു കരഞ്ഞു.","p":1},{"v":15,"t":"അവൻ തന്റെ സഹോദരന്മാരെയെല്ലാവരെയും ചുംബിക്കുകയും അവരുടെ മേൽചാഞ്ഞ് കരയുകയും ചെയ്തു. അനന്തരം അവന്റെ സഹോദരന്മാർ അവനോടു സംസാരിച്ചു.","p":1},{"v":16,"t":"\"ജോസഫിന്റെ സഹോദരന്മാർ വന്നിട്ടുണ്ട് എന്ന് ഫറവോയുടെ ഭവനത്തിൽ ശ്രുതിപരന്നു. ഫറവോയുടെ ദൃഷ്ടികളിലും അദ്ദേഹത്തിന്റെ ദാസരുടെ ദൃഷ്ടികളിലും അത് നന്നായിരുന്നു.","p":1},{"v":17,"t":"ഫറവോ ജോസഫിനോടു പറഞ്ഞു: താങ്കളുടെ സഹോദരന്മാരോട് ഇതു ചെയ്യുവിൻ എന്നു പറയുക: നിങ്ങളുടെ മൃഗങ്ങളുടെമേൽ ചുമടേറ്റുവിൻ; കാനാൻദേശത്തേക്കു വേഗം ചെല്ലുവിൻ.","p":1},{"v":18,"t":"നിങ്ങളുടെ പിതാവിനെയും നിങ്ങളുടെ കുടുംബങ്ങളെയും എന്റെയടുത്തു കൂട്ടിക്കൊണ്ടുവരുവിൻ. ഈജിപ്തുനാട്ടിലെ ഐശ്വര്യം നിങ്ങൾക്കു ഞാൻ സമ്മാനിക്കാം; ദേശത്തിന്റെ പുഷ്ടി നിങ്ങൾക്കു ആസ്വദിക്കുകയും ചെയ്യാം.","p":1},{"v":19,"t":"ഇതാ, താങ്കൾ നിയുക്തനായിരിക്കുന്നു. നിങ്ങൾ ഇതു ചെയ്യുവിൻ: നിങ്ങൾക്കുവേണ്ടി, നിങ്ങളുടെ കുഞ്ഞുങ്ങൾക്കും നിങ്ങളുടെ ഭാര്യമാർക്കുംവേണ്ടി, ഈജിപ്തുനാട്ടിൽനിന്നു വാഹനങ്ങൾ കൊണ്ടുപോകുവിൻ. നിങ്ങളുടെ പിതാവിനെ കയറ്റി നിങ്ങൾ വരുവിൻ.","p":1},{"v":20,"t":"നിങ്ങളുടെ സാധനസാമഗ്രികളെപ്പറ്റി പര്യാകുലരാകേണ്ട; എന്തെന്നാൽ, ഈജിപ്തുനാട്ടിലെങ്ങുമുള്ള ഐശ്വര്യം നിങ്ങളുടേതായിരിക്കും.","p":1},{"v":21,"t":"ഇസ്രായേലിന്റെ പുത്രന്മാർ അങ്ങനെ ചെയ്തു. ഫറവോയുടെ കല്പനപ്രകാരം ജോസഫ് അവർക്കു വാഹനങ്ങൾ കൊടുത്തു; യാത്രയ്ക്കുവേണ്ടതും നൽകി.","p":1},{"v":22,"t":"അവൻ അവർക്ക് ഓരോരുത്തർക്കും വിശിഷ്ടവസ്ത്രങ്ങൾ നൽകി. ബെഞ്ചമിന് അവൻ മൂന്നൂറു വെള്ളിനാണയവും അഞ്ചു വിശിഷ്ടവസ്ത്രങ്ങളും കൊടുത്തു.","p":1},{"v":23,"t":"അവൻ തന്റെ പിതാവിനായി കൊടുത്തയച്ചവ ഇവയാണ്: ഈജിപ്തിലെ വിശിഷ്ടവസ്തുക്കൾ സംവഹിക്കുന്ന പത്തു കഴുതകൾ, ഗോതമ്പും അപ്പവും തന്റെ പിതാവിന്റെ യാത്രയ്ക്കുവേണ്ട ഭക്ഷണവും വഹിക്കുന്ന പത്തു പെൺകഴുതകൾ.","p":1},{"v":24,"t":"അങ്ങനെ അവൻ തന്റെ സഹോദരന്മാരെ യാത്രയാക്കി. അവർ പോകുമ്പോൾ അവൻ അവരോടു പറഞ്ഞു: വഴിക്കുവെച്ചു ശണ്ഠകൂടരുത്.","p":1},{"v":25,"t":"അവർ ഈജിപ്തിൽനിന്നു പുറപ്പെട്ട് കാനാൻദേശത്ത് തങ്ങളുടെ പിതാവായ യാക്കോബിന്റെ അടുത്തെത്തി.","p":1},{"v":26,"t":"അവർ അദ്ദേഹത്തോട് ഇപ്രകാരം വിവരിച്ചു: ജോസഫ് ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നു. അവൻതന്നെയാണ് ഈജിപ്തുദേശംമുഴുവന്റെയും ഭരണാധികാരി. അപ്പോൾ അദ്ദേഹത്തിന്റെ ഹൃദയം ജീവസ്സറ്റതായി; കാരണം, അദ്ദേഹം അവരെ വിശ്വസിച്ചില്ല.","p":1},{"v":27,"t":"എന്നാൽ, ജോസഫ് അവരോടു പറഞ്ഞകാര്യങ്ങളെല്ലാം അവർ അദ്ദേഹത്തോടു പറയുകയും തന്നെ കയറ്റാൻ ജോസഫ് അയച്ച വാഹനങ്ങൾ കാണുകയും ചെയ്തപ്പോൾ, അവരുടെ പിതാവായ യാക്കോബിന്റെ ചൈതന്യം ജീവസ്സുറ്റതായി.","p":1},{"v":28,"t":"അപ്പോൾ ഇസ്രായേൽ പറഞ്ഞു: കൊള്ളാം; എന്റെ മകൻ ജോസഫ് ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നു! ഞാൻ മരിക്കുംമുമ്പ് അവനെ എനിക്ക് കാണാനിടയാകട്ടെ!","p":1}],"46":[{"h":"യാക്കോബും മക്കളും ഈജിപ്തിൽ"},{"v":1,"t":"ഇസ്രായേൽ തനിക്കുള്ള സകലതിനോടുമൊപ്പം യാത്രതിരിച്ചു; ബേർഷെബായിലേക്കു വന്നു. അപ്പോൾ അദ്ദേഹം തന്റെ പിതാവായ ഇസഹാക്കിന്റെ ദൈവത്തിനു ബലികൾ സമർപ്പിച്ചു.","p":1},{"v":2,"t":"നിശാദർശനങ്ങളിലൂടെ ദൈവം ഇസ്രായേലിനോടു സംസാരിച്ചു. അവിടന്നു വിളിച്ചു: യാക്കോബേ, യാക്കോബേ. ഇതാ ഞാൻ, അദ്ദേഹം പറഞ്ഞു.","p":1},{"v":3,"t":"അവിടന്നു പറഞ്ഞു: ഞാൻ ദൈവമാണ്, നിന്റെ പിതാവിന്റെ ദൈവം. ഈജിപ്തിലേക്കു പോകുന്നതുകൊണ്ടു നീ ഭയപ്പെടേണ്ടാ. കാരണം, അവിടെ ഞാൻ നിന്നെ ഒരു വലിയ ജനതയാക്കി സ്ഥാപിക്കും.","p":1},{"v":4,"t":"ഞാൻ നിന്നോടൊപ്പം ഈജിപ്തിലേക്ക് ഇറങ്ങിവരും. നിന്നെ ഞാൻ ഉത്തരോത്തരം ഉയർത്തും. ജോസഫ് നിന്റെ കണ്ണുകളിൽ തന്റെ കൈവെയ്ക്കും.","p":1},{"v":5,"t":"ബേർഷെബായിൽനിന്ന് യാക്കോബ് എഴുന്നേറ്റു. ഇസ്രായേലിന്റെ മക്കൾ തങ്ങളുടെ പിതാവായ യാക്കോബിനെയും കുഞ്ഞുങ്ങളെയും ഭാര്യമാരെയും അദ്ദേഹത്തെ കൊണ്ടുവരാൻ ഫറവോ കൊടുത്തയച്ചിരുന്ന വാഹനങ്ങളിൽ കയറ്റി.","p":1},{"v":6,"t":"തങ്ങളുടെ കന്നുകാലികളും കാനാൻനാട്ടിൽ തങ്ങൾ സമ്പാദിച്ച വസ്തുവകകളും അവർ കൂടെയെടുത്തു. യാക്കോബും അദ്ദേഹത്തോടൊപ്പം അദ്ദേഹത്തിന്റെ ഓരോ സന്തതിയും ഈജിപ്തിലേക്കു പോയി.","p":1},{"v":7,"t":"സ്വപുത്രന്മാരെയും തന്നോടൊപ്പമുള്ള പുത്രന്മാരുടെ പുത്രന്മാരെയും സ്വപുത്രിമാരെയും പുത്രന്മാരുടെ പുത്രിമാരെയും അങ്ങനെ തന്റെ ഓരോ സന്തതിയെയും അദ്ദേഹം തന്നോടൊപ്പം ഈജിപ്തിലേക്കു കൊണ്ടുപോയി.","p":1},{"v":8,"t":"ഈജിപ്തിലേക്കു പോയ ഇസ്രായേല്യരുടെ അതായത്, യാക്കോബിന്റെയും അവന്റെ മക്കളുടെയും പേരുകൾ ഇവയാണ്: യാക്കോബിന്റെ ആദ്യജാതൻ റൂബൻ.","p":1},{"v":9,"t":"റൂബന്റെ പുത്രന്മാർ: ഹനോക്ക്, പല്ലു, ഹെസ്രോൻ, കർമി എന്നിവർ.","p":1},{"v":10,"t":"ശിമയോന്റെ പുത്രന്മാർ: യെമുവേൽ, യാമീൻ, ഓഹദ്, യാക്കീൻ, സോഹാർ, കാനാൻകാരിയുടെ മകൻ സാവൂൾ.","p":1},{"v":11,"t":"ലേവിയുടെ പുത്രന്മാർ: ഗർഷോൻ, കോഹാത്ത്, മെറാറി.","p":1},{"v":12,"t":"യൂദായുടെ പുത്രന്മാർ: ഏർ, ഓനാൻ, ഷേലാഫ്, പേരെസ്, സേറഹ്. ഏറും ഓനാനും കാനാൻദേശത്തുവെച്ചു മരിച്ചിരുന്നു. പേരെസിന്റെ പുത്രന്മാരായിരുന്നു ഹെസ്രോൻ, ഹാമുൽ എന്നിവർ.","p":1},{"v":13,"t":"ഇസ്സാക്കറിന്റെ പുത്രന്മാർ: തോലാ, ഫുവ്വാ, യോബ്, ഷിമ്രോൻ.","p":1},{"v":14,"t":"സെബുലൂണിന്റെ പുത്രന്മാർ: സേരെദ്, ഏലോൻ, യാഹ്ലേൽ.","p":1},{"v":15,"t":"ഇവരും ദീനാ എന്ന യാക്കോബിന്റെ പുത്രിയും പാദാൻആരാമിൽവെച്ച് ലെയാ പ്രസവിച്ച, അവന്റെ മക്കളാണ്. അവന്റെ പുത്രന്മാരും അവന്റെ പുത്രിമാരും ആകെ മുപ്പത്തിമൂന്ന് ആളുകൾ.","p":1},{"v":16,"t":"ഗാദിന്റെ പുത്രന്മാർ: സിഫ്യോൻ, ഹഗ്ഗി, ഷൂനി, എസ്ബോൻ, ഏരി, അരോഡി, അരേലി.","p":1},{"v":17,"t":"ആഷേരിന്റെ പുത്രന്മാർ: ഇമ്നാ, ഇഷ്വാ, ഇഷ്വി, ബെറിയാ; അവരുടെ സഹോദരി സേറഹ്. ബെറിയായുടെ പുത്രന്മാർ: ഹേബെർ, മൽക്കീയേൽ.","p":1},{"v":18,"t":"ലാബാൻ തന്റെ മകളായ ലെയായ്ക്കു പരിചാരികയായിക്കൊടുത്ത സിൽഫായുടെ മക്കളാണിവർ. അവൾ യാക്കോബിനുവേണ്ടി ഈ പതിനാറുപേരെ പ്രസവിച്ചു.","p":1},{"v":19,"t":"യാക്കോബിന്റെ ഭാര്യയായ റാഹേലിന്റെ മക്കളാണ് ജോസഫും ബെഞ്ചമിനും.","p":1},{"v":20,"t":"ഓനിലെ പുരോഹിതനായ പൊത്തിഫെറായുടെ പുത്രി അസ്നത്ത് ജോസഫിനുവേണ്ടി ഈജിപ്തിൽവെച്ച് മനാസ്സെ, എഫ്രായിം എന്നിവരെ പ്രസവിച്ചു.","p":1},{"v":21,"t":"ബെഞ്ചമിന്റെ പുത്രന്മാർ: ബെലാ, ബെക്കെർ, അഷ്ബേൽ, ഗേരാ, നാമാൻ, ഏഹി, റോഷ്, മുപ്പീം, ഹുപ്പീം, ആർദ്ദ്.","p":1},{"v":22,"t":"ഇവർ യാക്കോബിന് റാഹേലിൽ ജനിച്ച മക്കളാണ് - ആകെ പതിനാലുപേർ.","p":1},{"v":23,"t":"ദാനിന്റെ മക്കളാണ് ഹുഷ്യർ","p":1},{"v":24,"t":"നഫ്ത്താലിയുടെ പുത്രന്മാർ: യഹ്സേൽ, ഗൂനി, യേസെർ, ഷില്ലേം.","p":1},{"v":25,"t":"ലാബാൻ തന്റെ മകളായ റാഹേലിനു പരിചാരികയായി കൊടുത്ത ബിൽഹായുടെ പുത്രന്മാരാണിവർ. യാക്കോബിനുവേണ്ടി അവൾ ഇവരെ പ്രസവിച്ചു; ആകെ ഏഴുപേർ.","p":1},{"v":26,"t":"പുത്രന്മാരുടെ ഭാര്യമാരെക്കൂടാതെ, യാക്കോബിനോടൊപ്പം ഈജിപ്തിലേക്ക് തിരിച്ച, യാക്കോബിൽനിന്നുതന്നെ ഉടലെടുത്ത മക്കൾ ആകെ അറുപത്താറുപേരാണ്.","p":1},{"v":27,"t":"ജോസഫിന്റെ പുത്രന്മാർ: ഈജിപ്തിൽ അവനു ജനിച്ച രണ്ടുപേർ. അങ്ങനെ ഈജിപ്തിലേക്കു വന്ന, യാക്കോബിന്റെ കുടുംബത്തിൽപ്പെട്ട ആകെയാളുകൾ എഴുപതുപേരാണ്.","p":1},{"v":28,"t":"തനിക്കുമുമ്പേ ഗോഷെനിലേക്ക് നയിക്കുന്നതിനുവേണ്ടി അദ്ദേഹം ജോസഫിന്റെ പക്കലേക്ക് മുൻകൂറായി യൂദായെ അയച്ചു. അവർ ഗോഷെൻ പ്രദേശത്തേക്കു വന്നു.","p":1},{"v":29,"t":"ജോസഫ് തന്റെ രഥമൊരുക്കി തന്റെ പിതാവായ ഇസ്രായേലിനെ എതിരേല്ക്കാനായി ഗോഷെനിലേക്കു ചെന്നു. അവൻ അദ്ദേഹത്തിന്റെ അടുത്തെത്തി ആശ്ലേഷിച്ചു; അദ്ദേഹത്തിന്റെ തോളിൽ അവൻ തുടരേ കണ്ണീരൊഴുക്കി.","p":1},{"v":30,"t":"ഇസ്രായേൽ ജോസഫിനോടു പറഞ്ഞു: ഒടുവിൽ നിന്റെ മുഖം ഞാൻ കണ്ടുകഴിഞ്ഞിരിക്കെ, ഞാൻ മരിച്ചുകൊള്ളട്ടെ! നീ ഇനിയും ജീവനോടിരിക്കുന്നുവല്ലോ.","p":1},{"v":31,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരോടും തന്റെ പിതൃകുടുംബത്തോടുമായി പറഞ്ഞു: ഞാൻ പോയി ഫറവോയോടു വിവരിക്കട്ടെ. അദ്ദേഹത്തോട് ഞാൻ പറയാം: കാനാൻദേശത്തായിരുന്ന എന്റെ സഹോദരന്മാരും പിതൃകുടുംബംമുഴുവനും എന്റെയടുത്തു വന്നിട്ടുണ്ട്.","p":1},{"v":32,"t":"ഈ ആളുകൾ മൃഗങ്ങളെ മേയ്ക്കുന്നവരാണ്; അതായത്, കന്നുകാലിവളർത്തുകാരാണ്. അവരുടെ ആടുമാടുകളും അവർക്കുള്ളതൊക്കെയും അവർ കൊണ്ടുവന്നിട്ടുണ്ട്.","p":1},{"v":33,"t":"അപ്പോൾ, ഫറവോ നിങ്ങളെ വിളിച്ച് നിങ്ങളുടെ തൊഴിലുകൾ എന്തൊക്കെയാണെന്നു ചോദിക്കുമ്പോൾ","p":1},{"v":34,"t":"നിങ്ങൾ പറയണം: അങ്ങയുടെ ദാസന്മാർ, ഞങ്ങളെപ്പോലെതന്നെ ഞങ്ങളുടെ പൂർവികരും, ഞങ്ങളുടെ ചെറുപ്പംമുതൽ ഇതുവരെ കന്നുകാലിവളർത്തുകാരാണ്. അങ്ങനെയെങ്കിലേ നിങ്ങൾക്ക് ഗോഷെൻനാട്ടിൽ പാർക്കാനൊക്കു. കാരണം ആളിക്കുന്ന എല്ലാവരും ഈജിപ്തുകാർക്ക് മ്ലേച്ഛരാണ്.","p":1}],"47":[{"h":"ഫറവോയുടെ മുമ്പിൽ"},{"v":1,"t":"ജോസഫ് ചെന്ന് ഫറവോയോട് വിവരിച്ചു: എന്റെ പിതാവും സഹോദരന്മാരും അവരുടെ ആടുമാടുകളും അവർക്കുള്ള സകലതും കാനാൻദേശത്തുനിന്ന് എത്തിച്ചേർന്നിരിക്കുന്നു. അവരിതാ, ഗോഷെൻദേശത്തുണ്ട്.","p":1},{"v":2,"t":"അവൻ തന്റെ സഹോദരന്മാർക്കിടയിൽനിന്ന് അഞ്ചുപേരെ തിരഞ്ഞെടുത്ത് അവരെ ഫറവോയുടെമുമ്പിൽ കൊണ്ടുചെന്നു.","p":1},{"v":3,"t":"അവന്റെ സഹോദരന്മാരോടു ഫറവോ ചോദിച്ചു: നിങ്ങളുടെ തൊഴിലുകൾ എന്തൊക്കെയാണ്? അവർ ഫറവോയോടു പറഞ്ഞു: അങ്ങയുടെ ദാസർ, ഞങ്ങളെപ്പോലെതന്നെ ഞങ്ങളുടെ പൂർവികരും, മൃഗങ്ങളെ മേയ്ക്കുന്നവരാണ്.","p":1},{"v":4,"t":"തുടർന്ന് അവർ പറഞ്ഞു: ഇവിടെ തത്കാലവാസത്തിനാണ് ഞങ്ങൾ വന്നിരിക്കുന്നത്. എന്തെന്നാൽ, കാനാൻദേശത്തു ക്ഷാമം രൂക്ഷമായതുകൊണ്ട് അങ്ങയുടെ ദാസരുടെ കാലിക്കൂട്ടത്തിന് തീറ്റയില്ലാതായിരിക്കുന്നു. അതുകൊണ്ട്, ഇപ്പോൾ അങ്ങയുടെ ദാസർ ഗോഷെൻദേശത്തു കുടിപാർക്കാൻ ദയചെയ്യണമേ!","p":1},{"v":5,"t":"അപ്പോൾ ഫറവോ ജോസഫിനോട് ഇപ്രകാരം പറഞ്ഞു: നിന്റെ പിതാവും നിന്റെ സഹോദരന്മാരും നിന്റെയടുത്തേക്കു വന്നിരിക്കുകയാണല്ലോ.","p":1},{"v":6,"t":"ഈജിപ്തുനാടു നിനക്കുമുമ്പിലുണ്ട്. നാടിന്റെ മെച്ചപ്പെട്ട ഭാഗത്ത് നിന്റെ പിതാവിനെയും നിന്റെ സഹോദരന്മാരെയും പാർപ്പിക്കുക. അവർ ഗോഷെൻദേശത്തു താമസിക്കട്ടെ. അവരിൽ കാര്യശേഷിയുള്ളവരുണ്ടെന്നു നിനക്കറിയാമെങ്കിൽ അവരെ എന്റെ കന്നുകാലിക്കൂട്ടത്തിന്റെ മേലാളന്മാരായി നിയോഗിക്കുക.","p":1},{"v":7,"t":"അതിനുശേഷം ജോസഫ് തന്റെ പിതാവായ യാക്കോബിനെ വരുത്തി ഫറവോയുടെ മുമ്പിൽ നിർത്തി. യാക്കോബ് ഫറവോയെ അനുഗ്രഹിച്ചു.","p":1},{"v":8,"t":"താങ്കളുടെ ആയുഷ്കാലസംവത്സരങ്ങൾ എത്രയാണ്? ഫറവോ യാക്കോബിനോടു ചോദിച്ചു.","p":1},{"v":9,"t":"എന്റെ ദേശാന്തരവാസകാലം നൂറ്റിമുപ്പതു വർഷമാണ്. ഹ്രസ്വമെങ്കിലും ദുരിതപൂർണമായിരുന്നു എന്റെ ആയുഷ്കാലസംവത്സരങ്ങൾ. എന്നാൽ, എന്റെ പിതാക്കന്മാരുടെ ദേശാന്തരവാസകാലത്തിലെ അവരുടെ ആയുഷ്കാലസംവത്സരങ്ങളെ അവ മറികടന്നിട്ടില്ല.","p":1},{"v":10,"t":"ഫറവോയെ അനുഗ്രഹിച്ചശേഷം യാക്കോബ് ഫറവോയുടെ സന്നിധിയിൽനിന്ന് പോയി.","p":1},{"v":11,"t":"ഫറവോ കൽപ്പിച്ചപോലെ, ഈജിപ്തുനാട്ടിലെ മെച്ചപ്പെട്ട ഒരു പ്രദേശം റംസേസ്നാട്ടിൽ അവകാശമായി നൽകി, ജോസഫ് തന്റെ പിതാവിനെയും സഹോദരന്മാരെയും അധിവസിപ്പിച്ചു.","p":1},{"v":12,"t":"ജോസഫ് തന്റെ പിതാവിനും സഹോദരന്മാർക്കും തന്റെ പിതൃഭവനം മുഴുവനും, ആശ്രിതരുടെ എണ്ണമനുസരിച്ച്, ആഹാരം കൊടുത്തുപോന്നു.","p":1},{"h":"ക്ഷാമം രൂക്ഷമാകുന്നു"},{"v":13,"t":"ക്ഷാമം ഏറെ രൂക്ഷമായിരുന്നതിനാൽ നാട്ടിലെങ്ങും ആഹാരമില്ലാതായി. ഈജിപ്തുദേശവും കാനാൻദേശവും ക്ഷാമംമൂലം വലഞ്ഞു.","p":1},{"v":14,"t":"ഈജിപ്തുദേശത്തും കാനാൻദേശത്തും ലഭ്യമായ പണമുഴുവൻ അവർ വാങ്ങിയ ധാന്യത്തിനു വിലയായി ജോസഫ് ശേഖരിച്ചു. ആ പണം അവൻ ഫറവോയുടെ ഭവനത്തിലേക്കു മുതൽകൂട്ടി.","p":1},{"v":15,"t":"ഈജിപ്തുദേശത്തും കാനാൻദേശത്തുമുള്ള പണം തീർന്നപ്പോൾ ഈജിപ്തുകാരെല്ലാം ജോസഫിന്റെയടുത്തു വന്നു പറഞ്ഞു: ഞങ്ങൾക്ക് ആഹാരം തരുക. പണം തീർന്നെന്ന കാരണത്താൽ ഞങ്ങൾ എന്തിന് അങ്ങയുടെമുമ്പിൽ മരിക്കണം?","p":1},{"v":16,"t":"ജോസഫ് പറഞ്ഞു: പണം തീർന്നെങ്കിൽ നിങ്ങളുടെ കന്നുകാലികളെ തരുവിൻ; നിങ്ങളുടെ കന്നുകാലികൾക്കു വിലയായി ഞാൻ നിങ്ങൾക്ക് അതു തരാം.","p":1},{"v":17,"t":"തങ്ങളുടെ കന്നുകാലികളെ അവർ ജോസഫിന്റെയടുത്തു കൊണ്ടുവന്നു. കുതിരകൾക്കും ആട്ടിൻപറ്റത്തിനും കന്നുകാലിക്കൂട്ടത്തിനും കഴുതകൾക്കും വിലയായി ജോസഫ് അവർക്ക് ആഹാരം കൊടുത്തു. അവൻ അവരുടെ കന്നുകാലികൾക്കെല്ലാം വിലയായി അവർക്ക് ആ വർഷത്തേക്ക് ആഹാരം വിതരണംചെയ്തു.","p":1},{"v":18,"t":"ആ വർഷം അവസാനിച്ച് രണ്ടാം വർഷം അവർ അവന്റെയടുത്തുചെന്ന് അവനോടു പറഞ്ഞു: പണം തീർന്ന കാര്യം യജമാനനിൽനിന്നു ഞങ്ങൾ മറച്ചുവെക്കുന്നില്ല. മൃഗസമ്പത്ത് യജമാനന്റേതായി; യജമാനസമക്ഷം ഞങ്ങളുടെ ദേഹവും നിലവുമല്ലാതെ ഞങ്ങൾക്കിനി ഒന്നും അവശേഷിക്കുന്നില്ല.","p":1},{"v":19,"t":"ഞങ്ങളെന്തിനു മരിക്കണം? ഞങ്ങളും ഞങ്ങളുടെ നിലവും അങ്ങയുടെ കൺമുമ്പിലുണ്ട്. ആഹാരത്തിനു വിലയായി ഞങ്ങളുടെ നിലം വാങ്ങിയാലും! ഞങ്ങളും ഞങ്ങളുടെ നിലവും ഫറവോയ്ക്ക് അടിമകളായിരിക്കും. ഞങ്ങൾ മരിക്കാതെ ജീവിച്ചുപോകാനും നിലം തരിശാകാതിരിക്കാനുംവേണ്ടി വിത്തു തന്നാലും.","p":1},{"v":20,"t":"അങ്ങനെ ജോസഫ് ഈജിപ്തുകാരുടെ നിലമുഴുവൻ ഫറവോയ്ക്കുവേണ്ടി വാങ്ങി. എന്തെന്നാൽ, ക്ഷാമം തങ്ങളുടെമേൽ ശക്തിപ്രാപിച്ചപ്പോൾ ഈജിപ്തുകാരെല്ലാവരും തങ്ങളുടെ വയൽ വിറ്റു; അങ്ങനെ നാട് ഫറവോയുടേതായി.","p":1},{"v":21,"t":"ജനത്തെയ ആകട്ടെ, ഈജിപ്തിന്റെ അതിർത്തിയുടെ ഒരറ്റംമുതൽ മറ്റേയറ്റംവരെ","p":1},{"v":21,"t":"അവൻ പട്ടണങ്ങളിലേക്ക് ഒഴിപ്പിച്ചു.","p":1},{"v":22,"t":"പുരോഹിതന്മാർക്കായി ഒരു വിഹിതം ഫറവോയിൽനിന്ന് ഉണ്ടായിരുന്നതിനാൽ, പുരോഹിതന്മാരുടെ നിലം മാത്രം അവൻ വാങ്ങിയില്ല. അവരാകട്ടെ, ഫറവോ അവർക്കു നൽകിയിരുന്ന അവരുടെ വിഹിതം ഭക്ഷിച്ചുപോന്നു. അതിനാൽ, അവർ തങ്ങളുടെ നിലം വിറ്റില്ല.","p":1},{"v":23,"t":"ജോസഫ് ജനങ്ങളോടു പറഞ്ഞു: നോക്കൂ, ഇന്ന് ഞാൻ നിങ്ങളെയും നിങ്ങളുടെ നിലവും ഫറവോയ്ക്കായി വാങ്ങിയിരിക്കുന്നു. ഇതാ, നിങ്ങൾക്കുള്ള വിത്ത്; നിങ്ങൾക്ക് നിലംവിതയ്ക്കാം.","p":1},{"v":24,"t":"വിളവുണ്ടാകുമ്പോൾ അഞ്ചിലൊന്ന് നിങ്ങൾ ഫറവോയ്ക്കു കൊടുക്കണം. നാലുഭാഗം നിങ്ങൾക്ക് വയൽവിത്തിനും നിങ്ങളുടെ ഭക്ഷണത്തിനുമാണ്, നിങ്ങളുടെ വീട്ടിലുള്ളവരുടെയും നിങ്ങളുടെ കുഞ്ഞുങ്ങളുടെയും ഭക്ഷണത്തിനുവേണ്ടിയുള്ളത്.","p":1},{"v":25,"t":"അവർ പറഞ്ഞു: അങ്ങ് ഞങ്ങളുടെ ജീവൻ കാത്തു. ഞങ്ങൾ യജമാനന്റെ ദൃഷ്ടികളിൽ പ്രീതി കണ്ടെത്തട്ടെ. ഞങ്ങൾ ഫറവോയ്ക്ക് അടിമകളായിരിക്കും.","p":1},{"v":26,"t":"അങ്ങനെ ജോസഫ് ഈജിപ്തിലെ നിലം സംബന്ധിച്ച് ഇന്നും പ്രാബല്യത്തിലുള്ള, അഞ്ചിലൊന്നു ഫറവോയ്ക്ക് എന്നൊരു നിയമം നടപ്പാക്കി. പുരോഹിതന്മാരുടെ നിലംമാത്രം അവരുടേതുമാത്രമായി; അത് ഫറവോയുടേതായില്ല.","p":1},{"h":"യാക്കോബിന്റെ അന്ത്യാഭിലാഷം"},{"v":27,"t":"ഇസ്രായേൽ ഈജിപ്തുനാട്ടിലെ ഗോഷെൻദേശത്തു പാർത്തു; അവർ അതിൽ അവകാശം സ്ഥാപിച്ചു; ഏറെ പെറ്റുപെരുകുകയും ചെയ്തു.","p":1},{"v":28,"t":"യാക്കോബ് ഈജിപ്തുനാട്ടിൽ പതിനേഴു വർഷം ജീവിച്ചു; യാക്കോബിന്റെ ആയുഷ്കാലം നൂറ്റിനാൽപ്പത്തേഴു വർഷമായിരുന്നു.","p":1},{"v":29,"t":"ഇസ്രായേലിന്റെ മരണത്തിനുള്ള ദിവസങ്ങളടുത്തപ്പോൾ, അദ്ദേഹം തന്റെ മകൻ ജോസഫിനെ വിളിച്ച് അവനോടു പറഞ്ഞു: ഞാൻ നിന്റെ ദൃഷ്ടികളിൽ പ്രീതികണ്ടെത്തിയെങ്കിൽ നിന്റെ കൈ എന്റെ തുടയുടെ കീഴിൽ വച്ചാലും. എന്നോടു കരുണയോടെയും വിശ്വസ്തതയോടെയും പ്രവർത്തിക്കണം. ദയചെയ്ത് എന്നെ ഈജിപ്തിൽ സംസ്കരിക്കരുത്.","p":1},{"v":30,"t":"ഞാൻ എന്റെ പിതാക്കന്മാരോടൊപ്പം കിടക്കുമ്പോൾ എന്നെ ഈജിപ്തിൽനിന്നു സംവഹിച്ച് അവരുടെ കുഴിമാടത്തിൽ സംസ്കരിക്കണം. അവൻ പറഞ്ഞു: അങ്ങയുടെ വാക്കുപോലെ ഞാൻ ചെയ്തുകൊള്ളാം.","p":1},{"v":31,"t":"എന്നോടു ശപഥംചെയ്യുക, അദ്ദേഹം പറഞ്ഞു; അവൻ അദ്ദേഹത്തോട് ശപഥം ചെയ്തു. അപ്പോൾ ഇസ്രായേൽ കട്ടിൽതലയ്ക്കൽ കുമ്പിട്ടു.","p":1}],"48":[{"h":"എഫ്രായിമിനും മനാസ്സെയ്ക്കും അനുഗ്രഹം"},{"v":1,"t":"ഈകാര്യങ്ങൾക്കുശേഷം ജോസഫിനോട് ഒരാൾ പറഞ്ഞു: ഇതാ, നിന്റെ പിതാവ് രോഗിയാണ്. അപ്പോൾ അവൻ തന്റെ രണ്ടു പുത്രന്മാരെ, മനാസ്സെയെയും എഫ്രായിമിനെയും, കൂടെക്കൊണ്ടുപോയി.","p":1},{"v":2,"t":"അവൻ യാക്കോബിനെ അറിയിച്ചുകൊണ്ട് പറഞ്ഞു: ഇതാ അങ്ങയുടെ മകനായ ജോസഫ് അങ്ങയുടെ അടുത്തേക്കു വരുന്നു. അപ്പോൾ ഇസ്രായേൽ ശക്തി സംഭരിച്ച് കിടക്കയിൽ എഴുന്നേറ്റിരുന്നു.","p":1},{"v":3,"t":"യാക്കോബ് ജോസഫിനോടു പറഞ്ഞു: കാനാൻദേശത്തുള്ള ലൂസിൽവെച്ച് ഏൽ ഷദ്ദായ് എനിക്ക് പ്രത്യക്ഷപ്പെട്ട് എന്നെ അനുഗ്രഹിച്ചു.","p":1},{"v":4,"t":"അവിടന്ന് എന്നോട് അരുൾചെയ്തു ഇതാ, ഞാൻ നിന്നെ സന്താനപുഷ്ടിയുള്ളവനാക്കി വർധിപ്പിക്കും. നിന്നെ ഞാൻ ജനങ്ങളുടെ ഒരു സമൂഹമാക്കും. നിനക്കുശേഷം നിന്റെ സന്തതിക്കു നിത്യവകാശമായി ഈ നാട് ഞാൻ നൽകും.","p":1},{"v":5,"t":"ഞാൻ ഈജിപ്തിൽ നിന്റെ അടുത്തേത്തുന്നതിനുമുമ്പ് നിനക്ക് ഈജിപ്തുനാട്ടിൽ ജനിച്ച നിന്റെ പുത്രന്മാരിരുവരും, എഫ്രായിമും മനാസ്സെയും, ഇപ്പോൾ എന്റേതാണ്. റൂബനും ശിമെയോനും എന്നപോലെ അവർ എന്റേതായിരിക്കും.","p":1},{"v":6,"t":"അവർക്കുശേഷം നീ ജനിപ്പിക്കുന്ന നിന്റെ സന്താനങ്ങൾ നിന്റേതായിരിക്കും. അവർ തങ്ങളുടെ അവകാശത്തിൽ തങ്ങളുടെ സഹോദരന്മാരുടെ പേരിലായിരിക്കും അറിയപ്പെടുന്നത്.","p":1},{"v":7,"t":"ഞാൻ പദാനിൽനിന്നു പോരുമ്പോൾ വഴിക്ക് കാനാൻദേശത്തുവെച്ച്, എഫ്രാത്തായിലെത്താൻ ഒരു കിബ്റാ ദുരംകൂടി ഉണ്ടായിരുന്നപ്പോൾ, റാഹേൽ എൻ്റെമേൽ ചാഞ്ഞുമരിച്ചു, എഫ്രാത്തായിലേക്കുള്ള, അതായത് ബേത്ലെഹെമിലേക്കുള്ള വഴിയിൽ, ഞാൻ അവളെ സംസ്കരിച്ചു.","p":1},{"v":8,"t":"ജോസഫിന്റെ പുത്രന്മാരെ കണ്ടപ്പോൾ ഇസ്രായേൽ ചോദിച്ചു: ഇവർ ആരാണ്?","p":1},{"v":9,"t":"ജോസഫ് തന്റെ പിതാവിനോടു പറഞ്ഞു: ഇവിടെ വെച്ച് ദൈവം എനിക്ക് തന്ന എന്റെ മക്കളാണിവർ. അദ്ദേഹം പറഞ്ഞു: ഞാൻ അവരെ അനുഗ്രഹിക്കേണ്ടതിന് അവരെ എന്റെയടുക്കൽ കൊണ്ടുവന്നാലും.","p":1},{"v":10,"t":"പ്രായംകൊണ്ട് കണ്ണുകൾ മ","p":1},{"v":10,"t":"വീങ്ങിയിരുന്നതിനാൽ ഇസ്രായേലിനു കാണാൻ കഴിയുമായിരുന്നില്ല. അദ്ദേഹത്തിന്റെ അടുത്ത് അവൻ അവരെ കൊണ്ടചെന്നു. അദ്ദേഹം അവരെ കെട്ടിപ്പിടിച്ച് ചുംബിച്ചു.","p":1},{"v":11,"t":"ഇസ്രായേൽ ജോസഫിനോടു പറഞ്ഞു: നിന്റെ മുഖം കാണുമെന്നു ഞാൻ വിചാരിച്ചിരുന്നില്ല. എന്നാൽ ഇതാ, നിന്റെ സന്തതിയെക്കൂടി ദൈവം എന്നെ കാണിച്ചിരിക്കുന്നു!","p":1},{"v":12,"t":"അപ്പോൾ, ജോസഫ് അവരെ അദ്ദേഹത്തിന്റെ മുട്ടുകളിൽനിന്ന് മാറ്റിയിട്ട്, നിലംപറ്റെ തന്റെ മുഖം കുനിച്ചു.","p":1},{"v":13,"t":"പിന്നെ ജോസഫ് ഇരുവരെയും എഫ്രായിമിനെ തന്റെ വലത്തുകൈകൊണ്ട് ഇസ്രായേലിന്റെ ഇടത്തുകൈക്കുനേരെയും, മനാസ്സെയെ തന്റെ ഇടത്തുകൈകൊണ്ട് ഇസ്രായേലിന്റെ വലത്തുകൈക്കുനേരെയും നിർത്തി, അദ്ദേഹത്തിന്റെയടുത്തേക്കു കൊണ്ടുചെന്നു.","p":1},{"v":14,"t":"എന്നാൽ, ഇസ്രായേൽ തന്റെ കൈകൾപിണച്ച് വലതുകൈ എഫ്രായിമിന്റെ തലയിലും ഇടതുകൈ മനാസ്സെയുടെ തലയിലുമാണ് വെച്ചത്. മനാസ്സെയായിരുന്നല്ലോ കടിഞ്ഞൂൽ പുത്രൻ.","p":1},{"v":15,"t":"അവൻ ജോസഫിനെ അനുഗ്രഹിച്ചുകൊണ്ട് പറഞ്ഞു: എന്റെ പിതാക്കന്മാരായ അബ്രഹാമും ഇസഹാക്കും ഏതു ദൈവത്തിന്റെമുമ്പിൽ വ്യാപരിച്ചിരുന്നവോ അവിടന്ന്, എന്റെ ആരംഭംമുതൽ ഇന്നുവരെ എന്നെ മേയിച്ചിരുന്ന ദൈവം,","p":1},{"v":16,"t":"തിന്മയായ എല്ലാറ്റിൽനിന്നും എന്നെ വീണ്ടെടുത്ത ദൂതൻ ഈ ബാലന്മാരെ അനുഗ്രഹിക്കട്ടെ! എന്റെ നാമവും എന്റെ പിതാക്കന്മാരായ അബ്രഹാത്തിന്റെയും ഇസഹാക്കിന്റെയും നാമവും അവയിലൂടെ വിളിക്കപ്പെടട്ടെ! അവർ ഭൂമധ്യേ പുരുഷാരമായി നിറയട്ടെ!","p":1},{"v":17,"t":"തന്റെ പിതാവ് തന്റെ വലതുകൈ എഫ്രായിമിന്റെ തലയിൽ വെച്ചിരിക്കുന്നത് ജോസഫ് കണ്ടു; അവന്റെ ദൃഷ്ടികളിൽ അത് അനിഷ്ടകരമായി. എഫ്രായിമിന്റെ തലയിൽനിന്ന് മനാസ്സെയുടെ തലയിലേക്ക് അതു മാറ്റാൻ അവൻ പിതാവിന്റെ കൈയിൽ കടന്നുപിടിച്ചു.","p":1},{"v":18,"t":"ജോസഫ് തന്റെ പിതാവിനോടു പറഞ്ഞു: എന്റെ പിതാവേ, അങ്ങനെയല്ല, ഇവാനാണല്ലോ ആദ്യജാതൻ. അങ്ങയുടെ വലതുകൈ ഇവന്റെ തലയിൽ വെക്കണേ.","p":1},{"v":19,"t":"അവന്റെ പിതാവ് നിരസിച്ചുകൊണ്ട് പറഞ്ഞു: എനിക്കറിയാം, എന്റെ മകനേ, എനിക്കറിയാം. അവനും ഒരു ജനമായിതീരും; അവനും വലിയവനാകും. എന്നാൽ അവന്റെ ഇളയ സഹോദരൻ അവനെക്കാൾ വലിയവനാകും; അവന്റെ സന്തതിയാകട്ടെ, ജനങ്ങളുടെ മഹാഗണവും.","p":1},{"v":20,"t":"അവരെ അനുഗ്രഹിച്ചുകൊണ്ട് ആ ദിവസം അദ്ദേഹം പറഞ്ഞു: നിന്നെക്കൊണ്ട് ഇസ്രായേൽ ഇപ്രകാരം അനുഗ്രഹിക്കും: ദൈവം നിന്നെ എഫ്രായിമിനെയുംപോലെയും മനാസ്സെയെപ്പോലെയും സുസ്ഥാപിതമാക്കട്ടെ! അദ്ദേഹം എഫ്രായിമിനെ മനാസ്സെയ്ക്കു മുമ്പനാക്കി.","p":1},{"v":21,"t":"അതു കഴിഞ്ഞ്, ഇസ്രായേൽ ജോസഫിനോടു പറഞ്ഞു: ഞാൻ ഇതാ, മരിക്കാറായി. ദൈവം നിങ്ങളുടെ കൂടെയുണ്ടാകും. അവിടന്ന് നിങ്ങളെ നിങ്ങളുടെ പിതാക്കന്മാരുടെ നാട്ടിലേക്ക് തിരിയെ കൊണ്ടുചെന്നാക്കും.","p":1},{"v":22,"t":"എന്റെ വാളും വില്ലുംകൊണ്ട് അമോര്യരുടെ കയ്യിൽനിന്ന് പിടിച്ചെടക്കിയ ഷെക്കെം, നിന്റെ സഹോദരന്മാർക്കുള്ളതിനേക്കാൾ ഒന്നുകൂടുതലായി, നിനക്കു ഞാൻ തരുന്നു.","p":1}],"49":[{"h":"യാക്കോബിന്റെ അനുഗ്രഹം"},{"v":1,"t":"യാക്കോബ് തന്റെ മക്കളെ വിളിച്ച് പറഞ്ഞു: ഒന്നിച്ചുകൂടുവിൻ. വരുംകാലങ്ങളിൽ നിങ്ങൾക്ക് എന്തു സംഭവിക്കുമെന്ന് ഞാൻ നിങ്ങളോട് വിശദീകരിക്കാം.","p":1},{"v":2,"t":"യാക്കോബിന്റെ പുത്രന്മാരേ, ഒന്നിച്ചുകൂടി കേൾക്കുവിൻ. നിങ്ങളുടെ പിതാവായ ഇസ്രായേലിനെ ശ്രദ്ധിക്കുവിൻ.","p":1},{"v":3,"t":"റൂബൻ, നീ എന്റെ ആദ്യജാതനാണ്; എന്റെ ശക്തിയും എന്റെ പൗരുഷത്തിന്റെ ആരംഭവും; പ്രാഗല്ഭ്യത്തിന്റെ മഹത്വവും ശക്തിയുടെ മഹത്വവും.","p":1},{"v":4,"t":"വെള്ളംപോലെ അസ്ഥിരനായ നീ പ്രഥമസ്ഥാനീയനാകില്ല. എന്തെന്നാൽ, നീ നിന്റെ പിതാവിന്റെ കിടക്കയിൽ കയറി - അതെ, എന്റെ ശയ്യ നീ അശുദ്ധമാക്കിയ കയറ്റം!","p":1},{"v":5,"t":"ശിമയോനും ലേവിയും സഹോദരന്മാരാണ്. അവരുടെ വാളുകൾ അക്രമത്തിന്റെ ആയുധങ്ങളാണ്.","p":1},{"v":6,"t":"അവരുടെ ഗൂഢാലോചനയിൽ എന്റെ ആത്മാവ് പങ്കുകൊള്ളാതിരിക്കട്ടെ അവരുടെ സമ്മേളനത്തിൽ എന്റെ മഹത്വം ചേരാതിരിക്കട്ടെ. എന്തെന്നാൽ, തങ്ങളുടെ കോപത്തിൽ അവർ മനുഷ്യനെ കൊന്നു. തങ്ങളുടെ സ്വാർഥസന്തോഷത്തിന് അവർ കാളകളുടെ കുതിഞരമ്പ് വെട്ടി.","p":1},{"v":7,"t":"ശക്തമായിരുന്നതുകൊണ്ട് അവരുടെ കോപവും ഉഗ്രമായിരുന്നതുകൊണ്ട് അവരുടെ ക്രോധവും ശപിക്കപ്പെടട്ടെ! ഞാൻ അവരെ യാക്കോബിൽ വീതംവെക്കും; ഇസ്രായേലിൽ ഞാൻവരെ ചിതറിക്കുകയും ചെയ്യും.","p":1},{"v":8,"t":"നീയോ യൂദാ, നിന്റെ സഹോദരന്മാർ നിന്നെ അംഗീകരിക്കും; നിന്റെ കൈ നിന്റെ ശത്രുക്കളുടെ പിടലിയിലായിരിക്കും. നിന്റെ പിതാവിന്റെ പുത്രന്മാർ നിന്നെ കുമ്പിടും.","p":1},{"v":9,"t":"യൂദാ ഒരു യുവസിംഹമാണ്. എന്റെ മകനേ, നീ ഇരയിൽനിന്ന് ഉയർന്നുവരുന്നു. അവൻ ഒരു സിംഹത്തെപ്പോലെയും സിംഹിയെപ്പോലെയും പതുങ്ങിവിശ്രമിക്കുന്നു. അവനെ ആര് ഉണർത്തും?","p":1},{"v":10,"t":"യൂദായിൽനിന്ന് ചെങ്കോൽ വിട്ടകലുകയില്ല; അധികാരദണ്ഡ് അവന്റെ പാദങ്ങൾക്കിടയിൽ നിന്നും. അവൻ ശീലോയിൽ വന്നുയെത്തുന്നതുവരെ ജനങ്ങളുടെ അനുസരണം അവനു സ്വന്തമായിരിക്കും.","p":1},{"v":11,"t":"അവൻ തന്റെ കഴുതയെ മുന്തിരിവള്ളിയിൽ കെട്ടിയിടും; തന്റെ കഴുതക്കുട്ടിയെ ദ്രാക്ഷാവള്ളിയിലും. അവൻ തന്റെ ഉടുപ്പ് മുന്തിരിച്ചാറിൽ കഴുകും; തന്റെ മേലങ്കി ദ്രാക്ഷാരസത്തിലും.","p":1},{"v":12,"t":"വീഞ്ഞിനെക്കാൾ തിളക്കമുള്ള കണ്ണിണ പാലിനെക്കാൾ വെളുത്ത ദംഷ്ട്രദ്വയം.","p":1},{"v":13,"t":"സെബുലൂണാകട്ടെ, കടൽത്തീരത്തു വസിക്കും; അവൻ കപ്പലുകൾക്കു തീരമായിരിക്കും; സീദോനുമേലും അവന്റെ അതിർത്തിയായിരിക്കും.","p":1},{"v":14,"t":"ഇസ്സാക്കർ എല്ലുള്ള ഒരു കഴുതയാണ്; അവൻ രണ്ട് ആലകങ്ങൾക്കിടയിൽ വിശ്രമിക്കുന്നു.","p":1},{"v":15,"t":"വിശ്രമസ്ഥലം നല്ലതെന്ന് അവൻ കണ്ടു, ദേശം മനോഹരമാണെന്നും. അതുകൊണ്ട് അവൻ ചുമടെടുക്കാൻ തന്റെ ചുമൽ കുനിച്ചു; കൂലിവേലചെയ്യുന്ന ഒരു കരാറുപണിക്കാരനായി.","p":1},{"v":16,"t":"ദാൻ സ്വജനത്തിനു ന്യായം നടത്തിക്കൊടുക്കും, ഇസ്രായേലിലെ ഗോത്രങ്ങളിലൊന്നിനെപ്പോലെ.","p":1},{"v":17,"t":"ദാൻ വഴിവക്കിൽ സർപ്പമായിരിക്കട്ടെ; പാതയോരത്ത് അണലിയും. അവൻ കുതിരയുടെ കുതികാലുകൾ കടിക്കും; കുതിരക്കാരൻ മലർന്നുവീഴുകയും ചെയ്യും.","p":1},{"v":18,"t":"കർത്താവേ, ഞാൻ അങ്ങയുടെ രക്ഷയ്ക്കായി കാത്തിരിക്കുന്നു.","p":1},{"v":19,"t":"ഗാദിനെപ്പറ്റി: കവർച്ചക്കാർ അവനെ കൊള്ളയടിക്കും; എന്നാൽ, അവൻ പതിയിരുന്ന് ആക്രമിക്കും.","p":1},{"v":20,"t":"ആശേറിനെപ്പറ്റി: അവന്റെ ആഹാരം സമൃദ്ധമായിരിക്കും; രാജാവിനുള്ള വിശിഷ്ടഭവനങ്ങൾ അവൻ പ്രദാനം ചെയ്യും.","p":1},{"v":21,"t":"നഫ്താലി സ്വച്ഛന്ദതയുള്ള ഒരു പേടമാനാണ്; അവൻ മൃദുലോകതികൽ പൊഴിക്കുന്നു.","p":1},{"v":22,"t":"ജോസഫ് ഒരു ഫലവൃക്ഷകുമാരനാണ്; നീരുറവയ്ക്കുമീതെയുള്ള ഫലവൃക്ഷകുമാരൻ; ശാഖാകുമാരികൾ മതിലിനുമീതെ പന്തലിക്കുന്നു.","p":1},{"v":23,"t":"വില്ലാളിവീരന്മാർ അമ്പെയ്ത് അവനെ തിക്തതയിലാഴ്ത്തി; അവർ അവനോടു ശത്രുത പുലർത്തി.","p":1},{"v":24,"t":"എന്നാൽ, അവന്റെ വില്ല് ഉറച്ചുനിന്നു; അവന്റെ കൈപ്പത്തികൾ അയവുള്ളതായി,","p":1},{"v":24,"t":"യാക്കോബിന്റെ ശക്തനായവന്റെ കൈകളിൽനിന്ന്, ഇസ്രായേലിന്റെ പാറയായ ഇടയൻ ഉള്ള ഇടത്തുനിന്ന്,","p":1},{"v":25,"t":"നിന്നെ സഹായിക്കുന്ന നിന്റെ പിതാവിന്റെ ദൈവത്തിൽനിന്ന്, നിന്നെ അനുഗ്രഹിക്കുന്ന സർവശക്തനോടൊത്ത് ഉന്നതത്തിൽനിന്ന് ആകാശങ്ങളുടെ അനുഗ്രഹങ്ങൾ, അഗാധത്തിൽ വിശ്രമിക്കുന്ന ആഴത്തിന്റെ അനുഗ്രഹങ്ങൾ, മാരിടത്തിന്റെയും ഉദരത്തിന്റെയും അനുഗ്രഹങ്ങൾ,","p":1},{"v":26,"t":"നിന്റെ പിതാവിന്റെ അനുഗ്രഹങ്ങൾ, എന്റെ പർവതങ്ങളുടെ അനുഗ്രഹങ്ങൾക്കുമേൽ നിത്യശ്യംഗങ്ങളുടെ സീമവരെ വളരുന്നു. അവ ജോസഫിന്റെ ശിരസ്സിൽ ആയിരിക്കട്ടെ! സ്വസഹോദരരുടെ നേതാവിന്റെ മൂർധാവിൽത്തന്നെ!"},{"v":27,"t":"ബെഞ്ചമിൻ ആർത്തിയുള്ള ഒരു ചെന്നായാണ്. അവൻ രാവിലെ കൊള്ളയടിക്കുകയും വൈകുന്നേരം കവർച്ചമുതൽ പങ്കിടുകയും ചെയ്യും.","p":1},{"v":28,"t":"ഇവരെല്ലാമാണ് ഇസ്രായേലിലെ പന്ത്രണ്ടു ഗോത്രങ്ങൾ. അവരുടെ പിതാവ് അവരോടു പറഞ്ഞതാണിത്; അദ്ദേഹം അവരെ പ്രത്യേകം പ്രത്യേകം അനുഗ്രഹിച്ചു, തന്റെ സംപ്രീതിക്കനുസൃതം അവരെ അനുഗ്രഹിച്ചു.","p":1},{"h":"യാക്കോബിന്റെ മരണവും സംസ്കാരവും"},{"v":29,"t":"അദ്ദേഹം അവരോടു കൽപ്പിച്ചരുളി: ഞാൻ എന്റെ ജനത്തോടു ചേരുകയാണ്. എന്റെ പിതാക്കന്മാരുടെ അടുത്ത്, ഹിത്യനായ എഫ്രോണിന്റെ പറമ്പിലുള്ള ഗുഹയിൽ, എന്നെ സംസ്കരിക്കണം;","p":1},{"v":30,"t":"കാനാൻദേശത്ത് മാമ്രേക്കു മുമ്പിലായി മക്പെലായുടെ പറമ്പിലുള്ള ആ ഗുഹയിൽതന്നെ. അബ്രഹാം കല്ലറയ്ക്കുള്ള അവകാശമായി ഹിത്യനായ എഫ്രോണിൽനിന്ന് വാങ്ങിയതാണ് ആ പറമ്പ്.","p":1},{"v":31,"t":"അബ്രഹാമും അദ്ദേഹത്തിന്റെ ഭാര്യ സാറായെയും അവിടെയാണ് അവർ അടക്കംചെയ്തത്. അവിടെതന്നെയാണ് ഇസഹാക്കിനെയും അദ്ദേഹത്തിന്റെ ഭാര്യ റബേക്കായെയും സംസ്കരിച്ചത്. ഞാൻ ലെയായെ സംസ്കരിച്ചതും അവിടെതന്നെ.","p":1},{"v":32,"t":"ആ പറമ്പിന്റെയും അതിലുള്ള ഗുഹയുടെയും കൈവശാവകാശം ഹിത്യരുടെപക്കൽ നിന്നുള്ളതാണ്.","p":1},{"v":33,"t":"തന്റെ പുത്രന്മാരോടു കൽപ്പിക്കാനുള്ളതു പൂർത്തിയാക്കി, യാക്കോബ് തന്റെ കാലുകൾ കിടക്കയോടു ചേർത്തു. അദ്ദേഹം അന്ത്യശ്വാസംവലിച്ച് തന്റെ ജനങ്ങളോടു ചേർന്നു.","p":1}],"50":[{"v":1,"t":"ജോസഫ് തന്റെ പിതാവിന്റെ മുഖത്തേക്കു വീണു; അദ്ദേഹത്തെ പ്രതി വിലപിക്കുകയും അദ്ദേഹത്തെ ചുംബിക്കുകയും ചെയ്തു.","p":1},{"v":2,"t":"ജോസഫ് തന്റെ ദാസന്മാരായ വൈദ്യന്മാരോട് തന്റെ പിതാവിനെ സുരഭീകരിക്കാൻ ആജ്ഞാപിച്ചു. വൈദ്യന്മാർ ഇസ്രായേലിനെ തൈലംപൂശി.","p":1},{"v":3,"t":"നാല്പതുദിവസംകൊണ്ട് അദ്ദേഹത്തിനു വേണ്ടി അവർ അതു പൂർത്തിയാക്കി. കാരണം, അങ്ങനെയാണ് അവർ സുരഭീകരണദിനങ്ങൾ പൂർത്തിയാക്കിയിരുന്നത്. ഈജിപ്തുകാർ എഴുപതു ദിവസം അദ്ദേഹത്തെപ്രതി വിലപിച്ചു.","p":1},{"v":4,"t":"അദ്ദേഹത്തിനുവേണ്ടിയുള്ള വിലാപദിനങ്ങൾ പിന്നിട്ടപ്പോൾ, ജോസഫ് ഫറവോയുടെ കുടുംബത്തോടു ഇപ്രകാരം പറഞ്ഞു: നിങ്ങളുടെ ദൃഷ്ടികളിൽ ഞാൻ സംപ്രീതി കണ്ടെത്തിയിട്ടുണ്ടെങ്കിൽ, ഫറവോയുടെ ചെവികളിൽ ഇപ്രകാരം ഉണർത്തിച്ചാലും:","p":1},{"v":5,"t":"എന്റെ പിതാവ് എന്നെക്കൊണ്ട് ഒരു പ്രതിജ്ഞ ചെയ്യിച്ചിരുന്നു. 'ഇതാ, ഞാൻ മരിക്കാറായി; എനിക്കുവേണ്ടി ഞാൻ കാനാൻദേശത്തു തയ്യാറാക്കിയിരിക്കുന്ന എന്റെ കല്ലറയിൽത്തന്നെ നീ എന്നെ സംസ്കരിക്കണം' എന്നാണ് അവൻ പറഞ്ഞത്.","p":1},{"v":6,"t":"അതുകൊണ്ട്, ഇപ്പോൾ 'ഞാൻ പോയി എന്റെ പിതാവിനെ സംസ്കരിച്ചു തിരിച്ചുവരട്ടെ'. ഫറവോ പറഞ്ഞു: അദ്ദേഹം നിന്നെക്കൊണ്ട് പ്രതിജ്ഞചെയ്യിച്ചതനുസരിച്ച് നീ പോയി നിന്റെ പിതാവിനെ സംസ്കരിക്കുക.","p":1},{"v":7,"t":"അങ്ങനെ ജോസഫ് തന്റെ പിതാവിനെ സംസ്കരിക്കാൻ പോയി. അവനോടൊപ്പം ഫറവോയുടെ എല്ലാ ദാസന്മാരും അവന്റെ വീട്ടിലെ കാരണവന്മാരും ഈജിപ്തുദേശത്തെ എല്ലാ മുതിർന്നവരും പോയി;","p":1},{"v":8,"t":"കൂടാതെ, ജോസഫിന്റെ കുടുംബം മുഴുവനും അവന്റെ സഹോദരന്മാരും അവന്റെ പിതാവിൻ്റെ കുടുംബവും തങ്ങളുടെ കുട്ടികളെയും ആടുമാടുകളെയും മാത്രമേ അവർ ഗോഷെൻ ദേശത്ത് നിർത്തിയുള്ളൂ","p":1},{"v":9,"t":"രഥവും കുതിരക്കാരും അവനോടൊപ്പം പോയി; അങ്ങനെ ആ വ്യൂഹം അതി സാന്ദ്രമായിരുന്നു","p":1},{"v":10,"t":"ജോർദാന് അക്കരെയുള്ള അത്താദിലെ മെതിക്കളംവരെ അവരെത്തി. അവിടെ അവർ വിപുലവും അതിതീവ്രവുമായ ഒരു ദുഖാചരണം നടത്തി. അവൻ ഏഴു ദിവസം തന്റെ പിതാനുവേണ്ടി വിലാപം അനുഷ്ഠിച്ചു.","p":1},{"v":11,"t":"അന്നാട്ടിൽ നിവസിച്ചിരുന്ന കാനാൻകാർ അത്താദിന്റെ മെതിക്കളത്തിൽ നടന്ന വിലാപം കണ്ടപ്പോൾ പറഞ്ഞു: ഇത് ഈജിപ്തുകാർക്ക് ഗൗരവമേറിയ ഒരു വിലാപംതന്നെ. അതുകൊണ്ട്, ജോർദ്ദാനക്കരയുള്ള ആബേൽ മിസ്രയിം എന്ന് അതിനെ പേരുവിളിക്കുന്നു.","p":1},{"v":12,"t":"എന്നിട്ട്, അദ്ദേഹത്തിന്റെ പുത്രന്മാർ, തങ്ങളോടു കൽപ്പിച്ചിരുന്നപോലെതന്നെ അദ്ദേഹത്തിനായി പ്രവർത്തിച്ചു.","p":1},{"v":13,"t":"അദ്ദേഹത്തിന്റെ പുത്രന്മാർ അദ്ദേഹത്തെ കാനാൻദേശത്തേക്കു സംവഹിച്ച് മക്പെലായുടെ പറമ്പിലെ ഗുഹയിൽ അവർ അദ്ദേഹത്തെ സംസ്കരിച്ചു. അബ്രഹാം മാമ്രേക്കു മുമ്പിലായി ഹിത്യനായ എഫ്രോണിൽനിന്ന് കല്ലറയ്ക്കുള്ള അവകാശമായി വാങ്ങിയതാണ് ആ പറമ്പ്.","p":1},{"v":14,"t":"തന്റെ പിതാവിനെ സംസ്കരിച്ചശേഷം ജോസഫ്, അവനും അവന്റെ സഹോദരന്മാരും അവന്റെ പിതാവിനെ സംസ്കരിക്കാനായി അവനോടുകൂടെ ഇറങ്ങിത്തിരിച്ച എല്ലാവരും, ഈജിപ്തിലേക്ക് മടങ്ങി.","p":1},{"h":"ജോസഫിന്റെ ഹൃദയവിശാലത"},{"v":15,"t":"തങ്ങളുടെ പിതാവ് മരിച്ചെന്നു കണ്ട് ജോസഫിന്റെ സഹോദരന്മാർ പറഞ്ഞു: ഇനി മിക്കവാറും ജോസഫ് നമ്മെ വെറുക്കുകയും നാം അവനോടു ചെയ്ത ദ്രോഹത്തിനെല്ലാം നമ്മോട് നിശ്ചയമായും പകരം വീട്ടുകയും ചെയ്യും.","p":1},{"v":16,"t":"അവർ ജോസഫിന് ഇപ്രകാരം ഒരു സന്ദേശം നൽകി: അങ്ങയുടെ പിതാവ് തന്റെ മരണത്തിനുമുമ്പ് ഇങ്ങനെ കൽപ്പിച്ചിരുന്നു:","p":1},{"v":17,"t":"ജോസഫിനോട് നിങ്ങൾ ഇപ്രകാരം പറയണം: ദയയുണ്ടാകണമെ! അങ്ങയുടെ സഹോദരന്മാരുടെ അതിക്രമവും പാപവും സന്ദയം ക്ഷമിക്കണമേ. എന്തെന്നാൽ, അവർ അങ്ങയോടു ദ്രോഹംചെയ്തു. എന്നാൽ, ഇപ്പോൾ അങ്ങയുടെ പിതാവിന്റെ ദൈവത്തിന്റെ ദാസന്മാരുടെ അതിക്രമം സദയം പൊറുക്കണമെ. തന്നോട് അവർ പറഞ്ഞതിനെപ്പറ്റി ജോസഫ് കരഞ്ഞുപോയി.","p":1},{"v":18,"t":"പിന്നീട് അവന്റെ സഹോദരന്മാർതന്നെവന്ന് അവന്റെ മുമ്പിൽ വീണു. അവർ പറഞ്ഞു: ഇതാ ഞങ്ങൾ അങ്ങേക്ക് അടിമകളാണ്.","p":1},{"v":19,"t":"ജോസഫ് അവരോടു പറഞ്ഞു: നിങ്ങൾ പേടിക്കേണ്ടയോ, ഞാനെന്താ ദൈവത്തിന്റെ സ്ഥാനത്താണോ?","p":1},{"v":20,"t":"നിങ്ങൾ എനിക്കെതിരെ തിന്മ വിഭാവനം ചെയ്തു. ദൈവമാകട്ടെ, അതു നന്മക്കായി പരിഗണിച്ചു. ഒരു വലിയ ജനത്തിന്റെ ഇന്നത്തെപോലുള്ള ജീവസന്ധാരണത്തിനുവേണ്ടിയാണ് അവിടുന്നു പ്രവർത്തിച്ചത്.","p":1},{"v":21,"t":"ആകയാൽ ഇപ്പോൾ നിങ്ങൾ ഭയപ്പെടേണ്ടാ, നിങ്ങളെയും നിങ്ങളുടെ കുഞ്ഞുങ്ങളെയും ഞാൻ പോറ്റിക്കൊള്ളാം. അങ്ങനെ, അവൻ അവരെ സാന്ത്വനപ്പെടുത്തുകയും അവരോടു ഹൃദ്യമായി സംസാരിക്കുകയും ചെയ്തു.","p":1},{"h":"ജോസഫിന്റെ മരണം"},{"v":22,"t":"ജോസഫ് അവന്റെ പിതാവിന്റെ കുടുംബത്തോടൊപ്പം ഈജിപ്തിൽ പാർത്തു. ജോസഫ് നൂറ്റിപ്പത്തു വർഷം ജീവിച്ചു. എഫ്രായിമിന്റെ മൂന്നാം തലമുറയിലെ മക്കളെ ജോസഫ് കണ്ടു. മനാസ്സെയുടെ മകനായ മാക്കിറിന്റെ കുഞ്ഞുങ്ങളും ജനിച്ചത് ജോസഫിന്റെ മുട്ടുകളിലാണ്.","p":1},{"v":23,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: ഞാൻ മരിക്കുകയാണ്. എന്നാൽ, ദൈവം നിങ്ങളെ തീർച്ചയായും സന്ദർശിക്കും. അവിടുന്നു നിങ്ങളെ ഈ നാട്ടിൽനിന്ന് അബ്രഹാമിനോടും ഇസഹാക്കിനോടും യാക്കോബിനോടും വാഗ്ദാനംചെയ്ത നാട്ടിലേക്ക് കൊണ്ടുപോകും.","p":1},{"v":24,"t":"തുടർന്ന്, 'ദൈവം നിങ്ങളെ തീർച്ചയായും സന്ദർശിക്കും. അപ്പോൾ, നിങ്ങൾ എന്റെ അസ്ഥികൾ ഇവിടെന്നു കൊണ്ടുപോകണം' എന്നുപറഞ്ഞ് ജോസഫ് ഇസ്രായേലിന്റെ പുത്രന്മാരെക്കൊണ്ട് പ്രതിജ്ഞ ചെയ്യിച്ചു.","p":1},{"v":25,"t":"നൂറ്റിപ്പത്തുവർഷം പ്രായമായപ്പോൾ ജോസഫ് മരിച്ചു. അവർ അവനെ സുഗന്ധലേപനം ചെയ്ത്, ഒരു പേടകത്തിൽ ഈജിപ്തിൽ സൂക്ഷിച്ചു.","p":1}]}},{"id":"EXO","name":"പുറപ്പാട്","chapters":{"1":[{"h":"ഈജിപ്തിലെ അടിമത്തം"},{"v":1,"t":"ഇസ്രായേല്യരിലെ ഓരോരുത്തനും അവനവന്റെ കുടുംബവും യാക്കോബിനോടൊപ്പം ഈജിപ്തിലേക്കു വന്നു. അവരുടെ പേരുകൾ ഇവയാണ്:","p":1},{"v":2,"t":"റൂബൻ, ശിമയോൻ, ലേവി, യൂദാ;"},{"v":3,"t":"ഇസ്സാക്കർ, സെബുലൂൺ, ബെഞ്ചമിൻ;"},{"v":4,"t":"ദാൻ, നഫ്താലി; ഗാദ്, ആഷേർ."},{"v":5,"t":"യാക്കോബിൽനിന്നുതന്നെ ഉടലെടുത്ത ആളുകൾ ആകെ എഴുപതുപേരായിരുന്നു. ജോസഫാകട്ടെ, ഈജിപ്തിലായിരുന്നു."},{"v":6,"t":"ജോസഫും അവന്റെ എല്ലാ സഹോദരന്മാരും ആ തലമുറമുഴുവനും മരിച്ചു."},{"v":7,"t":"ഇസ്രായേല്യർ പെറ്റുപെരുകി; അവർ വർധിച്ചു വളരെയധികം ശക്തിപ്രാപിച്ചു. ദേശം അവരെക്കൊണ്ടു നിറഞ്ഞു."},{"v":8,"t":"ജോസഫിനെ അറിയാത്ത ഒരു പുതിയ രാജാവ് ഈജിപ്തിൽ ഉയർന്നുവന്നു.","p":1},{"v":9,"t":"അവൻ തന്റെ ജനത്തോടു പറഞ്ഞു: ഇതാ, ഇസ്രായേല്യജനം നമ്മെക്കാൾ വലുതും പ്രബലവുമാണ്."},{"v":10,"t":"വരു! അവൻ പെരുകാതിരിക്കാൻ നമുക്ക് അവനോടു കൗശലംപ്രയോഗിക്കാം. അല്ലെങ്കിൽ, ഒരു യുദ്ധം നേരിടേണ്ടിവന്നാൽ അവൻ നമ്മെ വെറുക്കുന്നവരോടുചേർന്ന് നമുക്കെതിരേ പൊരുതുകയും രാജ്യത്തുനിന്നു വിട്ടുപോവുകയും ചെയ്തേക്കാം."},{"v":11,"t":"തങ്ങളുടെ കഠിനജോലികൾകൊണ്ട് അവനെ ഞെരുക്കാൻ നിർബന്ധിതവേലകൾക്കുള്ള കങ്കാണിമാരെ അവർ അവന്റെമേൽ നിയമിച്ചു. അങ്ങനെ അവൻ ഫറവോയ്ക്കുവേണ്ടി പിത്തോം, റമ്സേസ് എന്നീ സംഭരണനഗരങ്ങൾ നിർമിച്ചു."},{"v":12,"t":"എന്നാൽ, അവർ അവനെ എത്രമാത്രം പീഡിപ്പിച്ചുവോ അത്രയ്ക്ക് അവൻ പെരുകുകയും അതനുസരിച്ച് അവൻ വ്യാപിക്കുകയും ചെയ്തു. ഇസ്രായേല്യർനിമിത്തം അവർ പരിഭ്രാന്തരായി."},{"v":13,"t":"ഈജിപ്തുകാർ ഇസ്രായേല്യരെ ദണ്ഡനംകൊണ്ട് അടിമവേല ചെയ്യിച്ചു."},{"v":14,"t":"കുമ്മായവും ഇഷ്ടികയും കൊണ്ടുള്ള കഠിനജോലികൊണ്ടും വയലിലെ ജോലിയെല്ലാംകൊണ്ടും അവരുടെ ജീവിതങ്ങൾ അവർ കയ്പുള്ളതാക്കി. അക്കൂട്ടരുടെയിടയിൽ അവർ ചെയ്ത ഓരോ അടിമവേലയും കാഠിന്യമുള്ളതായിരുന്നു."},{"v":15,"t":"ഈജിപ്തുരാജാവ് ഹെബ്രായസൂതികർമിണികളോടു സംസാരിച്ചു. അതിലൊരുവളുടെ പേര് ഷിഫ്റാ, രണ്ടാമത്തവളുടെ പേര് പൂവാ.","p":1},{"v":16,"t":"അവൻ പറഞ്ഞു: നിങ്ങൾ ഹെബ്രായസ്ത്രീകളുടെ പ്രസവമെടുക്കുമ്പോൾ ലിംഗവ്യത്യാസം ശ്രദ്ധിക്കണം. പുത്രനാണെങ്കിൽ അവനെ വധിക്കണം; പുത്രിയാണെങ്കിൽ അവൾ ജീവിച്ചുകൊള്ളട്ടെ."},{"v":17,"t":"എന്നാൽ, ആ സൂതികർമിണികൾ ദൈവത്തെ ഭയപ്പെട്ടിരുന്നതിനാൽ ഈജിപ്തുരാജാവ് അവരോടു പറഞ്ഞതുപോലെ ചെയ്തില്ല; അവർ ആൺകുഞ്ഞുങ്ങളെ ജീവിക്കാനനുവദിച്ചു."},{"v":18,"t":"ആകയാൽ, ഈജിപ്തുരാജാവ് സൂതികർമിണികളെ വിളിച്ച് അവരോടു ചോദിച്ചു: നിങ്ങൾ ഇക്കാര്യം ചെയ്ത് ആൺകുഞ്ഞുങ്ങളെ ജീവിക്കാനനുവദിച്ചത് എന്തുകൊണ്ട്?"},{"v":19,"t":"സൂതികർമിണികൾ ഫറവോയോടു പറഞ്ഞു: ഈജിപ്തുകാരികളെപ്പോലെയല്ല ഹെബ്രായസ്ത്രീകൾ. അവർ ഓജസ്സുറ്റവരാകയാൽ, സൂതികർമിണി അവരുടെപക്കൽ എത്തും മുമ്പേ പ്രസവിച്ചിരിക്കും."},{"v":20,"t":"ദൈവം സൂതികർമിണികൾക്കു നന്മ വരുത്തി. ജനം പെരുകി; അവർ ഏറെ ശക്തരായി."},{"v":21,"t":"സൂതികർമിണികൾ ദൈവത്തെ ഭയപ്പെട്ടിരുന്നതുകൊണ്ട് അവിടന്ന് അവർക്കായി കുടുംബങ്ങൾ സംസ്ഥാപിച്ചു."},{"v":22,"t":"അപ്പോൾ ഫറവോ തന്റെ സകലജനത്തോടും ഇപ്രകാരം കല്പിച്ചു: ജനിക്കുന്ന ഓരോ പുത്രനെയും നദിയിലേക്ക് എറിയുവിൻ; ഓരോ പുത്രിയും ജീവിച്ചുകൊള്ളട്ടെ."}],"2":[{"h":"മോശയുടെ ജനനം"},{"v":1,"t":"ലേവികുടുംബത്തിൽപ്പെട്ട ഒരാൾ ചെന്ന് ലേവിയുടെ ഒരു പുത്രിയെ സ്വീകരിച്ചു.","p":1},{"v":2,"t":"ആ സ്ത്രീ ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൻ കോമളനാണെന്നു കണ്ട് അവനെ അവൾ മൂന്നുമാസം ഒളിപ്പിച്ചു."},{"v":3,"t":"അവനെ ഇനിയും ഒളിപ്പിക്കാൻ സാധിക്കാതായപ്പോൾ അവൾ അവനായി ഒരു പപ്പീറസ് പെട്ടകമെടുത്ത് കളിമണ്ണും താറും പൂശി, അതിൽ ശിശുവിനെ കിടത്തി, നൈൽതീരത്ത് ഞാങ്ങണയ്ക്കിടയിൽ വച്ചു."},{"v":4,"t":"അവനോട് എന്തു ചെയ്യുമെന്ന് അറിയാനായി അവന്റെ സഹോദരി അകലെയായി നിന്നിരുന്നു."},{"v":5,"t":"അപ്പോൾ ഫറവോയുടെ പുത്രി കുളിക്കാനായി നദിയിലിറങ്ങി. അവളുടെ ഭൃത്യകൾ നദീതീരത്തു നടക്കുകയായിരുന്നു. അവൾ ഞാങ്ങണയ്ക്കിടയിൽ ആ പെട്ടകം കണ്ടു. തന്റെ ഒരു ദാസിയെ അയച്ച് അവൾ അതെടുത്തു."},{"v":6,"t":"അവൾ അതു തുറന്നപ്പോൾ ശിശുവിനെ കണ്ടു. അതാ, കുട്ടി കരയുകയായിരുന്നു. അവന്റെമേൽ അനുകമ്പതോന്നി അവൾ പറഞ്ഞു: ഇവൻ ഹെബ്രായശിശുക്കളിൽപ്പെട്ടവനാണ്."},{"v":7,"t":"അപ്പോൾ അവന്റെ സഹോദരി ഫറവോയുടെ പുത്രിയോടു ചോദിച്ചു: ഞാൻ പോയി നിനക്കുവേണ്ടി ഹെബ്രായസ്ത്രീകളിൽനിന്ന് മുലയൂട്ടുന്ന ഒരുവളെ വിളിക്കട്ടെയോ?"}]}}]};
